window.WORDS = [{"id":1,"w":"a","def":"something that is being considered","pos":[{"p":"article","senses":[{"ko":"하나의, 어떤","en":"used before a singular noun that has not been mentioned before"},{"ko":"~마다, ~당","en":"used to mean each or every, as in prices and rates"}]}],"ph":[{"t":"a bit","ko":"조금, 약간"},{"t":"a lot","ko":"많이"},{"t":"a couple of","ko":"두어 개의, 몇몇의"}],"ex":{"en":"Can I get a coffee, please?","ko":"커피 한 잔 주시겠어요?"}},{"id":2,"w":"able","def":"having the power, skill, money, or means to do something","pos":[{"p":"adjective","senses":[{"ko":"~할 수 있는","en":"having the power, skill, money, or means to do something"},{"ko":"유능한, 능력 있는","en":"good at doing things, clever or skilled"}]}],"ph":[{"t":"be able to","ko":"~할 수 있다"},{"t":"as soon as I'm able","ko":"할 수 있게 되는 대로"}],"ex":{"en":"I wasn't able to sleep last night.","ko":"어젯밤에 잠을 못 잤어."}},{"id":3,"w":"about","def":"on the subject of, or concerning something","pos":[{"p":"preposition","senses":[{"ko":"~에 대해, ~에 관한","en":"on the subject of something, or connected with it"}]},{"p":"adverb","senses":[{"ko":"약, 대략","en":"a little more or less than a number or amount"},{"ko":"막 ~하려는","en":"going to happen or be done very soon, used in be about to"}]}],"ph":[{"t":"What about ...?","ko":"~는 어때?"},{"t":"How about ...?","ko":"~하는 게 어때?"},{"t":"be about to","ko":"막 ~하려던 참이다"}],"ex":{"en":"What are you talking about?","ko":"무슨 소리야?"}},{"id":4,"w":"absolutely","def":"completely","pos":[{"p":"adverb","senses":[{"ko":"완전히, 전적으로","en":"to the fullest degree, totally"},{"ko":"물론이지, 그럼","en":"used to strongly agree with someone or say yes"}]}],"ph":[{"t":"absolutely not","ko":"절대 안 돼"},{"t":"absolutely nothing","ko":"아무것도 전혀"}],"ex":{"en":"You're absolutely right.","ko":"네 말이 완전히 맞아."}},{"id":5,"w":"accept","def":"to receive or take something that is offered","pos":[{"p":"verb","senses":[{"ko":"받아들이다, 받다","en":"to take something that someone offers you"},{"ko":"인정하다, 수용하다","en":"to agree that something is true or that you must live with it"},{"ko":"받아 주다, 합격시키다","en":"to allow someone to join a school, group, or company"}]}],"ph":[{"t":"accept an apology","ko":"사과를 받아들이다"},{"t":"accept the fact that","ko":"~라는 사실을 받아들이다"},{"t":"We accept cards.","ko":"카드 결제 돼요"}],"ex":{"en":"Please accept this small gift.","ko":"이 작은 선물 받아 주세요."}},{"id":6,"w":"account","def":"a story or report about something","pos":[{"p":"noun","senses":[{"ko":"설명, 이야기","en":"a spoken or written report of something that happened"},{"ko":"계좌, 계정","en":"an arrangement to keep money in a bank, or a login for a website"}]},{"p":"verb","senses":[{"ko":"설명하다, 차지하다","en":"to explain something, or to form a part of a total, used with for"}]}],"ph":[{"t":"account for","ko":"설명하다; (비율을) 차지하다"},{"t":"on account of","ko":"~ 때문에"},{"t":"take into account","ko":"고려하다, 감안하다"}],"ex":{"en":"She gave us a full account of the accident.","ko":"그녀가 사고에 대해 자세히 얘기해 줬어."}},{"id":7,"w":"across","def":"from one side to the other of something","pos":[{"p":"preposition","senses":[{"ko":"~을 가로질러, 건너","en":"from one side of something to the other"},{"ko":"~ 건너편에","en":"on the other side of something"}]},{"p":"adverb","senses":[{"ko":"가로질러, 건너서","en":"from one side to the other side"}]}],"ph":[{"t":"across the street","ko":"길 건너편에"},{"t":"come across","ko":"우연히 발견하다, 마주치다"},{"t":"across the board","ko":"전반적으로, 일괄적으로"}],"ex":{"en":"Let's walk across the bridge.","ko":"다리 건너서 걸어가자."}},{"id":8,"w":"action","def":"something that a person does","pos":[{"p":"noun","senses":[{"ko":"행동, 조치","en":"something that a person does, especially to deal with a problem"},{"ko":"활동, 액션","en":"exciting events, or the process of doing things"}]}],"ph":[{"t":"take action","ko":"조치를 취하다"},{"t":"in action","ko":"활동 중인, 작동 중인"},{"t":"action movie","ko":"액션 영화"}],"ex":{"en":"His actions speak louder than his words.","ko":"걔는 말보다 행동이 더 확실해."}},{"id":9,"w":"actually","def":"used when you are saying what is the truth of a situation","pos":[{"p":"adverb","senses":[{"ko":"사실은, 실제로","en":"used to say what is really true, often when it is surprising"},{"ko":"실은, 그런데","en":"used to politely correct someone or add new information"}]}],"ph":[{"t":"Actually, ...","ko":"실은요, ..."},{"t":"Did you actually ...?","ko":"진짜로 ~했어?"}],"ex":{"en":"Actually, I've never been to Seoul.","ko":"사실 나 서울 가 본 적 없어."}},{"id":10,"w":"add","def":"to put something together with another thing","pos":[{"p":"verb","senses":[{"ko":"더하다, 추가하다","en":"to put something together with another thing"},{"ko":"합하다, 더하다","en":"to put numbers together to get a total"},{"ko":"덧붙여 말하다","en":"to say something more after what was already said"}]}],"ph":[{"t":"add up","ko":"합계하다; 앞뒤가 맞다"},{"t":"It doesn't add up.","ko":"말이 안 맞아"},{"t":"add to","ko":"~을 늘리다, 더하다"}],"ex":{"en":"Add a little salt to the soup.","ko":"수프에 소금 조금 넣어."}},{"id":11,"w":"address","def":"the words and numbers that are used to describe the location of a building and that are written on letters, envelopes, and packages so that they can be mailed to that location","pos":[{"p":"noun","senses":[{"ko":"주소","en":"the details of where a building is, used for sending mail there"},{"ko":"(이메일) 주소","en":"a set of letters and symbols used to send email to someone"}]},{"p":"verb","senses":[{"ko":"다루다, 처리하다","en":"to think about and deal with a problem or question"},{"ko":"연설하다, 말을 걸다","en":"to speak to a person or a group"}]}],"ph":[{"t":"email address","ko":"이메일 주소"},{"t":"home address","ko":"집 주소"},{"t":"address the issue","ko":"문제를 다루다"}],"ex":{"en":"What's your address?","ko":"주소가 어떻게 돼요?"}},{"id":12,"w":"affect","def":"to make an effect on someone or something","pos":[{"p":"verb","senses":[{"ko":"영향을 미치다","en":"to cause a change in someone or something"},{"ko":"(마음에) 충격을 주다","en":"to make someone feel strong emotions such as sadness"}]}],"ph":[{"t":"be affected by","ko":"~의 영향을 받다"},{"t":"affect someone deeply","ko":"~에게 큰 충격을 주다"}],"ex":{"en":"The rain might affect our plans.","ko":"비 때문에 계획이 틀어질 수도 있어."}},{"id":13,"w":"after","def":"following in time, at a later time","pos":[{"p":"preposition","senses":[{"ko":"~ 후에, ~ 다음에","en":"following something in time, at a later time"},{"ko":"~을 뒤쫓아","en":"following or chasing someone or something"}]},{"p":"conjunction","senses":[{"ko":"~한 후에","en":"at a time later than when something happens"}]}],"ph":[{"t":"after all","ko":"결국; 어쨌든"},{"t":"After you.","ko":"먼저 하세요"},{"t":"look after","ko":"돌보다"}],"ex":{"en":"Let's grab dinner after work.","ko":"퇴근하고 저녁 먹자."}},{"id":14,"w":"afternoon","def":"the middle part of the day : the part of the day between noon and evening","pos":[{"p":"noun","senses":[{"ko":"오후","en":"the middle part of the day, between noon and evening"}]}],"ph":[{"t":"Good afternoon.","ko":"안녕하세요 (오후 인사)"},{"t":"this afternoon","ko":"오늘 오후"},{"t":"in the afternoon","ko":"오후에"}],"ex":{"en":"I'll call you this afternoon.","ko":"오늘 오후에 전화할게."}},{"id":15,"w":"again","def":"one more time, once more","pos":[{"p":"adverb","senses":[{"ko":"다시, 또","en":"one more time, once more"},{"ko":"원래대로, 다시","en":"back to the way something was before"}]}],"ph":[{"t":"Come again?","ko":"뭐라고요?"},{"t":"again and again","ko":"몇 번이고, 되풀이해서"},{"t":"never again","ko":"다시는 안 해"}],"ex":{"en":"Could you say that again?","ko":"다시 한 번 말해 줄래요?"}},{"id":16,"w":"against","def":"in opposition to","pos":[{"p":"preposition","senses":[{"ko":"~에 반대하여","en":"in opposition to something, or not agreeing with it"},{"ko":"~에 기대어","en":"touching or leaning on something"},{"ko":"~에 맞서, ~ 상대로","en":"competing with someone in a game or fight"}]}],"ph":[{"t":"against the law","ko":"불법인"},{"t":"against the rules","ko":"규칙 위반인"},{"t":"I have nothing against it.","ko":"난 딱히 반대 안 해"}],"ex":{"en":"I'm against the idea.","ko":"난 그 생각에 반대야."}},{"id":17,"w":"age","def":"the amount of time a person has lived","pos":[{"p":"noun","senses":[{"ko":"나이","en":"the amount of time a person has lived"},{"ko":"시대, 시기","en":"a particular period of time in history"},{"ko":"오랫동안 (ages)","en":"a very long time, used in the plural form ages"}]},{"p":"verb","senses":[{"ko":"나이 들다, 늙다","en":"to become older, or to look older"}]}],"ph":[{"t":"for ages","ko":"오랫동안"},{"t":"at my age","ko":"내 나이에"},{"t":"act your age","ko":"나잇값 좀 해"}],"ex":{"en":"He looks young for his age.","ko":"그 사람 나이에 비해 어려 보여."}},{"id":18,"w":"ago","def":"in the past","pos":[{"p":"adverb","senses":[{"ko":"~ 전에","en":"in the past, used after a length of time"}]}],"ph":[{"t":"long ago","ko":"오래전에"},{"t":"a while ago","ko":"아까, 좀 전에"},{"t":"not long ago","ko":"얼마 전에"}],"ex":{"en":"I saw her two days ago.","ko":"이틀 전에 걔 봤어."}},{"id":19,"w":"agree","def":"to the same opinion about something","pos":[{"p":"verb","senses":[{"ko":"동의하다","en":"to have the same opinion as someone about something"},{"ko":"합의하다, 승낙하다","en":"to say yes to a plan, idea, or request"}]}],"ph":[{"t":"I agree.","ko":"동감이야"},{"t":"agree with","ko":"~에 동의하다"},{"t":"agree to disagree","ko":"서로 의견 차이를 인정하다"}],"ex":{"en":"I totally agree with you.","ko":"완전 네 말에 동의해."}},{"id":20,"w":"ahead","def":"in or toward the front","pos":[{"p":"adverb","senses":[{"ko":"앞에, 앞으로","en":"in or toward the front"},{"ko":"미리, 앞서","en":"before something else happens, or in the future"},{"ko":"앞선, 이기고 있는","en":"winning, or more successful than others"}]}],"ph":[{"t":"Go ahead.","ko":"그렇게 해, 먼저 해"},{"t":"ahead of time","ko":"미리"},{"t":"plan ahead","ko":"미리 계획하다"}],"ex":{"en":"The station is just ahead.","ko":"역 바로 앞에 있어."}},{"id":21,"w":"air","def":"the invisible mixture of gases that we breathe","pos":[{"p":"noun","senses":[{"ko":"공기","en":"the invisible mixture of gases around us that we breathe"},{"ko":"하늘, 공중","en":"the space above the ground"},{"ko":"항공 (by air)","en":"travel or transport by plane"}]},{"p":"verb","senses":[{"ko":"방송하다; 환기하다","en":"to broadcast on TV or radio, or to let fresh air into a room"}]}],"ph":[{"t":"fresh air","ko":"바깥 공기, 신선한 공기"},{"t":"on air","ko":"방송 중인"},{"t":"up in the air","ko":"아직 미정인"}],"ex":{"en":"Let's open the window and get some air.","ko":"창문 열고 바람 좀 쐬자."}},{"id":22,"w":"all","def":"the whole, entire or total amount","pos":[{"p":"determiner","senses":[{"ko":"모든, 전부의","en":"the whole, entire, or total amount or number of something"}]},{"p":"pronoun","senses":[{"ko":"모두, 전부","en":"every person or every thing in a group"}]},{"p":"adverb","senses":[{"ko":"완전히, 아주","en":"completely, or to a very great degree"}]}],"ph":[{"t":"at all","ko":"전혀 (부정문에서)"},{"t":"That's all.","ko":"그게 다야"},{"t":"all over","ko":"곳곳에; 완전히 끝난"}],"ex":{"en":"Who ate all the cake?","ko":"케이크 누가 다 먹었어?"}},{"id":23,"w":"allow","def":"to permit or treat as acceptable","pos":[{"p":"verb","senses":[{"ko":"허락하다, 허용하다","en":"to permit someone to do something, or let something happen"},{"ko":"(시간·돈을) 잡다","en":"to plan enough time or money for something"}]}],"ph":[{"t":"be allowed to","ko":"~해도 된다"},{"t":"Allow me.","ko":"제가 해 드릴게요"},{"t":"allow for","ko":"~을 감안하다"}],"ex":{"en":"Dogs aren't allowed in here.","ko":"여기 개는 못 들어와."}},{"id":24,"w":"almost","def":"only a little less than, nearly, not quite","pos":[{"p":"adverb","senses":[{"ko":"거의","en":"only a little less than, nearly but not quite"}]}],"ph":[{"t":"almost there","ko":"거의 다 왔어"},{"t":"almost never","ko":"거의 ~ 않는"},{"t":"almost always","ko":"거의 항상"}],"ex":{"en":"I'm almost done.","ko":"거의 다 했어."}},{"id":25,"w":"along","def":"at a point on something","pos":[{"p":"preposition","senses":[{"ko":"~을 따라 (있는)","en":"at a point on something long, such as a road or river"},{"ko":"~을 따라 쭉","en":"moving in a line from one part of something to another"}]},{"p":"adverb","senses":[{"ko":"앞으로, 함께","en":"moving forward, or together with someone"}]}],"ph":[{"t":"get along","ko":"사이좋게 지내다"},{"t":"come along","ko":"따라오다, 같이 가다"},{"t":"all along","ko":"처음부터 내내"}],"ex":{"en":"There's a nice café along this road.","ko":"이 길가에 괜찮은 카페 있어."}},{"id":26,"w":"already","def":"before this time","pos":[{"p":"adverb","senses":[{"ko":"이미, 벌써","en":"before this time, or before a certain time"},{"ko":"벌써 (놀람)","en":"used to show surprise that something happened so soon"}]}],"ph":[{"t":"Already?","ko":"벌써?"},{"t":"Come on already!","ko":"빨리 좀 해!"}],"ex":{"en":"I've already eaten.","ko":"나 벌써 먹었어."}},{"id":27,"w":"alright","def":"good enough, although not very good; safe or well","pos":[{"p":"adjective","senses":[{"ko":"괜찮은, 그럭저럭인","en":"good enough, although not very good"},{"ko":"무사한, 괜찮은","en":"safe, well, or not hurt"}]},{"p":"interjection","senses":[{"ko":"좋아, 알았어","en":"used to agree to something or say yes"}]}],"ph":[{"t":"Are you alright?","ko":"괜찮아?"},{"t":"It's alright.","ko":"괜찮아, 신경 쓰지 마"},{"t":"That's alright.","ko":"괜찮아요 (사과·감사에 대답)"}],"ex":{"en":"The movie was alright, but not great.","ko":"영화 그럭저럭 괜찮았어, 대단하진 않고."}},{"id":28,"w":"also","def":"in addition, too, in a similar way","pos":[{"p":"adverb","senses":[{"ko":"또한, ~도","en":"in addition, too, or in a similar way"}]}],"ph":[{"t":"not only ... but also","ko":"~뿐만 아니라 ~도"}],"ex":{"en":"I also like jazz.","ko":"나 재즈도 좋아해."}},{"id":29,"w":"although","def":"despite the fact that, however,","pos":[{"p":"conjunction","senses":[{"ko":"비록 ~이지만","en":"despite the fact that"},{"ko":"하지만, 그렇긴 해도","en":"but, used to add something that makes a statement less strong"}]}],"ph":[],"ex":{"en":"Although it was raining, we went out.","ko":"비가 왔지만 우리는 나갔어."}},{"id":30,"w":"always","def":"at all times","pos":[{"p":"adverb","senses":[{"ko":"항상, 언제나","en":"at all times, or every time"},{"ko":"영원히, 늘","en":"forever, or for as long as you can remember"},{"ko":"언제든지","en":"used to suggest another possible choice, as in you can always"}]}],"ph":[{"t":"as always","ko":"늘 그렇듯"},{"t":"You can always ...","ko":"언제든 ~하면 돼"}],"ex":{"en":"She's always late.","ko":"걔는 맨날 늦어."}},{"id":31,"w":"amount","def":"a quantity of something","pos":[{"p":"noun","senses":[{"ko":"양, 액수","en":"a quantity of something, such as money or time"}]},{"p":"verb","senses":[{"ko":"(합계가) ~에 달하다","en":"to add up to a total, used with to"}]}],"ph":[{"t":"amount to","ko":"~에 달하다; ~와 다름없다"},{"t":"a huge amount of","ko":"엄청난 양의"}],"ex":{"en":"That's a huge amount of food!","ko":"음식 양 엄청나다!"}},{"id":32,"w":"and","def":"used to join words or groups of words","pos":[{"p":"conjunction","senses":[{"ko":"그리고, ~와","en":"used to join words, phrases, or sentences"},{"ko":"그래서, 그러자","en":"used to show that one thing follows or results from another"}]}],"ph":[{"t":"and so on","ko":"기타 등등"},{"t":"and then","ko":"그러고 나서"},{"t":"nice and ...","ko":"아주 ~한, 기분 좋게 ~한"}],"ex":{"en":"I'll have a burger and fries.","ko":"버거랑 감자튀김 주세요."}},{"id":33,"w":"another","def":"one more in addition","pos":[{"p":"determiner","senses":[{"ko":"또 하나의, 한 번 더","en":"one more in addition to the ones already mentioned"},{"ko":"다른","en":"a different one of the same kind"}]},{"p":"pronoun","senses":[{"ko":"또 하나, 다른 것","en":"one more person or thing, or a different one"}]}],"ph":[{"t":"one another","ko":"서로"},{"t":"another time","ko":"다음에, 다른 때에"},{"t":"yet another","ko":"또 하나의"}],"ex":{"en":"Can I have another cup?","ko":"한 잔 더 주실래요?"}},{"id":34,"w":"answer","def":"a reaction to a question someone asks","pos":[{"p":"noun","senses":[{"ko":"대답, 답","en":"something you say or write as a reaction to a question"},{"ko":"해답, 해결책","en":"a way to solve a problem"}]},{"p":"verb","senses":[{"ko":"대답하다","en":"to reply to a question someone asks"},{"ko":"(전화를) 받다","en":"to pick up a ringing phone or open the door to a visitor"}]}],"ph":[{"t":"answer the phone","ko":"전화를 받다"},{"t":"answer the door","ko":"현관에 나가 보다"},{"t":"The answer is no.","ko":"대답은 안 돼야"}],"ex":{"en":"I asked him, but he didn't give an answer.","ko":"물어봤는데 걔가 대답을 안 했어."}},{"id":35,"w":"any","def":"used to refer to something not particular or specific","pos":[{"p":"determiner","senses":[{"ko":"어떤 ~든, 아무","en":"used to refer to one or some of something, no matter which"},{"ko":"조금도, 하나도","en":"used in negatives and questions to talk about an amount"}]},{"p":"adverb","senses":[{"ko":"조금이라도, 더","en":"at all, used to make a comparison stronger"}]}],"ph":[{"t":"any time","ko":"언제든지; 천만에요"},{"t":"in any case","ko":"어쨌든"},{"t":"not any more","ko":"더 이상 ~ 아닌"}],"ex":{"en":"Pick any color you like.","ko":"맘에 드는 색 아무거나 골라."}},{"id":36,"w":"anybody","def":"any person : anyone","pos":[{"p":"pronoun","senses":[{"ko":"아무나, 누구든","en":"any person at all, the same as anyone"},{"ko":"누군가 (의문문)","en":"some person, used in questions and negatives"}]}],"ph":[{"t":"Anybody home?","ko":"집에 누구 있어요?"},{"t":"anybody else","ko":"다른 누구"}],"ex":{"en":"Anybody can learn to cook.","ko":"요리는 누구나 배울 수 있어."}},{"id":37,"w":"anyone","def":"any person","pos":[{"p":"pronoun","senses":[{"ko":"누구든, 아무나","en":"any person, no matter who"},{"ko":"누군가 (의문문)","en":"some person, used in questions and negatives"}]}],"ph":[{"t":"anyone else","ko":"다른 누구"},{"t":"Anyone want ...?","ko":"~할 사람?"}],"ex":{"en":"Does anyone want coffee?","ko":"커피 마실 사람?"}},{"id":38,"w":"anything","def":"a thing of any kind, used to refer to a thing, no matter what","pos":[{"p":"pronoun","senses":[{"ko":"무엇이든, 아무거나","en":"a thing of any kind, no matter what it is"},{"ko":"무언가, 아무것도","en":"something, used in questions and negatives"}]}],"ph":[{"t":"Anything else?","ko":"더 필요한 거 있으세요?"},{"t":"anything but","ko":"결코 ~이 아닌"},{"t":"if anything","ko":"오히려, 굳이 말하자면"}],"ex":{"en":"You can order anything you want.","ko":"먹고 싶은 거 아무거나 시켜."}},{"id":39,"w":"anyway","def":"despite something that has been stated before","pos":[{"p":"adverb","senses":[{"ko":"어쨌든, 그래도","en":"despite something that has been said before"},{"ko":"아무튼, 그건 그렇고","en":"used to change the subject or end a conversation"}]}],"ph":[{"t":"Anyway, ...","ko":"아무튼, ..."},{"t":"Thanks anyway.","ko":"아무튼 고마워"}],"ex":{"en":"It was raining, but we went anyway.","ko":"비가 왔는데 그래도 갔어."}},{"id":40,"w":"apply","def":"to ask formally for something such as a job","pos":[{"p":"verb","senses":[{"ko":"지원하다, 신청하다","en":"to formally ask for something such as a job or a place"},{"ko":"적용되다, 해당되다","en":"to affect or be relevant to a person or situation"},{"ko":"(크림 등을) 바르다","en":"to put something such as cream onto a surface"}]}],"ph":[{"t":"apply for","ko":"~에 지원하다, 신청하다"},{"t":"apply to","ko":"~에 해당되다"}],"ex":{"en":"I'm going to apply for that job.","ko":"나 그 자리에 지원할 거야."}},{"id":41,"w":"area","def":"a part or section in a large place","pos":[{"p":"noun","senses":[{"ko":"지역, 구역","en":"a part or section of a city, country, or larger place"},{"ko":"분야, 영역","en":"a particular subject or field of activity"},{"ko":"공간, 면적","en":"a space used for a purpose, or the size of a surface"}]}],"ph":[{"t":"in the area","ko":"근처에, 이 동네에"},{"t":"gray area","ko":"애매한 부분"},{"t":"area code","ko":"지역 번호"}],"ex":{"en":"Do you live in this area?","ko":"이 동네 살아요?"}},{"id":42,"w":"around","def":"located on every side or along something","pos":[{"p":"preposition","senses":[{"ko":"~ 주위에, 둘레에","en":"on every side of something, or along its edges"},{"ko":"~ 여기저기","en":"in or to many parts of a place"}]},{"p":"adverb","senses":[{"ko":"약, ~쯤","en":"approximately, used before a number or time"},{"ko":"근처에, 주변에","en":"nearby, or present in a place"}]}],"ph":[{"t":"around the corner","ko":"모퉁이 돌면; 코앞에"},{"t":"look around","ko":"둘러보다"},{"t":"See you around.","ko":"또 보자"}],"ex":{"en":"We sat around the table.","ko":"우리는 테이블에 둘러앉았어."}},{"id":43,"w":"as","def":"used to refer to the same degree or amount","pos":[{"p":"adverb","senses":[{"ko":"~만큼 (as ~ as)","en":"used in comparisons to say two things are the same in degree or amount"}]},{"p":"preposition","senses":[{"ko":"~로서, ~처럼","en":"in the role of someone, or in the same way as something"}]},{"p":"conjunction","senses":[{"ko":"~할 때, ~하면서","en":"while or at the same time as something happens"},{"ko":"~ 때문에","en":"because, or for the reason that"}]}],"ph":[{"t":"as well","ko":"또한, ~도"},{"t":"as soon as possible","ko":"가능한 한 빨리"},{"t":"as usual","ko":"평소처럼"}],"ex":{"en":"He's as tall as his dad.","ko":"걔 아빠만큼 키가 커."}},{"id":44,"w":"ask","def":"to request","pos":[{"p":"verb","senses":[{"ko":"부탁하다, 요청하다","en":"to request that someone do or give something"},{"ko":"묻다, 질문하다","en":"to say something to get information or an answer"},{"ko":"초대하다, 청하다","en":"to invite someone to come somewhere"}]}],"ph":[{"t":"ask out","ko":"데이트 신청하다"},{"t":"ask for","ko":"~을 요청하다"},{"t":"if you ask me","ko":"내 생각엔"}],"ex":{"en":"Can I ask you a favor?","ko":"부탁 하나 해도 돼?"}},{"id":45,"w":"at","def":"used to indicate place, location, or arrival","pos":[{"p":"preposition","senses":[{"ko":"~에서, ~에 (장소)","en":"used to show the place where someone or something is or arrives"},{"ko":"~에 (시각)","en":"used to show an exact time"},{"ko":"~을 향해, ~에게","en":"toward someone or something"}]}],"ph":[{"t":"at home","ko":"집에서; 편안한"},{"t":"at least","ko":"적어도"},{"t":"at all","ko":"전혀 (부정문에서)"}],"ex":{"en":"I'll meet you at the station.","ko":"역에서 만나자."}},{"id":46,"w":"available","def":"when something is there to be used easily","pos":[{"p":"adjective","senses":[{"ko":"이용할 수 있는","en":"there and ready to be used or bought easily"},{"ko":"시간이 되는","en":"free to meet, talk, or do something"},{"ko":"사귀는 사람이 없는","en":"not in a romantic relationship"}]}],"ph":[{"t":"Are you available?","ko":"시간 돼요?"},{"t":"available online","ko":"온라인으로 이용 가능한"},{"t":"readily available","ko":"쉽게 구할 수 있는"}],"ex":{"en":"Is this seat available?","ko":"이 자리 비었어요?"}},{"id":47,"w":"aware","def":"knowing or feeling that something exists","pos":[{"p":"adjective","senses":[{"ko":"알고 있는, 인식하는","en":"knowing or feeling that something exists or is happening"},{"ko":"의식이 높은, 잘 아는","en":"interested in and knowing a lot about a subject"}]}],"ph":[{"t":"be aware of","ko":"~을 알고 있다"},{"t":"as far as I'm aware","ko":"내가 알기로는"},{"t":"self-aware","ko":"자기 자신을 잘 아는"}],"ex":{"en":"Were you aware of the problem?","ko":"그 문제 알고 있었어?"}},{"id":48,"w":"away","def":"at a distance from a particular person or place","pos":[{"p":"adverb","senses":[{"ko":"떨어져, 멀리","en":"at a distance from a particular person or place"},{"ko":"자리에 없는, 떠나 있는","en":"not at home or work, or gone to another place"},{"ko":"없어져, 사라져","en":"into a state of being gone or removed"}]}],"ph":[{"t":"go away","ko":"저리 가; 사라지다"},{"t":"right away","ko":"바로, 즉시"},{"t":"far away","ko":"멀리 떨어진"}],"ex":{"en":"The beach is ten minutes away.","ko":"해변은 10분 거리야."}},{"id":49,"w":"awful","def":"very bad, of low quality, or unpleasant","pos":[{"p":"adjective","senses":[{"ko":"끔찍한, 형편없는","en":"very bad, of low quality, or unpleasant"},{"ko":"(몸·기분이) 안 좋은","en":"feeling ill, or feeling very sorry about something"},{"ko":"엄청난","en":"very great, used in an awful lot"}]}],"ph":[{"t":"an awful lot","ko":"엄청 많이"},{"t":"feel awful","ko":"너무 미안하다; 몸이 안 좋다"}],"ex":{"en":"The food there was awful.","ko":"거기 음식 진짜 별로였어."}},{"id":50,"w":"baby","def":"a very young child","pos":[{"p":"noun","senses":[{"ko":"아기","en":"a very young child"},{"ko":"자기야 (애칭)","en":"a name used when talking to someone you love"},{"ko":"막내; 애 같은 사람","en":"the youngest in a family, or someone who acts like a child"}]}],"ph":[{"t":"have a baby","ko":"아기를 낳다"},{"t":"baby steps","ko":"작은 한 걸음씩"},{"t":"Don't be such a baby.","ko":"애처럼 굴지 마"}],"ex":{"en":"The baby is sleeping, so be quiet.","ko":"아기 자니까 조용히 해."}},{"id":51,"w":"back","def":"the rear surface of something","pos":[{"p":"noun","senses":[{"ko":"뒤쪽, 뒷면","en":"the rear surface or part of something, farthest from the front"},{"ko":"등, 허리","en":"the part of the body between the neck and the hips, opposite the chest"}]},{"p":"adverb","senses":[{"ko":"다시, 원래 자리로","en":"to the place or state where someone or something was before"},{"ko":"뒤로","en":"in or toward the rear"}]},{"p":"verb","senses":[{"ko":"지지하다, 후원하다","en":"to give support or help to someone or something"}]}],"ph":[{"t":"be right back","ko":"금방 돌아올게"},{"t":"back up","ko":"뒷받침하다; 후진하다; 백업하다"},{"t":"behind someone's back","ko":"~ 몰래, 뒤에서"}],"ex":{"en":"Write your name on the back of the card.","ko":"카드 뒷면에 이름 써."}},{"id":52,"w":"bad","def":"low or poor in quality, not correct or proper","pos":[{"p":"adjective","senses":[{"ko":"나쁜, 질 낮은","en":"low or poor in quality, or not correct or proper"},{"ko":"해로운, 안 좋은","en":"harmful, unpleasant, or not good for you"},{"ko":"심한, 심각한","en":"very serious or severe, such as an illness"},{"ko":"서투른, 잘 못하는","en":"not skilled at doing something, as in bad at math"},{"ko":"상한, 썩은","en":"no longer fresh and not safe to eat or drink"}]}],"ph":[{"t":"not bad","ko":"괜찮은데, 나쁘지 않아"},{"t":"too bad","ko":"안됐다, 아쉽다"},{"t":"my bad","ko":"내 잘못이야"}],"ex":{"en":"This coffee is really bad.","ko":"이 커피 진짜 맛없다."}},{"id":53,"w":"bag","def":"a container made of thin material (such as paper, plastic, or cloth) that opens at the top and is used for holding or carrying things","pos":[{"p":"noun","senses":[{"ko":"가방, 봉투","en":"a container of paper, plastic, or cloth for holding or carrying things"},{"ko":"한 봉지 (분량)","en":"the amount that a bag holds"}]}],"ph":[{"t":"pack your bags","ko":"짐을 싸다"},{"t":"in the bag","ko":"따 놓은 당상인"},{"t":"bags under your eyes","ko":"다크서클, 눈 밑 처짐"}],"ex":{"en":"Do you need a bag?","ko":"봉투 필요하세요?"}},{"id":54,"w":"base","def":"the bottom or lowest part of something : the part on which something rests or is supported","pos":[{"p":"noun","senses":[{"ko":"맨 아래, 받침","en":"the bottom part of something, on which it rests or is supported"},{"ko":"근거지, 기지","en":"the main place where someone works, lives, or is stationed"},{"ko":"기초, 토대","en":"the main part or idea from which something develops"}]},{"p":"verb","senses":[{"ko":"~에 근거를 두다","en":"to use something as the starting point for something else, used with on"}]}],"ph":[{"t":"based on","ko":"~에 근거한, ~을 바탕으로"},{"t":"touch base","ko":"잠깐 연락하다"},{"t":"off base","ko":"완전히 틀린"}],"ex":{"en":"The lamp has a heavy base.","ko":"그 램프는 받침이 무거워."}},{"id":55,"w":"basically","def":"in the most important or fundamental ways","pos":[{"p":"adverb","senses":[{"ko":"기본적으로, 근본적으로","en":"in the most important or basic ways"},{"ko":"요컨대, 그러니까","en":"used to give the simple truth or a short summary"}]}],"ph":[],"ex":{"en":"The two phones are basically the same.","ko":"그 두 폰은 기본적으로 똑같아."}},{"id":56,"w":"be","def":"used to show the identity of a thing","pos":[{"p":"verb","senses":[{"ko":"~이다","en":"used to say who or what someone or something is"},{"ko":"있다, 존재하다","en":"to exist, or to be in a place"},{"ko":"(상태가) ~하다","en":"used to describe a quality, feeling, or state"}]}],"ph":[{"t":"be into","ko":"~에 빠져 있다, ~을 좋아하다"},{"t":"Let it be.","ko":"그냥 내버려 둬"},{"t":"to be honest","ko":"솔직히 말하면"}],"ex":{"en":"This is my brother, Tom.","ko":"얘는 내 동생 톰이야."}},{"id":57,"w":"bear","def":"to accept or endure difficulties","pos":[{"p":"verb","senses":[{"ko":"참다, 견디다","en":"to accept or deal with something painful or difficult"},{"ko":"(무게를) 지탱하다","en":"to support the weight of something"}]},{"p":"noun","senses":[{"ko":"곰","en":"a large, heavy wild animal with thick fur"}]}],"ph":[{"t":"can't bear","ko":"~을 못 참다, 너무 싫다"},{"t":"Bear with me.","ko":"잠깐만 기다려 줘"},{"t":"bear in mind","ko":"명심하다"}],"ex":{"en":"I can't bear this heat.","ko":"이 더위 못 참겠어."}},{"id":58,"w":"because","def":"for a reason","pos":[{"p":"conjunction","senses":[{"ko":"~ 때문에, 왜냐하면","en":"for the reason that"}]}],"ph":[{"t":"because of","ko":"~ 때문에"},{"t":"just because","ko":"~라고 해서; 그냥"}],"ex":{"en":"I'm tired because I worked late.","ko":"늦게까지 일해서 피곤해."}},{"id":59,"w":"become","def":"to begin to be, grow to be, develop into","pos":[{"p":"verb","senses":[{"ko":"~이 되다, ~해지다","en":"to begin to be something, or grow or develop into it"}]}],"ph":[{"t":"What became of ...?","ko":"~은 어떻게 됐어?"},{"t":"become friends","ko":"친구가 되다"}],"ex":{"en":"She became a doctor last year.","ko":"그녀는 작년에 의사가 됐어."}},{"id":60,"w":"bed","def":"a piece of furniture that people sleep on","pos":[{"p":"noun","senses":[{"ko":"침대","en":"a piece of furniture that people sleep on"},{"ko":"잠자리, 취침","en":"the time when you go to sleep"},{"ko":"바닥, 화단","en":"the bottom of a sea or river, or an area for growing plants"}]}],"ph":[{"t":"go to bed","ko":"자러 가다"},{"t":"make the bed","ko":"침대를 정리하다"},{"t":"wake up on the wrong side of the bed","ko":"아침부터 기분이 안 좋다"}],"ex":{"en":"I'm going to bed early tonight.","ko":"오늘은 일찍 잘 거야."}},{"id":61,"w":"before","def":"at an earlier time, in front of","pos":[{"p":"preposition","senses":[{"ko":"~ 전에","en":"at an earlier time than something"},{"ko":"~ 앞에","en":"in front of someone or something"}]},{"p":"adverb","senses":[{"ko":"전에, 이전에","en":"at an earlier time, previously"}]},{"p":"conjunction","senses":[{"ko":"~하기 전에","en":"earlier than the time when something happens"}]}],"ph":[{"t":"before long","ko":"머지않아, 곧"},{"t":"the day before yesterday","ko":"그저께"},{"t":"Have we met before?","ko":"우리 전에 만난 적 있나요?"}],"ex":{"en":"Wash your hands before dinner.","ko":"저녁 먹기 전에 손 씻어."}},{"id":62,"w":"begin","def":"to do the first part of an action, to start","pos":[{"p":"verb","senses":[{"ko":"시작하다","en":"to do the first part of an action, to start"},{"ko":"시작되다","en":"to start happening or existing"}]}],"ph":[{"t":"to begin with","ko":"우선, 애초에"},{"t":"begin with","ko":"~부터 시작하다"}],"ex":{"en":"Let's begin with a quick review.","ko":"간단히 복습부터 시작하자."}},{"id":63,"w":"behind","def":"in or toward the back","pos":[{"p":"preposition","senses":[{"ko":"~ 뒤에","en":"in or toward the back of someone or something"},{"ko":"~보다 뒤처진","en":"slower or less advanced than others"},{"ko":"~을 지지하는","en":"supporting or giving help to someone"}]},{"p":"adverb","senses":[{"ko":"뒤에, 뒤처져","en":"at the back, or late in doing something"}]}],"ph":[{"t":"behind someone's back","ko":"~ 몰래, 뒤에서"},{"t":"fall behind","ko":"뒤처지다"},{"t":"leave behind","ko":"두고 가다"}],"ex":{"en":"The parking lot is behind the building.","ko":"주차장은 건물 뒤에 있어."}},{"id":64,"w":"believe","def":"to accept that something is true","pos":[{"p":"verb","senses":[{"ko":"믿다","en":"to accept that something is true or that someone is honest"},{"ko":"(~라고) 생각하다","en":"to think that something is true, without being completely sure"}]}],"ph":[{"t":"I can't believe it.","ko":"믿을 수가 없어"},{"t":"believe in","ko":"~을 믿다, ~의 존재를 믿다"},{"t":"believe it or not","ko":"믿기 힘들겠지만"}],"ex":{"en":"I don't believe you.","ko":"네 말 못 믿겠어."}},{"id":65,"w":"benefit","def":"a good result or effect, something helpful","pos":[{"p":"noun","senses":[{"ko":"이익, 혜택","en":"a good or helpful result or effect"},{"ko":"수당, 복리후생","en":"money or extras given by an employer or the government"}]},{"p":"verb","senses":[{"ko":"이득을 보다, 도움이 되다","en":"to be helped by something, or to help someone"}]}],"ph":[{"t":"the benefit of the doubt","ko":"(의심스러워도) 일단 믿어 줌"},{"t":"for your benefit","ko":"너를 위해서"}],"ex":{"en":"Exercise has a lot of benefits.","ko":"운동은 좋은 점이 많아."}},{"id":66,"w":"bet","def":"to risk money on the result of a game, competition, etc.","pos":[{"p":"verb","senses":[{"ko":"(돈을) 걸다, 내기하다","en":"to risk money on what will happen in a game or race"},{"ko":"틀림없다, 장담하다","en":"to feel sure that something is true or will happen"}]},{"p":"noun","senses":[{"ko":"내기, 내기 돈","en":"an agreement to risk money on a result"}]}],"ph":[{"t":"I bet","ko":"분명 ~일 거야"},{"t":"You bet!","ko":"물론이지!"},{"t":"best bet","ko":"가장 나은 방법"}],"ex":{"en":"He bet fifty dollars on the game.","ko":"걔 그 경기에 50달러 걸었어."}},{"id":67,"w":"between","def":"in the space that separates to objects","pos":[{"p":"preposition","senses":[{"ko":"~ 사이에","en":"in the space that separates two things or people"},{"ko":"~ 사이에 (시간)","en":"in the period after one time and before another"},{"ko":"~ 중에서","en":"used when choosing from two or more things"}]}],"ph":[{"t":"between you and me","ko":"우리끼리 얘긴데"},{"t":"in between","ko":"중간에, 사이에"},{"t":"read between the lines","ko":"숨은 뜻을 읽다"}],"ex":{"en":"The bank is between the café and the park.","ko":"은행은 카페랑 공원 사이에 있어."}},{"id":68,"w":"big","def":"large in size or extent","pos":[{"p":"adjective","senses":[{"ko":"큰","en":"large in size, amount, or extent"},{"ko":"중요한, 큰","en":"important, serious, or having a lot of influence"},{"ko":"손위의","en":"older, as in big brother or big sister"}]}],"ph":[{"t":"No big deal.","ko":"별거 아니야"},{"t":"a big fan","ko":"열성 팬"},{"t":"think big","ko":"크게 생각하다"}],"ex":{"en":"That's a really big house.","ko":"집 진짜 크다."}},{"id":69,"w":"bill","def":"a document that says how much money you owe for something you have bought or used","pos":[{"p":"noun","senses":[{"ko":"청구서, 계산서","en":"a document that shows how much money you owe for something"},{"ko":"지폐","en":"a piece of paper money, in American English"},{"ko":"법안","en":"a written plan for a new law"}]},{"p":"verb","senses":[{"ko":"청구하다","en":"to send someone a document asking for payment"}]}],"ph":[{"t":"Can I get the bill?","ko":"계산서 주세요"},{"t":"split the bill","ko":"나눠서 계산하다"},{"t":"pay the bills","ko":"생활비를 벌다"}],"ex":{"en":"My phone bill was huge this month.","ko":"이번 달 휴대폰 요금 엄청 나왔어."}},{"id":70,"w":"bit","def":"a small piece of something","pos":[{"p":"noun","senses":[{"ko":"조금, 작은 조각","en":"a small piece or amount of something"},{"ko":"잠깐","en":"a short period of time"}]}],"ph":[{"t":"a bit","ko":"조금, 약간"},{"t":"bit by bit","ko":"조금씩"},{"t":"quite a bit","ko":"꽤 많이"}],"ex":{"en":"Can I have a bit of your sandwich?","ko":"샌드위치 조금만 줄래?"}},{"id":71,"w":"black","def":"having the very dark color of coal or the night sky","pos":[{"p":"adjective","senses":[{"ko":"검은, 까만","en":"having the very dark color of coal or the night sky"},{"ko":"흑인의","en":"belonging to a group of people with dark skin"},{"ko":"(커피) 블랙의","en":"served without milk or cream"}]},{"p":"noun","senses":[{"ko":"검은색","en":"the darkest color, like the night sky"}]}],"ph":[{"t":"black and white","ko":"흑백의; 명백한"},{"t":"black out","ko":"정신을 잃다; 정전되다"},{"t":"in the black","ko":"흑자인"}],"ex":{"en":"She wore a black dress to the party.","ko":"그녀는 파티에 검은 드레스를 입고 왔어."}},{"id":72,"w":"bloody","def":"covered in blood; violent and involving a lot of blood and injuries","pos":[{"p":"adjective","senses":[{"ko":"피투성이의, 유혈의","en":"covered in blood, or violent with a lot of injuries"},{"ko":"빌어먹을, 지독한","en":"a rude British word used to make an angry statement stronger"}]},{"p":"adverb","senses":[{"ko":"지독히, 엄청","en":"a rude British word meaning very, used for emphasis"}]}],"ph":[{"t":"bloody nose","ko":"코피"},{"t":"Bloody hell!","ko":"젠장!, 맙소사!"}],"ex":{"en":"His shirt was all bloody after the fall.","ko":"넘어지고 나서 걔 셔츠가 피범벅이었어."}},{"id":73,"w":"board","def":"a long, thin, flat piece of wood","pos":[{"p":"noun","senses":[{"ko":"판자, 널빤지","en":"a long, thin, flat piece of wood"},{"ko":"게시판, 칠판, 판","en":"a flat surface used for notices, writing, or games"},{"ko":"이사회, 위원회","en":"a group of people who manage a company or organization"}]},{"p":"verb","senses":[{"ko":"타다, 탑승하다","en":"to get onto a ship, plane, train, or bus"}]}],"ph":[{"t":"on board","ko":"탑승한; 함께하는"},{"t":"board game","ko":"보드게임"},{"t":"boarding pass","ko":"탑승권"}],"ex":{"en":"He nailed a board over the broken window.","ko":"그는 깨진 창문에 판자를 대서 박았어."}},{"id":74,"w":"body","def":"a person's physical self","pos":[{"p":"noun","senses":[{"ko":"몸, 신체","en":"a person's physical self, or the whole form of an animal"},{"ko":"시체","en":"the body of a dead person"},{"ko":"단체, 기관","en":"an organized group of people with a shared purpose"}]}],"ph":[{"t":"body language","ko":"몸짓 언어"},{"t":"Over my dead body!","ko":"내 눈에 흙이 들어가도 안 돼!"}],"ex":{"en":"My whole body hurts.","ko":"온몸이 쑤셔."}},{"id":75,"w":"book","def":"a printed or written work that is bound together and has a cover","pos":[{"p":"noun","senses":[{"ko":"책","en":"a set of printed or written pages fastened together inside a cover"}]},{"p":"verb","senses":[{"ko":"예약하다","en":"to arrange to have a seat, room, or ticket in advance"}]}],"ph":[{"t":"book a table","ko":"테이블을 예약하다"},{"t":"fully booked","ko":"예약이 꽉 찬"},{"t":"by the book","ko":"원칙대로, 규정대로"}],"ex":{"en":"I'm reading a great book right now.","ko":"요즘 진짜 재밌는 책 읽고 있어."}},{"id":76,"w":"both","def":"used to emphasis two things at the same time","pos":[{"p":"determiner","senses":[{"ko":"둘 다의, 양쪽의","en":"used to talk about two people or things at the same time"}]},{"p":"pronoun","senses":[{"ko":"둘 다, 양쪽 모두","en":"the two people or things together"}]},{"p":"conjunction","senses":[{"ko":"A와 B 둘 다","en":"used with and to show that two things are both true"}]}],"ph":[{"t":"both of us","ko":"우리 둘 다"},{"t":"the best of both worlds","ko":"양쪽의 좋은 점을 다 누림"}],"ex":{"en":"Both my parents are teachers.","ko":"우리 부모님 두 분 다 선생님이셔."}},{"id":77,"w":"bother","def":"to make someone feel worried or upset","pos":[{"p":"verb","senses":[{"ko":"신경 쓰이게 하다","en":"to make someone feel worried, upset, or annoyed"},{"ko":"귀찮게 하다, 방해하다","en":"to interrupt or annoy someone"},{"ko":"애써 ~하다","en":"to make the effort to do something"}]},{"p":"noun","senses":[{"ko":"귀찮은 일, 성가심","en":"trouble or effort that is annoying"}]}],"ph":[{"t":"Don't bother.","ko":"괜찮아, 신경 쓰지 마"},{"t":"Sorry to bother you.","ko":"귀찮게 해서 죄송해요"},{"t":"can't be bothered","ko":"귀찮아서 하기 싫다"}],"ex":{"en":"Does the noise bother you?","ko":"소리 신경 쓰여?"}},{"id":78,"w":"bottom","def":"the lowest part, point, or level of something","pos":[{"p":"noun","senses":[{"ko":"맨 아래, 바닥","en":"the lowest part, point, or level of something"},{"ko":"엉덩이","en":"the part of your body that you sit on"},{"ko":"꼴찌, 최하위","en":"the lowest position in a list, class, or group"}]},{"p":"adjective","senses":[{"ko":"맨 아래의","en":"in the lowest position"}]}],"ph":[{"t":"Bottoms up!","ko":"건배!, 원샷!"},{"t":"from the bottom of my heart","ko":"진심으로"},{"t":"get to the bottom of","ko":"~의 진상을 밝히다"}],"ex":{"en":"There's a coin at the bottom of the pool.","ko":"수영장 바닥에 동전이 있어."}},{"id":79,"w":"box","def":"a container that is made of a hard material (such as wood, metal, or cardboard) and that usually has four straight sides","pos":[{"p":"noun","senses":[{"ko":"상자, 박스","en":"a container made of a hard material, usually with four straight sides"},{"ko":"(서식의) 칸, 네모","en":"a square space on a form for writing or ticking"}]},{"p":"verb","senses":[{"ko":"상자에 담다","en":"to put something into a box"}]}],"ph":[{"t":"think outside the box","ko":"틀에서 벗어나 생각하다"},{"t":"check the box","ko":"칸에 체크하다"}],"ex":{"en":"Put the books in that box.","ko":"책은 저 상자에 넣어."}},{"id":80,"w":"boy","def":"a male child or youth, a young man","pos":[{"p":"noun","senses":[{"ko":"소년, 남자아이","en":"a male child, or a young man"},{"ko":"아들","en":"a son of any age"}]},{"p":"interjection","senses":[{"ko":"와, 이런","en":"used to show surprise or strong feeling"}]}],"ph":[{"t":"Oh boy!","ko":"맙소사!, 와!"},{"t":"Boys will be boys.","ko":"남자애들이 다 그렇지 뭐"}],"ex":{"en":"A little boy was playing in the park.","ko":"꼬마 남자애가 공원에서 놀고 있었어."}},{"id":81,"w":"break","def":"to separate into pieces","pos":[{"p":"verb","senses":[{"ko":"깨다, 부수다","en":"to separate something into pieces, often by hitting or dropping it"},{"ko":"고장 나다, 고장 내다","en":"to stop working, or to make something stop working"},{"ko":"(규칙·약속을) 어기다","en":"to fail to obey a rule or keep a promise"}]},{"p":"noun","senses":[{"ko":"휴식, 쉬는 시간","en":"a short period of rest from work or study"},{"ko":"방학, 짧은 휴가","en":"a short holiday from school or work, such as spring break"}]}],"ph":[{"t":"take a break","ko":"잠깐 쉬다"},{"t":"break up","ko":"헤어지다"},{"t":"Give me a break.","ko":"그만 좀 해, 좀 봐줘"}],"ex":{"en":"Be careful, don't break the glass.","ko":"조심해, 컵 깨지 마."}},{"id":82,"w":"breath","def":"the air that you take into your lungs and send out from your lungs when you breathe","pos":[{"p":"noun","senses":[{"ko":"숨, 호흡","en":"the air that you take into your lungs and send out again"},{"ko":"입김, 입 냄새","en":"the air coming out of your mouth, or its smell"}]}],"ph":[{"t":"take a deep breath","ko":"심호흡하다"},{"t":"out of breath","ko":"숨이 찬"},{"t":"Don't hold your breath.","ko":"너무 기대하지 마"}],"ex":{"en":"Hold your breath and count to ten.","ko":"숨 참고 열까지 세 봐."}},{"id":83,"w":"brief","def":"lasting , having only a short period of time","pos":[{"p":"adjective","senses":[{"ko":"짧은, 잠깐의","en":"lasting only a short period of time"},{"ko":"간단한, 간결한","en":"using only a few words"}]},{"p":"verb","senses":[{"ko":"브리핑하다, 요약 보고하다","en":"to give someone the important facts about something"}]}],"ph":[{"t":"in brief","ko":"간단히 말해서"},{"t":"brief someone on","ko":"~에게 ~에 대해 알려 주다"}],"ex":{"en":"We had a brief chat after class.","ko":"수업 끝나고 잠깐 얘기했어."}},{"id":84,"w":"bring","def":"to take or go with to a place,","pos":[{"p":"verb","senses":[{"ko":"가져오다, 데려오다","en":"to take something or someone with you to a place"},{"ko":"가져오다, 초래하다","en":"to cause something to happen or exist"}]}],"ph":[{"t":"bring up","ko":"(화제를) 꺼내다; 키우다"},{"t":"bring back","ko":"돌려주다; 떠올리게 하다"},{"t":"Bring it on!","ko":"덤벼 봐!"}],"ex":{"en":"Can I bring a friend?","ko":"친구 데려가도 돼?"}},{"id":85,"w":"brother","def":"a boy or man who has one or both of the same parents as you","pos":[{"p":"noun","senses":[{"ko":"형제, 형, 오빠, 남동생","en":"a boy or man who has one or both of the same parents as you"},{"ko":"형제 같은 친구","en":"a close male friend, or a man in the same group"}]}],"ph":[{"t":"big brother","ko":"형, 오빠"},{"t":"little brother","ko":"남동생"},{"t":"brother-in-law","ko":"매형, 처남, 시동생 등"}],"ex":{"en":"My brother lives in Busan.","ko":"우리 형 부산 살아."}},{"id":86,"w":"budget","def":"a plan of how you will spend your money; the amount of money you have for something","pos":[{"p":"noun","senses":[{"ko":"예산, 지출 계획","en":"a plan for spending money, or the amount of money you have for something"}]},{"p":"verb","senses":[{"ko":"예산을 세우다","en":"to plan carefully how you will spend money"}]},{"p":"adjective","senses":[{"ko":"저렴한, 저가의","en":"cheap and simple, made for people with little money"}]}],"ph":[{"t":"on a budget","ko":"적은 돈으로, 아껴서"},{"t":"over budget","ko":"예산을 초과한"},{"t":"tight budget","ko":"빠듯한 예산"}],"ex":{"en":"We're on a tight budget this month.","ko":"이번 달은 예산이 빠듯해."}},{"id":87,"w":"build","def":"to construct by putting parts or materials together","pos":[{"p":"verb","senses":[{"ko":"짓다, 건설하다","en":"to make something by putting parts or materials together"},{"ko":"쌓아 가다, 키우다","en":"to develop something gradually over time"}]},{"p":"noun","senses":[{"ko":"체격","en":"the size and shape of a person's body"}]}],"ph":[{"t":"build up","ko":"쌓아 올리다, 늘리다"},{"t":"build trust","ko":"신뢰를 쌓다"}],"ex":{"en":"They're building a new school here.","ko":"여기 새 학교 짓고 있어."}},{"id":88,"w":"bus","def":"a large vehicle that is used for carrying passengers especially along a particular route at particular times","pos":[{"p":"noun","senses":[{"ko":"버스","en":"a large vehicle that carries many passengers along a fixed route"}]}],"ph":[{"t":"take the bus","ko":"버스를 타다"},{"t":"bus stop","ko":"버스 정류장"},{"t":"miss the bus","ko":"버스를 놓치다; 기회를 놓치다"}],"ex":{"en":"I usually take the bus to work.","ko":"나 보통 버스 타고 출근해."}},{"id":89,"w":"business","def":"the activity of making, buying, selling or providing goods","pos":[{"p":"noun","senses":[{"ko":"사업, 장사","en":"the activity of making, buying, selling, or providing goods or services"},{"ko":"회사, 가게","en":"a company or shop that sells goods or services"},{"ko":"일, 볼일","en":"something that is your concern or responsibility"}]}],"ph":[{"t":"None of your business.","ko":"네가 상관할 일 아니야"},{"t":"on business","ko":"업무차, 출장으로"},{"t":"get down to business","ko":"본론으로 들어가다"}],"ex":{"en":"Business has been slow this year.","ko":"올해는 장사가 잘 안 돼."}},{"id":90,"w":"but","def":"used to contrast a statement with a to previous one","pos":[{"p":"conjunction","senses":[{"ko":"하지만, 그런데","en":"used to add something that contrasts with what was said before"}]},{"p":"preposition","senses":[{"ko":"~ 외에, ~을 제외하고","en":"except someone or something"}]}],"ph":[{"t":"No buts.","ko":"토 달지 마"},{"t":"but then","ko":"하지만 그래도"},{"t":"all but","ko":"거의"}],"ex":{"en":"I'd love to, but I'm busy.","ko":"그러고 싶은데 바빠."}},{"id":91,"w":"buy","def":"to get something by paying money for it; purchase","pos":[{"p":"verb","senses":[{"ko":"사다, 구입하다","en":"to get something by paying money for it"},{"ko":"(말을) 믿다","en":"to believe that something someone says is true, used informally"}]},{"p":"noun","senses":[{"ko":"구매, 산 물건","en":"something that is bought, often at a good price"}]}],"ph":[{"t":"I'll buy you lunch.","ko":"점심 살게"},{"t":"I don't buy it.","ko":"그 말 못 믿겠어"},{"t":"a good buy","ko":"잘 산 물건"}],"ex":{"en":"I bought a new phone yesterday.","ko":"어제 새 폰 샀어."}},{"id":92,"w":"by","def":"close to or next to, up to and beyond, beside a place","pos":[{"p":"preposition","senses":[{"ko":"~ 옆에, ~ 곁에","en":"close to or next to someone or something"},{"ko":"~에 의해, ~로","en":"used to show who or what does something, or how"},{"ko":"~까지","en":"not later than a particular time"}]},{"p":"adverb","senses":[{"ko":"옆을 지나","en":"past someone or something"}]}],"ph":[{"t":"by the way","ko":"그건 그렇고, 그런데"},{"t":"by myself","ko":"혼자서"},{"t":"drop by","ko":"잠깐 들르다"}],"ex":{"en":"Come and sit by me.","ko":"와서 내 옆에 앉아."}},{"id":93,"w":"call","def":"to speak, announce or shout in a loud voice","pos":[{"p":"verb","senses":[{"ko":"부르다, 외치다","en":"to say something in a loud voice to get attention"},{"ko":"전화하다","en":"to phone someone or try to reach them"},{"ko":"~라고 부르다","en":"to give someone or something a name"}]},{"p":"noun","senses":[{"ko":"통화, 전화","en":"an act of phoning someone"},{"ko":"결정, 판단","en":"a decision, as in it's your call"}]}],"ph":[{"t":"call back","ko":"다시 전화하다"},{"t":"It's your call.","ko":"네가 결정해"},{"t":"call it a day","ko":"오늘은 여기까지 하다"}],"ex":{"en":"I heard someone call my name.","ko":"누가 내 이름 부르는 거 들었어."}},{"id":94,"w":"can","def":"to be able to do something","pos":[{"p":"modal","senses":[{"ko":"~할 수 있다","en":"used to say that someone is able to do something"},{"ko":"~해도 된다","en":"used to ask for or give permission"},{"ko":"~해 줄래?","en":"used in questions to ask someone to do something for you"},{"ko":"(can't) ~일 리가 없다","en":"used with not to say you are sure something is not true"}]},{"p":"noun","senses":[{"ko":"캔, 깡통","en":"a closed metal container for food or drink"}]}],"ph":[{"t":"Can I ...?","ko":"~해도 돼요?"},{"t":"can't help it","ko":"어쩔 수 없다"},{"t":"can't wait","ko":"너무 기대된다"}],"ex":{"en":"Can you help me with this?","ko":"이것 좀 도와줄 수 있어?"}},{"id":95,"w":"car","def":"a vehicle with four wheels and engine that can carry things","pos":[{"p":"noun","senses":[{"ko":"자동차, 차","en":"a road vehicle with four wheels and an engine that carries people"},{"ko":"(열차의) 칸","en":"one of the separate parts of a train"}]}],"ph":[{"t":"by car","ko":"차로"},{"t":"get in the car","ko":"차에 타다"},{"t":"car park","ko":"주차장 (영국)"}],"ex":{"en":"Where did you park the car?","ko":"차 어디에 세웠어?"}},{"id":96,"w":"card","def":"a small piece of stiff paper that is marked with symbols or pictures to show its value, comes in a set, and is used for playing games","pos":[{"p":"noun","senses":[{"ko":"(놀이용) 카드, 트럼프","en":"a piece of stiff paper with pictures or symbols, used in a set for games"},{"ko":"신용카드, 명함","en":"a small plastic or paper card for paying or showing information"},{"ko":"(축하) 카드","en":"a folded piece of stiff paper with a picture and a message"}]}],"ph":[{"t":"play cards","ko":"카드 게임을 하다"},{"t":"pay by card","ko":"카드로 결제하다"},{"t":"play your cards right","ko":"일을 잘 풀어 가다"}],"ex":{"en":"Let's play cards after dinner.","ko":"저녁 먹고 카드 게임 하자."}},{"id":97,"w":"care","def":"effort made to do something correctly or well","pos":[{"p":"noun","senses":[{"ko":"주의, 조심","en":"effort and attention given to doing something correctly or safely"},{"ko":"돌봄, 보살핌","en":"the work of looking after someone"}]},{"p":"verb","senses":[{"ko":"신경 쓰다, 관심 갖다","en":"to feel that something is important"},{"ko":"아끼다, 걱정하다","en":"to love someone and worry about what happens to them"}]}],"ph":[{"t":"Take care.","ko":"잘 지내, 몸조심해"},{"t":"I don't care.","ko":"상관없어"},{"t":"take care of","ko":"돌보다; 처리하다"}],"ex":{"en":"Carry the box with care.","ko":"상자 조심해서 옮겨."}},{"id":98,"w":"carry","def":"to move something from one place to another","pos":[{"p":"verb","senses":[{"ko":"나르다, 들고 가다","en":"to hold something and move it from one place to another"},{"ko":"가지고 다니다","en":"to have something with you all the time"},{"ko":"(가게에서) 팔다","en":"to have a product available for sale"}]}],"ph":[{"t":"carry on","ko":"계속하다"},{"t":"get carried away","ko":"흥분해서 도를 넘다"},{"t":"carry out","ko":"수행하다, 실행하다"}],"ex":{"en":"Can you help me carry this?","ko":"이거 옮기는 것 좀 도와줄래?"}},{"id":99,"w":"case","def":"an example or instance of something","pos":[{"p":"noun","senses":[{"ko":"경우, 사례","en":"a particular example or situation of something"},{"ko":"상자, 케이스","en":"a container for storing or protecting something"},{"ko":"사건, 소송","en":"a crime or legal matter that the police or a court deal with"}]}],"ph":[{"t":"just in case","ko":"혹시 모르니까"},{"t":"in that case","ko":"그렇다면"},{"t":"in case","ko":"~할 경우에 대비해"}],"ex":{"en":"In this case, you should call the police.","ko":"이런 경우엔 경찰을 불러야 해."}},{"id":100,"w":"catch","def":"to use your hands to stop and hold","pos":[{"p":"verb","senses":[{"ko":"잡다, 받다","en":"to use your hands to stop and hold something that is moving"},{"ko":"(버스 등을) 타다","en":"to get on a bus, train, or plane in time"},{"ko":"(병에) 걸리다","en":"to get an illness from someone or something"},{"ko":"알아듣다, 듣다","en":"to hear or understand something someone says"}]},{"p":"noun","senses":[{"ko":"함정, 숨은 문제","en":"a hidden problem or disadvantage"}]}],"ph":[{"t":"catch up","ko":"따라잡다; 밀린 얘기를 나누다"},{"t":"Catch you later.","ko":"나중에 봐"},{"t":"What's the catch?","ko":"함정이 뭐야?"}],"ex":{"en":"Catch the ball!","ko":"공 받아!"}},{"id":101,"w":"cause","def":"something that produces an effect","pos":[{"p":"noun","senses":[{"ko":"원인, 이유","en":"something that produces an effect or makes something happen"},{"ko":"대의, 목적","en":"an idea or aim that people support"}]},{"p":"verb","senses":[{"ko":"일으키다, 초래하다","en":"to make something happen, usually something bad"}]}],"ph":[{"t":"cause trouble","ko":"말썽을 일으키다"},{"t":"for a good cause","ko":"좋은 일을 위해"},{"t":"no cause for concern","ko":"걱정할 필요 없음"}],"ex":{"en":"What was the cause of the fire?","ko":"불 난 원인이 뭐였어?"}},{"id":102,"w":"center","def":"the middle point or part","pos":[{"p":"noun","senses":[{"ko":"중심, 한가운데","en":"the middle point or part of something"},{"ko":"센터, 중심지","en":"a building or place used for a particular activity"},{"ko":"(관심의) 중심","en":"the person or thing that gets the most attention"}]}],"ph":[{"t":"city center","ko":"시내, 도심"},{"t":"the center of attention","ko":"관심의 중심"},{"t":"shopping center","ko":"쇼핑센터"}],"ex":{"en":"There's a big table in the center of the room.","ko":"방 한가운데 큰 테이블이 있어."}},{"id":103,"w":"certain","def":"not having any doubt about something","pos":[{"p":"adjective","senses":[{"ko":"확신하는, 확실한","en":"not having any doubt about something"},{"ko":"어떤, 특정한","en":"particular, but not named or described"}]}],"ph":[{"t":"for certain","ko":"확실히"},{"t":"make certain","ko":"확인하다, 꼭 ~하다"},{"t":"to a certain extent","ko":"어느 정도는"}],"ex":{"en":"Are you certain about that?","ko":"그거 확실해?"}},{"id":104,"w":"certainly","def":"used to emphasize something and show that there is no doubt about it; used to agree to a request","pos":[{"p":"adverb","senses":[{"ko":"확실히, 분명히","en":"without any doubt, used to make a statement stronger"},{"ko":"물론이죠, 그럼요","en":"used to politely agree to a request"}]}],"ph":[{"t":"Certainly not.","ko":"절대 아니에요, 안 돼요"}],"ex":{"en":"It certainly looks like rain.","ko":"분명 비 올 것 같아."}},{"id":105,"w":"chance","def":"an opportunity to do something; an amount of time or a situation in which something can be done","pos":[{"p":"noun","senses":[{"ko":"기회","en":"an opportunity, or a time when something can be done"},{"ko":"가능성, 확률","en":"how likely it is that something will happen"},{"ko":"우연, 운","en":"luck, or something that happens without a plan"}]}],"ph":[{"t":"by any chance","ko":"혹시"},{"t":"take a chance","ko":"모험을 하다, 운에 맡기다"},{"t":"No chance.","ko":"어림없어"}],"ex":{"en":"Give me one more chance.","ko":"한 번만 더 기회를 줘."}},{"id":106,"w":"change","def":"to make or become different","pos":[{"p":"verb","senses":[{"ko":"바꾸다, 변하다","en":"to make or become different"},{"ko":"갈아입다, 갈아타다","en":"to put on other clothes, or move to another bus or train"},{"ko":"교환하다, 환전하다","en":"to exchange money or an item for another"}]},{"p":"noun","senses":[{"ko":"변화","en":"the act or result of something becoming different"},{"ko":"잔돈, 거스름돈","en":"money given back when you pay, or coins"}]}],"ph":[{"t":"change your mind","ko":"마음을 바꾸다"},{"t":"for a change","ko":"기분 전환으로"},{"t":"Keep the change.","ko":"잔돈은 가지세요"}],"ex":{"en":"You haven't changed at all.","ko":"너 하나도 안 변했다."}},{"id":107,"w":"charge","def":"to ask for money as a price for a service or goods","pos":[{"p":"verb","senses":[{"ko":"(요금을) 청구하다, 받다","en":"to ask for money as a price for goods or a service"},{"ko":"충전하다","en":"to put electricity into a battery"},{"ko":"기소하다, 고발하다","en":"to formally accuse someone of a crime"}]},{"p":"noun","senses":[{"ko":"요금","en":"the amount of money asked for something"},{"ko":"책임, 담당","en":"control of or responsibility for something, as in in charge"}]}],"ph":[{"t":"in charge","ko":"담당인, 책임자인"},{"t":"free of charge","ko":"무료로"},{"t":"charge up","ko":"충전하다"}],"ex":{"en":"How much do you charge for delivery?","ko":"배달비 얼마 받아요?"}},{"id":108,"w":"cheap","def":"not costing a lot of money","pos":[{"p":"adjective","senses":[{"ko":"싼, 저렴한","en":"not costing a lot of money"},{"ko":"싸구려의","en":"low in price and also low in quality"},{"ko":"인색한, 쩨쩨한","en":"not liking to spend money"}]}],"ph":[{"t":"dirt cheap","ko":"엄청 싼"},{"t":"cheap shot","ko":"비열한 공격"}],"ex":{"en":"This shirt was really cheap.","ko":"이 셔츠 진짜 싸게 샀어."}},{"id":109,"w":"check","def":"to look at (something) carefully to find mistakes, problems, etc.","pos":[{"p":"verb","senses":[{"ko":"확인하다, 점검하다","en":"to look at something carefully to find mistakes or problems"},{"ko":"(짐을) 맡기다","en":"to leave bags or a coat to be looked after"}]},{"p":"noun","senses":[{"ko":"확인, 점검","en":"a look to see if something is correct or safe"},{"ko":"계산서; 수표","en":"a bill in a restaurant, or a written order to pay money"}]}],"ph":[{"t":"check out","ko":"확인해 보다; 체크아웃하다"},{"t":"check in","ko":"체크인하다"},{"t":"Check, please.","ko":"계산서 주세요"}],"ex":{"en":"Let me check my schedule.","ko":"일정 좀 확인해 볼게."}},{"id":110,"w":"child","def":"a young person","pos":[{"p":"noun","senses":[{"ko":"아이, 어린이","en":"a young person who is not yet an adult"},{"ko":"자녀, 자식","en":"a son or daughter of any age"}]}],"ph":[{"t":"only child","ko":"외동"},{"t":"child's play","ko":"식은 죽 먹기"}],"ex":{"en":"This movie isn't for children.","ko":"이 영화는 애들이 볼 게 아니야."}},{"id":111,"w":"choice","def":"the act of choosing : the act of picking or deciding between two or more possibilities","pos":[{"p":"noun","senses":[{"ko":"선택","en":"the act of picking or deciding between two or more possibilities"},{"ko":"선택권, 선택의 여지","en":"the right or chance to choose"},{"ko":"선택 범위, 선택지","en":"the range of things you can choose from"}]}],"ph":[{"t":"have no choice","ko":"어쩔 수 없다"},{"t":"Good choice.","ko":"잘 골랐어"},{"t":"by choice","ko":"스스로 원해서"}],"ex":{"en":"It was a hard choice.","ko":"어려운 선택이었어."}},{"id":112,"w":"choose","def":"to decide that a particular person or thing is the one that you want","pos":[{"p":"verb","senses":[{"ko":"고르다, 선택하다","en":"to decide which person or thing you want"},{"ko":"(~하기로) 정하다","en":"to decide to do something"}]}],"ph":[{"t":"pick and choose","ko":"까다롭게 고르다"},{"t":"choose wisely","ko":"신중하게 고르다"}],"ex":{"en":"You can choose any seat.","ko":"아무 자리나 골라 앉아도 돼."}},{"id":113,"w":"church","def":"a building used for Christian religious worship or services","pos":[{"p":"noun","senses":[{"ko":"교회, 성당","en":"a building used for Christian religious services"},{"ko":"예배","en":"the religious services held in a church"}]}],"ph":[{"t":"go to church","ko":"교회에 다니다, 예배 보러 가다"}],"ex":{"en":"There's an old church near my house.","ko":"우리 집 근처에 오래된 교회가 있어."}},{"id":114,"w":"city","def":"many people living in a place larger than a town","pos":[{"p":"noun","senses":[{"ko":"도시","en":"a large place where many people live, bigger than a town"}]}],"ph":[{"t":"city hall","ko":"시청"},{"t":"big city","ko":"대도시"},{"t":"city life","ko":"도시 생활"}],"ex":{"en":"I grew up in a big city.","ko":"나 대도시에서 자랐어."}},{"id":115,"w":"class","def":"a group of students who often meet and are taught together","pos":[{"p":"noun","senses":[{"ko":"반, 학급","en":"a group of students who often meet and are taught together"},{"ko":"수업","en":"a period of time when students are taught"},{"ko":"계층, 등급","en":"a group of people or things at the same level"}]}],"ph":[{"t":"in class","ko":"수업 중에"},{"t":"skip class","ko":"수업을 빼먹다"},{"t":"first class","ko":"일등석; 최고급의"}],"ex":{"en":"There are twenty kids in my class.","ko":"우리 반에 애들이 스무 명 있어."}},{"id":116,"w":"clean","def":"free from dirt, marks, etc. : not dirty","pos":[{"p":"adjective","senses":[{"ko":"깨끗한","en":"free from dirt or marks, not dirty"},{"ko":"깨끗한, 공정한","en":"fair and honest, or without any crimes or mistakes"}]},{"p":"verb","senses":[{"ko":"청소하다, 닦다","en":"to remove dirt from something"}]}],"ph":[{"t":"clean up","ko":"청소하다, 치우다"},{"t":"come clean","ko":"사실대로 털어놓다"},{"t":"a clean slate","ko":"백지 상태, 새 출발"}],"ex":{"en":"Are these towels clean?","ko":"이 수건들 깨끗한 거야?"}},{"id":117,"w":"clear","def":"very obvious or easy to perceive","pos":[{"p":"adjective","senses":[{"ko":"분명한, 명확한","en":"very obvious, or easy to see, hear, or understand"},{"ko":"맑은, 투명한","en":"easy to see through, or without clouds"},{"ko":"막힌 것이 없는","en":"free from things that block the way"}]},{"p":"verb","senses":[{"ko":"치우다, 비우다","en":"to remove things from a place"},{"ko":"(날씨가) 개다","en":"to become brighter as clouds go away"}]}],"ph":[{"t":"make it clear","ko":"분명히 하다"},{"t":"clear up","ko":"정리하다; (날씨가) 개다"},{"t":"Is that clear?","ko":"알아들었어?"}],"ex":{"en":"It's clear that she's upset.","ko":"걔 화난 게 확실해."}},{"id":118,"w":"clock","def":"a device that shows what time it is and that is usually placed in a room or attached to a wall","pos":[{"p":"noun","senses":[{"ko":"시계","en":"a device that shows the time, usually kept on a wall or table"}]},{"p":"verb","senses":[{"ko":"(시간·속도를) 재다","en":"to measure or record a time or speed"}]}],"ph":[{"t":"around the clock","ko":"24시간 내내"},{"t":"clock in","ko":"출근 시간을 찍다"},{"t":"against the clock","ko":"시간에 쫓겨"}],"ex":{"en":"The clock on the wall is slow.","ko":"벽시계가 느려."}},{"id":119,"w":"close","def":"to move so that things cannot path through","pos":[{"p":"verb","senses":[{"ko":"닫다, 닫히다","en":"to move something so that things cannot pass through"},{"ko":"(가게가) 문을 닫다","en":"to stop being open for business"},{"ko":"끝내다, 마치다","en":"to bring something to an end"}]},{"p":"adjective","senses":[{"ko":"가까운","en":"near in distance or time"},{"ko":"친한","en":"having a strong friendship or relationship"}]}],"ph":[{"t":"close to","ko":"~에 가까운"},{"t":"That was close!","ko":"큰일 날 뻔했다!"},{"t":"close down","ko":"폐업하다, 문을 닫다"}],"ex":{"en":"Could you close the door, please?","ko":"문 좀 닫아 줄래요?"}},{"id":120,"w":"cold","def":"having a very low temperature","pos":[{"p":"adjective","senses":[{"ko":"추운, 차가운","en":"having a very low temperature"},{"ko":"쌀쌀맞은, 냉정한","en":"unfriendly, or not showing kind feelings"}]},{"p":"noun","senses":[{"ko":"감기","en":"a common illness that makes you sneeze and cough"},{"ko":"추위","en":"cold weather or a low temperature"}]}],"ph":[{"t":"catch a cold","ko":"감기에 걸리다"},{"t":"get cold feet","ko":"겁이 나서 망설이다"},{"t":"out cold","ko":"완전히 의식을 잃은"}],"ex":{"en":"It's freezing cold today.","ko":"오늘 엄청 춥다."}},{"id":121,"w":"college","def":"an school or educational institution for adults","pos":[{"p":"noun","senses":[{"ko":"대학, 전문대","en":"a school or educational institution for adults after high school"},{"ko":"단과 대학","en":"a part of a university that teaches a particular subject"}]}],"ph":[{"t":"go to college","ko":"대학에 다니다"},{"t":"college student","ko":"대학생"},{"t":"college degree","ko":"대학 학위"}],"ex":{"en":"My sister is in college now.","ko":"우리 언니 지금 대학 다녀."}},{"id":122,"w":"color","def":"a quality such as red, blue, green, etc.","pos":[{"p":"noun","senses":[{"ko":"색, 색깔","en":"the quality such as red, blue, or green that you see in things"},{"ko":"혈색, 안색","en":"the natural healthy look of a person's skin"}]},{"p":"verb","senses":[{"ko":"색칠하다","en":"to fill in a picture or shape with colors"}]}],"ph":[{"t":"What color is it?","ko":"그거 무슨 색이야?"},{"t":"in color","ko":"컬러로"},{"t":"full of color","ko":"다채로운, 화려한"}],"ex":{"en":"What's your favorite color?","ko":"제일 좋아하는 색이 뭐야?"}},{"id":123,"w":"come","def":"to move toward someone, to approach","pos":[{"p":"verb","senses":[{"ko":"오다, 다가오다","en":"to move toward the speaker or toward a particular person or place"},{"ko":"(어떤 상태가) 되다","en":"to reach a particular state or condition"},{"ko":"(물건이) 나오다, 딸려 있다","en":"to be available or sold in a particular way"}]}],"ph":[{"t":"Come on!","ko":"어서!; 에이, 왜 그래"},{"t":"come up with","ko":"(생각을) 떠올리다"},{"t":"come over","ko":"(집에) 놀러 오다"}],"ex":{"en":"Can you come here for a second?","ko":"잠깐 이리 와 볼래?"}},{"id":124,"w":"comment","def":"to discuss or write an opinion on something","pos":[{"p":"verb","senses":[{"ko":"논평하다, 의견을 말하다","en":"to say or write what you think about something"}]},{"p":"noun","senses":[{"ko":"논평, 의견","en":"something you say or write that gives your opinion"},{"ko":"댓글","en":"a short message posted under something online"}]}],"ph":[{"t":"No comment.","ko":"드릴 말씀 없습니다"},{"t":"make a comment","ko":"한마디 하다, 언급하다"},{"t":"leave a comment","ko":"댓글을 남기다"}],"ex":{"en":"He didn't comment on my new haircut.","ko":"걔는 내 새 머리에 대해 아무 말도 안 했어."}},{"id":125,"w":"committee","def":"a group of people who are chosen to make decisions about something","pos":[{"p":"noun","senses":[{"ko":"위원회","en":"a group of people chosen to make decisions or plans about something"}]}],"ph":[{"t":"on a committee","ko":"위원회 소속인"},{"t":"committee meeting","ko":"위원회 회의"}],"ex":{"en":"She's on the planning committee this year.","ko":"그녀는 올해 기획 위원회에 있어."}},{"id":126,"w":"community","def":"a group of people who share a common idea or area","pos":[{"p":"noun","senses":[{"ko":"공동체, 지역 사회","en":"a group of people who live in the same area or share interests"},{"ko":"동네 사람들, 주민","en":"the people living together in one place"}]}],"ph":[{"t":"community center","ko":"주민 센터, 문화 센터"},{"t":"the local community","ko":"지역 사회"},{"t":"online community","ko":"온라인 커뮤니티"}],"ex":{"en":"Our community is really friendly.","ko":"우리 동네 사람들은 정말 친절해."}},{"id":127,"w":"company","def":"a business that sells thing or provides services","pos":[{"p":"noun","senses":[{"ko":"회사","en":"a business that sells goods or provides services"},{"ko":"함께 있음, 동행","en":"the fact of being with someone so you are not alone"},{"ko":"손님, 일행","en":"a visitor or visitors in your home"}]}],"ph":[{"t":"keep someone company","ko":"~와 함께 있어 주다"},{"t":"have company","ko":"손님이 와 있다"},{"t":"work for a company","ko":"회사에 다니다"}],"ex":{"en":"What company do you work for?","ko":"어느 회사 다녀?"}},{"id":128,"w":"completely","def":"in every way or as much as possible","pos":[{"p":"adverb","senses":[{"ko":"완전히, 전적으로","en":"in every way or as much as possible"}]}],"ph":[{"t":"completely different","ko":"완전히 다른"},{"t":"I completely forgot.","ko":"완전히 깜빡했어"},{"t":"completely agree","ko":"전적으로 동의하다"}],"ex":{"en":"Sorry, I completely forgot about it.","ko":"미안, 완전히 까먹었어."}},{"id":129,"w":"computer","def":"an electronic machine that can store and process large amounts of information","pos":[{"p":"noun","senses":[{"ko":"컴퓨터","en":"an electronic machine that stores and processes information"}]}],"ph":[{"t":"on the computer","ko":"컴퓨터로, 컴퓨터를 하는 중"},{"t":"computer game","ko":"컴퓨터 게임"},{"t":"turn on the computer","ko":"컴퓨터를 켜다"}],"ex":{"en":"My computer keeps freezing today.","ko":"오늘 내 컴퓨터가 계속 멈춰."}},{"id":130,"w":"concern","def":"a feeling of worry or anxiety","pos":[{"p":"noun","senses":[{"ko":"걱정, 우려","en":"a feeling of worry about something or someone"},{"ko":"관심사, 중요한 일","en":"something that is important to you or that affects you"}]},{"p":"verb","senses":[{"ko":"걱정시키다","en":"to make someone feel worried"},{"ko":"~와 관련되다","en":"to be about or affect someone or something"}]}],"ph":[{"t":"not my concern","ko":"내 알 바 아니야"},{"t":"as far as I'm concerned","ko":"내 생각으로는"},{"t":"concerned about","ko":"~을 걱정하는"}],"ex":{"en":"Thanks for your concern, but I'm fine.","ko":"걱정해 줘서 고마워, 근데 난 괜찮아."}},{"id":131,"w":"consider","def":"to think about carefully","pos":[{"p":"verb","senses":[{"ko":"곰곰이 생각하다, 고려하다","en":"to think about something carefully before deciding"},{"ko":"~라고 여기다","en":"to think of someone or something in a particular way"}]}],"ph":[{"t":"consider it done","ko":"맡겨만 줘, 그렇게 할게"},{"t":"all things considered","ko":"모든 걸 고려하면"}],"ex":{"en":"I'm considering moving to Busan.","ko":"부산으로 이사 갈까 생각 중이야."}},{"id":132,"w":"contact","def":"the state or condition where two things are touching","pos":[{"p":"noun","senses":[{"ko":"접촉, 닿음","en":"the state of two people or things touching each other"},{"ko":"연락","en":"communication with someone by phone, email, or meeting"},{"ko":"연줄, 아는 사람","en":"a person you know who can help you"}]},{"p":"verb","senses":[{"ko":"연락하다","en":"to call, write, or email someone"}]}],"ph":[{"t":"keep in contact","ko":"계속 연락하다"},{"t":"eye contact","ko":"눈 맞춤"},{"t":"contact lenses","ko":"콘택트렌즈"}],"ex":{"en":"Avoid contact with your eyes.","ko":"눈에 닿지 않게 해."}},{"id":133,"w":"continue","def":"to do something without stopping","pos":[{"p":"verb","senses":[{"ko":"계속하다","en":"to keep doing something without stopping"},{"ko":"(중단 후) 다시 시작하다","en":"to start again after a pause"}]}],"ph":[{"t":"continue with","ko":"~을 계속하다"},{"t":"to be continued","ko":"다음 편에 계속"}],"ex":{"en":"Let's continue after lunch.","ko":"점심 먹고 계속하자."}},{"id":134,"w":"control","def":"to direct or influence the behavior of something or someone","pos":[{"p":"verb","senses":[{"ko":"통제하다, 조종하다","en":"to direct or influence how someone or something behaves"},{"ko":"억제하다, 참다","en":"to stop yourself from showing a strong feeling"}]},{"p":"noun","senses":[{"ko":"통제, 지배","en":"the power to make someone or something do what you want"}]}],"ph":[{"t":"out of control","ko":"통제 불능인"},{"t":"under control","ko":"잘 처리되고 있는"},{"t":"lose control","ko":"자제력을 잃다"}],"ex":{"en":"I can't control my dog in the park.","ko":"공원에선 우리 개를 감당할 수가 없어."}},{"id":135,"w":"conversation","def":"an informal talk involving two people or a small group of people","pos":[{"p":"noun","senses":[{"ko":"대화","en":"an informal talk between two people or a small group"}]}],"ph":[{"t":"have a conversation","ko":"대화를 나누다"},{"t":"make conversation","ko":"(어색함을 피하려) 말을 붙이다"},{"t":"start a conversation","ko":"말을 걸다"}],"ex":{"en":"We had a long conversation last night.","ko":"어젯밤에 우리 오래 얘기했어."}},{"id":136,"w":"cool","def":"somewhat cold : not warm or hot","pos":[{"p":"adjective","senses":[{"ko":"시원한, 서늘한","en":"a little cold in a pleasant way"},{"ko":"멋진, 괜찮은","en":"very good, fashionable, or attractive"},{"ko":"침착한, 차분한","en":"calm and not nervous or excited"}]},{"p":"verb","senses":[{"ko":"식히다, 식다","en":"to become or make something less warm"}]}],"ph":[{"t":"That's cool.","ko":"좋아, 괜찮아"},{"t":"cool down","ko":"식다; 진정하다"},{"t":"keep your cool","ko":"침착함을 유지하다"}],"ex":{"en":"It's a bit cool outside tonight.","ko":"오늘 밤 밖이 좀 쌀쌀해."}},{"id":137,"w":"copy","def":"something that is or looks exactly or almost exactly like something else","pos":[{"p":"noun","senses":[{"ko":"복사본, 사본","en":"something made to look exactly or almost exactly like another thing"},{"ko":"(책 등의) 한 부, 한 권","en":"a single book, magazine, or record of many made"}]},{"p":"verb","senses":[{"ko":"복사하다","en":"to make something that is exactly like something else"},{"ko":"베끼다, 따라 하다","en":"to do the same thing as someone else"}]}],"ph":[{"t":"make a copy","ko":"복사하다"},{"t":"copy and paste","ko":"복사해서 붙여넣다"},{"t":"Copy that.","ko":"알았다, 잘 들었다"}],"ex":{"en":"Can you make me a copy of this?","ko":"이거 한 부 복사해 줄래?"}},{"id":138,"w":"correct","def":"true or accurate; agreeing with facts","pos":[{"p":"adjective","senses":[{"ko":"맞는, 정확한","en":"true or accurate and agreeing with the facts"},{"ko":"적절한, 올바른","en":"suitable or right for a particular situation"}]},{"p":"verb","senses":[{"ko":"바로잡다, 고치다","en":"to fix a mistake or make something right"}]}],"ph":[{"t":"That's correct.","ko":"맞아요"},{"t":"Correct me if I'm wrong.","ko":"내 말이 틀리면 말해 줘"}],"ex":{"en":"Is this the correct address?","ko":"이 주소 맞아?"}},{"id":139,"w":"cost","def":"the price of something","pos":[{"p":"noun","senses":[{"ko":"비용, 가격","en":"the amount of money you need to pay for something"},{"ko":"대가, 희생","en":"something you lose or give up to get something"}]},{"p":"verb","senses":[{"ko":"(비용이) 들다","en":"to have a particular price"},{"ko":"(~을) 잃게 하다","en":"to make someone lose something"}]}],"ph":[{"t":"How much does it cost?","ko":"이거 얼마예요?"},{"t":"at all costs","ko":"무슨 수를 써서라도"},{"t":"cost a fortune","ko":"돈이 엄청 들다"}],"ex":{"en":"The cost of living here is crazy.","ko":"여기 생활비가 장난 아니야."}},{"id":140,"w":"cough","def":"to force air through your throat with a short, loud noise often because you are sick","pos":[{"p":"verb","senses":[{"ko":"기침하다","en":"to push air out of your throat suddenly with a short loud noise"}]},{"p":"noun","senses":[{"ko":"기침","en":"the act or sound of coughing, or an illness that causes it"}]}],"ph":[{"t":"have a cough","ko":"기침이 나다"},{"t":"cough up","ko":"(마지못해) 돈을 내놓다"}],"ex":{"en":"I've been coughing all night.","ko":"밤새 기침했어."}},{"id":141,"w":"could","def":"used as the past tense of can, to indicate possibility","pos":[{"p":"modal","senses":[{"ko":"~할 수 있었다","en":"used as the past form of can to talk about ability"},{"ko":"~일 수도 있다","en":"used to say that something is possible"},{"ko":"~해 주시겠어요?","en":"used to ask for something politely"},{"ko":"~해도 될까요?","en":"used to politely ask if you may do something"}]}],"ph":[{"t":"Could you ...?","ko":"~해 주실 수 있나요?"},{"t":"couldn't care less","ko":"전혀 관심 없다"},{"t":"I could use ...","ko":"~이 있으면 좋겠다"}],"ex":{"en":"It could rain later, so bring an umbrella.","ko":"이따 비 올 수도 있으니까 우산 챙겨."}},{"id":142,"w":"council","def":"a group of people who are chosen to make rules, laws, or decisions about something","pos":[{"p":"noun","senses":[{"ko":"의회, 협의회","en":"a group of people chosen to make rules or decisions for an area or group"}]}],"ph":[{"t":"city council","ko":"시의회"},{"t":"student council","ko":"학생회"}],"ex":{"en":"My sister is on the student council.","ko":"우리 언니 학생회 해."}},{"id":143,"w":"country","def":"an area, nation that is controlled by government","pos":[{"p":"noun","senses":[{"ko":"나라, 국가","en":"an area of land with its own government"},{"ko":"시골, 전원","en":"land outside cities and towns, with fields and farms"}]}],"ph":[{"t":"in the country","ko":"시골에서"},{"t":"all over the country","ko":"전국적으로"},{"t":"country music","ko":"컨트리 음악"}],"ex":{"en":"Which country are you from?","ko":"어느 나라에서 왔어요?"}},{"id":144,"w":"couple","def":"two people or things being together","pos":[{"p":"noun","senses":[{"ko":"커플, 한 쌍","en":"two people or things that are together, especially a romantic pair"},{"ko":"두어 개, 몇 개","en":"a small number of people or things, about two"}]}],"ph":[{"t":"a couple of","ko":"두어 개의, 몇몇의"},{"t":"a couple of days","ko":"이틀 정도, 며칠"},{"t":"married couple","ko":"부부"}],"ex":{"en":"They're such a cute couple.","ko":"걔네 진짜 귀여운 커플이야."}},{"id":145,"w":"course","def":"the route or direction that something moves along","pos":[{"p":"noun","senses":[{"ko":"진로, 방향","en":"the route or direction that something moves along"},{"ko":"강좌, 과목","en":"a series of lessons on a particular subject"},{"ko":"(식사의) 코스","en":"one part of a meal served at one time"}]}],"ph":[{"t":"of course","ko":"물론이지"},{"t":"in the course of","ko":"~하는 동안에"},{"t":"golf course","ko":"골프장"}],"ex":{"en":"The plane had to change course because of the storm.","ko":"폭풍 때문에 비행기가 항로를 바꿨어."}},{"id":146,"w":"cover","def":"put something over or on top of something else","pos":[{"p":"verb","senses":[{"ko":"덮다, 가리다","en":"to put something over or on top of something else"},{"ko":"다루다, 포함하다","en":"to deal with or include a subject"},{"ko":"대신 일해 주다","en":"to do someone's work while they are away"},{"ko":"(비용을) 내 주다, 대다","en":"to pay for something, often for someone else"}]},{"p":"noun","senses":[{"ko":"덮개, 표지","en":"a thing that is put over something to protect or hide it"}]}],"ph":[{"t":"cover for someone","ko":"~ 대신 일하다; 감싸 주다"},{"t":"take cover","ko":"몸을 숨기다, 대피하다"},{"t":"cover up","ko":"숨기다, 은폐하다"}],"ex":{"en":"Cover the pot so it doesn't boil over.","ko":"넘치지 않게 냄비 뚜껑 덮어."}},{"id":147,"w":"create","def":"to make, cause, or bring into existence","pos":[{"p":"verb","senses":[{"ko":"만들다, 창조하다","en":"to make or bring into existence something new"},{"ko":"일으키다, 야기하다","en":"to cause a situation or feeling to happen"}]}],"ph":[{"t":"create a problem","ko":"문제를 일으키다"},{"t":"create an account","ko":"계정을 만들다"}],"ex":{"en":"I need to create a new password.","ko":"새 비밀번호 만들어야 해."}},{"id":148,"w":"cut","def":"to use a sharp tool or object to open or divide something","pos":[{"p":"verb","senses":[{"ko":"자르다, 베다","en":"to divide or open something with a knife or sharp tool"},{"ko":"줄이다, 삭감하다","en":"to make something smaller in amount or size"},{"ko":"(머리를) 깎다","en":"to make hair or grass shorter"}]},{"p":"noun","senses":[{"ko":"베인 상처","en":"an injury where the skin has been cut"},{"ko":"삭감, 인하","en":"a reduction in amount or size"}]}],"ph":[{"t":"Cut it out!","ko":"그만해!"},{"t":"cut in line","ko":"새치기하다"},{"t":"cut down on","ko":"~을 줄이다"}],"ex":{"en":"Can you cut the cake for us?","ko":"케이크 좀 잘라 줄래?"}},{"id":149,"w":"dad","def":"father","pos":[{"p":"noun","senses":[{"ko":"아빠","en":"an informal word for a father"}]}],"ph":[{"t":"my dad","ko":"우리 아빠"},{"t":"Dad!","ko":"아빠!"}],"ex":{"en":"My dad makes the best pancakes.","ko":"우리 아빠 팬케이크 진짜 잘 만들어."}},{"id":150,"w":"date","def":"a particular day of a month or year","pos":[{"p":"noun","senses":[{"ko":"날짜","en":"a particular day of the month or year"},{"ko":"데이트, 데이트 상대","en":"a romantic meeting, or the person you meet"}]},{"p":"verb","senses":[{"ko":"사귀다, 데이트하다","en":"to have a romantic relationship with someone"}]}],"ph":[{"t":"save the date","ko":"날짜를 비워 둬"},{"t":"up to date","ko":"최신의"},{"t":"go on a date","ko":"데이트하다"}],"ex":{"en":"What's the date today?","ko":"오늘 며칠이야?"}},{"id":151,"w":"day","def":"each of the 24 hours beginning at midnight","pos":[{"p":"noun","senses":[{"ko":"하루, 날","en":"a period of 24 hours, starting at midnight"},{"ko":"낮","en":"the time between sunrise and sunset when it is light"},{"ko":"(일하는) 날, 근무일","en":"the hours of the day when you work"}]}],"ph":[{"t":"Have a nice day!","ko":"좋은 하루 보내!"},{"t":"one day","ko":"언젠가, 어느 날"},{"t":"call it a day","ko":"그만 끝내다"}],"ex":{"en":"I'm off work for two days.","ko":"나 이틀 쉬어."}},{"id":152,"w":"deal","def":"to trade or do business with someone","pos":[{"p":"verb","senses":[{"ko":"거래하다, 장사하다","en":"to buy and sell goods or do business with someone"},{"ko":"(카드를) 나눠 주다","en":"to give out playing cards to each player"}]},{"p":"noun","senses":[{"ko":"거래, 합의","en":"an agreement, especially in business"},{"ko":"싸게 산 물건","en":"something bought at a good price"}]}],"ph":[{"t":"deal with","ko":"처리하다, 다루다"},{"t":"It's a deal.","ko":"좋아, 그렇게 하자"},{"t":"big deal","ko":"큰일; 별것 아냐"}],"ex":{"en":"We only deal with local suppliers.","ko":"우리는 지역 업체하고만 거래해."}},{"id":153,"w":"dear","def":"loved or valued very much","pos":[{"p":"adjective","senses":[{"ko":"소중한, 사랑하는","en":"loved or valued very much"},{"ko":"~에게 (편지 첫머리)","en":"used before a name at the start of a letter"}]},{"p":"interjection","senses":[{"ko":"이런, 어머","en":"used to show surprise, worry, or sadness"}]}],"ph":[{"t":"Oh dear!","ko":"이런!, 어쩌나"},{"t":"my dear","ko":"얘야, 자기야"},{"t":"hold dear","ko":"소중히 여기다"}],"ex":{"en":"She's a very dear friend of mine.","ko":"걔는 나한테 정말 소중한 친구야."}},{"id":154,"w":"decide","def":"to make a choice about something or choose after thinking","pos":[{"p":"verb","senses":[{"ko":"결정하다, 정하다","en":"to make a choice about something after thinking about it"}]}],"ph":[{"t":"decide on","ko":"~으로 정하다"},{"t":"I can't decide.","ko":"못 고르겠어"},{"t":"decide to","ko":"~하기로 하다"}],"ex":{"en":"I can't decide what to order.","ko":"뭘 시킬지 못 고르겠어."}},{"id":155,"w":"decision","def":"a choice that you make about something after thinking about it","pos":[{"p":"noun","senses":[{"ko":"결정, 판단","en":"a choice you make after thinking about something"}]}],"ph":[{"t":"make a decision","ko":"결정을 내리다"},{"t":"tough decision","ko":"어려운 결정"},{"t":"final decision","ko":"최종 결정"}],"ex":{"en":"It's your decision, not mine.","ko":"그건 내가 아니라 네가 결정할 일이야."}},{"id":156,"w":"definitely","def":"without any doubt","pos":[{"p":"adverb","senses":[{"ko":"확실히, 분명히","en":"in a way that leaves no doubt at all"},{"ko":"물론이지, 당연하지","en":"used to strongly agree or say yes"}]}],"ph":[{"t":"definitely not","ko":"절대 아니야"},{"t":"I'll definitely be there.","ko":"나 꼭 갈게"}],"ex":{"en":"I'm definitely coming to your party.","ko":"네 파티 꼭 갈게."}},{"id":157,"w":"degree","def":"a unit for measuring temperature or the size of an angle","pos":[{"p":"noun","senses":[{"ko":"(온도, 각도의) 도","en":"a unit for measuring temperature or the size of an angle"},{"ko":"학위","en":"an official title a university gives when you finish a course"},{"ko":"정도, 수준","en":"the amount or level of something"}]}],"ph":[{"t":"to some degree","ko":"어느 정도는"},{"t":"college degree","ko":"대학 학위"}],"ex":{"en":"It's thirty degrees outside today.","ko":"오늘 밖이 30도야."}},{"id":158,"w":"depend","def":"to need (someone or something) for support, help, etc.","pos":[{"p":"verb","senses":[{"ko":"의지하다, 기대다","en":"to need someone or something for help or support"},{"ko":"~에 달려 있다","en":"to be decided by or change because of something else"},{"ko":"믿다, 신뢰하다","en":"to trust that someone will do what you expect"}]}],"ph":[{"t":"It depends.","ko":"상황에 따라 달라"},{"t":"depending on","ko":"~에 따라"},{"t":"You can depend on me.","ko":"나만 믿어"}],"ex":{"en":"Kids depend on their parents for everything.","ko":"애들은 모든 걸 부모한테 의지해."}},{"id":159,"w":"detail","def":"a small part of something","pos":[{"p":"noun","senses":[{"ko":"세부 사항, 디테일","en":"a small part or fact about something"}]}],"ph":[{"t":"in detail","ko":"자세히"},{"t":"go into detail","ko":"자세히 설명하다"},{"t":"attention to detail","ko":"꼼꼼함"}],"ex":{"en":"I'll text you the details later.","ko":"자세한 건 나중에 문자할게."}},{"id":160,"w":"develop","def":"to cause to grow or bigger or more advanced","pos":[{"p":"verb","senses":[{"ko":"발전시키다, 성장하다","en":"to grow or make something grow bigger or more advanced"},{"ko":"개발하다","en":"to create a new product or idea over time"},{"ko":"(병, 문제가) 생기다","en":"to start to have an illness, problem, or habit"}]}],"ph":[{"t":"develop a habit","ko":"습관이 생기다"},{"t":"develop an app","ko":"앱을 개발하다"}],"ex":{"en":"She's really developed as a player this year.","ko":"걔 올해 선수로서 정말 성장했어."}},{"id":161,"w":"development","def":"when someone or something grows or changes and becomes more advanced","pos":[{"p":"noun","senses":[{"ko":"발달, 발전","en":"the process of growing or becoming more advanced"},{"ko":"개발","en":"the work of creating new products or ideas"},{"ko":"새로운 상황, 진전","en":"a new event that changes a situation"}]}],"ph":[{"t":"child development","ko":"아동 발달"},{"t":"new development","ko":"새로운 진전, 새 소식"}],"ex":{"en":"Sleep is important for a baby's development.","ko":"잠은 아기 발달에 중요해."}},{"id":162,"w":"die","def":"to stop living or end life","pos":[{"p":"verb","senses":[{"ko":"죽다","en":"to stop being alive"},{"ko":"(기계 등이) 꺼지다, 멈추다","en":"to stop working, like a battery or engine"}]}],"ph":[{"t":"be dying to","ko":"~하고 싶어 죽겠다"},{"t":"die down","ko":"잦아들다, 약해지다"},{"t":"die of laughter","ko":"웃겨 죽다"}],"ex":{"en":"My phone just died.","ko":"방금 폰 배터리 나갔어."}},{"id":163,"w":"difference","def":"a quality that is unlike something else","pos":[{"p":"noun","senses":[{"ko":"차이, 다른 점","en":"the way in which two things are not like each other"},{"ko":"(수량의) 차이","en":"the amount by which one number is bigger than another"}]}],"ph":[{"t":"make a difference","ko":"변화를 가져오다, 영향을 주다"},{"t":"What's the difference?","ko":"뭐가 달라?"},{"t":"tell the difference","ko":"차이를 구별하다"}],"ex":{"en":"I can't tell the difference between them.","ko":"둘이 뭐가 다른지 모르겠어."}},{"id":164,"w":"different","def":"not of the same kind, unlike in nature","pos":[{"p":"adjective","senses":[{"ko":"다른, 차이가 있는","en":"not the same as another person or thing"},{"ko":"여러 가지의, 각각 다른","en":"used to talk about several separate things of one type"}]}],"ph":[{"t":"different from","ko":"~와 다른"},{"t":"something different","ko":"색다른 것"},{"t":"a different story","ko":"또 다른 얘기"}],"ex":{"en":"You look different today.","ko":"너 오늘 좀 달라 보인다."}},{"id":165,"w":"difficult","def":"not easy : requiring much work or skill to do or make","pos":[{"p":"adjective","senses":[{"ko":"어려운, 힘든","en":"not easy and needing a lot of work or skill"},{"ko":"까다로운, 다루기 힘든","en":"not friendly and hard to please or deal with"}]}],"ph":[{"t":"have a difficult time","ko":"힘든 시간을 보내다"},{"t":"make it difficult","ko":"어렵게 만들다"}],"ex":{"en":"This test is really difficult.","ko":"이 시험 진짜 어려워."}},{"id":166,"w":"dinner","def":"the main meal of the day","pos":[{"p":"noun","senses":[{"ko":"저녁 식사","en":"the main meal of the day, usually eaten in the evening"}]}],"ph":[{"t":"have dinner","ko":"저녁을 먹다"},{"t":"dinner's ready","ko":"저녁 다 됐어"},{"t":"go out for dinner","ko":"외식하다"}],"ex":{"en":"What do you want for dinner?","ko":"저녁 뭐 먹고 싶어?"}},{"id":167,"w":"discuss","def":"to talk about (something) with another person or group","pos":[{"p":"verb","senses":[{"ko":"논의하다, 이야기하다","en":"to talk about something with another person or group"}]}],"ph":[{"t":"discuss it later","ko":"나중에 얘기하다"},{"t":"Let's discuss it.","ko":"얘기 좀 해 보자"}],"ex":{"en":"We need to discuss this with your mom.","ko":"이거 너희 엄마랑 얘기해 봐야 해."}},{"id":168,"w":"discussion","def":"the act of talking about something with another person or a group of people : a conversation about something","pos":[{"p":"noun","senses":[{"ko":"논의, 토론","en":"a talk about something between two or more people"}]}],"ph":[{"t":"have a discussion","ko":"의논하다"},{"t":"under discussion","ko":"논의 중인"},{"t":"group discussion","ko":"그룹 토론"}],"ex":{"en":"We had a long discussion about money.","ko":"우리 돈 문제로 오래 얘기했어."}},{"id":169,"w":"do","def":"to perform an action or activity; to work on something","pos":[{"p":"verb","senses":[{"ko":"하다, 행하다","en":"to perform an action or activity, or to work on something"},{"ko":"(의문문, 부정문을 만듦)","en":"used with another verb to make questions and negative sentences"},{"ko":"(일, 직업으로) 하다","en":"to have something as your job or study"},{"ko":"(강조) 정말 ~하다","en":"used before a verb to give it extra emphasis, as in I do like it"}]}],"ph":[{"t":"How are you doing?","ko":"잘 지내?"},{"t":"do someone a favor","ko":"~의 부탁을 들어주다"},{"t":"That'll do.","ko":"그거면 됐어"}],"ex":{"en":"I have to do my homework first.","ko":"나 먼저 숙제해야 돼."}},{"id":170,"w":"doctor","def":"a person who skilled to treat people who are ill, sick and injured","pos":[{"p":"noun","senses":[{"ko":"의사","en":"a person trained to treat people who are sick or injured"},{"ko":"박사","en":"a person who has the highest university degree"}]}],"ph":[{"t":"see a doctor","ko":"진찰을 받다"},{"t":"go to the doctor","ko":"병원에 가다"},{"t":"doctor's appointment","ko":"병원 예약"}],"ex":{"en":"You should see a doctor about that.","ko":"그거 병원 가 봐야겠다."}},{"id":171,"w":"document","def":"an official record that gives information","pos":[{"p":"noun","senses":[{"ko":"문서, 서류","en":"an official paper or file that gives information"},{"ko":"(컴퓨터) 문서 파일","en":"a computer file that contains text"}]},{"p":"verb","senses":[{"ko":"기록하다","en":"to record details about something in writing or pictures"}]}],"ph":[{"t":"sign a document","ko":"서류에 서명하다"},{"t":"open a document","ko":"문서를 열다"}],"ex":{"en":"Please bring all your documents tomorrow.","ko":"내일 서류 전부 가져와 주세요."}},{"id":172,"w":"dog","def":"a type of animal that is often kept as a pet or trained to work for people by guarding buildings, hunting, etc.","pos":[{"p":"noun","senses":[{"ko":"개","en":"an animal often kept as a pet or trained to guard or hunt"}]}],"ph":[{"t":"walk the dog","ko":"개를 산책시키다"},{"t":"dog person","ko":"개를 좋아하는 사람"},{"t":"hot dog","ko":"핫도그"}],"ex":{"en":"I have to walk the dog.","ko":"나 개 산책시켜야 돼."}},{"id":173,"w":"dollar","def":"a basic unit of money in the U.S., Canada, Australia, and other countries that is equal to 100 cents","pos":[{"p":"noun","senses":[{"ko":"달러","en":"a unit of money in the US, Canada, and other countries, worth 100 cents"}]}],"ph":[{"t":"a few dollars","ko":"몇 달러"},{"t":"dollar store","ko":"천원숍 같은 할인 매장"},{"t":"million-dollar question","ko":"가장 중요한 질문"}],"ex":{"en":"It's only five dollars.","ko":"겨우 5달러야."}},{"id":174,"w":"door","def":"a movable entrance to a building or room","pos":[{"p":"noun","senses":[{"ko":"문","en":"a part of a building or room that opens and closes to let you in"},{"ko":"(한) 집, 건물","en":"a house or building, when counting how far away it is"}]}],"ph":[{"t":"Get the door.","ko":"문 좀 열어 줘"},{"t":"next door","ko":"옆집"},{"t":"answer the door","ko":"(누가 와서) 문을 열어 주다"}],"ex":{"en":"Can you close the door, please?","ko":"문 좀 닫아 줄래?"}},{"id":175,"w":"down","def":"going from a higher position to a lower position","pos":[{"p":"adverb","senses":[{"ko":"아래로, 밑으로","en":"from a higher place or position to a lower one"},{"ko":"(양, 수준이) 줄어서","en":"to a lower amount, level, or volume"}]},{"p":"preposition","senses":[{"ko":"~을 따라, ~ 아래로","en":"along or toward the lower part of something"}]},{"p":"adjective","senses":[{"ko":"우울한, 기운 없는","en":"sad or not feeling happy"},{"ko":"작동이 안 되는, 다운된","en":"not working for a period of time, used about computers or systems"}]}],"ph":[{"t":"sit down","ko":"앉다"},{"t":"calm down","ko":"진정하다"},{"t":"I'm down.","ko":"나 콜, 좋아"}],"ex":{"en":"Can you turn the music down a bit?","ko":"음악 소리 좀 줄여 줄래?"}},{"id":176,"w":"draw","def":"to produce by making lines on a paper","pos":[{"p":"verb","senses":[{"ko":"그리다","en":"to make a picture by making lines on paper"},{"ko":"끌다, 당기다","en":"to pull or move something somewhere"},{"ko":"(관심, 사람을) 끌다","en":"to attract people or attention"}]},{"p":"noun","senses":[{"ko":"무승부","en":"a game that ends with both sides having the same score"}]}],"ph":[{"t":"draw the line","ko":"선을 긋다, 한계를 정하다"},{"t":"draw attention","ko":"관심을 끌다"},{"t":"draw the curtains","ko":"커튼을 치다"}],"ex":{"en":"My son loves to draw animals.","ko":"우리 아들은 동물 그리는 걸 좋아해."}},{"id":177,"w":"drink","def":"to take a liquid into your mouth and swallow it","pos":[{"p":"verb","senses":[{"ko":"마시다","en":"to take liquid into your mouth and swallow it"},{"ko":"술을 마시다","en":"to drink alcohol, especially regularly"}]},{"p":"noun","senses":[{"ko":"음료, 마실 것","en":"a liquid for drinking, or an amount of it"},{"ko":"술, 한잔","en":"a drink that contains alcohol, like beer or wine"}]}],"ph":[{"t":"grab a drink","ko":"한잔하다"},{"t":"Drinks are on me.","ko":"술은 내가 살게"},{"t":"drink up","ko":"다 마시다"}],"ex":{"en":"You should drink more water.","ko":"너 물 좀 더 마셔야겠다."}},{"id":178,"w":"drive","def":"to control the movement of a car","pos":[{"p":"verb","senses":[{"ko":"운전하다","en":"to control a car or other vehicle and make it move"},{"ko":"태워다 주다","en":"to take someone somewhere in a car"},{"ko":"(어떤 상태로) 몰아가다","en":"to make someone feel a strong emotion or act a certain way"}]},{"p":"noun","senses":[{"ko":"드라이브, 차로 가는 길","en":"a trip in a car, or the time it takes"}]}],"ph":[{"t":"drive someone crazy","ko":"~를 미치게 하다"},{"t":"go for a drive","ko":"드라이브하러 가다"},{"t":"drive-thru","ko":"드라이브스루"}],"ex":{"en":"Can you drive me to the station?","ko":"역까지 태워다 줄 수 있어?"}},{"id":179,"w":"drop","def":"to let something fall","pos":[{"p":"verb","senses":[{"ko":"떨어뜨리다, 떨어지다","en":"to let something fall, or to fall"},{"ko":"(수준이) 떨어지다, 줄다","en":"to become lower in amount or level"},{"ko":"(차로) 내려 주다","en":"to take someone somewhere and leave them there"}]},{"p":"noun","senses":[{"ko":"방울","en":"a very small amount of liquid in a round shape"},{"ko":"하락, 감소","en":"a fall in amount or level"}]}],"ph":[{"t":"drop by","ko":"잠깐 들르다"},{"t":"drop off","ko":"내려 주다; 깜빡 잠들다"},{"t":"Drop it.","ko":"그 얘긴 그만해"}],"ex":{"en":"Oops, I dropped my phone again.","ko":"아이고, 또 폰 떨어뜨렸어."}},{"id":180,"w":"during","def":"throughout the entire time","pos":[{"p":"preposition","senses":[{"ko":"~ 동안 내내","en":"throughout the whole time that something happens"},{"ko":"~ 중에, ~ 동안에","en":"at some point while something else is happening"}]}],"ph":[{"t":"during the day","ko":"낮 동안에"},{"t":"during the week","ko":"주중에"}],"ex":{"en":"I fell asleep during the movie.","ko":"영화 보다가 잠들었어."}},{"id":181,"w":"each","def":"every one of two more things","pos":[{"p":"determiner","senses":[{"ko":"각각의, 각자의","en":"every one of two or more people or things, seen separately"}]},{"p":"pronoun","senses":[{"ko":"각자, 각각","en":"every single one of a group"}]},{"p":"adverb","senses":[{"ko":"하나에, 한 개당","en":"for every one, as in prices"}]}],"ph":[{"t":"each other","ko":"서로"},{"t":"each time","ko":"~할 때마다"},{"t":"each and every","ko":"하나하나 모두"}],"ex":{"en":"Each kid gets one cookie.","ko":"애들마다 쿠키 하나씩이야."}},{"id":182,"w":"early","def":"at or near the beginning of time, done before the expected time","pos":[{"p":"adjective","senses":[{"ko":"이른, 초기의","en":"near the beginning of a period of time"},{"ko":"예정보다 이른","en":"happening before the usual or expected time"}]},{"p":"adverb","senses":[{"ko":"일찍, 초기에","en":"before the usual or expected time"}]}],"ph":[{"t":"early bird","ko":"아침형 인간, 일찍 오는 사람"},{"t":"early on","ko":"초반에"},{"t":"It's too early.","ko":"너무 이르다"}],"ex":{"en":"I'm an early riser.","ko":"나 아침에 일찍 일어나는 편이야."}},{"id":183,"w":"easy","def":"not hard to do, not difficult","pos":[{"p":"adjective","senses":[{"ko":"쉬운, 수월한","en":"not difficult and needing little work or effort"},{"ko":"편안한, 느긋한","en":"relaxed and without worry or problems"}]},{"p":"adverb","senses":[{"ko":"쉽게, 살살","en":"in a relaxed or careful way, without hurrying"}]}],"ph":[{"t":"Take it easy.","ko":"진정해; 잘 지내"},{"t":"Easy does it.","ko":"천천히, 조심조심"},{"t":"easy-going","ko":"느긋한, 무던한"}],"ex":{"en":"The test was easier than I thought.","ko":"시험 생각보다 쉬웠어."}},{"id":184,"w":"eat","def":"to take food into your mouth and swallow it","pos":[{"p":"verb","senses":[{"ko":"먹다","en":"to take food into your mouth and swallow it"},{"ko":"식사하다","en":"to have a meal"}]}],"ph":[{"t":"eat out","ko":"외식하다"},{"t":"grab something to eat","ko":"뭐 좀 먹다"},{"t":"What's eating you?","ko":"무슨 걱정 있어?"}],"ex":{"en":"Have you eaten yet?","ko":"밥 먹었어?"}},{"id":185,"w":"education","def":"the process of giving or receiving instruction","pos":[{"p":"noun","senses":[{"ko":"교육","en":"the process of teaching or learning, especially at school"},{"ko":"학력, 받은 교육","en":"the knowledge and training a person gets from school"}]}],"ph":[{"t":"higher education","ko":"고등 교육, 대학 교육"},{"t":"get an education","ko":"교육을 받다"}],"ex":{"en":"Education is really expensive here.","ko":"여기는 교육비가 진짜 비싸."}},{"id":186,"w":"effect","def":"a change or results of something being done","pos":[{"p":"noun","senses":[{"ko":"영향, 효과, 결과","en":"a change that happens because of something else"},{"ko":"(영화 등의) 특수 효과","en":"sounds or images made to look or seem real"}]}],"ph":[{"t":"have an effect on","ko":"~에 영향을 주다"},{"t":"side effect","ko":"부작용"},{"t":"take effect","ko":"효과가 나타나다; 시행되다"}],"ex":{"en":"The medicine had no effect on me.","ko":"그 약 나한텐 전혀 안 들었어."}},{"id":187,"w":"effort","def":"work done by the mind or body","pos":[{"p":"noun","senses":[{"ko":"노력, 수고","en":"the physical or mental work used to do something"},{"ko":"시도","en":"an attempt to do something difficult"}]}],"ph":[{"t":"make an effort","ko":"노력하다"},{"t":"worth the effort","ko":"애쓸 만한 가치가 있는"},{"t":"put effort into","ko":"~에 공들이다"}],"ex":{"en":"Thanks for making the effort to come.","ko":"일부러 와 줘서 고마워."}},{"id":188,"w":"eight","def":"the number 8","pos":[{"p":"number","senses":[{"ko":"8, 여덟","en":"the number 8"}]}],"ph":[{"t":"eight o'clock","ko":"8시"}],"ex":{"en":"Let's meet at eight.","ko":"8시에 만나자."}},{"id":189,"w":"eighty","def":"the number 80","pos":[{"p":"number","senses":[{"ko":"80, 여든","en":"the number 80"}]}],"ph":[{"t":"in your eighties","ko":"80대인"}],"ex":{"en":"My grandma is eighty this year.","ko":"우리 할머니 올해 여든이셔."}},{"id":190,"w":"either","def":"one or the other of two","pos":[{"p":"determiner","senses":[{"ko":"(둘 중) 어느 하나의","en":"one or the other of two people or things"},{"ko":"양쪽의, 각각의","en":"both of two things"}]},{"p":"pronoun","senses":[{"ko":"(둘 중) 어느 쪽이든","en":"one or the other of two"}]},{"p":"adverb","senses":[{"ko":"(부정문에서) ~도 역시","en":"used in negative sentences to mean also"}]}],"ph":[{"t":"either way","ko":"어느 쪽이든"},{"t":"Me either.","ko":"나도 아니야"},{"t":"either ... or ...","ko":"~이거나 ~이거나"}],"ex":{"en":"You can sit in either seat.","ko":"아무 자리에나 앉아도 돼."}},{"id":191,"w":"eleven","def":"the number 11","pos":[{"p":"number","senses":[{"ko":"11, 열하나","en":"the number 11"}]}],"ph":[{"t":"eleven o'clock","ko":"11시"}],"ex":{"en":"The store opens at eleven.","ko":"가게 11시에 문 열어."}},{"id":192,"w":"else","def":"in a different or additional manner or place","pos":[{"p":"adverb","senses":[{"ko":"그 밖에, 다른","en":"in addition to or different from what was mentioned"},{"ko":"그렇지 않으면","en":"used in or else to mean otherwise"}]}],"ph":[{"t":"anything else?","ko":"더 필요한 거 있어요?"},{"t":"or else","ko":"안 그러면"},{"t":"someone else","ko":"다른 사람"}],"ex":{"en":"Do you want anything else?","ko":"다른 거 더 필요해?"}},{"id":193,"w":"end","def":"a point that marks the limit of something","pos":[{"p":"noun","senses":[{"ko":"끝, 마지막","en":"the final point or part of something"},{"ko":"끝부분, 가장자리","en":"the part that marks the limit of something"}]},{"p":"verb","senses":[{"ko":"끝나다, 끝내다","en":"to finish or make something finish"}]}],"ph":[{"t":"in the end","ko":"결국"},{"t":"at the end of the day","ko":"결국, 따지고 보면"},{"t":"end up","ko":"결국 ~하게 되다"}],"ex":{"en":"I'll see you at the end of the week.","ko":"주말쯤에 보자."}},{"id":194,"w":"enjoy","def":"to take pleasure in (something)","pos":[{"p":"verb","senses":[{"ko":"즐기다, 좋아하다","en":"to get pleasure from something"},{"ko":"(좋은 것을) 누리다","en":"to have something good, like good health"}]}],"ph":[{"t":"Enjoy!","ko":"맛있게 드세요, 즐겨"},{"t":"enjoy yourself","ko":"즐거운 시간을 보내다"},{"t":"Enjoy your meal.","ko":"맛있게 드세요"}],"ex":{"en":"Did you enjoy the movie?","ko":"영화 재밌었어?"}},{"id":195,"w":"enough","def":"equal to what is needed, as much as required","pos":[{"p":"determiner","senses":[{"ko":"충분한","en":"as much or as many as you need"}]},{"p":"adverb","senses":[{"ko":"충분히, ~할 만큼","en":"to the necessary degree or amount"}]},{"p":"pronoun","senses":[{"ko":"충분한 양","en":"as much as is needed or wanted"}]}],"ph":[{"t":"That's enough!","ko":"그만해!"},{"t":"Enough is enough.","ko":"이제 됐어, 참을 만큼 참았어"},{"t":"fair enough","ko":"그래, 일리 있네"}],"ex":{"en":"Do we have enough time?","ko":"우리 시간 충분해?"}},{"id":196,"w":"especially","def":"more than usually; very, extremely","pos":[{"p":"adverb","senses":[{"ko":"특히, 특별히","en":"more than usual or more than others"},{"ko":"특별히 ~을 위해","en":"for one particular purpose or person"}]}],"ph":[{"t":"especially for you","ko":"특별히 너를 위해"},{"t":"not especially","ko":"딱히 그렇진 않아"}],"ex":{"en":"I love fruit, especially strawberries.","ko":"과일 좋아해, 특히 딸기."}},{"id":197,"w":"even","def":"being flat, equal or smooth","pos":[{"p":"adjective","senses":[{"ko":"평평한, 고른","en":"flat, smooth, or equal in level or amount"},{"ko":"대등한, 동점인","en":"equal, with neither side ahead"},{"ko":"짝수의","en":"able to be divided by two exactly"}]},{"p":"adverb","senses":[{"ko":"심지어, ~조차","en":"used to say that something is surprising"},{"ko":"훨씬, 더욱","en":"used to make a comparison stronger"}]}],"ph":[{"t":"even if","ko":"~라 하더라도"},{"t":"even though","ko":"~인데도"},{"t":"get even","ko":"복수하다, 앙갚음하다"}],"ex":{"en":"Make sure the table is even.","ko":"테이블이 평평한지 확인해."}},{"id":198,"w":"evening","def":"the last part of the day and early part of the night","pos":[{"p":"noun","senses":[{"ko":"저녁","en":"the end of the day and the early part of the night"}]}],"ph":[{"t":"Good evening.","ko":"안녕하세요 (저녁 인사)"},{"t":"this evening","ko":"오늘 저녁"},{"t":"in the evening","ko":"저녁에"}],"ex":{"en":"What are you doing this evening?","ko":"오늘 저녁에 뭐 해?"}},{"id":199,"w":"ever","def":"at any time, at all times","pos":[{"p":"adverb","senses":[{"ko":"언제든, 한 번이라도","en":"at any time, used in questions and negatives"},{"ko":"늘, 항상","en":"at all times or always"}]}],"ph":[{"t":"Have you ever ...?","ko":"~해 본 적 있어?"},{"t":"ever since","ko":"~ 이후로 줄곧"},{"t":"best ever","ko":"역대 최고의"}],"ex":{"en":"Have you ever been to Japan?","ko":"일본 가 본 적 있어?"}},{"id":200,"w":"every","def":"including each person or thing in a group","pos":[{"p":"determiner","senses":[{"ko":"모든, 하나하나 다","en":"each person or thing in a group, without exception"},{"ko":"~마다","en":"used to say how often something happens"}]}],"ph":[{"t":"every day","ko":"매일"},{"t":"every other day","ko":"이틀에 한 번"},{"t":"every time","ko":"~할 때마다"}],"ex":{"en":"I go to the gym every morning.","ko":"나 매일 아침 헬스장 가."}},{"id":201,"w":"everybody","def":"every person; everyone","pos":[{"p":"pronoun","senses":[{"ko":"모든 사람, 모두","en":"every person in a group or place"}]}],"ph":[{"t":"Hi, everybody!","ko":"여러분, 안녕!"},{"t":"everybody else","ko":"다른 사람들 모두"}],"ex":{"en":"Everybody loves her cooking.","ko":"다들 걔 요리 좋아해."}},{"id":202,"w":"everyone","def":"every person; everybody","pos":[{"p":"pronoun","senses":[{"ko":"모든 사람, 모두","en":"all the people in a group or place"}]}],"ph":[{"t":"everyone else","ko":"다른 사람들 모두"},{"t":"Thanks, everyone.","ko":"모두 고마워요"}],"ex":{"en":"Is everyone here?","ko":"다들 왔어?"}},{"id":203,"w":"everything","def":"every thing there is or all that exists","pos":[{"p":"pronoun","senses":[{"ko":"모든 것","en":"all things, or all that exists"},{"ko":"가장 중요한 것","en":"the most important thing to someone"}]}],"ph":[{"t":"Is everything okay?","ko":"괜찮아?, 별일 없어?"},{"t":"everything's fine","ko":"다 괜찮아"},{"t":"mean everything","ko":"전부나 다름없다"}],"ex":{"en":"Thanks for everything.","ko":"여러모로 고마워."}},{"id":204,"w":"exactly","def":"completely correct","pos":[{"p":"adverb","senses":[{"ko":"정확히, 꼭","en":"in a completely correct way, with no difference"},{"ko":"바로 그거야","en":"used to agree completely with someone"}]}],"ph":[{"t":"Exactly!","ko":"바로 그거야!"},{"t":"not exactly","ko":"꼭 그렇진 않아"},{"t":"exactly the same","ko":"완전히 똑같은"}],"ex":{"en":"That's exactly what I meant.","ko":"내 말이 바로 그거야."}},{"id":205,"w":"example","def":"a thing which is seen as a model","pos":[{"p":"noun","senses":[{"ko":"모범, 본보기","en":"a person or thing seen as a good model to copy"},{"ko":"예, 사례","en":"something that shows what other things of the same kind are like"}]}],"ph":[{"t":"for example","ko":"예를 들어"},{"t":"set an example","ko":"모범을 보이다"},{"t":"give an example","ko":"예를 들다"}],"ex":{"en":"You should set a good example for your brother.","ko":"네가 동생한테 좋은 본보기가 돼야지."}},{"id":206,"w":"expect","def":"to be regarded as likely to happen","pos":[{"p":"verb","senses":[{"ko":"예상하다, 기대하다","en":"to think that something is likely to happen"},{"ko":"(당연히) 바라다, 요구하다","en":"to think someone should do something"}]}],"ph":[{"t":"I expect so.","ko":"아마 그럴 거야"},{"t":"be expecting","ko":"임신 중이다"},{"t":"as expected","ko":"예상대로"}],"ex":{"en":"I didn't expect to see you here.","ko":"여기서 너 볼 줄은 몰랐어."}},{"id":207,"w":"experience","def":"the act of having things happen to you","pos":[{"p":"noun","senses":[{"ko":"경험, 체험","en":"something that happens to you, or knowledge you get from doing things"}]},{"p":"verb","senses":[{"ko":"경험하다, 겪다","en":"to have something happen to you or feel something"}]}],"ph":[{"t":"work experience","ko":"경력, 실무 경험"},{"t":"from experience","ko":"경험상"},{"t":"learning experience","ko":"배움이 된 경험"}],"ex":{"en":"It was an amazing experience.","ko":"정말 멋진 경험이었어."}},{"id":208,"w":"explain","def":"to make clear or easy to understand by describing","pos":[{"p":"verb","senses":[{"ko":"설명하다","en":"to make something clear or easy to understand by describing it"},{"ko":"해명하다, 이유를 대다","en":"to give a reason for something"}]}],"ph":[{"t":"Let me explain.","ko":"내가 설명할게"},{"t":"explain yourself","ko":"어떻게 된 건지 말해 봐"}],"ex":{"en":"Can you explain that again?","ko":"그거 다시 설명해 줄래?"}},{"id":209,"w":"extra","def":"more than is usual or necessary : additional","pos":[{"p":"adjective","senses":[{"ko":"추가의, 여분의","en":"more than is usual or needed"},{"ko":"(좀) 오버하는, 과한","en":"acting in a dramatic way, used informally"}]},{"p":"adverb","senses":[{"ko":"특별히, 더","en":"more than usual or more than expected"}]},{"p":"noun","senses":[{"ko":"추가 요금, 추가분","en":"something added that costs more"}]}],"ph":[{"t":"go the extra mile","ko":"한층 더 노력하다"},{"t":"extra cheese","ko":"치즈 추가"},{"t":"at no extra cost","ko":"추가 비용 없이"}],"ex":{"en":"Do you have an extra pen?","ko":"펜 하나 남는 거 있어?"}},{"id":210,"w":"eye","def":"the part of the body that you see with","pos":[{"p":"noun","senses":[{"ko":"눈","en":"one of the two parts of the face that you see with"},{"ko":"보는 눈, 안목","en":"the ability to notice or judge things well"}]}],"ph":[{"t":"keep an eye on","ko":"~을 지켜보다, 봐 주다"},{"t":"catch someone's eye","ko":"~의 눈길을 끌다"},{"t":"see eye to eye","ko":"의견이 일치하다"}],"ex":{"en":"Close your eyes for a second.","ko":"잠깐 눈 감아 봐."}},{"id":211,"w":"face","def":"the front part of a person's head, the surface of a thing","pos":[{"p":"noun","senses":[{"ko":"얼굴","en":"the front part of the head, with the eyes, nose, and mouth"},{"ko":"표면, 면","en":"the front or main surface of something"},{"ko":"표정","en":"a look on someone's face that shows a feeling"}]},{"p":"verb","senses":[{"ko":"마주하다, 향하다","en":"to look toward or be in front of something"},{"ko":"직면하다, 맞서다","en":"to deal with a difficult situation or person"}]}],"ph":[{"t":"make a face","ko":"얼굴을 찡그리다"},{"t":"Let's face it.","ko":"현실을 인정하자"},{"t":"face to face","ko":"얼굴을 맞대고"}],"ex":{"en":"Go wash your face.","ko":"가서 세수해."}},{"id":212,"w":"fact","def":"something that is known or proved to be true","pos":[{"p":"noun","senses":[{"ko":"사실","en":"something that is known or proven to be true"}]}],"ph":[{"t":"in fact","ko":"사실은, 실제로"},{"t":"the fact is","ko":"사실은 말이야"},{"t":"as a matter of fact","ko":"실은"}],"ex":{"en":"It's a fact that I'm always late.","ko":"내가 맨날 늦는 건 사실이야."}},{"id":213,"w":"fair","def":"agreeing with what is thought to be right or acceptable","pos":[{"p":"adjective","senses":[{"ko":"공정한, 공평한","en":"treating people equally in a way that is right"},{"ko":"꽤 괜찮은, 상당한","en":"fairly large or good, but not very"}]},{"p":"noun","senses":[{"ko":"박람회, 장터","en":"an event where people show or sell things"}]}],"ph":[{"t":"That's not fair!","ko":"불공평해!"},{"t":"fair enough","ko":"그래, 일리 있네"},{"t":"to be fair","ko":"공정하게 말하자면"}],"ex":{"en":"It's not fair that he gets more.","ko":"걔만 더 받는 건 불공평해."}},{"id":214,"w":"fairly","def":"more than average, but less than very; something done in a fair way","pos":[{"p":"adverb","senses":[{"ko":"꽤, 상당히","en":"more than average but less than very"},{"ko":"공정하게","en":"in a fair or honest way"}]}],"ph":[{"t":"fairly good","ko":"꽤 괜찮은"},{"t":"fairly sure","ko":"꽤 확신하는"},{"t":"treat fairly","ko":"공평하게 대하다"}],"ex":{"en":"I'm fairly sure he's coming.","ko":"걔 올 거라고 꽤 확신해."}},{"id":215,"w":"fall","def":"to come or go down from a higher to a lower place","pos":[{"p":"verb","senses":[{"ko":"떨어지다, 넘어지다","en":"to come or go down from a higher to a lower place"},{"ko":"(수량이) 줄다, 떨어지다","en":"to become lower in amount or level"},{"ko":"(어떤 상태가) 되다","en":"to change into a new state"}]},{"p":"noun","senses":[{"ko":"가을","en":"the season between summer and winter, used in American English"},{"ko":"넘어짐, 추락","en":"an act of falling down"}]}],"ph":[{"t":"fall asleep","ko":"잠들다"},{"t":"fall in love","ko":"사랑에 빠지다"},{"t":"fall apart","ko":"무너지다, 망가지다"}],"ex":{"en":"Be careful not to fall.","ko":"넘어지지 않게 조심해."}},{"id":216,"w":"family","def":"a group of people who are related to each other","pos":[{"p":"noun","senses":[{"ko":"가족, 가정","en":"a group of people who are related to each other"},{"ko":"자녀, 아이들","en":"the children of a parent"}]}],"ph":[{"t":"start a family","ko":"아이를 갖다"},{"t":"run in the family","ko":"집안 내력이다"},{"t":"family friend","ko":"집안끼리 아는 사람"}],"ex":{"en":"I'm visiting my family this weekend.","ko":"이번 주말에 가족 보러 가."}},{"id":217,"w":"far","def":"to a great distance in space or time","pos":[{"p":"adverb","senses":[{"ko":"멀리, 먼","en":"to or at a great distance in space or time"},{"ko":"훨씬, 크게","en":"very much, used to make a comparison stronger"}]},{"p":"adjective","senses":[{"ko":"먼, 멀리 있는","en":"a long way away"}]}],"ph":[{"t":"so far","ko":"지금까지"},{"t":"How far is it?","ko":"얼마나 멀어?"},{"t":"far from it","ko":"전혀 그렇지 않아"}],"ex":{"en":"Is the hotel far from here?","ko":"호텔 여기서 멀어?"}},{"id":218,"w":"father","def":"a male parent","pos":[{"p":"noun","senses":[{"ko":"아버지","en":"a male parent of a child"},{"ko":"신부님","en":"a title for a Catholic priest"}]}],"ph":[{"t":"father-in-law","ko":"시아버지, 장인"},{"t":"Father's Day","ko":"아버지의 날"}],"ex":{"en":"My father works in a bank.","ko":"우리 아버지는 은행에서 일하셔."}},{"id":219,"w":"feel","def":"to be aware of or experience an emotion or sensation","pos":[{"p":"verb","senses":[{"ko":"느끼다","en":"to experience an emotion or a physical sensation"},{"ko":"(만져서) 느끼다, 만져 보다","en":"to touch something to learn what it is like"},{"ko":"~라고 생각하다","en":"to have a particular opinion"}]}],"ph":[{"t":"feel like","ko":"~하고 싶다"},{"t":"feel free to","ko":"얼마든지 ~해도 돼"},{"t":"I feel you.","ko":"무슨 말인지 알아"}],"ex":{"en":"I feel so tired today.","ko":"오늘 너무 피곤해."}},{"id":220,"w":"few","def":"not many, a small number","pos":[{"p":"determiner","senses":[{"ko":"거의 없는, 많지 않은","en":"not many, only a small number"},{"ko":"(a few) 몇몇의, 조금","en":"a small number of, but some"}]},{"p":"pronoun","senses":[{"ko":"소수, 몇 명","en":"a small number of people or things"}]}],"ph":[{"t":"a few","ko":"몇몇의, 조금"},{"t":"quite a few","ko":"꽤 많은"},{"t":"every few days","ko":"며칠마다"}],"ex":{"en":"Very few people came to the party.","ko":"파티에 온 사람이 거의 없었어."}},{"id":221,"w":"fifteen","def":"the number 15","pos":[{"p":"number","senses":[{"ko":"15, 열다섯","en":"the number 15"}]}],"ph":[{"t":"fifteen minutes","ko":"15분"}],"ex":{"en":"The bus comes in fifteen minutes.","ko":"버스 15분 뒤에 와."}},{"id":222,"w":"fifty","def":"the number 50","pos":[{"p":"number","senses":[{"ko":"50, 쉰","en":"the number 50"}]}],"ph":[{"t":"fifty-fifty","ko":"반반으로; 반반의 확률"}],"ex":{"en":"I paid fifty bucks for these shoes.","ko":"이 신발 50달러 줬어."}},{"id":223,"w":"figure","def":"a an amount that is expressed in numbers","pos":[{"p":"noun","senses":[{"ko":"수치, 숫자","en":"an amount expressed in numbers"},{"ko":"인물, 사람","en":"a person, especially an important or well-known one"},{"ko":"몸매, 체형","en":"the shape of a person's body"}]},{"p":"verb","senses":[{"ko":"생각하다, 판단하다","en":"to think or decide something is likely"}]}],"ph":[{"t":"figure out","ko":"알아내다, 이해하다"},{"t":"Go figure.","ko":"이해가 안 가네, 별일이야"},{"t":"That figures.","ko":"그럴 줄 알았어"}],"ex":{"en":"The sales figures look good this month.","ko":"이번 달 매출 수치 좋아 보여."}},{"id":224,"w":"fill","def":"to make something full or to spread through","pos":[{"p":"verb","senses":[{"ko":"채우다, 가득 차다","en":"to make something full, or to become full"},{"ko":"(공간에) 퍼지다","en":"to spread through a space"}]}],"ph":[{"t":"fill out","ko":"(서류를) 작성하다"},{"t":"fill in for","ko":"~ 대신 일하다"},{"t":"fill up","ko":"가득 채우다; 배부르다"}],"ex":{"en":"Can you fill this bottle with water?","ko":"이 병에 물 좀 채워 줄래?"}},{"id":225,"w":"find","def":"to discover something","pos":[{"p":"verb","senses":[{"ko":"찾다, 발견하다","en":"to discover or get something by looking for it"},{"ko":"(~라고) 생각하다, 느끼다","en":"to have a particular feeling or opinion about something"}]}],"ph":[{"t":"find out","ko":"알아내다"},{"t":"find it hard to","ko":"~하기 어렵다고 느끼다"}],"ex":{"en":"I can't find my keys anywhere.","ko":"열쇠가 아무 데도 없어."}},{"id":226,"w":"fine","def":"good, acceptable, or satisfactory","pos":[{"p":"adjective","senses":[{"ko":"괜찮은, 좋은","en":"good, acceptable, or satisfactory"},{"ko":"건강한, 잘 지내는","en":"in good health and feeling well"},{"ko":"가는, 고운","en":"very thin or made of very small pieces"}]},{"p":"noun","senses":[{"ko":"벌금","en":"money you must pay as a punishment"}]},{"p":"adverb","senses":[{"ko":"잘, 괜찮게","en":"in a way that is good enough or without problems"}]},{"p":"verb","senses":[{"ko":"벌금을 물리다","en":"to make someone pay money as a punishment"}]}],"ph":[{"t":"I'm fine.","ko":"난 괜찮아"},{"t":"That's fine.","ko":"그거 괜찮아"},{"t":"fine with me","ko":"난 상관없어"}],"ex":{"en":"Don't worry, everything's fine.","ko":"걱정 마, 다 괜찮아."}},{"id":227,"w":"finish","def":"to reach the end of (something) : to stop doing (something) because it is completed","pos":[{"p":"verb","senses":[{"ko":"끝내다, 마치다","en":"to complete something or stop doing it because it is done"},{"ko":"다 먹다, 다 쓰다","en":"to eat, drink, or use all of something"}]},{"p":"noun","senses":[{"ko":"끝, 결승점","en":"the end or last part of something, like a race"}]}],"ph":[{"t":"finish up","ko":"마무리하다"},{"t":"finish off","ko":"다 먹어 치우다"},{"t":"finish line","ko":"결승선"}],"ex":{"en":"Let me finish my coffee first.","ko":"커피 좀 다 마시고 갈게."}},{"id":228,"w":"fire","def":"the light, heat and the flame produced by burning something","pos":[{"p":"noun","senses":[{"ko":"불, 화재","en":"the heat, light, and flames made when something burns"}]},{"p":"verb","senses":[{"ko":"해고하다","en":"to make someone leave their job"},{"ko":"(총을) 쏘다, 발사하다","en":"to shoot a gun or other weapon"}]}],"ph":[{"t":"on fire","ko":"불이 난; 잘나가는"},{"t":"catch fire","ko":"불이 붙다"},{"t":"You're fired!","ko":"넌 해고야!"}],"ex":{"en":"Call 119, there's a fire!","ko":"119 불러, 불났어!"}},{"id":229,"w":"first","def":"coming before all others in time or place","pos":[{"p":"adjective","senses":[{"ko":"첫 번째의, 최초의","en":"coming before all others in time, order, or place"},{"ko":"가장 중요한, 으뜸의","en":"most important or best"}]},{"p":"adverb","senses":[{"ko":"먼저, 우선","en":"before anything or anyone else"},{"ko":"처음으로","en":"for the first time"}]}],"ph":[{"t":"at first","ko":"처음에는"},{"t":"first of all","ko":"우선, 무엇보다도"},{"t":"first thing","ko":"맨 먼저, 일어나자마자"}],"ex":{"en":"Is this your first time in Seoul?","ko":"서울은 처음이야?"}},{"id":230,"w":"fit","def":"proper or acceptable : morally or socially correct","pos":[{"p":"adjective","senses":[{"ko":"적합한, 알맞은","en":"suitable or good enough for a purpose or situation"},{"ko":"건강한, 탄탄한","en":"healthy and strong, especially from exercise"}]},{"p":"verb","senses":[{"ko":"(크기가) 맞다","en":"to be the right size or shape for someone or something"},{"ko":"들어가다, 맞추어 넣다","en":"to have enough space for something"}]},{"p":"noun","senses":[{"ko":"(옷의) 맞음새, 핏","en":"the way clothes fit your body"}]}],"ph":[{"t":"fit in","ko":"어울리다, 적응하다"},{"t":"keep fit","ko":"건강을 유지하다"},{"t":"see fit","ko":"적절하다고 여기다"}],"ex":{"en":"This movie isn't fit for kids.","ko":"이 영화는 애들 보기엔 안 맞아."}},{"id":231,"w":"five","def":"the number 5","pos":[{"p":"number","senses":[{"ko":"5, 다섯","en":"the number 5"}]}],"ph":[{"t":"high five","ko":"하이파이브"},{"t":"take five","ko":"잠깐 쉬다"}],"ex":{"en":"Give me five minutes.","ko":"5분만 줘."}},{"id":232,"w":"floor","def":"the part of a room on which you stand","pos":[{"p":"noun","senses":[{"ko":"바닥, 마루","en":"the flat surface of a room that you walk on"},{"ko":"(건물의) 층","en":"a level in a building"}]}],"ph":[{"t":"on the floor","ko":"바닥에"},{"t":"ground floor","ko":"1층"},{"t":"the floor is yours","ko":"말씀하세요"}],"ex":{"en":"Don't leave your clothes on the floor.","ko":"옷 바닥에 두지 마."}},{"id":233,"w":"focus","def":"the main purpose or center of interest or activity","pos":[{"p":"noun","senses":[{"ko":"초점, 중심","en":"the main purpose or center of interest or activity"},{"ko":"(사진의) 초점","en":"the point where an image looks clear and sharp"}]},{"p":"verb","senses":[{"ko":"집중하다","en":"to give all your attention to one thing"}]}],"ph":[{"t":"focus on","ko":"~에 집중하다"},{"t":"out of focus","ko":"초점이 안 맞는"},{"t":"lose focus","ko":"집중력을 잃다"}],"ex":{"en":"The main focus today is the budget.","ko":"오늘의 핵심은 예산이야."}},{"id":234,"w":"follow","def":"to come after, to move or travel behind","pos":[{"p":"verb","senses":[{"ko":"따라가다, 뒤따르다","en":"to come or go after someone or something"},{"ko":"(지시를) 따르다","en":"to do what someone tells you or what rules say"},{"ko":"이해하다, 따라가다","en":"to understand what someone is saying"},{"ko":"(SNS에서) 팔로우하다","en":"to choose to see someone's posts on social media"}]}],"ph":[{"t":"follow up","ko":"후속 조치를 하다"},{"t":"I don't follow.","ko":"무슨 말인지 모르겠어"},{"t":"follow me","ko":"날 따라와"}],"ex":{"en":"Just follow me, I know the way.","ko":"그냥 나 따라와, 길 알아."}},{"id":235,"w":"food","def":"the things that people and animals eat","pos":[{"p":"noun","senses":[{"ko":"음식, 먹을 것","en":"the things that people and animals eat"}]}],"ph":[{"t":"fast food","ko":"패스트푸드"},{"t":"food poisoning","ko":"식중독"},{"t":"food for thought","ko":"생각해 볼 거리"}],"ex":{"en":"The food here is amazing.","ko":"여기 음식 진짜 맛있어."}},{"id":236,"w":"foot","def":"the part of the leg below ankle","pos":[{"p":"noun","senses":[{"ko":"발","en":"the part of the body at the end of the leg, below the ankle"},{"ko":"피트 (길이 단위)","en":"a unit for measuring length, equal to 12 inches"},{"ko":"(산, 계단의) 아랫부분","en":"the bottom or lowest part of something"}]}],"ph":[{"t":"on foot","ko":"걸어서"},{"t":"put your foot down","ko":"단호하게 나서다"},{"t":"get cold feet","ko":"겁이 나다, 망설이다"}],"ex":{"en":"My foot really hurts.","ko":"발이 너무 아파."}},{"id":237,"w":"for","def":"indicating the purpose or need of something","pos":[{"p":"preposition","senses":[{"ko":"~을 위해, ~용으로","en":"used to show the purpose or need of something"},{"ko":"~ 동안","en":"used to show how long something lasts"},{"ko":"~에게 주려고","en":"intended to be given to someone"},{"ko":"~ 때문에, ~에 대해","en":"because of or in return for something, as in thanks for"},{"ko":"~치고는","en":"considering what is usual for a type of person or thing"}]}],"ph":[{"t":"for now","ko":"당분간, 일단은"},{"t":"for sure","ko":"확실히"},{"t":"What for?","ko":"뭐 때문에?"}],"ex":{"en":"This knife is for cutting bread.","ko":"이 칼은 빵 자르는 용이야."}},{"id":238,"w":"force","def":"to use physical strength, power, or energy used on something","pos":[{"p":"verb","senses":[{"ko":"(힘으로) 밀다, 억지로 하다","en":"to use physical strength or power to make something move or open"},{"ko":"강요하다, 억지로 ~하게 하다","en":"to make someone do something they do not want to do"}]},{"p":"noun","senses":[{"ko":"힘, 물리력","en":"physical strength, power, or energy"},{"ko":"(군대 등의) 부대","en":"a group of people such as soldiers or police"}]}],"ph":[{"t":"force yourself","ko":"억지로 하다"},{"t":"join forces","ko":"힘을 합치다"},{"t":"by force","ko":"강제로"}],"ex":{"en":"We had to force the door open.","ko":"우리 문을 억지로 열어야 했어."}},{"id":239,"w":"forget","def":"to be unable to think of or remember (something)","pos":[{"p":"verb","senses":[{"ko":"잊다, 기억하지 못하다","en":"to be unable to remember something"},{"ko":"깜빡하다, 두고 오다","en":"to fail to do or bring something"}]}],"ph":[{"t":"Forget it.","ko":"됐어, 신경 쓰지 마"},{"t":"Don't forget to ...","ko":"~하는 거 잊지 마"},{"t":"forget about it","ko":"잊어버려"}],"ex":{"en":"I forgot her name again.","ko":"또 걔 이름 까먹었어."}},{"id":240,"w":"form","def":"a type or kind of something, the visible shape, style","pos":[{"p":"noun","senses":[{"ko":"종류, 형태","en":"a type or kind of something, or its shape"},{"ko":"서식, 양식","en":"a paper with spaces where you write information"}]},{"p":"verb","senses":[{"ko":"형성하다, 만들다","en":"to make something or come into existence"}]}],"ph":[{"t":"fill out a form","ko":"양식을 작성하다"},{"t":"in the form of","ko":"~의 형태로"},{"t":"in good form","ko":"컨디션이 좋은"}],"ex":{"en":"Walking is a great form of exercise.","ko":"걷기는 아주 좋은 운동이야."}},{"id":241,"w":"forty","def":"the number 40","pos":[{"p":"number","senses":[{"ko":"40, 마흔","en":"the number 40"}]}],"ph":[{"t":"in your forties","ko":"40대인"}],"ex":{"en":"My dad just turned forty.","ko":"우리 아빠 이제 막 마흔 되셨어."}},{"id":242,"w":"forward","def":"toward the front : to or toward what is ahead or in front","pos":[{"p":"adverb","senses":[{"ko":"앞으로","en":"toward the front or toward what is ahead"},{"ko":"(미래로) 앞으로, 장래에","en":"toward the future or a later time"}]},{"p":"verb","senses":[{"ko":"(메일 등을) 전달하다","en":"to send an email or letter on to another person"}]}],"ph":[{"t":"look forward to","ko":"~을 기대하다, 고대하다"},{"t":"move forward","ko":"앞으로 나아가다"},{"t":"fast-forward","ko":"빨리 감기"}],"ex":{"en":"Take one step forward.","ko":"한 발짝 앞으로 나와."}},{"id":243,"w":"four","def":"the number 4","pos":[{"p":"number","senses":[{"ko":"4, 넷","en":"the number 4, one more than three"}]}],"ph":[{"t":"on all fours","ko":"네 발로 기어서"}],"ex":{"en":"We need a table for four, please.","ko":"네 명 자리 부탁해요."}},{"id":244,"w":"free","def":"without control by others","pos":[{"p":"adjective","senses":[{"ko":"자유로운","en":"able to do what you want without being controlled by others"},{"ko":"무료의, 공짜인","en":"costing nothing, so you do not have to pay"},{"ko":"한가한, 시간이 있는","en":"not busy and available to do something"}]},{"p":"verb","senses":[{"ko":"풀어주다, 해방하다","en":"to let someone or something go from a place or control"}]}],"ph":[{"t":"feel free to","ko":"마음껏 ~하세요"},{"t":"for free","ko":"공짜로"},{"t":"free time","ko":"여가 시간"}],"ex":{"en":"You're free to leave whenever you want.","ko":"원할 때 언제든 가도 돼."}},{"id":245,"w":"friend","def":"a person who you like and enjoy being with","pos":[{"p":"noun","senses":[{"ko":"친구","en":"a person you like and enjoy spending time with"},{"ko":"지지자, 편","en":"someone who supports or helps a person or cause"}]}],"ph":[{"t":"make friends","ko":"친구를 사귀다"},{"t":"best friend","ko":"가장 친한 친구"},{"t":"just friends","ko":"그냥 친구 사이"}],"ex":{"en":"She's my best friend from high school.","ko":"걔는 고등학교 때부터 제일 친한 친구야."}},{"id":246,"w":"from","def":"indicating the starting point of motion or action","pos":[{"p":"preposition","senses":[{"ko":"~에서, ~부터","en":"used to show where a movement or action starts"},{"ko":"~ 출신의","en":"used to show where someone was born or lives"},{"ko":"~에게서, ~로부터","en":"used to show who sent or gave something"}]}],"ph":[{"t":"Where are you from?","ko":"어디 출신이에요?"},{"t":"from now on","ko":"지금부터, 앞으로"},{"t":"from time to time","ko":"가끔, 때때로"}],"ex":{"en":"I just got back from work.","ko":"방금 퇴근하고 왔어."}},{"id":247,"w":"front","def":"the forward part of an object","pos":[{"p":"noun","senses":[{"ko":"앞, 앞면, 앞부분","en":"the part of something that faces forward or is seen first"},{"ko":"겉모습, 위장","en":"a way of behaving that hides your real feelings"}]},{"p":"adjective","senses":[{"ko":"앞쪽의, 정면의","en":"at or in the front of something"}]}],"ph":[{"t":"in front of","ko":"~ 앞에"},{"t":"front door","ko":"현관문"},{"t":"up front","ko":"미리, 선불로; 솔직하게"}],"ex":{"en":"I'll wait for you in front of the station.","ko":"역 앞에서 기다릴게."}},{"id":248,"w":"full","def":"containing or holding as much as possible","pos":[{"p":"adjective","senses":[{"ko":"가득 찬","en":"holding as much or as many as possible"},{"ko":"배부른","en":"having eaten so much that you cannot eat more"},{"ko":"완전한, 전체의","en":"complete, with nothing missing"}]}],"ph":[{"t":"I'm full.","ko":"배불러"},{"t":"full-time","ko":"정규직의, 전일제의"},{"t":"in full","ko":"전부, 전액"}],"ex":{"en":"The bus was full, so I walked.","ko":"버스가 꽉 차서 걸어왔어."}},{"id":249,"w":"fun","def":"someone or something that is amusing or enjoyable","pos":[{"p":"noun","senses":[{"ko":"재미, 즐거움","en":"enjoyment, or something or someone that is enjoyable"}]},{"p":"adjective","senses":[{"ko":"재미있는, 즐거운","en":"enjoyable, amusing, or pleasant to do"}]}],"ph":[{"t":"Have fun!","ko":"재밌게 놀아!"},{"t":"make fun of","ko":"~를 놀리다"},{"t":"just for fun","ko":"그냥 재미로"}],"ex":{"en":"The party was really fun last night.","ko":"어젯밤 파티 진짜 재밌었어."}},{"id":250,"w":"fund","def":"a sum of money that is used for a special purpose","pos":[{"p":"noun","senses":[{"ko":"기금, 자금","en":"an amount of money saved or collected for a special purpose"},{"ko":"(복수) 돈, 재원","en":"money that is available to spend"}]},{"p":"verb","senses":[{"ko":"자금을 대다","en":"to provide money for something"}]}],"ph":[{"t":"raise funds","ko":"기금을 모으다"},{"t":"short of funds","ko":"돈이 부족한"}],"ex":{"en":"We started a fund for her surgery.","ko":"그녀 수술비 모금을 시작했어."}},{"id":251,"w":"funny","def":"causing laughter","pos":[{"p":"adjective","senses":[{"ko":"웃기는, 재미있는","en":"making you laugh or smile"},{"ko":"이상한, 묘한","en":"strange or surprising in a way that is hard to explain"}]}],"ph":[{"t":"That's funny.","ko":"웃기네; 이상하네"},{"t":"funny feeling","ko":"묘한 느낌, 예감"},{"t":"Very funny.","ko":"하나도 안 웃기거든"}],"ex":{"en":"He's so funny, he always makes me laugh.","ko":"걔 진짜 웃겨, 맨날 나 웃게 해."}},{"id":252,"w":"further","def":"at a more distant place than here","pos":[{"p":"adverb","senses":[{"ko":"더 멀리","en":"at or to a greater distance"},{"ko":"더, 더 나아가","en":"to a greater degree or extent"}]},{"p":"adjective","senses":[{"ko":"추가의, 그 이상의","en":"more, or added to what already exists"}]}],"ph":[{"t":"until further notice","ko":"추후 공지가 있을 때까지"},{"t":"go further","ko":"더 나아가다"},{"t":"further information","ko":"추가 정보"}],"ex":{"en":"The station is a little further down the road.","ko":"역은 이 길로 조금 더 가면 있어."}},{"id":253,"w":"future","def":"the period of time coming after the present","pos":[{"p":"noun","senses":[{"ko":"미래, 장래","en":"the time that will come after now"},{"ko":"앞날, 전망","en":"what will happen to someone or something later"}]},{"p":"adjective","senses":[{"ko":"미래의, 장래의","en":"happening or existing at a later time"}]}],"ph":[{"t":"in the future","ko":"미래에, 앞으로"},{"t":"in the near future","ko":"가까운 미래에"},{"t":"for future reference","ko":"나중을 위해 참고로"}],"ex":{"en":"What do you want to do in the future?","ko":"앞으로 뭐 하고 싶어?"}},{"id":254,"w":"game","def":"one of the games that are part of a larger contest","pos":[{"p":"noun","senses":[{"ko":"경기, 시합","en":"a single match played as part of a larger competition"},{"ko":"게임, 놀이","en":"an activity or sport played for fun, with rules"}]},{"p":"adjective","senses":[{"ko":"기꺼이 하는","en":"willing to try something new or risky"}]}],"ph":[{"t":"I'm game.","ko":"난 좋아, 해볼래"},{"t":"game over","ko":"끝났다, 다 틀렸다"},{"t":"play games","ko":"장난치다, 속이다"}],"ex":{"en":"Did you watch the game last night?","ko":"어젯밤 경기 봤어?"}},{"id":255,"w":"general","def":"widespread, normal or usual","pos":[{"p":"adjective","senses":[{"ko":"일반적인, 보통의","en":"common, normal, or true for most people or things"},{"ko":"대략적인, 전반적인","en":"not detailed, giving only the main points"}]},{"p":"noun","senses":[{"ko":"장군","en":"a military officer of very high rank"}]}],"ph":[{"t":"in general","ko":"일반적으로, 대체로"},{"t":"general idea","ko":"대략적인 생각"}],"ex":{"en":"In general, people here are really friendly.","ko":"대체로 여기 사람들 진짜 친절해."}},{"id":256,"w":"get","def":"to obtain, receive or be given something","pos":[{"p":"verb","senses":[{"ko":"얻다, 받다","en":"to obtain, receive, or be given something"},{"ko":"~이 되다","en":"to change into a certain state"},{"ko":"이해하다","en":"to understand what someone means"},{"ko":"도착하다, 가다","en":"to arrive at or reach a place"},{"ko":"사 주다, 가져다주다","en":"to buy or bring something for yourself or someone else"}]}],"ph":[{"t":"get it","ko":"알겠다, 이해하다"},{"t":"get up","ko":"일어나다"},{"t":"get along","ko":"사이좋게 지내다"}],"ex":{"en":"I got a text from her.","ko":"걔한테서 문자 받았어."}},{"id":257,"w":"girl","def":"a female child, a young woman","pos":[{"p":"noun","senses":[{"ko":"소녀, 여자아이","en":"a female child or a young woman"},{"ko":"딸","en":"used to mean a person's daughter"},{"ko":"여자 친구들, 여자","en":"used informally for women, especially a group of friends"}]}],"ph":[{"t":"girls' night out","ko":"여자들끼리 노는 밤"},{"t":"baby girl","ko":"여자 아기; 우리 딸"},{"t":"girlfriend","ko":"여자 친구"}],"ex":{"en":"Their little girl just started school.","ko":"그 집 딸이 이제 막 학교 들어갔어."}},{"id":258,"w":"give","def":"to hand over or present something to another","pos":[{"p":"verb","senses":[{"ko":"주다, 건네다","en":"to hand something to someone or let them have it"},{"ko":"(행동을) 하다","en":"used with nouns to do an action, like give a call"}]}],"ph":[{"t":"give up","ko":"포기하다"},{"t":"give it a try","ko":"한번 해 보다"},{"t":"give someone a hand","ko":"~를 도와주다"}],"ex":{"en":"Can you give me that pen?","ko":"그 펜 좀 줄래?"}},{"id":259,"w":"go","def":"to move or travel from one place to another","pos":[{"p":"verb","senses":[{"ko":"가다, 이동하다","en":"to move or travel from one place to another"},{"ko":"(일이) 되어 가다","en":"to happen or develop in a particular way"},{"ko":"~하게 되다","en":"to change into a different state, often a worse one"},{"ko":"(going to) ~할 거야","en":"used as be going to to talk about the future or a plan"},{"ko":"(물건이) 놓이다, 들어가다","en":"to belong in a particular place or fit into a space"}]},{"p":"noun","senses":[{"ko":"차례, 시도","en":"a turn or an attempt to do something"}]}],"ph":[{"t":"How's it going?","ko":"어떻게 지내?"},{"t":"Let's go.","ko":"가자"},{"t":"have a go","ko":"한번 해 보다"}],"ex":{"en":"I usually go to work by subway.","ko":"난 보통 지하철로 출근해."}},{"id":260,"w":"good","def":"of high quality","pos":[{"p":"adjective","senses":[{"ko":"좋은, 질 높은","en":"of high quality or a high standard"},{"ko":"잘하는, 능숙한","en":"able to do something well"},{"ko":"착한, 친절한","en":"kind, helpful, or morally right"},{"ko":"괜찮아요, 됐어요","en":"used as I'm good to politely say you do not need anything"}]},{"p":"noun","senses":[{"ko":"이익, 도움","en":"something that helps or benefits someone"}]}],"ph":[{"t":"Good for you!","ko":"잘됐다! 잘했어!"},{"t":"for good","ko":"영원히, 아주"},{"t":"Sounds good.","ko":"좋아, 그러자"}],"ex":{"en":"This coffee is really good.","ko":"이 커피 진짜 맛있다."}},{"id":261,"w":"government","def":"the group of people who officially control a country","pos":[{"p":"noun","senses":[{"ko":"정부","en":"the group of people who officially run a country"},{"ko":"통치, 행정","en":"the act or system of governing a country or area"}]}],"ph":[{"t":"local government","ko":"지방 정부, 지자체"},{"t":"government official","ko":"공무원, 정부 관리"}],"ex":{"en":"The government announced new tax rules today.","ko":"정부가 오늘 새 세금 규정을 발표했어."}},{"id":262,"w":"grade","def":"a level of study that is completed by a student","pos":[{"p":"noun","senses":[{"ko":"학년","en":"a year or level of study in school"},{"ko":"성적, 점수","en":"a mark or score given for a student's work"},{"ko":"등급, 품질","en":"a level of quality, size, or rank"}]},{"p":"verb","senses":[{"ko":"채점하다, 등급을 매기다","en":"to give a mark or level to work or products"}]}],"ph":[{"t":"good grades","ko":"좋은 성적"},{"t":"make the grade","ko":"기준에 도달하다, 성공하다"}],"ex":{"en":"My son is in third grade.","ko":"우리 아들 3학년이야."}},{"id":263,"w":"great","def":"very large in size, extent or amount","pos":[{"p":"adjective","senses":[{"ko":"큰, 엄청난","en":"very large in size, amount, or degree"},{"ko":"아주 좋은, 훌륭한","en":"very good or enjoyable"},{"ko":"위대한, 뛰어난","en":"important, famous, or very skilled"}]}],"ph":[{"t":"That's great!","ko":"잘됐다! 좋다!"},{"t":"a great deal","ko":"많이, 다량"},{"t":"great job","ko":"정말 잘했어"}],"ex":{"en":"A great crowd waited outside the stadium.","ko":"엄청난 인파가 경기장 밖에서 기다렸어."}},{"id":264,"w":"group","def":"a number of people or things located or gathered together","pos":[{"p":"noun","senses":[{"ko":"무리, 집단, 그룹","en":"a number of people or things that are together"},{"ko":"(음악) 그룹, 밴드","en":"a band of musicians who perform together"}]},{"p":"verb","senses":[{"ko":"모으다, 분류하다","en":"to put people or things together in groups"}]}],"ph":[{"t":"group chat","ko":"단톡방, 단체 채팅"},{"t":"in groups","ko":"무리 지어, 조별로"},{"t":"group photo","ko":"단체 사진"}],"ex":{"en":"A group of us are going hiking.","ko":"우리 몇 명이 등산 가."}},{"id":265,"w":"grow","def":"to become larger","pos":[{"p":"verb","senses":[{"ko":"자라다, 커지다","en":"to become bigger or taller over time"},{"ko":"기르다, 재배하다","en":"to raise plants or let hair grow"},{"ko":"점점 ~해지다","en":"to gradually become something"}]}],"ph":[{"t":"grow up","ko":"자라다, 철들다"},{"t":"Grow up!","ko":"철 좀 들어!"},{"t":"grow on someone","ko":"점점 좋아지다"}],"ex":{"en":"Kids grow so fast these days.","ko":"요즘 애들 진짜 빨리 커."}},{"id":266,"w":"guess","def":"to form an opinion or give an answer about something when you do not know much or anything about it","pos":[{"p":"verb","senses":[{"ko":"추측하다, 짐작하다","en":"to give an answer or opinion without knowing all the facts"},{"ko":"(I guess) ~인 것 같다","en":"used to say you think something is probably true"}]},{"p":"noun","senses":[{"ko":"추측, 짐작","en":"an answer or opinion you give without being sure"}]}],"ph":[{"t":"Guess what!","ko":"있잖아! 맞춰 봐!"},{"t":"I guess so.","ko":"그런 것 같아"},{"t":"Your guess is as good as mine.","ko":"나도 몰라"}],"ex":{"en":"Can you guess how old she is?","ko":"그녀 몇 살인지 맞혀 볼래?"}},{"id":267,"w":"guy","def":"a man","pos":[{"p":"noun","senses":[{"ko":"남자, 녀석","en":"an informal word for a man"},{"ko":"(you guys) 너희, 여러분","en":"used to talk to a group of people of any gender"}]}],"ph":[{"t":"you guys","ko":"너희들, 얘들아"},{"t":"nice guy","ko":"좋은 사람"},{"t":"bad guy","ko":"악당, 나쁜 놈"}],"ex":{"en":"Who's that guy talking to your sister?","ko":"너희 언니랑 얘기하는 저 남자 누구야?"}},{"id":268,"w":"hair","def":"a thin threadlike growth from the skin of a person or animal","pos":[{"p":"noun","senses":[{"ko":"털, 머리카락 한 올","en":"a thin threadlike strand that grows from the skin"},{"ko":"머리카락, 머리","en":"all the hair that grows on a person's head"}]}],"ph":[{"t":"get a haircut","ko":"머리를 자르다"},{"t":"bad hair day","ko":"일진 안 좋은 날"},{"t":"let your hair down","ko":"긴장을 풀고 놀다"}],"ex":{"en":"There's a hair in my soup.","ko":"내 수프에 머리카락 들어 있어."}},{"id":269,"w":"half","def":"one of two equal parts something can be divided into","pos":[{"p":"noun","senses":[{"ko":"반, 절반","en":"one of two equal parts of something"}]},{"p":"adverb","senses":[{"ko":"반쯤, 부분적으로","en":"partly, but not completely"}]}],"ph":[{"t":"half an hour","ko":"30분"},{"t":"half past","ko":"~시 반"},{"t":"cut in half","ko":"반으로 자르다"}],"ex":{"en":"Do you want half of my sandwich?","ko":"내 샌드위치 반 먹을래?"}},{"id":270,"w":"hand","def":"the body parts at the end of a person's arm","pos":[{"p":"noun","senses":[{"ko":"손","en":"the part of the body at the end of the arm"},{"ko":"도움, 일손","en":"help with doing something"},{"ko":"(시계) 바늘","en":"one of the pointers on a clock"}]},{"p":"verb","senses":[{"ko":"건네주다","en":"to give something to someone with your hand"}]}],"ph":[{"t":"give someone a hand","ko":"~를 도와주다"},{"t":"on the other hand","ko":"반면에, 다른 한편으로"},{"t":"hand in","ko":"제출하다"}],"ex":{"en":"Wash your hands before dinner.","ko":"저녁 먹기 전에 손 씻어."}},{"id":271,"w":"hang","def":"to attach or place something so that it is held up without support from below","pos":[{"p":"verb","senses":[{"ko":"걸다, 매달다","en":"to fix something at the top so it holds up without support below"},{"ko":"걸려 있다, 매달리다","en":"to be held up from above"}]}],"ph":[{"t":"hang out","ko":"어울려 놀다"},{"t":"Hang on.","ko":"잠깐만"},{"t":"hang up","ko":"전화를 끊다"}],"ex":{"en":"Where should I hang my coat?","ko":"코트 어디에 걸면 돼?"}},{"id":272,"w":"happen","def":"to take place or occur","pos":[{"p":"verb","senses":[{"ko":"일어나다, 발생하다","en":"to take place, especially without being planned"},{"ko":"우연히 ~하다","en":"to do or be something by chance"}]}],"ph":[{"t":"What happened?","ko":"무슨 일이야?"},{"t":"happen to","ko":"우연히 ~하다"},{"t":"These things happen.","ko":"그럴 수도 있지"}],"ex":{"en":"What happened to your arm?","ko":"팔 왜 그래?"}},{"id":273,"w":"happy","def":"feeling pleasure and enjoyment because of your life","pos":[{"p":"adjective","senses":[{"ko":"행복한, 기쁜","en":"feeling pleasure and enjoyment"},{"ko":"만족하는","en":"satisfied that something is good or right"},{"ko":"기꺼이 ~하는","en":"willing to do something"}]}],"ph":[{"t":"Happy birthday!","ko":"생일 축하해!"},{"t":"happy to help","ko":"기꺼이 도와줄게"},{"t":"happy hour","ko":"할인 시간대"}],"ex":{"en":"I'm so happy for you!","ko":"정말 잘됐다!"}},{"id":274,"w":"hard","def":"something that is firm or difficult to bend","pos":[{"p":"adjective","senses":[{"ko":"단단한, 딱딱한","en":"firm and solid, not easy to bend or break"},{"ko":"어려운, 힘든","en":"difficult to do or understand"}]},{"p":"adverb","senses":[{"ko":"열심히","en":"with a lot of effort"},{"ko":"세게, 심하게","en":"with a lot of force"}]}],"ph":[{"t":"work hard","ko":"열심히 일하다"},{"t":"No hard feelings.","ko":"악감정은 없어"},{"t":"have a hard time","ko":"고생하다"}],"ex":{"en":"This bread is too hard to eat.","ko":"이 빵 너무 딱딱해서 못 먹겠어."}},{"id":275,"w":"hate","def":"a very strong feeling of dislike","pos":[{"p":"noun","senses":[{"ko":"증오, 미움","en":"a very strong feeling of dislike"}]},{"p":"verb","senses":[{"ko":"몹시 싫어하다, 미워하다","en":"to dislike someone or something very much"},{"ko":"~하기 싫다, 유감이다","en":"used to say politely that you are sorry to do something"}]}],"ph":[{"t":"I hate to say it, but","ko":"이런 말 하긴 싫지만"},{"t":"love-hate relationship","ko":"애증 관계"},{"t":"hate it when","ko":"~할 때 정말 싫어"}],"ex":{"en":"There's too much hate on the internet.","ko":"인터넷엔 미움이 너무 많아."}},{"id":276,"w":"have","def":"to own, possess, or hold something","pos":[{"p":"verb","senses":[{"ko":"가지다, 소유하다","en":"to own or hold something"},{"ko":"먹다, 마시다","en":"to eat or drink something"},{"ko":"(have to) ~해야 하다","en":"used to say something is necessary"},{"ko":"(병·증상이) 있다, 걸리다","en":"to suffer from an illness, pain, or other health problem"},{"ko":"(남에게) 시키다, 맡기다","en":"to arrange for someone to do something for you"}]}],"ph":[{"t":"have to","ko":"~해야 한다"},{"t":"have a good time","ko":"좋은 시간 보내다"},{"t":"have got","ko":"가지고 있다"}],"ex":{"en":"Do you have a charger I can borrow?","ko":"충전기 좀 빌릴 수 있어?"}},{"id":277,"w":"he","def":"used to refer to a male person that is the subject","pos":[{"p":"pronoun","senses":[{"ko":"그, 그 남자","en":"used for a male person or animal as the subject"}]}],"ph":[{"t":"he said, she said","ko":"서로 말이 엇갈리는 상황"}],"ex":{"en":"He said he'd call me later.","ko":"걔가 나중에 전화한대."}},{"id":278,"w":"head","def":"the upper part of the body","pos":[{"p":"noun","senses":[{"ko":"머리","en":"the top part of the body with the eyes, ears, and mouth"},{"ko":"우두머리, 책임자","en":"the person in charge of a group or organization"},{"ko":"앞부분, 윗부분","en":"the top or front part of something"}]},{"p":"verb","senses":[{"ko":"~로 향하다","en":"to go in a particular direction"}]}],"ph":[{"t":"head out","ko":"나가다, 출발하다"},{"t":"Heads up!","ko":"조심해! 미리 알려줄게"},{"t":"off the top of my head","ko":"얼핏 생각나기로는"}],"ex":{"en":"I hit my head on the door.","ko":"문에 머리 부딪혔어."}},{"id":279,"w":"health","def":"the condition of being well or free from disease","pos":[{"p":"noun","senses":[{"ko":"건강","en":"the condition of being well and free from illness"},{"ko":"건강 상태","en":"the state of a person's body or mind"}]}],"ph":[{"t":"in good health","ko":"건강한"},{"t":"health insurance","ko":"건강 보험"},{"t":"mental health","ko":"정신 건강"}],"ex":{"en":"Smoking is really bad for your health.","ko":"담배는 건강에 정말 안 좋아."}},{"id":280,"w":"hear","def":"to be aware of sound, to perceive with the ear","pos":[{"p":"verb","senses":[{"ko":"듣다, 들리다","en":"to notice sounds with your ears"},{"ko":"소식을 듣다, 전해 듣다","en":"to be told or learn about something"}]}],"ph":[{"t":"I hear you.","ko":"무슨 말인지 알아"},{"t":"hear from","ko":"~에게서 연락을 받다"},{"t":"Did you hear?","ko":"너 그 얘기 들었어?"}],"ex":{"en":"Can you hear me now?","ko":"이제 내 말 들려?"}},{"id":281,"w":"help","def":"to assist in order to make it easier for someone to do a job","pos":[{"p":"verb","senses":[{"ko":"돕다, 도와주다","en":"to make it easier for someone to do something"},{"ko":"(can't help) ~할 수밖에 없다","en":"used to say you cannot stop yourself from doing something"}]},{"p":"noun","senses":[{"ko":"도움","en":"things you do to make something easier for someone"}]}],"ph":[{"t":"Help yourself.","ko":"마음껏 드세요"},{"t":"Can I help you?","ko":"도와드릴까요?"},{"t":"can't help it","ko":"어쩔 수 없다"}],"ex":{"en":"Could you help me move this box?","ko":"이 상자 옮기는 것 좀 도와줄래?"}},{"id":282,"w":"here","def":"in this place, at this location or position","pos":[{"p":"adverb","senses":[{"ko":"여기에, 이곳에","en":"in, at, or to this place"},{"ko":"자, 여기 (있어)","en":"used when giving something to someone"}]}],"ph":[{"t":"Here you go.","ko":"여기 있어"},{"t":"over here","ko":"이쪽에, 여기"},{"t":"here and there","ko":"여기저기"}],"ex":{"en":"Wait here, I'll be right back.","ko":"여기서 기다려, 금방 올게."}},{"id":283,"w":"high","def":"rising upward a great distance","pos":[{"p":"adjective","senses":[{"ko":"높은","en":"reaching a long way up from the ground"},{"ko":"(양, 수준이) 높은","en":"greater than usual in amount, level, or value"}]},{"p":"adverb","senses":[{"ko":"높이, 높게","en":"at or to a level far above the ground"}]}],"ph":[{"t":"high school","ko":"고등학교"},{"t":"high five","ko":"하이파이브"},{"t":"high and low","ko":"샅샅이, 구석구석"}],"ex":{"en":"That mountain is really high.","ko":"저 산 진짜 높다."}},{"id":284,"w":"hit","def":"to move your hand, a bat, etc., quickly so that it touches someone or something in a forceful or violent way","pos":[{"p":"verb","senses":[{"ko":"치다, 때리다","en":"to touch someone or something with force using your hand or an object"},{"ko":"부딪치다","en":"to crash into something while moving"},{"ko":"(문제가) 닥치다","en":"to affect someone or something badly and suddenly"}]},{"p":"noun","senses":[{"ko":"히트, 인기작","en":"a song, film, or thing that is very popular"}]}],"ph":[{"t":"hit it off","ko":"죽이 잘 맞다"},{"t":"hit the road","ko":"출발하다, 떠나다"},{"t":"hit on","ko":"~에게 작업 걸다"}],"ex":{"en":"He hit the ball over the fence.","ko":"걔가 공을 담장 너머로 쳤어."}},{"id":285,"w":"hold","def":"to have or keep in your hand","pos":[{"p":"verb","senses":[{"ko":"잡다, 들고 있다","en":"to have something in your hand or arms"},{"ko":"(행사를) 열다, 개최하다","en":"to have a meeting, party, or event"},{"ko":"담다, 수용하다","en":"to contain or have space for something"},{"ko":"맡아 두다, 잡아 두다","en":"to keep something for someone so that it is available later"},{"ko":"안다, 안아 주다","en":"to put your arms around someone, such as a baby or a loved one"}]},{"p":"noun","senses":[{"ko":"잡기, 붙잡음","en":"the act of holding something"}]}],"ph":[{"t":"Hold on.","ko":"잠깐만"},{"t":"on hold","ko":"보류 중인; 통화 대기 중인"},{"t":"hold hands","ko":"손을 잡다"}],"ex":{"en":"Can you hold my bag for a second?","ko":"내 가방 잠깐 들어 줄래?"}},{"id":286,"w":"holiday","def":"a special day of celebration","pos":[{"p":"noun","senses":[{"ko":"공휴일, 명절","en":"a special day of celebration when many people do not work"},{"ko":"휴가","en":"a period away from work or school, often for travel"}]}],"ph":[{"t":"on holiday","ko":"휴가 중인"},{"t":"Happy holidays!","ko":"즐거운 연휴 보내!"},{"t":"public holiday","ko":"공휴일"}],"ex":{"en":"Monday is a holiday, so the bank is closed.","ko":"월요일은 공휴일이라 은행 문 닫아."}},{"id":287,"w":"home","def":"the place where a person or a family lives","pos":[{"p":"noun","senses":[{"ko":"집, 가정","en":"the place where a person or family lives"},{"ko":"고향, 본고장","en":"the place where you come from or feel you belong"}]},{"p":"adverb","senses":[{"ko":"집으로, 집에","en":"to or at the place where you live"}]}],"ph":[{"t":"at home","ko":"집에서; 편안한"},{"t":"Make yourself at home.","ko":"편하게 있어"},{"t":"go home","ko":"집에 가다"}],"ex":{"en":"I'm heading home now.","ko":"나 지금 집에 가."}},{"id":288,"w":"hope","def":"a feeling of expectation, to want something to happen","pos":[{"p":"noun","senses":[{"ko":"희망, 기대","en":"a feeling that something good may happen"}]},{"p":"verb","senses":[{"ko":"바라다, 희망하다","en":"to want something to happen and think it is possible"}]}],"ph":[{"t":"I hope so.","ko":"그러길 바라"},{"t":"Hope you feel better.","ko":"빨리 낫길 바라"},{"t":"Don't get your hopes up.","ko":"너무 기대하지 마"}],"ex":{"en":"There's still hope, so don't give up.","ko":"아직 희망 있으니까 포기하지 마."}},{"id":289,"w":"hospital","def":"a place where sick or injured people are given care or treatment and where children are often born","pos":[{"p":"noun","senses":[{"ko":"병원","en":"a place where sick or injured people get medical care"}]}],"ph":[{"t":"in the hospital","ko":"입원 중인"},{"t":"go to the hospital","ko":"병원에 가다"}],"ex":{"en":"My grandma is still in the hospital.","ko":"할머니가 아직 입원해 계셔."}},{"id":290,"w":"hot","def":"having a high temperature","pos":[{"p":"adjective","senses":[{"ko":"뜨거운, 더운","en":"having a high temperature"},{"ko":"매운","en":"having a strong burning taste"},{"ko":"인기 있는, 섹시한","en":"very popular, or sexually attractive"}]}],"ph":[{"t":"hot water","ko":"뜨거운 물; 곤경"},{"t":"hot topic","ko":"뜨거운 화제"},{"t":"in hot water","ko":"곤경에 처한"}],"ex":{"en":"Careful, the soup is really hot.","ko":"조심해, 국 진짜 뜨거워."}},{"id":291,"w":"hour","def":"a period of time equal to 60 minutes","pos":[{"p":"noun","senses":[{"ko":"시간, 1시간","en":"a period of time equal to sixty minutes"},{"ko":"(정해진) 시간, 시각","en":"a particular time of day or a time for doing something"}]}],"ph":[{"t":"for hours","ko":"몇 시간 동안"},{"t":"rush hour","ko":"출퇴근 시간"},{"t":"working hours","ko":"근무 시간"}],"ex":{"en":"The movie is about two hours long.","ko":"그 영화 두 시간쯤 해."}},{"id":292,"w":"house","def":"a building in which a family lives","pos":[{"p":"noun","senses":[{"ko":"집, 주택","en":"a building where a person or family lives"},{"ko":"집안 식구들","en":"all the people living in a house"}]},{"p":"verb","senses":[{"ko":"수용하다, 거처를 주다","en":"to give someone a place to live or stay"}]}],"ph":[{"t":"It's on the house.","ko":"서비스예요, 무료예요"},{"t":"house party","ko":"집들이 파티, 홈파티"},{"t":"move house","ko":"이사하다"}],"ex":{"en":"They just bought a house near the park.","ko":"걔네 공원 근처에 집 샀어."}},{"id":293,"w":"how","def":"by what means or manner?","pos":[{"p":"adverb","senses":[{"ko":"어떻게, 어떤 방법으로","en":"in what way or by what means"},{"ko":"얼마나","en":"used to ask about amount, age, or degree"},{"ko":"어떤 상태로","en":"used to ask about someone's health or condition"}]}],"ph":[{"t":"How are you?","ko":"잘 지내?"},{"t":"How about ...?","ko":"~하는 게 어때?"},{"t":"How come?","ko":"어째서? 왜?"}],"ex":{"en":"How do you get to the station?","ko":"역에 어떻게 가?"}},{"id":294,"w":"hundred","def":"the number 100","pos":[{"p":"number","senses":[{"ko":"100, 백","en":"the number 100, ten times ten"},{"ko":"(hundreds) 수백, 많은","en":"a very large number of people or things"}]}],"ph":[{"t":"a hundred percent","ko":"100퍼센트, 완전히"},{"t":"hundreds of","ko":"수백의, 수많은"}],"ex":{"en":"I've told you a hundred times!","ko":"내가 백 번은 말했잖아!"}},{"id":295,"w":"husband","def":"a married man : the man someone is married to","pos":[{"p":"noun","senses":[{"ko":"남편","en":"the man that someone is married to"}]}],"ph":[{"t":"husband and wife","ko":"남편과 아내, 부부"},{"t":"ex-husband","ko":"전남편"}],"ex":{"en":"My husband is cooking dinner tonight.","ko":"오늘 저녁은 남편이 요리해."}},{"id":296,"w":"I","def":"the person who is speaking or writing","pos":[{"p":"pronoun","senses":[{"ko":"나, 저","en":"used by the person speaking or writing to mean themselves"}]}],"ph":[{"t":"I mean","ko":"내 말은, 그러니까"},{"t":"I know.","ko":"그러게, 알아"},{"t":"I see.","ko":"그렇구나, 알겠어"}],"ex":{"en":"I think I left my phone at home.","ko":"폰을 집에 두고 온 것 같아."}},{"id":297,"w":"idea","def":"a thought, suggestion, opinion or plan","pos":[{"p":"noun","senses":[{"ko":"생각, 아이디어","en":"a thought, plan, or suggestion about what to do"},{"ko":"의견, 견해","en":"an opinion or belief about something"},{"ko":"짐작, 이해","en":"knowledge or understanding of something"}]}],"ph":[{"t":"No idea.","ko":"전혀 모르겠어"},{"t":"Good idea!","ko":"좋은 생각이야!"},{"t":"That's the idea.","ko":"바로 그거야"}],"ex":{"en":"That's a great idea, let's do it.","ko":"그거 좋은 생각이다, 하자."}},{"id":298,"w":"if","def":"introducing a condition for something to happen","pos":[{"p":"conjunction","senses":[{"ko":"만약 ~라면","en":"used to say that one thing happens only when another does"},{"ko":"~인지 (아닌지)","en":"used to ask or talk about whether something is true"}]}],"ph":[{"t":"What if ...?","ko":"~하면 어쩌지?"},{"t":"if I were you","ko":"내가 너라면"},{"t":"as if","ko":"마치 ~처럼; 퍽이나"}],"ex":{"en":"If it rains, we'll stay home.","ko":"비 오면 그냥 집에 있자."}},{"id":299,"w":"imagine","def":"to think of or create something in one's mind that is not real","pos":[{"p":"verb","senses":[{"ko":"상상하다","en":"to form a picture in your mind of something not real"},{"ko":"생각하다, 추측하다","en":"to think that something is probably true"}]}],"ph":[{"t":"Imagine that!","ko":"세상에, 놀랍네!"},{"t":"I can't imagine","ko":"상상도 안 돼"},{"t":"You're imagining things.","ko":"네가 잘못 본 거야"}],"ex":{"en":"Imagine living by the beach!","ko":"바닷가에 산다고 상상해 봐!"}},{"id":300,"w":"important","def":"having great significance","pos":[{"p":"adjective","senses":[{"ko":"중요한","en":"having great value, meaning, or effect"},{"ko":"영향력 있는","en":"having a lot of power or influence"}]}],"ph":[{"t":"It's important to","ko":"~하는 게 중요해"},{"t":"most important","ko":"가장 중요한"}],"ex":{"en":"I have an important meeting tomorrow.","ko":"내일 중요한 회의가 있어."}},{"id":301,"w":"in","def":"used to indicate being inside of or surrounded by something else","pos":[{"p":"preposition","senses":[{"ko":"~ 안에, ~ 속에","en":"inside or surrounded by something"},{"ko":"(시간) ~에, ~ 후에","en":"during a period, or after a period from now"},{"ko":"(언어·방식) ~로","en":"using a particular language or way of doing something"}]},{"p":"adverb","senses":[{"ko":"안으로, 안에","en":"into or inside a place"}]}],"ph":[{"t":"Come in.","ko":"들어와"},{"t":"in a minute","ko":"곧, 잠시 후에"},{"t":"I'm in.","ko":"나도 낄게, 나도 할래"}],"ex":{"en":"Your keys are in the drawer.","ko":"네 열쇠 서랍 안에 있어."}},{"id":302,"w":"include","def":"to have as a part of a group","pos":[{"p":"verb","senses":[{"ko":"포함하다","en":"to have something as one part of a whole"},{"ko":"포함시키다, 넣다","en":"to make someone or something part of a group"}]}],"ph":[{"t":"including","ko":"~를 포함하여"},{"t":"tax included","ko":"세금 포함"}],"ex":{"en":"Does the price include breakfast?","ko":"가격에 아침 식사 포함이에요?"}},{"id":303,"w":"increase","def":"to become larger or greater in size, amount, or degree","pos":[{"p":"verb","senses":[{"ko":"늘다, 증가하다","en":"to become larger in size, amount, or degree"},{"ko":"늘리다, 올리다","en":"to make something larger in amount or degree"}]},{"p":"noun","senses":[{"ko":"증가, 인상","en":"a rise in amount, number, or degree"}]}],"ph":[{"t":"on the increase","ko":"증가하고 있는"},{"t":"price increase","ko":"가격 인상"}],"ex":{"en":"Prices have increased a lot this year.","ko":"올해 물가가 많이 올랐어."}},{"id":304,"w":"individual","def":"existing as just one member","pos":[{"p":"adjective","senses":[{"ko":"개개의, 각각의","en":"existing as one separate member of a group"},{"ko":"개인의, 개인적인","en":"for or relating to one person"}]},{"p":"noun","senses":[{"ko":"개인, 사람","en":"a single person, considered separately from a group"}]}],"ph":[{"t":"individual needs","ko":"개인의 필요"},{"t":"individual portions","ko":"1인분씩"}],"ex":{"en":"Each individual room has its own bathroom.","ko":"방마다 각각 욕실이 있어."}},{"id":305,"w":"information","def":"facts or data about a situation, person, event, etc.","pos":[{"p":"noun","senses":[{"ko":"정보","en":"facts or details about a person, thing, or situation"},{"ko":"안내, 안내소","en":"a service or desk where people can ask questions"}]}],"ph":[{"t":"for your information","ko":"참고로 말하자면"},{"t":"a piece of information","ko":"정보 하나"},{"t":"too much information","ko":"그런 얘긴 안 해도 돼"}],"ex":{"en":"I need more information before I decide.","ko":"결정하기 전에 정보가 더 필요해."}},{"id":306,"w":"instead","def":"used to say that one thing is done or is chosen when another is not chosen","pos":[{"p":"adverb","senses":[{"ko":"대신에","en":"in place of someone or something else"}]}],"ph":[{"t":"instead of","ko":"~ 대신에"}],"ex":{"en":"Let's stay in and cook instead.","ko":"대신 그냥 집에서 요리하자."}},{"id":307,"w":"interest","def":"a feeling of wanting to know or learn about something","pos":[{"p":"noun","senses":[{"ko":"관심, 흥미","en":"a feeling of wanting to know or learn about something"},{"ko":"취미, 관심사","en":"an activity or subject you enjoy"},{"ko":"이자","en":"money paid for borrowing or saving money"}]},{"p":"verb","senses":[{"ko":"관심을 끌다","en":"to make someone want to know more about something"}]}],"ph":[{"t":"lose interest","ko":"흥미를 잃다"},{"t":"take an interest in","ko":"~에 관심을 갖다"},{"t":"interest rate","ko":"금리, 이자율"}],"ex":{"en":"He has a real interest in history.","ko":"걔는 역사에 진짜 관심 많아."}},{"id":308,"w":"into","def":"introduce movement toward the inside of something","pos":[{"p":"preposition","senses":[{"ko":"~ 안으로, ~ 속으로","en":"moving toward the inside of a place or thing"},{"ko":"~로 (변하여)","en":"used to show a change from one state to another"},{"ko":"~에 빠진, ~를 좋아하는","en":"very interested in something, used informally"}]}],"ph":[{"t":"be into","ko":"~에 푹 빠지다, 좋아하다"},{"t":"run into","ko":"우연히 마주치다"},{"t":"get into","ko":"~에 들어가다; ~에 빠지다"}],"ex":{"en":"She walked into the room smiling.","ko":"그녀가 웃으며 방에 들어왔어."}},{"id":309,"w":"involve","def":"to have or include in a part of something","pos":[{"p":"verb","senses":[{"ko":"포함하다, 수반하다","en":"to include something as a necessary part"},{"ko":"관련시키다, 참여시키다","en":"to make someone take part in something"}]}],"ph":[{"t":"be involved in","ko":"~에 관련되다, 참여하다"},{"t":"get involved","ko":"관여하다, 끼어들다"}],"ex":{"en":"The job involves a lot of travel.","ko":"그 일은 출장이 많아."}},{"id":310,"w":"issue","def":"problems that people are talking or thinking about","pos":[{"p":"noun","senses":[{"ko":"문제, 쟁점","en":"a problem or subject that people discuss or worry about"},{"ko":"(잡지 등의) 호","en":"one copy of a magazine or newspaper in a series"}]},{"p":"verb","senses":[{"ko":"발행하다, 발급하다","en":"to officially give or produce something"}]}],"ph":[{"t":"That's not the issue.","ko":"그게 문제가 아니야"},{"t":"have issues","ko":"문제가 있다"},{"t":"big issue","ko":"큰 문제"}],"ex":{"en":"Money is a big issue for us right now.","ko":"지금 우리한텐 돈이 큰 문제야."}},{"id":311,"w":"it","def":"a thing that has been previously mentioned","pos":[{"p":"pronoun","senses":[{"ko":"그것","en":"used for a thing, animal, or idea already mentioned"},{"ko":"(날씨, 시간 등) 비인칭","en":"used as a subject for time, weather, or distance"}]}],"ph":[{"t":"That's it.","ko":"그게 다야; 바로 그거야"},{"t":"Go for it!","ko":"한번 해 봐!"},{"t":"Forget it.","ko":"됐어, 잊어버려"}],"ex":{"en":"I bought a new jacket. Do you like it?","ko":"새 재킷 샀어. 마음에 들어?"}},{"id":312,"w":"item","def":"an individual article, unit or piece of information","pos":[{"p":"noun","senses":[{"ko":"물품, 항목, 품목","en":"one separate thing in a list or group"},{"ko":"(뉴스) 기사, 소식","en":"a single piece of news or information"}]}],"ph":[{"t":"news item","ko":"뉴스 기사"},{"t":"item by item","ko":"하나하나, 항목별로"}],"ex":{"en":"I only bought three items.","ko":"물건 세 개만 샀어."}},{"id":313,"w":"itself","def":"the reflexive form of the pronoun 'it'","pos":[{"p":"pronoun","senses":[{"ko":"그것 자체, 스스로","en":"used when the subject is a thing and it does something to itself"},{"ko":"그 자체","en":"used to emphasize the thing you are talking about"}]}],"ph":[{"t":"by itself","ko":"저절로; 홀로"},{"t":"in itself","ko":"그 자체로"},{"t":"speaks for itself","ko":"굳이 설명할 필요 없다"}],"ex":{"en":"The door closed by itself.","ko":"문이 저절로 닫혔어."}},{"id":314,"w":"job","def":"the regular work of earning money","pos":[{"p":"noun","senses":[{"ko":"일, 직업, 일자리","en":"the regular work that you do to earn money"},{"ko":"(해야 할) 일, 과제","en":"a piece of work or a task that needs doing"}]}],"ph":[{"t":"Good job!","ko":"잘했어!"},{"t":"part-time job","ko":"아르바이트"},{"t":"do the job","ko":"효과가 있다, 쓸 만하다"}],"ex":{"en":"She just got a new job downtown.","ko":"걔 시내에 새 직장 구했어."}},{"id":315,"w":"just","def":"exactly, to an exact degree or manner","pos":[{"p":"adverb","senses":[{"ko":"정확히, 딱","en":"exactly, in an exact amount or way"},{"ko":"방금, 막","en":"a very short time ago"},{"ko":"그냥, 단지","en":"only, or simply, with nothing more"},{"ko":"정말, 그야말로","en":"used to add emphasis, as in it's just amazing"}]},{"p":"adjective","senses":[{"ko":"공정한, 정당한","en":"fair and morally right"}]}],"ph":[{"t":"just in case","ko":"혹시 모르니까"},{"t":"Just kidding.","ko":"농담이야"},{"t":"just a minute","ko":"잠깐만"}],"ex":{"en":"That's just what I needed.","ko":"딱 내가 필요했던 거야."}},{"id":316,"w":"keep","def":"to continue holding or retaining possession of","pos":[{"p":"verb","senses":[{"ko":"가지고 있다, 보관하다","en":"to continue to have something and not give it away"},{"ko":"계속 ~하다","en":"to continue doing something or stay in a state"},{"ko":"(약속을) 지키다","en":"to do what you promised or agreed"}]}],"ph":[{"t":"Keep the change.","ko":"거스름돈은 가지세요"},{"t":"keep in touch","ko":"연락하고 지내다"},{"t":"keep going","ko":"계속하다"}],"ex":{"en":"You can keep the book, I don't need it.","ko":"그 책 가져, 난 필요 없어."}},{"id":317,"w":"kid","def":"a child or young person","pos":[{"p":"noun","senses":[{"ko":"아이, 어린이","en":"a child or young person"},{"ko":"새끼 염소","en":"a young goat, the baby of a goat"}]},{"p":"verb","senses":[{"ko":"농담하다, 놀리다","en":"to say something that is not true as a joke"}]}],"ph":[{"t":"Just kidding.","ko":"농담이야"},{"t":"Are you kidding me?","ko":"장난해? 진짜야?"},{"t":"No kidding.","ko":"설마; 당연하지"}],"ex":{"en":"How many kids do you have?","ko":"애가 몇 명이에요?"}},{"id":318,"w":"kill","def":"to cause the death of a person, animal or plant","pos":[{"p":"verb","senses":[{"ko":"죽이다","en":"to make a person, animal, or plant die"},{"ko":"몹시 아프게 하다","en":"to cause great pain, used informally"},{"ko":"(시간을) 때우다","en":"to spend time doing something while you wait"}]}],"ph":[{"t":"kill time","ko":"시간을 때우다"},{"t":"My feet are killing me.","ko":"발 아파 죽겠어"},{"t":"It won't kill you.","ko":"그런다고 안 죽어"}],"ex":{"en":"The cold weather killed all my plants.","ko":"추운 날씨에 화분이 다 죽었어."}},{"id":319,"w":"kind","def":"having a friendly, gentle nature","pos":[{"p":"adjective","senses":[{"ko":"친절한, 다정한","en":"friendly, gentle, and caring toward others"}]},{"p":"noun","senses":[{"ko":"종류, 유형","en":"a type or sort of person or thing"}]}],"ph":[{"t":"kind of","ko":"좀, 약간"},{"t":"That's very kind of you.","ko":"정말 친절하시네요"},{"t":"what kind of","ko":"어떤 종류의"}],"ex":{"en":"She's always so kind to everyone.","ko":"그녀는 늘 모두에게 정말 친절해."}},{"id":320,"w":"know","def":"to have in your mind, be aware of something","pos":[{"p":"verb","senses":[{"ko":"알다, 알고 있다","en":"to have information in your mind or be aware of something"},{"ko":"(사람을) 알다","en":"to be familiar with a person or place"}]}],"ph":[{"t":"you know","ko":"있잖아, 그러니까"},{"t":"I don't know.","ko":"몰라, 글쎄"},{"t":"Let me know.","ko":"알려 줘"}],"ex":{"en":"Do you know where the bathroom is?","ko":"화장실 어딘지 알아?"}},{"id":321,"w":"lady","def":"a woman who behaves in a polite way","pos":[{"p":"noun","senses":[{"ko":"숙녀","en":"a woman who behaves in a polite and proper way"},{"ko":"여성, 여자분","en":"a polite word for a woman"}]}],"ph":[{"t":"Ladies and gentlemen","ko":"신사 숙녀 여러분"},{"t":"ladies' room","ko":"여자 화장실"},{"t":"old lady","ko":"할머니; 마누라"}],"ex":{"en":"She's a real lady, always polite.","ko":"그분은 진짜 숙녀야, 늘 예의 바르셔."}},{"id":322,"w":"land","def":"the solid part of the surface of the Earth","pos":[{"p":"noun","senses":[{"ko":"땅, 육지","en":"the solid surface of the Earth that is not water"},{"ko":"토지, 부지","en":"an area of ground that someone owns or uses"}]},{"p":"verb","senses":[{"ko":"착륙하다, 내리다","en":"to come down to the ground after flying"},{"ko":"(일자리 등을) 얻다","en":"to succeed in getting something you wanted"}]}],"ph":[{"t":"by land","ko":"육로로"},{"t":"land a job","ko":"일자리를 얻다"}],"ex":{"en":"After a week at sea, we finally saw land.","ko":"일주일 항해 끝에 드디어 육지가 보였어."}},{"id":323,"w":"language","def":"the system of words or signs that people use to express thoughts and feelings to each other","pos":[{"p":"noun","senses":[{"ko":"언어, 말","en":"the system of words people use to communicate"},{"ko":"말투, 표현","en":"a particular style or kind of words someone uses"}]}],"ph":[{"t":"Watch your language!","ko":"말조심해!"},{"t":"body language","ko":"몸짓 언어"},{"t":"first language","ko":"모국어"}],"ex":{"en":"How many languages do you speak?","ko":"몇 개 국어 해?"}},{"id":324,"w":"large","def":"great in size, extent, or capacity","pos":[{"p":"adjective","senses":[{"ko":"큰, 넓은, 많은","en":"big in size, amount, or number"}]}],"ph":[{"t":"at large","ko":"전반적인; 잡히지 않은"},{"t":"by and large","ko":"대체로"},{"t":"a large coffee","ko":"커피 큰 사이즈"}],"ex":{"en":"Can I get a large coffee, please?","ko":"커피 큰 걸로 주세요."}},{"id":325,"w":"last","def":"coming after others, final","pos":[{"p":"adjective","senses":[{"ko":"마지막의, 최후의","en":"coming after all others"},{"ko":"지난, 바로 전의","en":"most recent, just before the present one"}]},{"p":"verb","senses":[{"ko":"계속되다, 지속하다","en":"to continue for a period of time"}]},{"p":"adverb","senses":[{"ko":"마지막으로","en":"after everyone or everything else"}]}],"ph":[{"t":"at last","ko":"마침내, 드디어"},{"t":"last night","ko":"어젯밤"},{"t":"last but not least","ko":"마지막으로 중요한 것은"}],"ex":{"en":"This is the last train tonight.","ko":"이게 오늘 밤 막차야."}},{"id":326,"w":"late","def":"happening near the end of a given time","pos":[{"p":"adjective","senses":[{"ko":"후반의, 말기의","en":"near the end of a period of time"},{"ko":"늦은, 지각한","en":"arriving or happening after the expected time"},{"ko":"고(故), 돌아가신","en":"used to talk about someone who has died"}]},{"p":"adverb","senses":[{"ko":"늦게","en":"after the usual or expected time"}]}],"ph":[{"t":"Better late than never.","ko":"늦어도 안 하는 것보단 낫지"},{"t":"stay up late","ko":"늦게까지 안 자다"},{"t":"run late","ko":"늦어지다, 지연되다"}],"ex":{"en":"She moved to Seoul in her late twenties.","ko":"그녀는 20대 후반에 서울로 이사 왔어."}},{"id":327,"w":"laugh","def":"to show that you are happy or that you think something is funny by smiling and making a sound from your throat","pos":[{"p":"verb","senses":[{"ko":"웃다, 소리 내어 웃다","en":"to smile and make sounds because something is funny"},{"ko":"비웃다","en":"to make fun of someone or something"}]},{"p":"noun","senses":[{"ko":"웃음, 웃음소리","en":"the act or sound of laughing"}]}],"ph":[{"t":"laugh at","ko":"~를 비웃다, 보고 웃다"},{"t":"Don't make me laugh.","ko":"웃기지 마"},{"t":"for a laugh","ko":"재미로, 장난으로"}],"ex":{"en":"His jokes always make me laugh.","ko":"걔 농담 들으면 늘 웃게 돼."}},{"id":328,"w":"laughter","def":"the action or sound of laughing","pos":[{"p":"noun","senses":[{"ko":"웃음, 웃음소리","en":"the act or sound of people laughing"}]}],"ph":[{"t":"burst into laughter","ko":"웃음을 터뜨리다"},{"t":"Laughter is the best medicine.","ko":"웃음이 최고의 약이다"}],"ex":{"en":"I heard laughter from the next room.","ko":"옆방에서 웃음소리가 들렸어."}},{"id":329,"w":"law","def":"the system or rules made by the government","pos":[{"p":"noun","senses":[{"ko":"법, 법률","en":"the system of rules that a country's government makes"},{"ko":"법학","en":"the study of these rules as a subject or job"},{"ko":"법칙","en":"a rule that explains how something in nature works"}]}],"ph":[{"t":"against the law","ko":"불법인"},{"t":"break the law","ko":"법을 어기다"},{"t":"law school","ko":"로스쿨, 법학 대학원"}],"ex":{"en":"Driving without a license is against the law.","ko":"무면허 운전은 불법이야."}},{"id":330,"w":"lead","def":"to guide someone to a place , to go with, be in charge","pos":[{"p":"verb","senses":[{"ko":"안내하다, 이끌다","en":"to guide someone to a place by going with them"},{"ko":"지휘하다, 이끌다","en":"to be in charge of a group or activity"},{"ko":"~로 이어지다","en":"to cause something to happen as a result"}]},{"p":"noun","senses":[{"ko":"선두, 앞섬","en":"the first position in a race or competition"}]}],"ph":[{"t":"lead to","ko":"~로 이어지다"},{"t":"take the lead","ko":"앞장서다, 선두에 서다"},{"t":"lead the way","ko":"길을 안내하다"}],"ex":{"en":"Follow me, I'll lead you to your table.","ko":"따라오세요, 자리로 안내해 드릴게요."}},{"id":331,"w":"learn","def":"to acquire knowledge by study or experience","pos":[{"p":"verb","senses":[{"ko":"배우다, 익히다","en":"to get knowledge or a skill by study or experience"},{"ko":"알게 되다","en":"to find out about something"}]}],"ph":[{"t":"learn a lesson","ko":"교훈을 얻다"},{"t":"learn by heart","ko":"외우다, 암기하다"},{"t":"live and learn","ko":"살다 보면 배우는 거지"}],"ex":{"en":"I want to learn how to swim.","ko":"수영 배우고 싶어."}},{"id":332,"w":"least","def":"smallest in amount, extent or degree","pos":[{"p":"determiner","senses":[{"ko":"가장 적은, 최소의","en":"the smallest in amount, size, or degree"}]},{"p":"adverb","senses":[{"ko":"가장 적게, 가장 덜","en":"less than anything or anyone else"}]}],"ph":[{"t":"at least","ko":"적어도, 최소한"},{"t":"not in the least","ko":"조금도 ~않다"},{"t":"the least I can do","ko":"내가 할 수 있는 최소한"}],"ex":{"en":"It's the least I can do for you.","ko":"너한테 이 정도는 해야지."}},{"id":333,"w":"leave","def":"to go away from, depart from","pos":[{"p":"verb","senses":[{"ko":"떠나다, 출발하다","en":"to go away from a place or person"},{"ko":"두고 오다, 남기다","en":"to let something stay where it is, often by forgetting it"},{"ko":"그대로 두다","en":"to let something stay as it is"}]},{"p":"noun","senses":[{"ko":"휴가","en":"time when you are allowed to be away from work"}]}],"ph":[{"t":"Leave me alone.","ko":"나 좀 내버려 둬"},{"t":"leave it to me","ko":"나한테 맡겨"},{"t":"on leave","ko":"휴가 중인"}],"ex":{"en":"What time do you leave for work?","ko":"몇 시에 출근해?"}},{"id":334,"w":"less","def":"not so much, a smaller amount of","pos":[{"p":"determiner","senses":[{"ko":"더 적은","en":"a smaller amount of something"}]},{"p":"adverb","senses":[{"ko":"덜, 더 적게","en":"to a smaller degree or not as much"}]}],"ph":[{"t":"more or less","ko":"대략, 거의"},{"t":"less than","ko":"~보다 적은, ~ 미만"},{"t":"couldn't care less","ko":"전혀 관심 없다"}],"ex":{"en":"I'm trying to eat less sugar.","ko":"설탕 덜 먹으려고 노력 중이야."}},{"id":335,"w":"let","def":"to allow or permit to do something","pos":[{"p":"verb","senses":[{"ko":"~하게 하다, 허락하다","en":"to allow someone to do something"},{"ko":"(let's) ~하자","en":"used to make a suggestion that includes you"},{"ko":"세를 주다","en":"to rent a room or building to someone"}]}],"ph":[{"t":"Let me know.","ko":"알려 줘"},{"t":"let go","ko":"놓아주다, 손을 놓다"},{"t":"let someone down","ko":"~를 실망시키다"}],"ex":{"en":"My mom won't let me stay out late.","ko":"엄마가 늦게까지 못 놀게 해."}},{"id":336,"w":"letter","def":"a written, typed or printed message","pos":[{"p":"noun","senses":[{"ko":"편지","en":"a written message sent to someone, usually by post"},{"ko":"글자, 문자","en":"one of the signs used to write words, like A or B"}]}],"ph":[{"t":"capital letter","ko":"대문자"},{"t":"to the letter","ko":"문자 그대로, 정확히"},{"t":"letter of recommendation","ko":"추천서"}],"ex":{"en":"I wrote my grandma a letter.","ko":"할머니께 편지 썼어."}},{"id":337,"w":"level","def":"a specific height or line","pos":[{"p":"noun","senses":[{"ko":"높이, 높이의 위치","en":"a particular height or position measured from the ground"},{"ko":"수준, 정도","en":"an amount or standard of something"},{"ko":"(건물의) 층","en":"one floor of a building"}]},{"p":"adjective","senses":[{"ko":"평평한, 같은 높이의","en":"flat, or at the same height as something else"}]}],"ph":[{"t":"sea level","ko":"해수면"},{"t":"on the level","ko":"정직한, 솔직한"},{"t":"next level","ko":"한 단계 위, 차원이 다른"}],"ex":{"en":"The water came up to knee level.","ko":"물이 무릎 높이까지 찼어."}},{"id":338,"w":"life","def":"the existence of a human being or animal","pos":[{"p":"noun","senses":[{"ko":"생명, 목숨","en":"the state of being alive, for people and animals"},{"ko":"삶, 인생","en":"the time from birth to death, or a way of living"},{"ko":"활기, 생기","en":"lively energy and excitement in a person or place"}]}],"ph":[{"t":"That's life.","ko":"사는 게 다 그렇지"},{"t":"Get a life!","ko":"너도 좀 네 인생 살아!"},{"t":"for life","ko":"평생, 종신"}],"ex":{"en":"The doctor saved his life.","ko":"의사가 그의 목숨을 구했어."}},{"id":339,"w":"light","def":"the form of energy that makes things visible","pos":[{"p":"noun","senses":[{"ko":"빛","en":"the energy from the sun or a lamp that lets us see"},{"ko":"전등, 불","en":"a lamp or other thing that gives light"}]},{"p":"adjective","senses":[{"ko":"가벼운","en":"weighing only a little, not heavy"},{"ko":"밝은, (색이) 연한","en":"bright, or pale in color"}]},{"p":"verb","senses":[{"ko":"불을 붙이다, 밝히다","en":"to start a fire or make something bright"}]}],"ph":[{"t":"turn off the light","ko":"불을 끄다"},{"t":"traffic light","ko":"신호등"},{"t":"travel light","ko":"짐을 가볍게 다니다"}],"ex":{"en":"There's not enough light to read here.","ko":"여긴 책 읽기엔 빛이 부족해."}},{"id":340,"w":"like","def":"to find something agreeable or enjoyable","pos":[{"p":"verb","senses":[{"ko":"좋아하다","en":"to find someone or something pleasant or enjoyable"},{"ko":"(would like) 원하다","en":"used to politely say what you want"}]},{"p":"preposition","senses":[{"ko":"~ 같은, ~처럼","en":"similar to or in the same way as"}]},{"p":"adverb","senses":[{"ko":"그러니까, 막 (말 사이)","en":"used informally to fill a pause or when you are not exact"}]},{"p":"conjunction","senses":[{"ko":"~처럼, ~대로","en":"in the same way as, or as if, as in like I said"}]}],"ph":[{"t":"I'd like ...","ko":"~ 주세요, ~하고 싶어요"},{"t":"What's it like?","ko":"그거 어때?"},{"t":"feel like","ko":"~하고 싶다"}],"ex":{"en":"I really like this song.","ko":"나 이 노래 진짜 좋아."}},{"id":341,"w":"line","def":"a long narrow mark or band on a surface","pos":[{"p":"noun","senses":[{"ko":"선, 줄","en":"a long thin mark on a surface"},{"ko":"줄, 대열","en":"a row of people or things waiting or standing together"},{"ko":"(대사, 글의) 줄, 행","en":"a row of words, or words an actor says"}]},{"p":"verb","senses":[{"ko":"줄을 세우다, 늘어서다","en":"to stand or put things in a row"}]}],"ph":[{"t":"wait in line","ko":"줄 서서 기다리다"},{"t":"Drop me a line.","ko":"연락 좀 해"},{"t":"cross the line","ko":"선을 넘다"}],"ex":{"en":"Draw a line under your name.","ko":"이름 밑에 줄 그어."}},{"id":342,"w":"list","def":"a series of written names, words or numbers","pos":[{"p":"noun","senses":[{"ko":"목록, 명단","en":"a series of names, words, or numbers written one after another"}]},{"p":"verb","senses":[{"ko":"목록을 만들다, 열거하다","en":"to write or say things one after another"}]}],"ph":[{"t":"shopping list","ko":"장보기 목록"},{"t":"to-do list","ko":"할 일 목록"},{"t":"waiting list","ko":"대기자 명단"}],"ex":{"en":"I made a list of things to buy.","ko":"살 것 목록 만들었어."}},{"id":343,"w":"listen","def":"to pay attention to someone or something in order to hear what is being said, sung, played, etc.","pos":[{"p":"verb","senses":[{"ko":"듣다, 귀 기울이다","en":"to pay attention to sounds or to what someone says"},{"ko":"(충고를) 따르다","en":"to accept someone's advice and do what they say"}]}],"ph":[{"t":"Listen.","ko":"있잖아, 들어 봐"},{"t":"listen to","ko":"~를 듣다"},{"t":"listen up","ko":"잘 들어"}],"ex":{"en":"I listen to music on my way to work.","ko":"출근길에 음악 들어."}},{"id":344,"w":"little","def":"small in size, amount, or degree","pos":[{"p":"adjective","senses":[{"ko":"작은","en":"small in size, amount, or degree"},{"ko":"어린, 손아래의","en":"young, or younger than you"}]},{"p":"determiner","senses":[{"ko":"(a little) 조금, 약간","en":"a small amount of something"},{"ko":"거의 없는","en":"not much, or almost none"}]}],"ph":[{"t":"a little bit","ko":"조금, 약간"},{"t":"little by little","ko":"조금씩"},{"t":"little brother","ko":"남동생"}],"ex":{"en":"They live in a little house by the river.","ko":"걔네 강가 작은 집에 살아."}},{"id":345,"w":"live","def":"to be alive, to remain or continue to be alive","pos":[{"p":"verb","senses":[{"ko":"살다, 살아 있다","en":"to be alive or stay alive"},{"ko":"(~에) 살다, 거주하다","en":"to have your home in a particular place"}]},{"p":"adjective","senses":[{"ko":"라이브의, 생방송의","en":"performed or broadcast as it happens"},{"ko":"살아 있는","en":"living, not dead, as of animals or plants"}]}],"ph":[{"t":"Where do you live?","ko":"어디 살아?"},{"t":"live with","ko":"~와 함께 살다; 참고 견디다"},{"t":"live music","ko":"라이브 음악"}],"ex":{"en":"My grandpa lived to ninety-five.","ko":"할아버지는 아흔다섯까지 사셨어."}},{"id":346,"w":"load","def":"something that is lifted and carried","pos":[{"p":"noun","senses":[{"ko":"짐, 화물","en":"something heavy that is carried"},{"ko":"(a load of) 많음, 잔뜩","en":"a large amount of something, used informally"}]},{"p":"verb","senses":[{"ko":"싣다, 채우다","en":"to put things into a vehicle or machine"}]}],"ph":[{"t":"loads of","ko":"많은, 잔뜩"},{"t":"a load off my mind","ko":"마음의 짐을 덜다"},{"t":"load the dishwasher","ko":"식기세척기에 그릇을 넣다"}],"ex":{"en":"That's a heavy load for one person.","ko":"혼자 들기엔 무거운 짐이야."}},{"id":347,"w":"local","def":"relating or restricted to a particular area, city, or town","pos":[{"p":"adjective","senses":[{"ko":"지역의, 현지의","en":"relating to a particular area, city, or town"},{"ko":"동네의, 근처의","en":"near where you live"}]},{"p":"noun","senses":[{"ko":"현지인, 동네 사람","en":"a person who lives in a particular area"}]}],"ph":[{"t":"local time","ko":"현지 시간"},{"t":"local food","ko":"현지 음식"},{"t":"the locals","ko":"현지 사람들"}],"ex":{"en":"Let's try the local food here.","ko":"여기 현지 음식 먹어 보자."}},{"id":348,"w":"long","def":"extending a great distance","pos":[{"p":"adjective","senses":[{"ko":"긴, 먼","en":"measuring a great distance from one end to the other"},{"ko":"(시간이) 긴, 오랜","en":"lasting for a lot of time"}]},{"p":"adverb","senses":[{"ko":"오래, 오랫동안","en":"for a great amount of time"}]}],"ph":[{"t":"Long time no see.","ko":"오랜만이야"},{"t":"as long as","ko":"~하기만 하면"},{"t":"in the long run","ko":"결국에는, 장기적으로"}],"ex":{"en":"It's a long walk to the station.","ko":"역까지 걸어가기엔 멀어."}},{"id":349,"w":"look","def":"to direct one's gaze in a particular direction","pos":[{"p":"verb","senses":[{"ko":"보다, 바라보다","en":"to turn your eyes toward someone or something"},{"ko":"~해 보이다","en":"to seem or appear a certain way"}]},{"p":"noun","senses":[{"ko":"봄, 한번 보기","en":"the act of looking at something"},{"ko":"모습, 표정","en":"the way someone or something appears"}]},{"p":"interjection","senses":[{"ko":"이봐, 있잖아","en":"used to get attention before saying something important"}]}],"ph":[{"t":"look for","ko":"찾다"},{"t":"look forward to","ko":"~를 고대하다"},{"t":"Look out!","ko":"조심해!"}],"ex":{"en":"Look at that view!","ko":"저 경치 좀 봐!"}},{"id":350,"w":"lose","def":"to be unable to find something you once had","pos":[{"p":"verb","senses":[{"ko":"잃어버리다","en":"to be unable to find something you had"},{"ko":"지다, 패하다","en":"to fail to win a game or competition"},{"ko":"(체중 등을) 줄이다","en":"to have less of something, such as weight"}]}],"ph":[{"t":"lose weight","ko":"살을 빼다"},{"t":"lose your mind","ko":"미치다, 정신이 나가다"},{"t":"get lost","ko":"길을 잃다; 꺼져"}],"ex":{"en":"I lost my wallet on the bus.","ko":"버스에서 지갑 잃어버렸어."}},{"id":351,"w":"lot","def":"a small piece of land that is or could be used for building something or for some other purpose","pos":[{"p":"noun","senses":[{"ko":"부지, 터, 구역","en":"a small piece of land used for building or another purpose"},{"ko":"(a lot) 많음, 다수","en":"a large amount or number"},{"ko":"제비뽑기, 운명","en":"a way of choosing by chance, or your fate"}]},{"p":"adverb","senses":[{"ko":"(a lot) 많이, 훨씬","en":"used as a lot to mean very much or much more"}]}],"ph":[{"t":"a lot of","ko":"많은"},{"t":"Thanks a lot.","ko":"정말 고마워"},{"t":"parking lot","ko":"주차장"}],"ex":{"en":"They're building a café on that empty lot.","ko":"저 빈터에 카페를 짓고 있어."}},{"id":352,"w":"love","def":"feel great affection for","pos":[{"p":"verb","senses":[{"ko":"사랑하다","en":"to feel deep affection for someone"},{"ko":"아주 좋아하다","en":"to like something very much"}]},{"p":"noun","senses":[{"ko":"사랑","en":"a strong feeling of affection"},{"ko":"자기, 애인","en":"a person you love, or a friendly way to address someone"}]}],"ph":[{"t":"fall in love","ko":"사랑에 빠지다"},{"t":"I'd love to.","ko":"좋지, 기꺼이"},{"t":"Love you.","ko":"사랑해"}],"ex":{"en":"I love you more than anything.","ko":"세상 무엇보다 널 사랑해."}},{"id":353,"w":"lovely","def":"attractive or beautiful especially in a graceful way","pos":[{"p":"adjective","senses":[{"ko":"아름다운, 사랑스러운","en":"beautiful or attractive in a gentle way"},{"ko":"아주 좋은, 즐거운","en":"very pleasant or enjoyable"}]}],"ph":[{"t":"That's lovely.","ko":"정말 좋네요"},{"t":"lovely day","ko":"날씨 좋은 날"}],"ex":{"en":"What a lovely dress!","ko":"드레스 정말 예쁘다!"}},{"id":354,"w":"low","def":"not rising or extending upward","pos":[{"p":"adjective","senses":[{"ko":"낮은","en":"not high, close to the ground"},{"ko":"(양, 수준이) 낮은, 적은","en":"small in amount, level, or value"},{"ko":"우울한, 기운 없는","en":"sad or without energy"}]},{"p":"adverb","senses":[{"ko":"낮게","en":"in or to a low position or level"}]}],"ph":[{"t":"keep a low profile","ko":"눈에 띄지 않게 지내다"},{"t":"running low","ko":"얼마 안 남은"},{"t":"feel low","ko":"기분이 처지다"}],"ex":{"en":"Watch your head, the ceiling is low.","ko":"머리 조심해, 천장 낮아."}},{"id":355,"w":"machine","def":"a piece of equipment with moving parts that does work when it is given power from electricity, gasoline, etc.","pos":[{"p":"noun","senses":[{"ko":"기계","en":"a piece of equipment with moving parts that uses power to do work"}]}],"ph":[{"t":"washing machine","ko":"세탁기"},{"t":"vending machine","ko":"자판기"},{"t":"coffee machine","ko":"커피 머신"}],"ex":{"en":"The coffee machine isn't working again.","ko":"커피 머신 또 고장 났어."}},{"id":356,"w":"main","def":"most important","pos":[{"p":"adjective","senses":[{"ko":"주된, 가장 중요한","en":"largest or most important"}]}],"ph":[{"t":"main course","ko":"메인 요리"},{"t":"the main thing","ko":"가장 중요한 건"},{"t":"main street","ko":"중심가, 큰길"}],"ex":{"en":"The main thing is that you're safe.","ko":"제일 중요한 건 네가 무사하다는 거야."}},{"id":357,"w":"major","def":"important, serious, or large in number","pos":[{"p":"adjective","senses":[{"ko":"주요한, 중대한","en":"important, serious, or large"}]},{"p":"noun","senses":[{"ko":"전공","en":"the main subject a student studies at university"}]},{"p":"verb","senses":[{"ko":"전공하다","en":"to study something as your main subject at university"}]}],"ph":[{"t":"major in","ko":"~를 전공하다"},{"t":"a major problem","ko":"큰 문제"}],"ex":{"en":"There was a major accident on the highway.","ko":"고속도로에서 큰 사고가 났어."}},{"id":358,"w":"make","def":"to build, create, or produce something","pos":[{"p":"verb","senses":[{"ko":"만들다","en":"to build, create, or produce something"},{"ko":"~하게 하다","en":"to cause someone to do something or feel a certain way"},{"ko":"(돈을) 벌다","en":"to earn money from work or business"},{"ko":"(실수·결정을) 하다","en":"to do or perform an action, such as a mistake or a decision"}]}],"ph":[{"t":"make sure","ko":"꼭 ~하다, 확인하다"},{"t":"make it","ko":"해내다; 제시간에 가다"},{"t":"make sense","ko":"말이 되다, 이해가 되다"}],"ex":{"en":"I'll make some pasta for dinner.","ko":"저녁으로 파스타 만들게."}},{"id":359,"w":"man","def":"an adult male human being","pos":[{"p":"noun","senses":[{"ko":"남자, 성인 남성","en":"an adult male person"},{"ko":"사람, 인간","en":"a person or people in general"}]},{"p":"interjection","senses":[{"ko":"야, 이런, 와","en":"used to show surprise, anger, or excitement"}]}],"ph":[{"t":"Oh man!","ko":"아 이런!, 와!"},{"t":"my man","ko":"친구, 형 (친근하게)"},{"t":"man to man","ko":"남자 대 남자로, 솔직하게"}],"ex":{"en":"Who's that man by the door?","ko":"문 옆에 있는 저 남자 누구야?"}},{"id":360,"w":"many","def":"used to refer a large number of things","pos":[{"p":"determiner","senses":[{"ko":"많은","en":"a large number of people or things"}]},{"p":"pronoun","senses":[{"ko":"많은 사람, 많은 것","en":"a large number of people or things already mentioned"}]}],"ph":[{"t":"how many","ko":"몇 개, 몇 명"},{"t":"too many","ko":"너무 많은"},{"t":"so many","ko":"정말 많은"}],"ex":{"en":"How many people are coming tonight?","ko":"오늘 밤 몇 명 와?"}},{"id":361,"w":"market","def":"a place that products are bought and sold","pos":[{"p":"noun","senses":[{"ko":"시장","en":"a place where people buy and sell goods"},{"ko":"(경제) 시장, 수요","en":"the business of buying and selling a type of product"}]},{"p":"verb","senses":[{"ko":"판촉하다, 마케팅하다","en":"to advertise and sell a product"}]}],"ph":[{"t":"on the market","ko":"시판 중인, 매물로 나온"},{"t":"in the market for","ko":"~를 사려고 하는"},{"t":"night market","ko":"야시장"}],"ex":{"en":"I buy my vegetables at the market.","ko":"채소는 시장에서 사."}},{"id":362,"w":"marry","def":"to become the husband or wife of (someone)","pos":[{"p":"verb","senses":[{"ko":"~와 결혼하다","en":"to become someone's husband or wife"},{"ko":"결혼시키다, 주례하다","en":"to perform the ceremony that marries two people"}]}],"ph":[{"t":"get married","ko":"결혼하다"},{"t":"Will you marry me?","ko":"나랑 결혼해 줄래?"},{"t":"married with kids","ko":"결혼해서 애가 있는"}],"ex":{"en":"He wants to marry her next spring.","ko":"걔는 내년 봄에 그녀랑 결혼하고 싶어 해."}},{"id":363,"w":"mathematics","def":"the study or science of numbers and shapes","pos":[{"p":"noun","senses":[{"ko":"수학","en":"the study of numbers, amounts, and shapes"}]}],"ph":[{"t":"math","ko":"수학 (미국식 줄임말)"},{"t":"do the math","ko":"계산해 봐, 따져 봐"}],"ex":{"en":"Mathematics was my worst subject in school.","ko":"학교 다닐 때 수학이 제일 못하는 과목이었어."}},{"id":364,"w":"matter","def":"the physical substance things are made of","pos":[{"p":"noun","senses":[{"ko":"물질","en":"the physical substance that everything in the world is made of"},{"ko":"문제, 일","en":"a situation or subject that you have to think about or deal with"}]},{"p":"verb","senses":[{"ko":"중요하다, 문제가 되다","en":"to be important or to make a difference"}]}],"ph":[{"t":"What's the matter?","ko":"무슨 일이야?"},{"t":"It doesn't matter.","ko":"상관없어"},{"t":"no matter what","ko":"무슨 일이 있어도"}],"ex":{"en":"Everything around us is made of matter.","ko":"우리 주변의 모든 건 물질로 이루어져 있어."}},{"id":365,"w":"may","def":"used to express possibility or probability","pos":[{"p":"modal","senses":[{"ko":"~일지도 모른다","en":"used to say that something is possible or fairly likely"},{"ko":"~해도 된다","en":"used to ask for or give permission politely"}]}],"ph":[{"t":"May I ...?","ko":"~해도 될까요?"},{"t":"may as well","ko":"~하는 편이 낫겠다"},{"t":"come what may","ko":"무슨 일이 있어도"}],"ex":{"en":"It may rain later, so take an umbrella.","ko":"이따 비 올지도 모르니까 우산 챙겨."}},{"id":366,"w":"maybe","def":"possibly but not certainly : perhaps","pos":[{"p":"adverb","senses":[{"ko":"아마, 어쩌면","en":"possibly, but not certainly"},{"ko":"~하는 게 어때","en":"used to make a suggestion in a soft, polite way"}]}],"ph":[{"t":"maybe not","ko":"아닐 수도 있어"},{"t":"Maybe later.","ko":"나중에 하자"},{"t":"Maybe next time.","ko":"다음에 하자"}],"ex":{"en":"Maybe she's just busy.","ko":"어쩌면 그냥 바쁜 걸지도 몰라."}},{"id":367,"w":"mean","def":"to have in mind as your purpose or intention","pos":[{"p":"verb","senses":[{"ko":"의도하다, ~할 작정이다","en":"to have something in mind as your purpose or intention"},{"ko":"의미하다, 뜻하다","en":"to have a particular meaning or to express an idea"}]},{"p":"adjective","senses":[{"ko":"못된, 심술궂은","en":"unkind or cruel to other people"}]}],"ph":[{"t":"I mean","ko":"내 말은, 그러니까"},{"t":"You mean ...?","ko":"~라는 말이야?"},{"t":"I didn't mean to.","ko":"그럴 생각은 아니었어"}],"ex":{"en":"Sorry, I didn't mean to hurt you.","ko":"미안, 너 상처 주려던 건 아니었어."}},{"id":368,"w":"meet","def":"to be introduced for the first time","pos":[{"p":"verb","senses":[{"ko":"(처음) 만나다, 알게 되다","en":"to see and be introduced to someone for the first time"},{"ko":"만나다","en":"to come together with someone at an arranged time or place"},{"ko":"충족하다, 맞추다","en":"to reach a needed standard, goal, or deadline"}]}],"ph":[{"t":"Nice to meet you.","ko":"만나서 반가워요"},{"t":"meet up","ko":"(약속하고) 만나다"},{"t":"meet a deadline","ko":"마감을 맞추다"}],"ex":{"en":"We met at a friend's party.","ko":"우리 친구 파티에서 처음 만났어."}},{"id":369,"w":"member","def":"a person or country belonging to a group or team","pos":[{"p":"noun","senses":[{"ko":"회원, 구성원","en":"a person or country that belongs to a group, team, or organization"}]}],"ph":[{"t":"family member","ko":"가족 구성원"},{"t":"member of staff","ko":"직원"},{"t":"become a member","ko":"회원이 되다"}],"ex":{"en":"Are you a member of this gym?","ko":"너 이 헬스장 회원이야?"}},{"id":370,"w":"mention","def":"to talk about, write about, or refer to (something or someone) especially in a brief way","pos":[{"p":"verb","senses":[{"ko":"언급하다, 말하다","en":"to talk or write about something or someone briefly"}]},{"p":"noun","senses":[{"ko":"언급","en":"a short remark about someone or something"}]}],"ph":[{"t":"Don't mention it.","ko":"별말씀을요, 천만에요"},{"t":"not to mention","ko":"~은 말할 것도 없고"},{"t":"now that you mention it","ko":"듣고 보니, 그러고 보니"}],"ex":{"en":"She mentioned you the other day.","ko":"걔가 요전에 네 얘기 하더라."}},{"id":371,"w":"middle","def":"equally distant from the ends or sides : halfway between two points","pos":[{"p":"adjective","senses":[{"ko":"가운데의, 중간의","en":"halfway between two ends, sides, or points"}]},{"p":"noun","senses":[{"ko":"가운데, 중앙","en":"the central part or point of something"},{"ko":"한창, 도중","en":"the time when something is happening and not yet finished"}]}],"ph":[{"t":"in the middle of","ko":"~하는 중에, ~ 한가운데"},{"t":"middle-aged","ko":"중년의"},{"t":"middle name","ko":"중간 이름"}],"ex":{"en":"I got the middle seat again.","ko":"나 또 가운데 자리 걸렸어."}},{"id":372,"w":"might","def":"to say something is possible","pos":[{"p":"modal","senses":[{"ko":"~일지도 모른다","en":"used to say that something is possible but not certain"},{"ko":"~하는 게 좋겠다","en":"used to make a polite suggestion"}]}],"ph":[{"t":"might as well","ko":"~하는 게 낫겠다"},{"t":"You might want to ...","ko":"~하는 게 좋을 거야"},{"t":"I might be wrong, but","ko":"내가 틀릴 수도 있지만"}],"ex":{"en":"I might be a little late.","ko":"나 좀 늦을지도 몰라."}},{"id":373,"w":"mile","def":"a unit of measurement used in the US that is about 1600 meters","pos":[{"p":"noun","senses":[{"ko":"마일 (약 1.6km)","en":"a unit of distance used in the US, about 1,600 meters"},{"ko":"훨씬, 아주 많이","en":"used in the plural to mean a long way or a large amount"}]}],"ph":[{"t":"miles away","ko":"아주 멀리; 딴생각에 빠진"},{"t":"go the extra mile","ko":"한층 더 노력하다"},{"t":"miles better","ko":"훨씬 나은"}],"ex":{"en":"The beach is about two miles from here.","ko":"해변은 여기서 2마일쯤 돼."}},{"id":374,"w":"million","def":"the number 1000000","pos":[{"p":"number","senses":[{"ko":"백만","en":"the number 1,000,000, a thousand thousands"},{"ko":"수많은, 무수한","en":"used in the plural to mean a very large number"}]}],"ph":[{"t":"one in a million","ko":"아주 드문, 최고의"},{"t":"a million times","ko":"수도 없이"},{"t":"millions of","ko":"수많은"}],"ex":{"en":"The city has over ten million people.","ko":"그 도시 인구가 천만 명이 넘어."}},{"id":375,"w":"mind","def":"the part of person that enables us to think, feel, and reason","pos":[{"p":"noun","senses":[{"ko":"마음, 정신","en":"the part of a person that thinks, feels, and remembers"},{"ko":"생각, 의견","en":"what someone thinks or intends"}]},{"p":"verb","senses":[{"ko":"꺼리다, 신경 쓰다","en":"to be annoyed or worried by something"},{"ko":"조심하다, 주의하다","en":"to be careful of something, as in mind your head"}]}],"ph":[{"t":"Do you mind if ...?","ko":"~해도 괜찮을까요?"},{"t":"Never mind.","ko":"신경 쓰지 마"},{"t":"change your mind","ko":"마음을 바꾸다"}],"ex":{"en":"Do you mind if I sit here?","ko":"여기 앉아도 괜찮을까요?"}},{"id":376,"w":"mine","def":"that which belongs to me : my one : my ones","pos":[{"p":"pronoun","senses":[{"ko":"내 것","en":"the one or ones that belong to me"}]},{"p":"noun","senses":[{"ko":"광산","en":"a deep hole where people dig out coal, gold, or other minerals"}]}],"ph":[{"t":"a friend of mine","ko":"내 친구 (중 한 명)"},{"t":"The pleasure is mine.","ko":"제가 더 기뻐요"}],"ex":{"en":"That's not your phone, it's mine.","ko":"그거 네 폰 아니고 내 거야."}},{"id":377,"w":"minute","def":"a period of time equal to 60 seconds","pos":[{"p":"noun","senses":[{"ko":"분","en":"a period of time equal to 60 seconds"},{"ko":"잠깐, 순간","en":"a very short period of time"}]}],"ph":[{"t":"Wait a minute.","ko":"잠깐만"},{"t":"at the last minute","ko":"막판에, 마지막 순간에"},{"t":"any minute now","ko":"금방이라도, 곧"}],"ex":{"en":"The bus comes in five minutes.","ko":"버스 5분 뒤에 와."}},{"id":378,"w":"miss","def":"to fail to hit, catch, reach, or get (something)","pos":[{"p":"verb","senses":[{"ko":"놓치다, 빗나가다","en":"to fail to hit, catch, reach, or get something"},{"ko":"그리워하다, 보고 싶다","en":"to feel sad because someone or something is not with you"},{"ko":"빠지다, 거르다","en":"to not go to or take part in something"}]}],"ph":[{"t":"I miss you.","ko":"보고 싶어"},{"t":"miss out (on)","ko":"(좋은 기회를) 놓치다"},{"t":"You can't miss it.","ko":"쉽게 찾을 거야"}],"ex":{"en":"Hurry up, or we'll miss the train.","ko":"서둘러, 안 그러면 기차 놓쳐."}},{"id":379,"w":"moment","def":"a very short or brief period of time","pos":[{"p":"noun","senses":[{"ko":"잠깐, 순간","en":"a very short period of time"},{"ko":"(특정한) 때, 시점","en":"a particular point in time"}]}],"ph":[{"t":"Just a moment.","ko":"잠시만요"},{"t":"at the moment","ko":"지금, 현재"},{"t":"for the moment","ko":"당분간, 지금으로선"}],"ex":{"en":"Can you wait a moment?","ko":"잠깐만 기다려 줄래?"}},{"id":380,"w":"money","def":"something used to pay for goods and services","pos":[{"p":"noun","senses":[{"ko":"돈","en":"coins, notes, or other means used to pay for goods and services"},{"ko":"재산, 큰돈","en":"wealth, or a large amount of money"}]}],"ph":[{"t":"make money","ko":"돈을 벌다"},{"t":"save money","ko":"돈을 아끼다, 모으다"},{"t":"a waste of money","ko":"돈 낭비"}],"ex":{"en":"I don't have enough money for that.","ko":"그거 살 돈이 부족해."}},{"id":381,"w":"month","def":"one of the 12 periods of time a year is broken into","pos":[{"p":"noun","senses":[{"ko":"달, 월","en":"one of the twelve periods of time that a year is divided into"},{"ko":"한 달","en":"a period of about four weeks"}]}],"ph":[{"t":"last month","ko":"지난달"},{"t":"once a month","ko":"한 달에 한 번"},{"t":"a month from now","ko":"지금부터 한 달 뒤"}],"ex":{"en":"I'm moving next month.","ko":"나 다음 달에 이사 가."}},{"id":382,"w":"more","def":"greater in amount, number, or size","pos":[{"p":"determiner","senses":[{"ko":"더 많은","en":"greater in amount, number, or size"}]},{"p":"adverb","senses":[{"ko":"더, 더욱","en":"to a greater degree, or more often"}]},{"p":"pronoun","senses":[{"ko":"더 많은 것, 더","en":"a larger or extra amount or number"}]}],"ph":[{"t":"more or less","ko":"거의, 대략"},{"t":"no more","ko":"더 이상 ~않다"},{"t":"once more","ko":"한 번 더"}],"ex":{"en":"Can I have more rice?","ko":"밥 좀 더 먹어도 돼?"}},{"id":383,"w":"morning","def":"the early part of the day","pos":[{"p":"noun","senses":[{"ko":"아침, 오전","en":"the early part of the day, from sunrise until noon"}]}],"ph":[{"t":"Good morning.","ko":"좋은 아침, 안녕하세요"},{"t":"in the morning","ko":"아침에"},{"t":"first thing in the morning","ko":"아침에 제일 먼저"}],"ex":{"en":"I usually go running in the morning.","ko":"나는 보통 아침에 달리기해."}},{"id":384,"w":"most","def":"almost all of something","pos":[{"p":"determiner","senses":[{"ko":"대부분의","en":"almost all of a group of people or things"}]},{"p":"adverb","senses":[{"ko":"가장, 제일","en":"to the greatest degree"}]},{"p":"pronoun","senses":[{"ko":"대부분, 최대","en":"the largest amount or number, or nearly all"}]}],"ph":[{"t":"at most","ko":"기껏해야, 많아야"},{"t":"make the most of","ko":"~을 최대한 활용하다"},{"t":"most of the time","ko":"대부분, 거의 항상"}],"ex":{"en":"Most people here speak English.","ko":"여기 사람들 대부분 영어 해."}},{"id":385,"w":"mother","def":"a female who has a child or children","pos":[{"p":"noun","senses":[{"ko":"어머니, 엄마","en":"a woman who has a child or children"}]}],"ph":[{"t":"mother tongue","ko":"모국어"},{"t":"Mother's Day","ko":"어머니날"},{"t":"mother-in-law","ko":"시어머니, 장모"}],"ex":{"en":"My mother calls me every Sunday.","ko":"엄마가 일요일마다 전화하셔."}},{"id":386,"w":"move","def":"to cause to go in a specified direction or manner","pos":[{"p":"verb","senses":[{"ko":"옮기다, 움직이다","en":"to make someone or something go to a different place or position"},{"ko":"이사하다","en":"to go to live or work in a different place"},{"ko":"감동시키다","en":"to make someone feel a strong emotion"}]},{"p":"noun","senses":[{"ko":"움직임, 조치","en":"an action you take to achieve something"}]}],"ph":[{"t":"move on","ko":"넘어가다, 잊고 나아가다"},{"t":"move in","ko":"이사 들어오다"},{"t":"Get a move on!","ko":"서둘러!"}],"ex":{"en":"Can you help me move this table?","ko":"이 테이블 옮기는 것 좀 도와줄래?"}},{"id":387,"w":"movie","def":"a film or video","pos":[{"p":"noun","senses":[{"ko":"영화","en":"a film that people watch in a theater or on a screen"}]}],"ph":[{"t":"go to the movies","ko":"영화 보러 가다"},{"t":"movie theater","ko":"영화관"},{"t":"movie night","ko":"영화 보는 밤"}],"ex":{"en":"Do you want to watch a movie tonight?","ko":"오늘 밤에 영화 볼래?"}},{"id":388,"w":"much","def":"large in amount or extent","pos":[{"p":"determiner","senses":[{"ko":"많은","en":"a large amount of something, used with uncountable nouns"}]},{"p":"adverb","senses":[{"ko":"훨씬, 많이","en":"to a great degree, or a lot"}]}],"ph":[{"t":"How much is it?","ko":"얼마예요?"},{"t":"too much","ko":"너무 많은, 지나친"},{"t":"Not much.","ko":"별일 없어, 별로"}],"ex":{"en":"I don't have much time today.","ko":"오늘 시간이 별로 없어."}},{"id":389,"w":"music","def":"the art of making sounds that are sung or played","pos":[{"p":"noun","senses":[{"ko":"음악","en":"sounds that are sung or played in a pleasing pattern"},{"ko":"악보","en":"the written signs that show how music should be played"}]}],"ph":[{"t":"listen to music","ko":"음악을 듣다"},{"t":"music to my ears","ko":"듣던 중 반가운 소리"},{"t":"face the music","ko":"책임을 지다, 벌을 받다"}],"ex":{"en":"What kind of music do you like?","ko":"어떤 음악 좋아해?"}},{"id":390,"w":"must","def":"used to say that something is required or necessary","pos":[{"p":"modal","senses":[{"ko":"~해야 한다","en":"used to say that something is required or necessary"},{"ko":"~임에 틀림없다","en":"used to say that something is very likely to be true"}]},{"p":"noun","senses":[{"ko":"필수, 꼭 해야 할 것","en":"something that you really should have, see, or do"}]}],"ph":[{"t":"a must-see","ko":"꼭 봐야 할 것"},{"t":"I must say","ko":"정말이지, 솔직히"},{"t":"You must be ...","ko":"너 ~구나, ~겠다"}],"ex":{"en":"You must wear a seat belt.","ko":"안전벨트 꼭 매야 해."}},{"id":391,"w":"myself","def":"the reflexive form of the pronouns 'me' or 'I'","pos":[{"p":"pronoun","senses":[{"ko":"나 자신, 나를","en":"used when I am the object of my own action"},{"ko":"내가 직접","en":"used to stress that I did something personally"}]}],"ph":[{"t":"by myself","ko":"혼자서"},{"t":"enjoy myself","ko":"즐거운 시간을 보내다"},{"t":"help myself","ko":"마음껏 먹다"}],"ex":{"en":"I cut myself while cooking.","ko":"요리하다가 손 베였어."}},{"id":392,"w":"name","def":"a word that addressed or refers to a specific person","pos":[{"p":"noun","senses":[{"ko":"이름","en":"a word or words used to address or refer to a specific person"},{"ko":"평판, 명성","en":"the reputation that someone or something has"}]},{"p":"verb","senses":[{"ko":"이름을 짓다","en":"to give a name to someone or something"}]}],"ph":[{"t":"What's your name?","ko":"이름이 뭐예요?"},{"t":"call someone names","ko":"~에게 욕하다, 놀리다"},{"t":"You name it.","ko":"뭐든지 다, 말만 해"}],"ex":{"en":"Sorry, what was your name again?","ko":"죄송한데, 성함이 뭐였죠?"}},{"id":393,"w":"national","def":"relating to the whole of a country","pos":[{"p":"adjective","senses":[{"ko":"국가의, 전국적인","en":"relating to or involving a whole country"},{"ko":"국립의","en":"owned or run by the government of a country"}]}],"ph":[{"t":"national holiday","ko":"국경일, 공휴일"},{"t":"national park","ko":"국립공원"},{"t":"national anthem","ko":"국가 (노래)"}],"ex":{"en":"Tomorrow is a national holiday.","ko":"내일 공휴일이야."}},{"id":394,"w":"near","def":"close to something","pos":[{"p":"preposition","senses":[{"ko":"~ 가까이에, ~ 근처에","en":"close to someone or something"}]},{"p":"adjective","senses":[{"ko":"가까운","en":"only a short distance or time away"}]},{"p":"adverb","senses":[{"ko":"가까이","en":"at or to a short distance away"}]}],"ph":[{"t":"near here","ko":"이 근처에"},{"t":"in the near future","ko":"가까운 미래에, 머지않아"},{"t":"nowhere near","ko":"전혀 ~않은, 한참 먼"}],"ex":{"en":"Is there a bank near here?","ko":"이 근처에 은행 있어요?"}},{"id":395,"w":"need","def":"require because it is essential or important","pos":[{"p":"verb","senses":[{"ko":"필요하다","en":"to require something because it is essential or important"},{"ko":"~해야 한다","en":"to have to do something"}]},{"p":"noun","senses":[{"ko":"필요, 욕구","en":"a situation in which something is necessary or wanted"}]}],"ph":[{"t":"no need to","ko":"~할 필요 없어"},{"t":"Need a hand?","ko":"도와줄까?"},{"t":"in need","ko":"어려움에 처한"}],"ex":{"en":"I need a coffee right now.","ko":"지금 커피가 꼭 필요해."}},{"id":396,"w":"never","def":"not ever, not at any time","pos":[{"p":"adverb","senses":[{"ko":"결코 ~않다, 한 번도","en":"not ever, or not at any time"},{"ko":"전혀 ~하지 않다","en":"used as a strong way of saying not"}]}],"ph":[{"t":"Never mind.","ko":"신경 쓰지 마"},{"t":"never ever","ko":"절대로"},{"t":"Better late than never.","ko":"늦더라도 안 하는 것보단 낫다"}],"ex":{"en":"I've never been to Japan.","ko":"나 일본 한 번도 안 가 봤어."}},{"id":397,"w":"new","def":"not old, recently born, built or created","pos":[{"p":"adjective","senses":[{"ko":"새로운, 새","en":"not old, and recently made, built, or born"},{"ko":"처음 보는, 낯선","en":"not known, seen, or experienced before"},{"ko":"갓 온, 신입의","en":"having recently arrived or started something"}]}],"ph":[{"t":"What's new?","ko":"별일 없어?, 요즘 어때?"},{"t":"brand new","ko":"완전 새것인"},{"t":"Happy New Year!","ko":"새해 복 많이 받아!"}],"ex":{"en":"I just bought a new phone.","ko":"나 새 폰 샀어."}},{"id":398,"w":"news","def":"new information or a report about something that has happened recently","pos":[{"p":"noun","senses":[{"ko":"소식, 새로운 정보","en":"new information or a report about something that happened recently"},{"ko":"뉴스 (방송)","en":"a TV or radio program that reports recent events"}]}],"ph":[{"t":"good news","ko":"좋은 소식"},{"t":"That's news to me.","ko":"금시초문이야"},{"t":"break the news","ko":"(안 좋은) 소식을 전하다"}],"ex":{"en":"I have some good news for you!","ko":"너한테 좋은 소식 있어!"}},{"id":399,"w":"next","def":"coming immediately after this time","pos":[{"p":"adjective","senses":[{"ko":"다음의","en":"coming immediately after this one in time or order"},{"ko":"바로 옆의","en":"nearest in place, such as the next room or seat"}]},{"p":"adverb","senses":[{"ko":"그다음에","en":"immediately after something else happens"}]}],"ph":[{"t":"next to","ko":"~ 옆에"},{"t":"next time","ko":"다음번에"},{"t":"Who's next?","ko":"다음 분 누구세요?"}],"ex":{"en":"See you next week!","ko":"다음 주에 봐!"}},{"id":400,"w":"nice","def":"giving pleasure or joy : good and enjoyable","pos":[{"p":"adjective","senses":[{"ko":"좋은, 즐거운","en":"pleasant, enjoyable, or good"},{"ko":"친절한, 착한","en":"kind and friendly to other people"}]}],"ph":[{"t":"Nice to meet you.","ko":"만나서 반가워요"},{"t":"Have a nice day.","ko":"좋은 하루 보내세요"},{"t":"Nice try.","ko":"시도는 좋았어"}],"ex":{"en":"We had a really nice time.","ko":"우리 정말 즐거운 시간 보냈어."}},{"id":401,"w":"night","def":"the period of time of darkness between sunset and sunrise","pos":[{"p":"noun","senses":[{"ko":"밤","en":"the dark time between sunset and sunrise"},{"ko":"저녁","en":"the evening, the time before you go to bed"}]}],"ph":[{"t":"Good night.","ko":"잘 자, 안녕히 주무세요"},{"t":"last night","ko":"어젯밤"},{"t":"night out","ko":"밖에서 노는 밤"}],"ex":{"en":"I couldn't sleep last night.","ko":"어젯밤에 잠을 못 잤어."}},{"id":402,"w":"nine","def":"the number 9","pos":[{"p":"number","senses":[{"ko":"아홉, 9","en":"the number 9, one more than eight"}]}],"ph":[{"t":"nine to five","ko":"9시부터 5시까지 (평범한 직장 일)"},{"t":"on cloud nine","ko":"너무 행복한"}],"ex":{"en":"I start work at nine.","ko":"나 9시에 일 시작해."}},{"id":403,"w":"nineteen","def":"the number 19","pos":[{"p":"number","senses":[{"ko":"열아홉, 19","en":"the number 19, one more than eighteen"}]}],"ph":[],"ex":{"en":"She's only nineteen years old.","ko":"걔 아직 열아홉 살밖에 안 됐어."}},{"id":404,"w":"ninety","def":"the number 90","pos":[{"p":"number","senses":[{"ko":"아흔, 90","en":"the number 90, nine times ten"},{"ko":"90년대","en":"the years from 1990 to 1999, when used as the nineties"}]}],"ph":[{"t":"in the nineties","ko":"90년대에"}],"ex":{"en":"My grandma is ninety this year.","ko":"우리 할머니 올해 아흔이셔."}},{"id":405,"w":"no","def":"not at all, in a way that shows a negative response","pos":[{"p":"adverb","senses":[{"ko":"아니, 아니요","en":"used to give a negative answer or to refuse something"},{"ko":"조금도 ~않은","en":"not at all, used before words like better or more"}]},{"p":"determiner","senses":[{"ko":"어떤 ~도 없는","en":"not any, or not even one"}]}],"ph":[{"t":"No way!","ko":"말도 안 돼!, 절대 안 돼!"},{"t":"No problem.","ko":"문제없어, 천만에"},{"t":"no longer","ko":"더 이상 ~않다"}],"ex":{"en":"No, thanks. I'm full.","ko":"아니, 괜찮아. 배불러."}},{"id":406,"w":"nobody","def":"no person, no one","pos":[{"p":"pronoun","senses":[{"ko":"아무도 ~않다","en":"no person, or not anyone"}]},{"p":"noun","senses":[{"ko":"보잘것없는 사람","en":"a person who is not important or famous"}]}],"ph":[{"t":"Nobody knows.","ko":"아무도 몰라"},{"t":"Nobody's perfect.","ko":"완벽한 사람은 없어"}],"ex":{"en":"Nobody answered the phone.","ko":"아무도 전화를 안 받았어."}},{"id":407,"w":"noise","def":"a loud or unpleasant sound","pos":[{"p":"noun","senses":[{"ko":"소음, 시끄러운 소리","en":"a loud or unpleasant sound"},{"ko":"소리","en":"any sound, especially one you cannot identify"}]}],"ph":[{"t":"make noise","ko":"떠들다, 소리를 내다"},{"t":"background noise","ko":"주변 소음"}],"ex":{"en":"What's that noise outside?","ko":"밖에 저 소리 뭐야?"}},{"id":408,"w":"normally","def":"usually","pos":[{"p":"adverb","senses":[{"ko":"보통, 평소에","en":"usually, or in most cases"},{"ko":"정상적으로","en":"in a normal or ordinary way"}]}],"ph":[{"t":"I don't normally ...","ko":"평소엔 ~ 안 하는데"}],"ex":{"en":"I normally get up at seven.","ko":"나 보통 7시에 일어나."}},{"id":409,"w":"not","def":"used to make an expression negative","pos":[{"p":"adverb","senses":[{"ko":"~ 아니다, ~ 않다","en":"used to make a word, phrase, or sentence negative"}]}],"ph":[{"t":"not at all","ko":"전혀요, 천만에요"},{"t":"not really","ko":"별로, 그렇진 않아"},{"t":"not yet","ko":"아직"}],"ex":{"en":"I'm not hungry right now.","ko":"나 지금 배 안 고파."}},{"id":410,"w":"note","def":"a brief, short record of something","pos":[{"p":"noun","senses":[{"ko":"메모, 쪽지","en":"a short written record or message"},{"ko":"음, 음표","en":"a single musical sound, or the sign that shows it"}]},{"p":"verb","senses":[{"ko":"주목하다, 적어 두다","en":"to notice or pay attention to something, or write it down"}]}],"ph":[{"t":"take notes","ko":"필기하다"},{"t":"leave a note","ko":"메모를 남기다"},{"t":"make a note of","ko":"~을 적어 두다, 기억해 두다"}],"ex":{"en":"I left you a note on the fridge.","ko":"냉장고에 메모 남겨 놨어."}},{"id":411,"w":"nothing","def":"not anything, no a single thing","pos":[{"p":"pronoun","senses":[{"ko":"아무것도 ~않다","en":"not anything, or not a single thing"},{"ko":"별것 아닌 것","en":"something that has no importance or value"}]}],"ph":[{"t":"Nothing much.","ko":"별일 없어"},{"t":"It's nothing.","ko":"별거 아니야"},{"t":"for nothing","ko":"공짜로; 헛되이"}],"ex":{"en":"There's nothing in the fridge.","ko":"냉장고에 아무것도 없어."}},{"id":412,"w":"notice","def":"to become aware of (something or someone) by seeing, hearing, etc.","pos":[{"p":"verb","senses":[{"ko":"알아차리다, 눈치채다","en":"to become aware of something by seeing or hearing it"}]},{"p":"noun","senses":[{"ko":"공지, 안내문","en":"a written announcement that gives information"},{"ko":"예고, 통보","en":"information or a warning that something is going to happen"}]}],"ph":[{"t":"at short notice","ko":"갑작스럽게, 촉박하게"},{"t":"until further notice","ko":"추후 공지가 있을 때까지"},{"t":"take notice of","ko":"~에 주목하다"}],"ex":{"en":"Did you notice her new haircut?","ko":"걔 머리 새로 한 거 봤어?"}},{"id":413,"w":"now","def":"at the present time or moment","pos":[{"p":"adverb","senses":[{"ko":"지금, 현재","en":"at the present time or moment"},{"ko":"자, 이제","en":"used to get attention or to change the subject"}]}],"ph":[{"t":"right now","ko":"지금 당장"},{"t":"for now","ko":"당분간, 일단은"},{"t":"now that","ko":"~이니까, 이제 ~하니"}],"ex":{"en":"I'm busy right now, I'll call you later.","ko":"지금 바빠, 나중에 전화할게."}},{"id":414,"w":"number","def":"a word or symbol that stands for a specific amount or quantity","pos":[{"p":"noun","senses":[{"ko":"수, 숫자","en":"a word or symbol that stands for a specific amount"},{"ko":"번호","en":"a number used to identify something, such as a phone or room"},{"ko":"수량, 다수","en":"an amount of people or things"}]}],"ph":[{"t":"phone number","ko":"전화번호"},{"t":"a number of","ko":"여러, 다수의"},{"t":"wrong number","ko":"잘못 건 전화"}],"ex":{"en":"Pick a number between one and ten.","ko":"1부터 10 사이 숫자 하나 골라 봐."}},{"id":415,"w":"obviously","def":"in a way that is easy to understand or see","pos":[{"p":"adverb","senses":[{"ko":"분명히, 확실히","en":"in a way that is easy to see or understand"},{"ko":"당연히, 물론","en":"used to say that something is expected or already known"}]}],"ph":[],"ex":{"en":"She was obviously upset.","ko":"걔 확실히 기분 상해 보였어."}},{"id":416,"w":"of","def":"belonging to or connected with something","pos":[{"p":"preposition","senses":[{"ko":"~의","en":"belonging to or connected with someone or something"},{"ko":"~ 중의","en":"used to show a part of a larger group or amount"},{"ko":"~로 된, ~이 든","en":"used to show what something contains or is made of"}]}],"ph":[{"t":"of course","ko":"물론이지"},{"t":"a lot of","ko":"많은"},{"t":"kind of","ko":"좀, 약간"}],"ex":{"en":"She's a friend of my sister.","ko":"걔 우리 언니 친구야."}},{"id":417,"w":"off","def":"away from a place or at a distance","pos":[{"p":"adverb","senses":[{"ko":"떨어져, 멀리","en":"away from a place or at a distance"},{"ko":"꺼져서","en":"not working or not switched on"},{"ko":"쉬는, 비번인","en":"not at work or school"},{"ko":"할인되어","en":"taken away from the usual price, as in twenty percent off"}]},{"p":"preposition","senses":[{"ko":"~에서 떨어져","en":"away from or down from the surface of something"}]},{"p":"adjective","senses":[{"ko":"이상한, 상한","en":"not quite right, or no longer fresh, used about food or feelings"}]}],"ph":[{"t":"day off","ko":"쉬는 날"},{"t":"turn off","ko":"(전원을) 끄다"},{"t":"Off you go.","ko":"어서 가 봐"}],"ex":{"en":"He drove off without saying goodbye.","ko":"걔 인사도 없이 차 몰고 가 버렸어."}},{"id":418,"w":"offer","def":"to give someone the opportunity to accept something","pos":[{"p":"verb","senses":[{"ko":"제안하다, 권하다","en":"to give someone the chance to accept or refuse something"},{"ko":"제공하다","en":"to make something available to people"}]},{"p":"noun","senses":[{"ko":"제안, 제의","en":"an act of offering something to someone"},{"ko":"할인, 특가","en":"a lower price for something for a short time"}]}],"ph":[{"t":"job offer","ko":"일자리 제안"},{"t":"special offer","ko":"특가 판매"},{"t":"offer to help","ko":"돕겠다고 하다"}],"ex":{"en":"Can I offer you a drink?","ko":"음료 한 잔 드릴까요?"}},{"id":419,"w":"office","def":"a building of set of rooms used to do business or professional activities","pos":[{"p":"noun","senses":[{"ko":"사무실, 회사","en":"a building or rooms where people work, usually at desks"},{"ko":"직무, 관직","en":"an important position, especially in government"}]}],"ph":[{"t":"at the office","ko":"회사에서"},{"t":"office hours","ko":"근무 시간"},{"t":"head office","ko":"본사"}],"ex":{"en":"I'm still at the office.","ko":"나 아직 사무실이야."}},{"id":420,"w":"often","def":"many times, frequently, on many occasions","pos":[{"p":"adverb","senses":[{"ko":"자주, 흔히","en":"many times, or on many occasions"}]}],"ph":[{"t":"How often ...?","ko":"얼마나 자주 ~?"},{"t":"every so often","ko":"가끔, 이따금"},{"t":"more often than not","ko":"대개, 자주"}],"ex":{"en":"How often do you work out?","ko":"운동 얼마나 자주 해?"}},{"id":421,"w":"okay","def":"used when agreeing to do something or when allowing someone to do something","pos":[{"p":"interjection","senses":[{"ko":"좋아, 알았어","en":"used to agree or to allow something"}]},{"p":"adjective","senses":[{"ko":"괜찮은, 무사한","en":"not bad, acceptable, or safe and well"}]}],"ph":[{"t":"Are you okay?","ko":"괜찮아?"},{"t":"It's okay.","ko":"괜찮아, 문제없어"}],"ex":{"en":"Okay, let's meet at six.","ko":"좋아, 여섯 시에 만나자."}},{"id":422,"w":"old","def":"having lived for many years, no longer young","pos":[{"p":"adjective","senses":[{"ko":"늙은, 나이 든","en":"having lived for many years and no longer young"},{"ko":"오래된, 낡은","en":"having existed or been used for a long time"},{"ko":"예전의","en":"from an earlier time, or used before"}]}],"ph":[{"t":"How old are you?","ko":"몇 살이야?"},{"t":"old friend","ko":"오랜 친구"},{"t":"the good old days","ko":"좋았던 옛날"}],"ex":{"en":"My dog is getting old.","ko":"우리 개가 점점 늙어 가."}},{"id":423,"w":"on","def":"touching and being supported or physically in contact by something","pos":[{"p":"preposition","senses":[{"ko":"~ 위에","en":"touching and supported by the surface of something"},{"ko":"(날짜, 요일) ~에","en":"used to show the day or date something happens"},{"ko":"~에 관한","en":"about a particular subject"},{"ko":"(TV·전화 등) ~로, ~에서","en":"using a device or being broadcast by it, as in on TV or on the phone"}]},{"p":"adverb","senses":[{"ko":"켜져, 작동 중인","en":"working or switched on"},{"ko":"계속해서","en":"continuing an action without stopping"}]}],"ph":[{"t":"Come on!","ko":"어서!, 제발!"},{"t":"go on","ko":"계속하다; 일어나다"},{"t":"on and off","ko":"이따금, 했다 말았다"}],"ex":{"en":"Your keys are on the table.","ko":"네 열쇠 테이블 위에 있어."}},{"id":424,"w":"once","def":"one time only","pos":[{"p":"adverb","senses":[{"ko":"한 번","en":"one time only, and no more"},{"ko":"한때, 예전에","en":"at some time in the past"}]},{"p":"conjunction","senses":[{"ko":"~하자마자, 일단 ~하면","en":"as soon as, or from the moment that"}]}],"ph":[{"t":"at once","ko":"즉시; 한꺼번에"},{"t":"once in a while","ko":"가끔"},{"t":"for once","ko":"이번만은"}],"ex":{"en":"I've only been there once.","ko":"거기 딱 한 번 가 봤어."}},{"id":425,"w":"one","def":"the number 1, a single person or thing","pos":[{"p":"number","senses":[{"ko":"하나, 1, 한 개","en":"the number 1, or a single person or thing"}]},{"p":"pronoun","senses":[{"ko":"(앞에 나온) 것, 사람","en":"used instead of a noun to avoid repeating it"}]}],"ph":[{"t":"one day","ko":"언젠가; 어느 날"},{"t":"one by one","ko":"하나씩, 한 명씩"},{"t":"this one","ko":"이거"}],"ex":{"en":"Just one coffee, please.","ko":"커피 한 잔만 주세요."}},{"id":426,"w":"only","def":"alone in a class or category","pos":[{"p":"adjective","senses":[{"ko":"유일한","en":"being the single one of its kind or in its group"}]},{"p":"adverb","senses":[{"ko":"~만, 오직","en":"nothing more or nobody else than"},{"ko":"겨우, 불과","en":"used to say that an amount or time is small"}]}],"ph":[{"t":"only child","ko":"외동"},{"t":"if only","ko":"~라면 좋을 텐데"},{"t":"not only ... but also","ko":"~뿐만 아니라 ~도"}],"ex":{"en":"I'm the only one who knows.","ko":"아는 사람은 나뿐이야."}},{"id":427,"w":"open","def":"not closed","pos":[{"p":"adjective","senses":[{"ko":"열린","en":"not closed, so things can pass through"},{"ko":"영업 중인","en":"ready for customers or visitors"},{"ko":"솔직한, 개방적인","en":"honest and willing to talk or to accept new ideas"}]},{"p":"verb","senses":[{"ko":"열다, 열리다","en":"to move something so that it is no longer closed"}]}],"ph":[{"t":"open up","ko":"마음을 열다; 문을 열다"},{"t":"open-minded","ko":"열린 마음의"},{"t":"in the open","ko":"야외에서; 공공연하게"}],"ex":{"en":"Leave the window open, please.","ko":"창문 좀 열어 둬."}},{"id":428,"w":"opportunity","def":"an amount of time or a situation in which something can be done","pos":[{"p":"noun","senses":[{"ko":"기회","en":"a time or situation that makes it possible to do something"}]}],"ph":[{"t":"take the opportunity","ko":"기회를 잡다"},{"t":"a golden opportunity","ko":"절호의 기회"},{"t":"miss an opportunity","ko":"기회를 놓치다"}],"ex":{"en":"This is a great opportunity for you.","ko":"이건 너한테 좋은 기회야."}},{"id":429,"w":"or","def":"used to link alternatives, to introduce another choice","pos":[{"p":"conjunction","senses":[{"ko":"또는, 아니면","en":"used to link alternatives or to introduce another choice"},{"ko":"그렇지 않으면","en":"used to warn what will happen if something is not done"}]}],"ph":[{"t":"or so","ko":"~쯤, 대략"},{"t":"or something","ko":"~ 같은 거, 뭐 그런 거"},{"t":"either ... or","ko":"~이거나 ~이거나"}],"ex":{"en":"Do you want tea or coffee?","ko":"차 마실래, 커피 마실래?"}},{"id":430,"w":"order","def":"an instruction or direction that must be obeyed","pos":[{"p":"noun","senses":[{"ko":"명령, 지시","en":"an instruction or direction that must be obeyed"},{"ko":"주문","en":"a request for food, drinks, or goods"},{"ko":"순서, 질서","en":"the way things are arranged, or a state of being neat"}]},{"p":"verb","senses":[{"ko":"주문하다","en":"to ask for food, drinks, or goods"},{"ko":"명령하다","en":"to tell someone that they must do something"}]}],"ph":[{"t":"in order to","ko":"~하기 위해"},{"t":"out of order","ko":"고장 난"},{"t":"Are you ready to order?","ko":"주문하시겠어요?"}],"ex":{"en":"Soldiers have to follow orders.","ko":"군인은 명령을 따라야 해."}},{"id":431,"w":"other","def":"used to mention a person or thing is different from already mentioned","pos":[{"p":"determiner","senses":[{"ko":"다른","en":"different from the person or thing already mentioned"},{"ko":"나머지의","en":"used to mean the rest of a group"}]},{"p":"pronoun","senses":[{"ko":"다른 사람, 다른 것","en":"a different person or thing, or the remaining ones"}]}],"ph":[{"t":"the other day","ko":"요전에, 며칠 전에"},{"t":"each other","ko":"서로"},{"t":"on the other hand","ko":"반면에"}],"ex":{"en":"Do you have this in other colors?","ko":"이거 다른 색도 있어요?"}},{"id":432,"w":"ought","def":"used to indicate what is expected","pos":[{"p":"modal","senses":[{"ko":"~해야 한다, ~하는 게 맞다","en":"used to say what is expected or the right thing to do"},{"ko":"~일 것이다","en":"used to say that something will probably happen or be true"}]}],"ph":[{"t":"ought to","ko":"~해야 한다"},{"t":"You ought to know.","ko":"네가 알아야지"}],"ex":{"en":"You ought to see a doctor.","ko":"너 병원 가 봐야겠다."}},{"id":433,"w":"out","def":"in a direction or movement away from the inside or center","pos":[{"p":"adverb","senses":[{"ko":"밖으로","en":"in a direction away from the inside or center"},{"ko":"외출 중인","en":"away from your home or workplace"},{"ko":"꺼진, 다 떨어진","en":"no longer burning, or with none left"},{"ko":"나와서, 출시되어","en":"available to the public, such as a new movie or product"}]}],"ph":[{"t":"out of","ko":"~에서 밖으로; ~이 다 떨어진"},{"t":"find out","ko":"알아내다"},{"t":"work out","ko":"운동하다; 잘 풀리다"}],"ex":{"en":"She went out for a walk.","ko":"걔 산책하러 나갔어."}},{"id":434,"w":"outside","def":"an area around or near something such as a building","pos":[{"p":"noun","senses":[{"ko":"바깥, 외부","en":"the outer side of something, or the area around a building"}]},{"p":"adverb","senses":[{"ko":"밖에서, 밖으로","en":"in or to the area outside a building"}]},{"p":"preposition","senses":[{"ko":"~ 밖에","en":"beyond the outer side or limits of something"}]}],"ph":[{"t":"go outside","ko":"밖에 나가다"},{"t":"outside of","ko":"~ 밖에; ~ 이외에"},{"t":"on the outside","ko":"겉으로는"}],"ex":{"en":"The outside of the house needs painting.","ko":"집 바깥쪽에 페인트칠해야 돼."}},{"id":435,"w":"over","def":"in an upward direction across something","pos":[{"p":"preposition","senses":[{"ko":"~ 위로, ~을 넘어","en":"above or across something from one side to the other"},{"ko":"~ 이상","en":"more than a certain amount or number"},{"ko":"~하는 동안","en":"during a period of time"}]},{"p":"adverb","senses":[{"ko":"이리로, 건너서","en":"across a space, toward or away from someone"}]},{"p":"adjective","senses":[{"ko":"끝난","en":"finished, or come to an end"}]}],"ph":[{"t":"come over","ko":"(집에) 놀러 오다"},{"t":"over there","ko":"저쪽에"},{"t":"It's over.","ko":"끝났어"}],"ex":{"en":"The cat jumped over the fence.","ko":"고양이가 울타리를 뛰어넘었어."}},{"id":436,"w":"own","def":"when something belongs to someone","pos":[{"p":"adjective","senses":[{"ko":"자기 자신의","en":"belonging to a particular person and no one else"}]},{"p":"verb","senses":[{"ko":"소유하다","en":"to have something that legally belongs to you"}]}],"ph":[{"t":"on your own","ko":"혼자서, 스스로"},{"t":"of your own","ko":"자기 소유의"},{"t":"own up","ko":"자백하다, 인정하다"}],"ex":{"en":"I want my own room.","ko":"나 내 방 갖고 싶어."}},{"id":437,"w":"page","def":"one side of a sheet of paper especially in a book, magazine, etc.","pos":[{"p":"noun","senses":[{"ko":"페이지, 쪽","en":"one side of a sheet of paper in a book, magazine, etc"},{"ko":"(웹) 페이지","en":"a single screen of information on a website"}]}],"ph":[{"t":"on the same page","ko":"생각이 같은"},{"t":"turn the page","ko":"새 출발하다"},{"t":"front page","ko":"(신문) 1면"}],"ex":{"en":"Open your books to page ten.","ko":"책 10쪽 펴세요."}},{"id":438,"w":"paper","def":"the material that is used in the form of thin sheets for writing","pos":[{"p":"noun","senses":[{"ko":"종이","en":"material in thin sheets used for writing, printing, or wrapping"},{"ko":"신문","en":"a newspaper, or a single copy of one"},{"ko":"서류, 리포트","en":"an official document, or a piece of writing for school"}]}],"ph":[{"t":"a piece of paper","ko":"종이 한 장"},{"t":"on paper","ko":"서류상으로는, 이론상"},{"t":"paper towel","ko":"종이 타월"}],"ex":{"en":"Do you have a pen and paper?","ko":"펜이랑 종이 있어?"}},{"id":439,"w":"parent","def":"a person who is a father or mother","pos":[{"p":"noun","senses":[{"ko":"부모 (아버지, 어머니)","en":"a person who is a father or mother"}]}],"ph":[{"t":"single parent","ko":"한부모"},{"t":"parents-in-law","ko":"시부모, 처부모"}],"ex":{"en":"My parents live in Busan.","ko":"우리 부모님은 부산에 사셔."}},{"id":440,"w":"park","def":"a piece of public land in or near a city that can be used for pleasure and exercise","pos":[{"p":"noun","senses":[{"ko":"공원","en":"a public area of land in a city for people to enjoy and exercise"}]},{"p":"verb","senses":[{"ko":"주차하다","en":"to leave a car or other vehicle in a place for a time"}]}],"ph":[{"t":"parking lot","ko":"주차장"},{"t":"theme park","ko":"놀이공원"},{"t":"a walk in the park","ko":"식은 죽 먹기"}],"ex":{"en":"Let's take a walk in the park.","ko":"공원에서 산책하자."}},{"id":441,"w":"part","def":"one of the pieces of a whole","pos":[{"p":"noun","senses":[{"ko":"부분, 일부","en":"one of the pieces that together make up a whole"},{"ko":"역할, 배역","en":"a role in a play, movie, or activity"},{"ko":"부품","en":"a piece of a machine"}]}],"ph":[{"t":"take part in","ko":"~에 참여하다"},{"t":"for the most part","ko":"대체로"},{"t":"the best part","ko":"가장 좋은 부분"}],"ex":{"en":"The first part of the movie was boring.","ko":"영화 앞부분이 지루했어."}},{"id":442,"w":"particular","def":"used to single out an individual member","pos":[{"p":"adjective","senses":[{"ko":"특정한","en":"used to single out one person or thing from others"},{"ko":"특별한, 각별한","en":"special, or greater than usual"},{"ko":"까다로운","en":"very careful about choosing only what you like"}]}],"ph":[{"t":"in particular","ko":"특히"},{"t":"nothing in particular","ko":"특별한 건 없어"}],"ex":{"en":"Is there a particular reason?","ko":"무슨 특별한 이유라도 있어?"}},{"id":443,"w":"particularly","def":"especially","pos":[{"p":"adverb","senses":[{"ko":"특히, 특별히","en":"especially, or more than usual"}]}],"ph":[{"t":"not particularly","ko":"별로, 딱히"}],"ex":{"en":"I'm not particularly hungry.","ko":"딱히 배고프진 않아."}},{"id":444,"w":"party","def":"an organization of people who have the same political beliefs","pos":[{"p":"noun","senses":[{"ko":"정당","en":"an organization of people who share the same political beliefs"},{"ko":"파티","en":"a social event where people meet to enjoy themselves"},{"ko":"일행, 당사자","en":"a group of people doing something together, or one side in a deal"}]},{"p":"verb","senses":[{"ko":"파티를 하다, 놀다","en":"to enjoy yourself at a party or with friends"}]}],"ph":[{"t":"throw a party","ko":"파티를 열다"},{"t":"birthday party","ko":"생일 파티"},{"t":"party animal","ko":"파티광, 노는 거 좋아하는 사람"}],"ex":{"en":"Which party did you vote for?","ko":"너 어느 당 찍었어?"}},{"id":445,"w":"pass","def":"to move past something","pos":[{"p":"verb","senses":[{"ko":"지나가다","en":"to move past someone or something"},{"ko":"건네주다","en":"to give something to someone with your hand"},{"ko":"합격하다, 통과하다","en":"to succeed in a test or exam"}]},{"p":"noun","senses":[{"ko":"출입증, 탑승권","en":"a ticket or card that lets you enter or travel"}]}],"ph":[{"t":"pass away","ko":"돌아가시다"},{"t":"pass out","ko":"기절하다"},{"t":"I'll pass.","ko":"난 됐어, 사양할게"}],"ex":{"en":"I pass that bakery on my way home.","ko":"집에 가는 길에 그 빵집 지나가."}},{"id":446,"w":"past","def":"a time before the present","pos":[{"p":"noun","senses":[{"ko":"과거","en":"the time before the present"}]},{"p":"adjective","senses":[{"ko":"지난, 과거의","en":"having happened or existed before now"}]},{"p":"preposition","senses":[{"ko":"~을 지나, ~ 넘어서","en":"beyond a place, or later than a particular time"}]}],"ph":[{"t":"in the past","ko":"과거에, 예전에"},{"t":"half past","ko":"~시 반"},{"t":"past my bedtime","ko":"내 잘 시간이 지난"}],"ex":{"en":"Let's just forget about the past.","ko":"그냥 과거는 잊자."}},{"id":447,"w":"pause","def":"a temporary stop : a period of time in which something is stopped before it is started again","pos":[{"p":"noun","senses":[{"ko":"멈춤, 잠깐 쉼","en":"a short stop before something starts again"}]},{"p":"verb","senses":[{"ko":"잠시 멈추다","en":"to stop doing something for a short time"}]}],"ph":[{"t":"hit pause","ko":"일시정지를 누르다"},{"t":"pause for breath","ko":"숨을 돌리다"}],"ex":{"en":"There was a long pause before she answered.","ko":"걔가 대답하기 전에 한참 말이 없었어."}},{"id":448,"w":"pay","def":"give money for goods or work done","pos":[{"p":"verb","senses":[{"ko":"지불하다, 돈을 내다","en":"to give money for goods or for work that was done"},{"ko":"(대가를) 치르다","en":"to suffer because of something you did"}]},{"p":"noun","senses":[{"ko":"급여, 보수","en":"the money you get for doing a job"}]}],"ph":[{"t":"pay attention","ko":"주의를 기울이다"},{"t":"pay back","ko":"(돈을) 갚다"},{"t":"pay off","ko":"성과를 거두다; 다 갚다"}],"ex":{"en":"Let me pay for dinner tonight.","ko":"오늘 저녁은 내가 낼게."}},{"id":449,"w":"people","def":"human beings in general, plural of person","pos":[{"p":"noun","senses":[{"ko":"사람들","en":"human beings in general, the plural of person"},{"ko":"국민, 민족","en":"all the people who live in a country or share a culture"}]}],"ph":[{"t":"most people","ko":"대부분의 사람들"},{"t":"people person","ko":"사교적인 사람"},{"t":"People say ...","ko":"사람들이 그러는데 ~"}],"ex":{"en":"There were so many people at the concert.","ko":"콘서트에 사람 엄청 많았어."}},{"id":450,"w":"per","def":"for each one, by means of, as directed by or stated in","pos":[{"p":"preposition","senses":[{"ko":"~당, ~마다","en":"for each one, used in prices, rates, and amounts"},{"ko":"~에 따라","en":"according to or as stated in something"}]}],"ph":[{"t":"per person","ko":"1인당"},{"t":"per hour","ko":"시간당"},{"t":"as per usual","ko":"늘 그렇듯이"}],"ex":{"en":"It's ten dollars per person.","ko":"1인당 10달러야."}},{"id":451,"w":"percent","def":"a certain part of a whole","pos":[{"p":"noun","senses":[{"ko":"퍼센트, 백분율","en":"a part of a whole, shown as a number out of 100"}]}],"ph":[{"t":"a hundred percent","ko":"백 퍼센트, 완전히"}],"ex":{"en":"Only ten percent of us passed.","ko":"우리 중 10퍼센트만 붙었어."}},{"id":452,"w":"perhaps","def":"possibly but not certainly, maybe","pos":[{"p":"adverb","senses":[{"ko":"아마, 어쩌면","en":"possibly but not certainly, or maybe"},{"ko":"~하면 어떨까요","en":"used to make a polite suggestion or request"}]}],"ph":[{"t":"perhaps not","ko":"아닐 수도 있어요"}],"ex":{"en":"Perhaps he forgot about it.","ko":"어쩌면 걔가 그거 잊어버렸나 봐."}},{"id":453,"w":"period","def":"a length or portion of time during a series of events","pos":[{"p":"noun","senses":[{"ko":"기간, 시기","en":"a length of time during which something happens"},{"ko":"마침표","en":"the dot used at the end of a sentence"},{"ko":"생리","en":"the monthly bleeding from a woman's body"}]}],"ph":[{"t":"Period.","ko":"끝, 더 말할 것 없어"},{"t":"trial period","ko":"시험 기간, 체험 기간"},{"t":"for a period of","ko":"~ 동안"}],"ex":{"en":"It was a hard period in my life.","ko":"내 인생에서 힘든 시기였어."}},{"id":454,"w":"person","def":"a human being","pos":[{"p":"noun","senses":[{"ko":"사람","en":"a human being, a man, woman, or child"},{"ko":"~형 사람, ~파","en":"someone who likes or is good at a particular thing"}]}],"ph":[{"t":"in person","ko":"직접, 몸소"},{"t":"morning person","ko":"아침형 인간"},{"t":"cat person","ko":"고양이파"}],"ex":{"en":"She's a really nice person.","ko":"걔 진짜 좋은 사람이야."}},{"id":455,"w":"phone","def":"a communication system that is used to talk to someone who is in another place","pos":[{"p":"noun","senses":[{"ko":"전화, 전화기","en":"a system or device used to talk to someone in another place"},{"ko":"휴대폰","en":"a mobile phone that you carry with you"}]},{"p":"verb","senses":[{"ko":"전화하다","en":"to call someone using a phone"}]}],"ph":[{"t":"on the phone","ko":"통화 중인"},{"t":"answer the phone","ko":"전화를 받다"},{"t":"phone call","ko":"전화 통화"}],"ex":{"en":"Sorry, I was on the phone.","ko":"미안, 통화 중이었어."}},{"id":456,"w":"pick","def":"to choose or select (someone or something) from a group","pos":[{"p":"verb","senses":[{"ko":"고르다, 선택하다","en":"to choose someone or something from a group"},{"ko":"따다, 꺾다","en":"to take a flower, fruit, or leaf from a plant"}]},{"p":"noun","senses":[{"ko":"선택, 고른 것","en":"a choice, or the person or thing chosen"}]}],"ph":[{"t":"pick up","ko":"집어 들다; 데리러 가다"},{"t":"Take your pick.","ko":"마음대로 골라"},{"t":"pick on","ko":"괴롭히다, 트집 잡다"}],"ex":{"en":"Pick any card you like.","ko":"아무 카드나 골라 봐."}},{"id":457,"w":"picture","def":"a painting, drawing or photograph on paper or screen","pos":[{"p":"noun","senses":[{"ko":"그림, 사진","en":"a painting, drawing, or photograph on paper or a screen"},{"ko":"상황, 모습","en":"an idea or description of what something is like"}]},{"p":"verb","senses":[{"ko":"상상하다, 그려 보다","en":"to imagine something in your mind"}]}],"ph":[{"t":"take a picture","ko":"사진을 찍다"},{"t":"get the picture","ko":"이해하다, 감 잡다"},{"t":"the big picture","ko":"큰 그림, 전체 상황"}],"ex":{"en":"Can you take a picture of us?","ko":"우리 사진 좀 찍어 줄래요?"}},{"id":458,"w":"piece","def":"a part that is cut or separated from a whole","pos":[{"p":"noun","senses":[{"ko":"조각","en":"a part that is cut or separated from a whole"},{"ko":"한 개, 한 장","en":"a single item of a particular kind"}]}],"ph":[{"t":"a piece of cake","ko":"식은 죽 먹기"},{"t":"in one piece","ko":"무사히, 멀쩡히"},{"t":"a piece of advice","ko":"조언 한마디"}],"ex":{"en":"Can I have a piece of pizza?","ko":"피자 한 조각 먹어도 돼?"}},{"id":459,"w":"place","def":"a particular area or region","pos":[{"p":"noun","senses":[{"ko":"장소, 곳","en":"a particular area, region, or point"},{"ko":"집","en":"the house or apartment where someone lives"},{"ko":"자리, 위치","en":"a position or seat for someone or something"}]},{"p":"verb","senses":[{"ko":"놓다, 두다","en":"to put something in a particular position"}]}],"ph":[{"t":"take place","ko":"열리다, 일어나다"},{"t":"in place of","ko":"~ 대신에"},{"t":"out of place","ko":"어울리지 않는, 제자리에 없는"}],"ex":{"en":"This is my favorite place in town.","ko":"여기가 동네에서 제일 좋아하는 곳이야."}},{"id":460,"w":"plan","def":"a set of actions as a way to do, detailed proposal for doing","pos":[{"p":"noun","senses":[{"ko":"계획","en":"a set of actions decided in advance as a way to do something"}]},{"p":"verb","senses":[{"ko":"계획하다","en":"to decide in advance what you will do and how"},{"ko":"~할 작정이다","en":"to intend to do something"}]}],"ph":[{"t":"make plans","ko":"계획을 세우다"},{"t":"plan ahead","ko":"미리 계획하다"},{"t":"go according to plan","ko":"계획대로 되다"}],"ex":{"en":"Do you have any plans this weekend?","ko":"이번 주말에 무슨 계획 있어?"}},{"id":461,"w":"play","def":"to do activities for fun or enjoyment","pos":[{"p":"verb","senses":[{"ko":"놀다","en":"to do activities for fun or enjoyment"},{"ko":"(경기, 게임을) 하다","en":"to take part in a sport or game"},{"ko":"연주하다, 틀다","en":"to make music with an instrument, or to start a recording"}]},{"p":"noun","senses":[{"ko":"연극","en":"a story that actors perform on a stage"}]}],"ph":[{"t":"play with","ko":"~와 놀다, ~을 가지고 놀다"},{"t":"play it by ear","ko":"상황 봐서 하다"},{"t":"play a role","ko":"역할을 하다"}],"ex":{"en":"The kids are playing in the yard.","ko":"애들이 마당에서 놀고 있어."}},{"id":462,"w":"please","def":"used to ask for something in a polite way","pos":[{"p":"adverb","senses":[{"ko":"제발, 부디, ~해 주세요","en":"used to ask for something in a polite way"}]},{"p":"verb","senses":[{"ko":"기쁘게 하다","en":"to make someone happy or satisfied"}]}],"ph":[{"t":"Yes, please.","ko":"네, 주세요"},{"t":"Please yourself.","ko":"마음대로 해"},{"t":"as you please","ko":"원하는 대로"}],"ex":{"en":"Can you close the door, please?","ko":"문 좀 닫아 줄래?"}},{"id":463,"w":"plus","def":"having a value that is above zero","pos":[{"p":"adjective","senses":[{"ko":"영보다 큰, 플러스의","en":"having a value that is above zero"},{"ko":"~ 이상","en":"used after a number to mean more than that number"}]},{"p":"preposition","senses":[{"ko":"더하기, ~에 더하여","en":"added to, or together with"}]},{"p":"noun","senses":[{"ko":"장점, 이점","en":"an advantage or a good thing about something"}]}],"ph":[{"t":"Plus, ...","ko":"게다가, 그리고"},{"t":"a big plus","ko":"큰 장점"}],"ex":{"en":"It's plus five degrees outside today.","ko":"오늘 바깥 기온 영상 5도야."}},{"id":464,"w":"point","def":"an idea that you try to make others accept or understand","pos":[{"p":"noun","senses":[{"ko":"요점, 주장","en":"an idea that you try to make others accept or understand"},{"ko":"점수","en":"a unit used for counting the score in a game"},{"ko":"시점, 단계","en":"a particular time or stage in a process"}]},{"p":"verb","senses":[{"ko":"가리키다","en":"to show where something is using your finger"}]}],"ph":[{"t":"What's the point?","ko":"무슨 소용이야?"},{"t":"Good point.","ko":"좋은 지적이야"},{"t":"point out","ko":"지적하다, 짚어 주다"}],"ex":{"en":"I see your point, but I disagree.","ko":"무슨 말인지 알겠는데, 난 생각이 달라."}},{"id":465,"w":"police","def":"the people or the department of people who enforce laws, investigate crimes, and make arrests","pos":[{"p":"noun","senses":[{"ko":"경찰","en":"the people or department that enforce laws and investigate crimes"}]}],"ph":[{"t":"call the police","ko":"경찰을 부르다"},{"t":"police officer","ko":"경찰관"},{"t":"police station","ko":"경찰서"}],"ex":{"en":"Someone call the police!","ko":"누가 경찰 좀 불러 줘요!"}},{"id":466,"w":"policy","def":"a course of action proposed by an organization","pos":[{"p":"noun","senses":[{"ko":"정책, 방침","en":"a plan of action decided by an organization or government"},{"ko":"보험 증권","en":"a written contract with an insurance company"}]}],"ph":[{"t":"company policy","ko":"회사 방침"},{"t":"Honesty is the best policy.","ko":"정직이 최선의 방책이다"}],"ex":{"en":"Sorry, it's our policy. No refunds.","ko":"죄송해요, 저희 방침이라서요. 환불은 안 돼요."}},{"id":467,"w":"position","def":"the place something is located in","pos":[{"p":"noun","senses":[{"ko":"위치, 자리","en":"the place where someone or something is located"},{"ko":"입장, 처지","en":"a situation someone is in, or their opinion on something"},{"ko":"직위, 일자리","en":"a job or rank in an organization"}]}],"ph":[{"t":"in a position to","ko":"~할 수 있는 입장인"},{"t":"put yourself in my position","ko":"내 입장이 돼 봐"}],"ex":{"en":"Put the chair back in its position.","ko":"의자 원래 자리에 갖다 놔."}},{"id":468,"w":"possible","def":"to be able to be done","pos":[{"p":"adjective","senses":[{"ko":"가능한","en":"able to be done or achieved"},{"ko":"있을 수 있는","en":"able to happen or to be true"}]}],"ph":[{"t":"as soon as possible","ko":"가능한 한 빨리"},{"t":"if possible","ko":"가능하면"},{"t":"Is it possible to ...?","ko":"~할 수 있을까요?"}],"ex":{"en":"Anything is possible if you try.","ko":"노력하면 뭐든 가능해."}},{"id":469,"w":"pound","def":"a unit of weight that is equal to 16 ounces or 0.4536 kilograms","pos":[{"p":"noun","senses":[{"ko":"파운드 (무게, 약 454g)","en":"a unit of weight equal to 16 ounces, about 454 grams"},{"ko":"파운드 (영국 화폐)","en":"the unit of money used in the UK"}]},{"p":"verb","senses":[{"ko":"쿵쿵 치다, 두근거리다","en":"to hit something hard many times, or for the heart to beat strongly"}]}],"ph":[{"t":"My heart was pounding.","ko":"심장이 쿵쾅거렸어"}],"ex":{"en":"I lost five pounds this month.","ko":"이번 달에 5파운드 빠졌어."}},{"id":470,"w":"power","def":"the ability, capacity or right to control things","pos":[{"p":"noun","senses":[{"ko":"힘, 권력","en":"the ability or right to control people or things"},{"ko":"전기, 전력","en":"electricity used to run machines and devices"},{"ko":"능력","en":"a natural or special ability to do something"}]}],"ph":[{"t":"power outage","ko":"정전"},{"t":"in power","ko":"집권한, 권력을 쥔"},{"t":"power nap","ko":"짧은 낮잠"}],"ex":{"en":"The boss has the power to fire you.","ko":"사장은 널 해고할 권한이 있어."}},{"id":471,"w":"present","def":"existing or happening now, not in the past or future","pos":[{"p":"adjective","senses":[{"ko":"현재의, 지금의","en":"existing or happening now, not in the past or future"},{"ko":"참석한, 있는","en":"being in a particular place"}]},{"p":"noun","senses":[{"ko":"선물","en":"something that you give to someone, a gift"},{"ko":"현재","en":"the period of time that is happening now"}]},{"p":"verb","senses":[{"ko":"주다, 발표하다","en":"to give, show, or offer something formally"}]}],"ph":[{"t":"at present","ko":"현재, 지금"},{"t":"birthday present","ko":"생일 선물"},{"t":"for the present","ko":"당분간"}],"ex":{"en":"I'm happy with my present job.","ko":"지금 직장에 만족해."}},{"id":472,"w":"press","def":"newspapers, magazines, and TV news reports","pos":[{"p":"noun","senses":[{"ko":"언론, 기자들","en":"newspapers, magazines, and news reports, or the people who make them"}]},{"p":"verb","senses":[{"ko":"누르다","en":"to push firmly against something, often with your finger"},{"ko":"압박하다, 재촉하다","en":"to try hard to make someone do or say something"}]}],"ph":[{"t":"press the button","ko":"버튼을 누르다"},{"t":"press conference","ko":"기자 회견"},{"t":"pressed for time","ko":"시간에 쫓기는"}],"ex":{"en":"The press wants to talk to her.","ko":"기자들이 그 여자랑 얘기하고 싶어 해."}},{"id":473,"w":"pretty","def":"large or impressive","pos":[{"p":"adjective","senses":[{"ko":"상당한, 꽤 큰","en":"large or impressive in amount"},{"ko":"예쁜, 귀여운","en":"attractive in a pleasant or delicate way"}]},{"p":"adverb","senses":[{"ko":"꽤, 상당히","en":"to some degree, fairly"}]}],"ph":[{"t":"pretty much","ko":"거의, 대체로"},{"t":"pretty good","ko":"꽤 괜찮은"},{"t":"cost a pretty penny","ko":"돈이 꽤 많이 들다"}],"ex":{"en":"That car must have cost a pretty penny.","ko":"그 차 돈 꽤 들었겠다."}},{"id":474,"w":"price","def":"the amount of money that you pay for something or that something costs","pos":[{"p":"noun","senses":[{"ko":"가격, 값","en":"the amount of money you pay for something or that it costs"},{"ko":"대가","en":"something unpleasant you must accept to get something else"}]}],"ph":[{"t":"half price","ko":"반값"},{"t":"price tag","ko":"가격표"},{"t":"at any price","ko":"어떤 대가를 치르더라도"}],"ex":{"en":"The price is too high for me.","ko":"그 가격은 나한텐 너무 비싸."}},{"id":475,"w":"probably","def":"used to mean that something is very likely","pos":[{"p":"adverb","senses":[{"ko":"아마","en":"used to say that something is very likely"}]}],"ph":[{"t":"probably not","ko":"아마 아닐 거야"}],"ex":{"en":"I'll probably be home by eight.","ko":"아마 8시까지는 집에 갈 거야."}},{"id":476,"w":"problem","def":"something that is difficult to deal with or needs to overcome","pos":[{"p":"noun","senses":[{"ko":"문제, 골칫거리","en":"something difficult that you have to deal with or overcome"},{"ko":"(풀어야 할) 문제","en":"a question to be solved, especially in math"}]}],"ph":[{"t":"No problem.","ko":"문제없어, 천만에"},{"t":"What's your problem?","ko":"너 왜 그래?"},{"t":"That's not my problem.","ko":"그건 내 알 바 아니야"}],"ex":{"en":"We have a problem with the car.","ko":"차에 문제가 생겼어."}},{"id":477,"w":"process","def":"a series of actions that produce achievement","pos":[{"p":"noun","senses":[{"ko":"과정, 절차","en":"a series of actions that lead to a particular result"}]},{"p":"verb","senses":[{"ko":"처리하다","en":"to deal with documents, data, or requests in a fixed way"}]}],"ph":[{"t":"in the process","ko":"그 과정에서"},{"t":"be in the process of","ko":"~하는 중이다"}],"ex":{"en":"Learning a language is a slow process.","ko":"언어 배우는 건 오래 걸리는 과정이야."}},{"id":478,"w":"produce","def":"to use machines to make something from raw materials","pos":[{"p":"verb","senses":[{"ko":"생산하다, 제조하다","en":"to make goods from raw materials, often using machines"},{"ko":"만들어 내다, 일으키다","en":"to cause something to happen or exist"},{"ko":"(영화, 음반을) 제작하다","en":"to be in charge of making a movie, show, or record"}]},{"p":"noun","senses":[{"ko":"농산물","en":"fruits and vegetables that are grown for sale"}]}],"ph":[{"t":"produce results","ko":"성과를 내다"}],"ex":{"en":"This factory produces cars.","ko":"이 공장은 자동차를 생산해."}},{"id":479,"w":"product","def":"something that is made or grown to be sold or used","pos":[{"p":"noun","senses":[{"ko":"제품, 상품","en":"something that is made or grown to be sold or used"},{"ko":"결과물, 산물","en":"the result of an action or process"}]}],"ph":[{"t":"new product","ko":"신제품"},{"t":"beauty products","ko":"화장품, 미용 제품"}],"ex":{"en":"This product is really popular in Korea.","ko":"이 제품 한국에서 진짜 인기 많아."}},{"id":480,"w":"program","def":"a plan of things that are done to achieve a result","pos":[{"p":"noun","senses":[{"ko":"계획, 프로그램","en":"a planned series of activities done to achieve a result"},{"ko":"(방송) 프로그램","en":"a show on television or radio"},{"ko":"(컴퓨터) 프로그램","en":"a set of instructions that makes a computer do something"}]}],"ph":[{"t":"TV program","ko":"TV 프로그램"},{"t":"training program","ko":"교육 과정, 연수 프로그램"}],"ex":{"en":"She joined a training program at work.","ko":"걔 회사에서 연수 프로그램 들어갔어."}},{"id":481,"w":"project","def":"a planned piece of work for specific purpose","pos":[{"p":"noun","senses":[{"ko":"프로젝트, 과제","en":"a planned piece of work done for a particular purpose"}]},{"p":"verb","senses":[{"ko":"예상하다, 추정하다","en":"to calculate what an amount will probably be in the future"}]}],"ph":[{"t":"work on a project","ko":"프로젝트를 하다"},{"t":"group project","ko":"조별 과제"},{"t":"side project","ko":"사이드 프로젝트, 부업"}],"ex":{"en":"I'm working on a big project right now.","ko":"나 지금 큰 프로젝트 하는 중이야."}},{"id":482,"w":"provide","def":"to make available, to supply for use","pos":[{"p":"verb","senses":[{"ko":"제공하다, 공급하다","en":"to make something available for someone to use"},{"ko":"부양하다","en":"to give someone the money and things they need to live"}]}],"ph":[{"t":"provide for","ko":"부양하다; 대비하다"},{"t":"provided that","ko":"~라면, ~하는 조건으로"}],"ex":{"en":"The hotel provides free breakfast.","ko":"그 호텔은 무료 조식을 줘."}},{"id":483,"w":"public","def":"concerning or affecting all or most of the people in a group","pos":[{"p":"adjective","senses":[{"ko":"공공의, 대중의","en":"relating to or affecting all or most of the people"},{"ko":"공개된","en":"open to everyone, or known by many people"}]},{"p":"noun","senses":[{"ko":"대중, 일반 사람들","en":"ordinary people in general"}]}],"ph":[{"t":"in public","ko":"사람들 앞에서, 공공연히"},{"t":"public transportation","ko":"대중교통"},{"t":"go public","ko":"공개하다"}],"ex":{"en":"Smoking isn't allowed in public places.","ko":"공공장소에서는 담배 피우면 안 돼."}},{"id":484,"w":"pull","def":"to hold onto and move (someone or something) in a particular direction and especially toward yourself","pos":[{"p":"verb","senses":[{"ko":"끌다, 당기다","en":"to hold something and move it toward yourself or in a direction"},{"ko":"빼다, 뽑다","en":"to take something out of a place"}]}],"ph":[{"t":"pull over","ko":"차를 길가에 세우다"},{"t":"pull yourself together","ko":"정신 차려"},{"t":"pull someone's leg","ko":"놀리다, 장난치다"}],"ex":{"en":"Pull the door, don't push it.","ko":"문 당겨, 밀지 말고."}},{"id":485,"w":"purpose","def":"the reason for which something is done","pos":[{"p":"noun","senses":[{"ko":"목적, 의도","en":"the reason why something is done or made"},{"ko":"목표의식, 삶의 목적","en":"the feeling that your life or work has a clear aim"}]}],"ph":[{"t":"on purpose","ko":"일부러, 고의로"},{"t":"for the purpose of","ko":"~을 위해서"},{"t":"serve a purpose","ko":"쓸모가 있다, 도움이 되다"}],"ex":{"en":"What's the purpose of this meeting?","ko":"이 회의 목적이 뭐예요?"}},{"id":486,"w":"push","def":"to use force to move (someone or something) forward or away from you","pos":[{"p":"verb","senses":[{"ko":"밀다","en":"to use force to move someone or something forward or away from you"},{"ko":"강요하다, 압박하다","en":"to try hard to make someone do something"},{"ko":"누르다","en":"to press a button or switch with your finger"}]},{"p":"noun","senses":[{"ko":"밀기, 밀어붙이기","en":"an act of pushing someone or something"}]}],"ph":[{"t":"don't push it","ko":"너무 욕심내지 마, 적당히 해"},{"t":"push back","ko":"미루다; 반발하다"},{"t":"push someone's buttons","ko":"~의 신경을 건드리다"}],"ex":{"en":"Push the door, don't pull it.","ko":"문 밀어, 당기지 말고."}},{"id":487,"w":"put","def":"to move or place in a particular position","pos":[{"p":"verb","senses":[{"ko":"놓다, 두다","en":"to move something into a particular place or position"},{"ko":"(어떤 상태로) 만들다","en":"to cause someone or something to be in a particular state"},{"ko":"표현하다, 말하다","en":"to say or express something in a particular way"}]}],"ph":[{"t":"put on","ko":"입다, 쓰다, 신다"},{"t":"put off","ko":"미루다, 연기하다"},{"t":"put up with","ko":"참다, 견디다"}],"ex":{"en":"Just put it on the table.","ko":"그냥 테이블 위에 놔."}},{"id":488,"w":"quality","def":"how good or bad something is","pos":[{"p":"noun","senses":[{"ko":"질, 품질","en":"how good or bad something is"},{"ko":"특성, 자질","en":"a feature or characteristic of a person or thing"}]},{"p":"adjective","senses":[{"ko":"고급의, 질 좋은","en":"of a high standard, very good"}]}],"ph":[{"t":"quality time","ko":"(가족 등과 보내는) 소중한 시간"},{"t":"high quality","ko":"고품질"},{"t":"quality control","ko":"품질 관리"}],"ex":{"en":"The quality of the food here is great.","ko":"여기 음식 질이 정말 좋아."}},{"id":489,"w":"question","def":"to ask for or elicit information","pos":[{"p":"verb","senses":[{"ko":"질문하다, 심문하다","en":"to ask someone questions to get information"},{"ko":"의심하다, 의문을 제기하다","en":"to have or express doubts about whether something is true or right"}]},{"p":"noun","senses":[{"ko":"질문","en":"a sentence or phrase used to ask for information"},{"ko":"문제, 사안","en":"a matter or issue that people need to deal with"}]}],"ph":[{"t":"no question","ko":"틀림없이, 두말할 것 없이"},{"t":"out of the question","ko":"불가능한, 말도 안 되는"},{"t":"good question","ko":"좋은 질문이야(잘 모르겠네)"}],"ex":{"en":"The police questioned him for two hours.","ko":"경찰이 그를 두 시간 동안 심문했어."}},{"id":490,"w":"quick","def":"done or happening in a short amount of time","pos":[{"p":"adjective","senses":[{"ko":"빠른, 짧은","en":"done or happening in a short amount of time"},{"ko":"재빠른, 눈치 빠른","en":"able to move, think, or learn fast"}]},{"p":"adverb","senses":[{"ko":"빨리","en":"quickly, used in casual speech"}]}],"ph":[{"t":"quick question","ko":"간단한 질문인데"},{"t":"grab a quick bite","ko":"간단히 뭐 좀 먹다"},{"t":"quick fix","ko":"임시방편, 땜질 처방"}],"ex":{"en":"Let's have a quick lunch before the meeting.","ko":"회의 전에 점심 빨리 먹자."}},{"id":491,"w":"quite","def":"to a very large degree, very","pos":[{"p":"adverb","senses":[{"ko":"아주, 꽤, 상당히","en":"to a large degree, very"},{"ko":"완전히, 전적으로","en":"completely or totally, in every way"}]}],"ph":[{"t":"quite a few","ko":"꽤 많은"},{"t":"not quite","ko":"완전히 ~는 아닌, 꼭 그렇진 않은"},{"t":"quite a bit","ko":"꽤 많이"}],"ex":{"en":"It's quite cold today.","ko":"오늘 꽤 춥네."}},{"id":492,"w":"raise","def":"to lift or move something to a higher position","pos":[{"p":"verb","senses":[{"ko":"들어 올리다","en":"to lift or move something to a higher position"},{"ko":"올리다, 인상하다","en":"to increase an amount, level, or price"},{"ko":"키우다, 기르다","en":"to care for a child or animal until it is grown"}]},{"p":"noun","senses":[{"ko":"임금 인상","en":"an increase in the money you are paid for your work"}]}],"ph":[{"t":"raise your hand","ko":"손을 들다"},{"t":"raise money","ko":"돈을 모으다, 모금하다"},{"t":"raise a question","ko":"문제를 제기하다"}],"ex":{"en":"Raise your hand if you know the answer.","ko":"답 아는 사람 손 들어."}},{"id":493,"w":"rate","def":"the measure of speed or frequency over a particular period of time","pos":[{"p":"noun","senses":[{"ko":"속도, 비율","en":"how fast or how often something happens over a period of time"},{"ko":"요금, 가격","en":"a fixed amount of money charged for something"}]},{"p":"verb","senses":[{"ko":"평가하다, 점수를 매기다","en":"to judge how good or valuable something is"}]}],"ph":[{"t":"at any rate","ko":"어쨌든, 아무튼"},{"t":"at this rate","ko":"이런 식으로 가면"},{"t":"interest rate","ko":"이자율, 금리"}],"ex":{"en":"My heart rate goes up when I run.","ko":"뛰면 심박수가 올라가."}},{"id":494,"w":"rather","def":"to a certain extent","pos":[{"p":"adverb","senses":[{"ko":"다소, 약간, 꽤","en":"to a certain extent, fairly"},{"ko":"오히려, 차라리","en":"used to show what you prefer or what is more correct"}]}],"ph":[{"t":"would rather","ko":"차라리 ~하겠다"},{"t":"rather than","ko":"~보다는, ~ 대신에"},{"t":"or rather","ko":"아니 정확히 말하면"}],"ex":{"en":"It's rather late to call him now.","ko":"지금 걔한테 전화하기엔 좀 늦었어."}},{"id":495,"w":"read","def":"to look at and comprehend the meaning of something written","pos":[{"p":"verb","senses":[{"ko":"읽다","en":"to look at written words and understand what they mean"},{"ko":"읽어 주다, 낭독하다","en":"to say written words aloud for others to hear"},{"ko":"(수치를) 나타내다","en":"to show a measurement or piece of information"}]}],"ph":[{"t":"read between the lines","ko":"숨은 뜻을 알아채다"},{"t":"read someone's mind","ko":"~의 마음을 읽다"},{"t":"read up on","ko":"~에 대해 찾아 읽다, 공부하다"}],"ex":{"en":"I read that book last summer.","ko":"그 책 작년 여름에 읽었어."}},{"id":496,"w":"ready","def":"prepared to do something","pos":[{"p":"adjective","senses":[{"ko":"준비된","en":"prepared and able to do something"},{"ko":"기꺼이 하는","en":"willing and quick to do something"}]}],"ph":[{"t":"get ready","ko":"준비하다"},{"t":"ready to go","ko":"갈 준비가 된"},{"t":"ready when you are","ko":"너만 되면 난 준비됐어"}],"ex":{"en":"Are you ready to order?","ko":"주문하시겠어요?"}},{"id":497,"w":"real","def":"actually existing or happening, not imagined or supposed","pos":[{"p":"adjective","senses":[{"ko":"실제의, 현실의","en":"actually existing or happening, not imagined"},{"ko":"진짜의, 진품의","en":"not fake or artificial"}]},{"p":"adverb","senses":[{"ko":"정말, 아주","en":"very, used in informal speech"}]}],"ph":[{"t":"for real","ko":"진짜로; 정말이야?"},{"t":"get real","ko":"정신 차려, 현실을 봐"},{"t":"keep it real","ko":"솔직하게 해, 꾸밈없이 해"}],"ex":{"en":"Is this real, or am I dreaming?","ko":"이거 진짜야, 아니면 꿈이야?"}},{"id":498,"w":"realize","def":"to understand or become aware of something","pos":[{"p":"verb","senses":[{"ko":"깨닫다, 알아차리다","en":"to understand or become aware of something"},{"ko":"실현하다, 이루다","en":"to make a hope or plan actually happen"}]}],"ph":[{"t":"I didn't realize","ko":"몰랐어, 미처 생각 못 했어"},{"t":"come to realize","ko":"깨닫게 되다"},{"t":"realize a dream","ko":"꿈을 이루다"}],"ex":{"en":"I didn't realize it was so late.","ko":"벌써 이렇게 늦은 줄 몰랐어."}},{"id":499,"w":"really","def":"very or very much","pos":[{"p":"adverb","senses":[{"ko":"정말, 아주","en":"very or very much"},{"ko":"실제로, 진짜로","en":"used to say what is actually true"}]},{"p":"interjection","senses":[{"ko":"정말?, 그래?","en":"used to show surprise, interest, or doubt"}]}],"ph":[{"t":"not really","ko":"별로, 꼭 그렇진 않아"},{"t":"Really?","ko":"정말?, 진짜?"},{"t":"I really mean it","ko":"진심이야"}],"ex":{"en":"I really like your new haircut.","ko":"새 머리 진짜 마음에 들어."}},{"id":500,"w":"reason","def":"a cause for an action or event","pos":[{"p":"noun","senses":[{"ko":"이유, 원인","en":"a cause or explanation for an action or event"},{"ko":"이성, 사고력","en":"the ability to think clearly and sensibly"}]},{"p":"verb","senses":[{"ko":"추론하다, 판단하다","en":"to think about something in a logical way"}]}],"ph":[{"t":"for some reason","ko":"왠지, 어째서인지"},{"t":"for no reason","ko":"아무 이유 없이"},{"t":"within reason","ko":"상식선에서, 적당한 범위 내에서"}],"ex":{"en":"Is there a reason you're late?","ko":"늦은 이유가 있어?"}},{"id":501,"w":"receive","def":"to get or be presented with something","pos":[{"p":"verb","senses":[{"ko":"받다","en":"to get or be given something"},{"ko":"(반응을) 얻다, 받아들이다","en":"to react to someone or something in a particular way"}]}],"ph":[{"t":"receive a call","ko":"전화를 받다"},{"t":"well received","ko":"호평을 받은"}],"ex":{"en":"Did you receive my email?","ko":"내 이메일 받았어?"}},{"id":502,"w":"record","def":"an official piece of evidence or document about past events","pos":[{"p":"noun","senses":[{"ko":"기록, 문서","en":"a written account or document about past events"},{"ko":"최고 기록","en":"the best result ever achieved in a sport or activity"},{"ko":"음반, 레코드","en":"a disc or album of recorded music"}]},{"p":"verb","senses":[{"ko":"녹음하다, 녹화하다","en":"to store sounds or pictures so they can be played later"},{"ko":"기록하다","en":"to write down information so it can be used later"}]}],"ph":[{"t":"off the record","ko":"비공식적으로, 기록에 남기지 않고"},{"t":"break a record","ko":"기록을 깨다"},{"t":"for the record","ko":"분명히 말해 두는데"}],"ex":{"en":"We keep a record of every payment.","ko":"우리는 모든 결제 기록을 남겨."}},{"id":503,"w":"red","def":"having the color of blood","pos":[{"p":"adjective","senses":[{"ko":"빨간, 붉은","en":"having the color of blood"},{"ko":"(얼굴이) 빨개진","en":"pink or red in the face from embarrassment or anger"}]},{"p":"noun","senses":[{"ko":"빨간색","en":"the color of blood or fire"}]}],"ph":[{"t":"red flag","ko":"위험 신호, 경고 신호"},{"t":"in the red","ko":"적자인"},{"t":"turn red","ko":"얼굴이 빨개지다"}],"ex":{"en":"She was wearing a red dress.","ko":"그녀는 빨간 원피스를 입고 있었어."}},{"id":504,"w":"relate","def":"to show or make a connection between (two or more things)","pos":[{"p":"verb","senses":[{"ko":"관련시키다, 연관 짓다","en":"to show or make a connection between two or more things"},{"ko":"공감하다","en":"to understand someone's feelings because you have had a similar experience"},{"ko":"관련이 있다","en":"to be connected with something or be about it"}]}],"ph":[{"t":"I can relate","ko":"나도 공감해, 무슨 말인지 알아"},{"t":"relate to","ko":"~와 관련되다; ~에 공감하다"}],"ex":{"en":"Police are trying to relate the two crimes.","ko":"경찰이 두 사건을 연관 지으려 하고 있어."}},{"id":505,"w":"relationship","def":"a connection between two or more people or things","pos":[{"p":"noun","senses":[{"ko":"관계","en":"a connection between two or more people or things"},{"ko":"연인 관계, 교제","en":"a romantic connection between two people"}]}],"ph":[{"t":"in a relationship","ko":"사귀는 중인, 연애 중인"},{"t":"have a good relationship with","ko":"~와 사이가 좋다"}],"ex":{"en":"I have a good relationship with my boss.","ko":"나 상사랑 사이 좋아."}},{"id":506,"w":"remember","def":"to bring a previous image or idea to your mind","pos":[{"p":"verb","senses":[{"ko":"기억하다, 떠올리다","en":"to bring an image or idea from the past into your mind"},{"ko":"잊지 않고 ~하다","en":"to not forget to do something you need to do"}]}],"ph":[{"t":"if I remember correctly","ko":"내 기억이 맞다면"},{"t":"as far as I remember","ko":"내가 기억하기로는"}],"ex":{"en":"Do you remember his name?","ko":"그 사람 이름 기억나?"}},{"id":507,"w":"report","def":"a story given about a particular matter","pos":[{"p":"noun","senses":[{"ko":"보도, 보고, 이야기","en":"an account given about a particular matter or event"},{"ko":"보고서","en":"a written document that describes a situation or study"}]},{"p":"verb","senses":[{"ko":"보도하다, 보고하다","en":"to tell people about something that has happened"},{"ko":"신고하다","en":"to tell someone in authority about a crime, accident, or problem"}]}],"ph":[{"t":"report to","ko":"~에게 보고하다, ~ 밑에서 일하다"},{"t":"report card","ko":"성적표"},{"t":"news report","ko":"뉴스 보도"}],"ex":{"en":"Did you see the report on the news?","ko":"뉴스에서 그 보도 봤어?"}},{"id":508,"w":"require","def":"to need something, to make it necessary","pos":[{"p":"verb","senses":[{"ko":"필요로 하다","en":"to need something or make it necessary"},{"ko":"요구하다","en":"to officially demand that someone does something"}]}],"ph":[{"t":"be required to","ko":"~해야 한다, ~하도록 요구되다"},{"t":"if required","ko":"필요하면"}],"ex":{"en":"This job requires a lot of patience.","ko":"이 일은 인내심이 많이 필요해."}},{"id":509,"w":"research","def":"careful study to find and report new knowledge","pos":[{"p":"noun","senses":[{"ko":"연구, 조사","en":"careful study to find and report new knowledge"}]},{"p":"verb","senses":[{"ko":"연구하다, 조사하다","en":"to study something carefully to discover new facts"}]}],"ph":[{"t":"do research","ko":"조사하다, 연구하다"},{"t":"do your research","ko":"미리 알아보다"}],"ex":{"en":"She does research on climate change.","ko":"그녀는 기후 변화를 연구해."}},{"id":510,"w":"response","def":"an answer or reaction to something that has been said or done","pos":[{"p":"noun","senses":[{"ko":"응답, 반응","en":"an answer or reaction to something that was said or done"},{"ko":"대응","en":"the way people act after something happens, such as an emergency"}]}],"ph":[{"t":"in response to","ko":"~에 대한 응답으로"},{"t":"no response","ko":"응답 없음, 반응 없음"}],"ex":{"en":"I sent a message, but there's no response.","ko":"메시지 보냈는데 답이 없어."}},{"id":511,"w":"rest","def":"not at work, to have time to relax, sleep or do nothing","pos":[{"p":"verb","senses":[{"ko":"쉬다, 휴식하다","en":"to stop working and relax, sleep, or do nothing for a while"}]},{"p":"noun","senses":[{"ko":"휴식","en":"a period of time when you relax or sleep"},{"ko":"나머지","en":"the part of something that is left"}]}],"ph":[{"t":"get some rest","ko":"좀 쉬다"},{"t":"the rest of","ko":"~의 나머지"},{"t":"rest assured","ko":"안심해, 걱정 마"}],"ex":{"en":"You look tired. Go home and rest.","ko":"피곤해 보여. 집에 가서 쉬어."}},{"id":512,"w":"result","def":"a thing that is caused by something else that happened","pos":[{"p":"noun","senses":[{"ko":"결과","en":"something that happens because of something else"},{"ko":"(시험, 경기의) 결과, 성적","en":"the final score or outcome of a test, game, or election"}]},{"p":"verb","senses":[{"ko":"(결과로) 생기다","en":"to happen because of something else"}]}],"ph":[{"t":"as a result","ko":"그 결과, 결과적으로"},{"t":"result in","ko":"~을 초래하다, ~로 끝나다"}],"ex":{"en":"This is the result of hard work.","ko":"이게 노력의 결과야."}},{"id":513,"w":"review","def":"an act of carefully looking at or examining the quality or condition of something or someone","pos":[{"p":"noun","senses":[{"ko":"검토, 점검","en":"a careful look at the quality or condition of something"},{"ko":"후기, 평론","en":"an article or comment giving an opinion of a book, film, or product"}]},{"p":"verb","senses":[{"ko":"검토하다, 복습하다","en":"to look at or study something again carefully"}]}],"ph":[{"t":"under review","ko":"검토 중인"},{"t":"write a review","ko":"후기를 쓰다"},{"t":"good reviews","ko":"좋은 평, 호평"}],"ex":{"en":"We'll do a review of the plan next week.","ko":"다음 주에 계획을 검토할 거야."}},{"id":514,"w":"right","def":"to be true, correct or acceptable","pos":[{"p":"adjective","senses":[{"ko":"맞는, 옳은","en":"true, correct, or acceptable"},{"ko":"오른쪽의","en":"on or toward the side of the body that most people write with"},{"ko":"알맞은, 적절한","en":"suitable or best for a particular situation"}]},{"p":"adverb","senses":[{"ko":"바로, 곧","en":"exactly in a place or immediately at a time"},{"ko":"오른쪽으로","en":"toward the right side"}]},{"p":"noun","senses":[{"ko":"권리","en":"something you are morally or legally allowed to have or do"},{"ko":"오른쪽","en":"the right side or direction"}]},{"p":"interjection","senses":[{"ko":"그래, 알았어","en":"used to say you agree or understand"},{"ko":"(문장 끝) 그렇지?","en":"used at the end of a statement to check that it is true"}]}],"ph":[{"t":"You're right","ko":"네 말이 맞아"},{"t":"right now","ko":"지금 당장"},{"t":"right away","ko":"즉시, 바로"}],"ex":{"en":"You're right, it was my mistake.","ko":"네 말이 맞아, 내 실수였어."}},{"id":515,"w":"ring","def":"a piece of jewelry that is worn usually on a finger","pos":[{"p":"noun","senses":[{"ko":"반지","en":"a piece of jewelry worn on a finger"},{"ko":"(전화, 벨) 울림","en":"the sound that a bell or phone makes"},{"ko":"고리, 원","en":"a circle shape or a circular object"}]},{"p":"verb","senses":[{"ko":"(벨이) 울리다","en":"to make the sound of a bell or a phone"},{"ko":"전화하다","en":"to phone someone, mainly in British English"}]}],"ph":[{"t":"ring a bell","ko":"들어 본 것 같다, 낯이 익다"},{"t":"give someone a ring","ko":"~에게 전화하다"},{"t":"wedding ring","ko":"결혼반지"}],"ex":{"en":"He gave her a diamond ring.","ko":"그가 그녀에게 다이아몬드 반지를 줬어."}},{"id":516,"w":"road","def":"a hard flat surface for people or vehicles can use","pos":[{"p":"noun","senses":[{"ko":"길, 도로","en":"a hard flat surface that people or vehicles travel on"},{"ko":"길, 과정","en":"a way or process that leads to a particular result"}]}],"ph":[{"t":"hit the road","ko":"출발하다, 떠나다"},{"t":"on the road","ko":"이동 중인, 여행 중인"},{"t":"down the road","ko":"나중에, 앞으로"}],"ex":{"en":"Be careful when you cross the road.","ko":"길 건널 때 조심해."}},{"id":517,"w":"room","def":"a space that can be occupied which has its own floor and ceiling","pos":[{"p":"noun","senses":[{"ko":"방","en":"a space in a building with its own floor, walls, and ceiling"},{"ko":"공간, 자리","en":"empty space that can be used for something"},{"ko":"여지","en":"the chance or possibility for something to happen"}]}],"ph":[{"t":"make room","ko":"자리를 만들다, 비켜 주다"},{"t":"room for improvement","ko":"개선의 여지"},{"t":"room service","ko":"룸서비스"}],"ex":{"en":"My room is on the second floor.","ko":"내 방은 2층이야."}},{"id":518,"w":"round","def":"shaped like a circle or ball","pos":[{"p":"adjective","senses":[{"ko":"둥근","en":"shaped like a circle or a ball"}]},{"p":"noun","senses":[{"ko":"(경기의) 회, 라운드","en":"one stage or part of a competition or game"},{"ko":"(술) 한 차례","en":"a set of drinks bought for everyone in a group"}]},{"p":"preposition","senses":[{"ko":"~ 주위에, 빙 둘러","en":"around, mainly in British English"}]}],"ph":[{"t":"all year round","ko":"일 년 내내"},{"t":"this round's on me","ko":"이번 잔은 내가 살게"},{"t":"round trip","ko":"왕복 여행"}],"ex":{"en":"We sat at a big round table.","ko":"우리는 큰 원형 테이블에 앉았어."}},{"id":519,"w":"rule","def":"something that is not allowed in some situations","pos":[{"p":"noun","senses":[{"ko":"규칙, 규정","en":"a statement of what is or is not allowed in a situation"},{"ko":"통치, 지배","en":"control of a country by a person or group"}]},{"p":"verb","senses":[{"ko":"통치하다, 지배하다","en":"to control and lead a country or group"},{"ko":"판결하다","en":"to officially decide something, especially in a court"}]}],"ph":[{"t":"as a rule","ko":"대체로, 일반적으로"},{"t":"rule out","ko":"배제하다, 제외하다"},{"t":"break the rules","ko":"규칙을 어기다"}],"ex":{"en":"No phones in class. That's the rule.","ko":"수업 중엔 폰 금지야. 그게 규칙이야."}},{"id":520,"w":"run","def":"to move with your legs at a speed that is faster than walking","pos":[{"p":"verb","senses":[{"ko":"달리다, 뛰다","en":"to move with your legs at a speed faster than walking"},{"ko":"운영하다","en":"to manage or be in charge of a business or event"},{"ko":"작동하다, 운행하다","en":"to work or operate, or to travel on a regular route"},{"ko":"잠깐 다녀오다","en":"to go somewhere quickly or for a short time"},{"ko":"(물·콧물이) 흐르다","en":"to flow, or to let water flow, as in my nose is running"}]},{"p":"noun","senses":[{"ko":"달리기","en":"an act of running, often for exercise"}]}],"ph":[{"t":"run out of","ko":"~이 다 떨어지다"},{"t":"run into","ko":"우연히 만나다"},{"t":"in the long run","ko":"결국, 장기적으로"}],"ex":{"en":"I run every morning before work.","ko":"나는 매일 아침 출근 전에 달려."}},{"id":521,"w":"sale","def":"the act of selling something or exchanging for money","pos":[{"p":"noun","senses":[{"ko":"판매","en":"the act of selling something for money"},{"ko":"할인 판매, 세일","en":"a time when a shop sells things at lower prices"},{"ko":"매출, 판매량","en":"the number or value of things sold, usually plural"}]}],"ph":[{"t":"for sale","ko":"팔려고 내놓은"},{"t":"on sale","ko":"할인 중인; 판매 중인"}],"ex":{"en":"Is this car for sale?","ko":"이 차 파는 거예요?"}},{"id":522,"w":"same","def":"identical, not different","pos":[{"p":"adjective","senses":[{"ko":"같은, 동일한","en":"exactly alike and not different"}]},{"p":"pronoun","senses":[{"ko":"같은 것","en":"the same thing or person as one already mentioned"}]}],"ph":[{"t":"Same here","ko":"나도 그래"},{"t":"all the same","ko":"그래도, 어쨌든"},{"t":"same old","ko":"늘 그렇지 뭐"}],"ex":{"en":"We go to the same school.","ko":"우리 같은 학교 다녀."}},{"id":523,"w":"save","def":"to keep (someone or something) safe : to stop (someone or something) from dying or being hurt, damaged, or lost","pos":[{"p":"verb","senses":[{"ko":"구하다, 지키다","en":"to keep someone or something safe from harm, death, or loss"},{"ko":"저축하다, 아끼다","en":"to keep money or something else to use later"},{"ko":"저장하다","en":"to store data on a computer or phone"}]}],"ph":[{"t":"save time","ko":"시간을 아끼다"},{"t":"save someone a seat","ko":"~에게 자리를 맡아 주다"},{"t":"save the day","ko":"위기를 구하다"}],"ex":{"en":"The doctor saved his life.","ko":"의사가 그의 목숨을 구했어."}},{"id":524,"w":"say","def":"to use your voice to express something with words","pos":[{"p":"verb","senses":[{"ko":"말하다","en":"to use your voice to express something in words"},{"ko":"(글, 표시에) 쓰여 있다","en":"to show information in writing, numbers, or signs"}]},{"p":"noun","senses":[{"ko":"발언권","en":"the right to give your opinion in a decision"}]},{"p":"adverb","senses":[{"ko":"예를 들어, 가령","en":"used to give an example or a rough number"}]}],"ph":[{"t":"You can say that again","ko":"정말 그래, 내 말이 그 말이야"},{"t":"I'd say","ko":"내 생각엔"},{"t":"that is to say","ko":"즉, 다시 말해"}],"ex":{"en":"What did she say to you?","ko":"그녀가 너한테 뭐라고 했어?"}},{"id":525,"w":"school","def":"a place where children go to learn","pos":[{"p":"noun","senses":[{"ko":"학교","en":"a place where children go to learn"},{"ko":"수업","en":"the time you spend at school, or the lessons there"},{"ko":"대학, 학부","en":"a college, or a department of a university"}]}],"ph":[{"t":"after school","ko":"방과 후에"},{"t":"high school","ko":"고등학교"},{"t":"old school","ko":"구식의, 옛날 스타일의"}],"ex":{"en":"My kids walk to school every day.","ko":"우리 애들은 매일 걸어서 학교에 가."}},{"id":526,"w":"score","def":"the number of points someone gets in a game or test","pos":[{"p":"noun","senses":[{"ko":"점수, 득점","en":"the number of points someone gets in a game or test"}]},{"p":"verb","senses":[{"ko":"득점하다","en":"to win a point or goal in a game"},{"ko":"(시험에서) 점수를 받다","en":"to get a particular number of points in a test"}]}],"ph":[{"t":"What's the score?","ko":"몇 대 몇이야?"},{"t":"keep score","ko":"점수를 기록하다"},{"t":"settle a score","ko":"앙갚음하다, 복수하다"}],"ex":{"en":"What was your score on the test?","ko":"시험 점수 몇 점이었어?"}},{"id":527,"w":"second","def":"a unit of time, one sixtieth of a minute","pos":[{"p":"noun","senses":[{"ko":"초","en":"a unit of time, one sixtieth of a minute"},{"ko":"잠깐, 순간","en":"a very short period of time"}]},{"p":"adjective","senses":[{"ko":"두 번째의","en":"coming next after the first one"}]}],"ph":[{"t":"Just a second","ko":"잠깐만"},{"t":"have second thoughts","ko":"다시 생각해 보다, 망설이다"},{"t":"second-hand","ko":"중고의"}],"ex":{"en":"It only takes a few seconds.","ko":"몇 초밖에 안 걸려."}},{"id":528,"w":"see","def":"to notice or become aware of with the eyes","pos":[{"p":"verb","senses":[{"ko":"보다","en":"to notice or become aware of something with your eyes"},{"ko":"알다, 이해하다","en":"to understand something or realize what it means"},{"ko":"만나다","en":"to meet or spend time with someone"},{"ko":"사귀다, 연애하다","en":"to be in a romantic relationship with someone"}]}],"ph":[{"t":"See you later","ko":"나중에 봐"},{"t":"I see","ko":"그렇구나, 알겠어"},{"t":"Let me see","ko":"어디 보자, 글쎄"}],"ex":{"en":"Did you see that car?","ko":"저 차 봤어?"}},{"id":529,"w":"seem","def":"to appear to be something","pos":[{"p":"verb","senses":[{"ko":"~처럼 보이다, ~인 것 같다","en":"to appear to be something or to have a particular quality"}]}],"ph":[{"t":"It seems like","ko":"~인 것 같아"},{"t":"can't seem to","ko":"아무리 해도 ~이 안 되다"}],"ex":{"en":"You seem tired today.","ko":"너 오늘 피곤해 보여."}},{"id":530,"w":"sell","def":"to exchange (something) for money","pos":[{"p":"verb","senses":[{"ko":"팔다","en":"to give something to someone in exchange for money"},{"ko":"팔리다","en":"to be bought by people in a particular way or amount"},{"ko":"납득시키다, 설득하다","en":"to make someone believe that an idea is good"}]}],"ph":[{"t":"sold out","ko":"매진된, 다 팔린"},{"t":"sell out","ko":"매진되다; 변절하다"},{"t":"sell someone on","ko":"~에게 ~을 납득시키다"}],"ex":{"en":"I sold my old bike to a friend.","ko":"옛날 자전거 친구한테 팔았어."}},{"id":531,"w":"send","def":"to cause to go to another destination","pos":[{"p":"verb","senses":[{"ko":"보내다","en":"to make something go or be taken to another place"},{"ko":"(사람을) 보내다, 가게 하다","en":"to tell or cause someone to go somewhere"}]}],"ph":[{"t":"send my love","ko":"안부 전해 줘"},{"t":"send off","ko":"발송하다; 배웅하다"},{"t":"send for","ko":"~을 부르러 보내다"}],"ex":{"en":"Can you send me the photos?","ko":"사진 좀 보내 줄래?"}},{"id":532,"w":"sense","def":"one of our natural abilities for receiving information","pos":[{"p":"noun","senses":[{"ko":"감각","en":"one of the natural abilities of sight, hearing, smell, taste, and touch"},{"ko":"느낌, 감","en":"a feeling or understanding about something"},{"ko":"의미, 뜻","en":"the meaning of a word or idea"}]},{"p":"verb","senses":[{"ko":"감지하다, 느끼다","en":"to feel or become aware of something without being told"}]}],"ph":[{"t":"make sense","ko":"이해가 되다, 말이 되다"},{"t":"sense of humor","ko":"유머 감각"},{"t":"common sense","ko":"상식"}],"ex":{"en":"Dogs have a great sense of smell.","ko":"개는 후각이 아주 뛰어나."}},{"id":533,"w":"service","def":"the action of helping or doing work for someone","pos":[{"p":"noun","senses":[{"ko":"봉사, 근무, 도움","en":"the act of helping or doing work for someone"},{"ko":"(손님) 접대, 서비스","en":"the way staff treat customers in a shop, hotel, or restaurant"},{"ko":"(공공) 서비스, 제도","en":"a system that provides something people need, like transport or health care"}]}],"ph":[{"t":"customer service","ko":"고객 서비스, 고객 센터"},{"t":"at your service","ko":"무엇이든 말씀만 하세요"},{"t":"out of service","ko":"운행 중지, 고장 난"}],"ex":{"en":"Thank you for your years of service.","ko":"그동안 수고 많으셨어요."}},{"id":534,"w":"set","def":"to put or stand something in a place or position","pos":[{"p":"verb","senses":[{"ko":"놓다, 두다","en":"to put something in a particular place or position"},{"ko":"맞추다, 설정하다","en":"to adjust a clock, machine, or control so it is ready"},{"ko":"정하다","en":"to decide on a time, rule, or price"}]},{"p":"noun","senses":[{"ko":"세트, 한 벌","en":"a group of things that belong together"}]},{"p":"adjective","senses":[{"ko":"준비된, 정해진","en":"ready, or fixed and not changing"}]}],"ph":[{"t":"all set","ko":"준비 다 됐어"},{"t":"set up","ko":"설치하다, 마련하다"},{"t":"set an alarm","ko":"알람을 맞추다"}],"ex":{"en":"Set the box down over there.","ko":"상자를 저기에 내려놔."}},{"id":535,"w":"seven","def":"the number 7","pos":[{"p":"number","senses":[{"ko":"일곱, 7","en":"the number 7"}]}],"ph":[{"t":"seven days a week","ko":"일주일 내내"}],"ex":{"en":"I wake up at seven every day.","ko":"나 매일 7시에 일어나."}},{"id":536,"w":"seventy","def":"the number 70","pos":[{"p":"number","senses":[{"ko":"일흔, 70","en":"the number 70"}]}],"ph":[{"t":"in your seventies","ko":"70대인"}],"ex":{"en":"My grandma is seventy years old.","ko":"우리 할머니는 일흔 살이셔."}},{"id":537,"w":"several","def":"more than two but not many","pos":[{"p":"determiner","senses":[{"ko":"몇몇의, 여러","en":"more than two but not very many"}]},{"p":"pronoun","senses":[{"ko":"몇몇, 여러 개","en":"a few people or things, more than two"}]}],"ph":[{"t":"several times","ko":"몇 번, 여러 번"}],"ex":{"en":"I've been there several times.","ko":"거기 여러 번 가 봤어."}},{"id":538,"w":"shall","def":"expressing the future tense, to expect to happen","pos":[{"p":"modal","senses":[{"ko":"~할 것이다","en":"used to talk about the future, mainly with I and we"},{"ko":"~할까요?","en":"used to make an offer or a suggestion"}]}],"ph":[{"t":"Shall we?","ko":"우리 갈까?, 시작할까?"},{"t":"Shall I ...?","ko":"제가 ~할까요?"},{"t":"We shall see","ko":"두고 보면 알겠지"}],"ex":{"en":"I shall be back by noon.","ko":"정오까지는 돌아올 거예요."}},{"id":539,"w":"share","def":"to have or use something with others","pos":[{"p":"verb","senses":[{"ko":"함께 쓰다, 공유하다","en":"to have or use something together with other people"},{"ko":"나누다","en":"to divide something and give parts of it to others"},{"ko":"(생각, 경험을) 말하다","en":"to tell other people about your thoughts or experiences"}]},{"p":"noun","senses":[{"ko":"몫","en":"the part of something that one person has or does"},{"ko":"주식","en":"one of the equal parts that a company's value is divided into"}]}],"ph":[{"t":"share a room","ko":"방을 같이 쓰다"},{"t":"fair share","ko":"정당한 몫"},{"t":"Thanks for sharing","ko":"얘기해 줘서 고마워"}],"ex":{"en":"I share an apartment with two friends.","ko":"나 친구 둘이랑 아파트 같이 써."}},{"id":540,"w":"she","def":"used to refer to a female that is the subject","pos":[{"p":"pronoun","senses":[{"ko":"그녀, 그 여자","en":"used for a woman, girl, or female animal as the subject"}]}],"ph":[],"ex":{"en":"She's my best friend.","ko":"걔는 내 제일 친한 친구야."}},{"id":541,"w":"shop","def":"a building or room where goods and services are sold","pos":[{"p":"noun","senses":[{"ko":"가게, 상점","en":"a building or room where goods or services are sold"}]},{"p":"verb","senses":[{"ko":"쇼핑하다, 장을 보다","en":"to go to shops to look at and buy things"}]}],"ph":[{"t":"go shopping","ko":"쇼핑하러 가다"},{"t":"shop around","ko":"여러 곳을 비교해 보다"},{"t":"coffee shop","ko":"카페, 커피숍"}],"ex":{"en":"There's a nice little shop on the corner.","ko":"모퉁이에 괜찮은 작은 가게가 있어."}},{"id":542,"w":"short","def":"a small distance from one end to the other","pos":[{"p":"adjective","senses":[{"ko":"짧은","en":"having a small distance from one end to the other"},{"ko":"(키가) 작은","en":"less tall than most people"},{"ko":"부족한, 모자라는","en":"not having enough of something"}]}],"ph":[{"t":"in short","ko":"요컨대, 간단히 말해"},{"t":"short for","ko":"~의 줄임말"},{"t":"run short of","ko":"~이 모자라게 되다"}],"ex":{"en":"She has short hair now.","ko":"걔 지금 머리 짧아."}},{"id":543,"w":"should","def":"used to indicate what is proper or reasonable","pos":[{"p":"modal","senses":[{"ko":"~해야 한다, ~하는 게 좋다","en":"used to say what is right, proper, or reasonable"},{"ko":"~일 것이다","en":"used to say that something is probably true or will happen"}]}],"ph":[{"t":"You should","ko":"너 ~하는 게 좋겠어"},{"t":"should have","ko":"~했어야 했는데"},{"t":"I should think so","ko":"당연하지, 그래야지"}],"ex":{"en":"You should see a doctor.","ko":"병원에 가 보는 게 좋겠어."}},{"id":544,"w":"show","def":"to cause or allow to be seen","pos":[{"p":"verb","senses":[{"ko":"보여 주다","en":"to let someone see something"},{"ko":"알려 주다, 가르쳐 주다","en":"to explain how to do something by doing it"},{"ko":"드러나다, 보이다","en":"to be easy to see or notice"}]},{"p":"noun","senses":[{"ko":"쇼, 프로그램","en":"a performance, or a program on TV or radio"}]}],"ph":[{"t":"show up","ko":"나타나다, 오다"},{"t":"show off","ko":"자랑하다, 뽐내다"},{"t":"show someone around","ko":"~에게 구경시켜 주다"}],"ex":{"en":"Can you show me your photos?","ko":"사진 좀 보여 줄래?"}},{"id":545,"w":"side","def":"a position or direction that is away from the center","pos":[{"p":"noun","senses":[{"ko":"쪽, 측면","en":"a position or direction away from the center of something"},{"ko":"편, 입장","en":"one of the people or groups in an argument or game"},{"ko":"옆구리, 옆","en":"the part of the body from the armpit to the hip"}]}],"ph":[{"t":"on the bright side","ko":"좋게 보면"},{"t":"side by side","ko":"나란히"},{"t":"on the other side","ko":"반대편에, 건너편에"}],"ex":{"en":"Park on the left side of the street.","ko":"길 왼쪽에 주차해."}},{"id":546,"w":"sign","def":"something which shows that something else exists, is true, or will happen","pos":[{"p":"noun","senses":[{"ko":"징후, 표시","en":"something that shows something else exists, is true, or will happen"},{"ko":"표지판, 간판","en":"a board with words or pictures that gives information"},{"ko":"손짓, 신호","en":"a movement or gesture that gives a message"}]},{"p":"verb","senses":[{"ko":"서명하다","en":"to write your name on a document or letter"}]}],"ph":[{"t":"sign up","ko":"가입하다, 등록하다"},{"t":"sign in","ko":"로그인하다, 서명하고 들어가다"},{"t":"a good sign","ko":"좋은 징조"}],"ex":{"en":"Dark clouds are a sign of rain.","ko":"먹구름은 비가 올 징조야."}},{"id":547,"w":"since","def":"because, for the reason that","pos":[{"p":"conjunction","senses":[{"ko":"~ 때문에, ~이니까","en":"because, for the reason that"},{"ko":"~한 이후로","en":"from a time in the past until now"}]},{"p":"preposition","senses":[{"ko":"~ 이후로, ~부터","en":"from a particular time in the past until now"}]}],"ph":[{"t":"ever since","ko":"~ 이후로 줄곧"},{"t":"Since when?","ko":"언제부터?"},{"t":"long since","ko":"오래전에"}],"ex":{"en":"Since you're here, can you help me?","ko":"너 온 김에 나 좀 도와줄래?"}},{"id":548,"w":"sing","def":"to use your voice to make musical sounds in the form of a song or tune","pos":[{"p":"verb","senses":[{"ko":"노래하다","en":"to make musical sounds with your voice in the form of a song"},{"ko":"(새가) 지저귀다","en":"to make pleasant high sounds, used of birds"}]}],"ph":[{"t":"sing along","ko":"따라 부르다"},{"t":"sing someone's praises","ko":"~를 극찬하다"}],"ex":{"en":"She sings in the shower every morning.","ko":"그녀는 매일 아침 샤워하면서 노래해."}},{"id":549,"w":"single","def":"not having or including another, only one","pos":[{"p":"adjective","senses":[{"ko":"단 하나의","en":"only one, not including any others"},{"ko":"미혼의, 독신의","en":"not married or not in a romantic relationship"},{"ko":"1인용의","en":"made for or used by one person"}]},{"p":"noun","senses":[{"ko":"(음악) 싱글","en":"a piece of recorded music released on its own"}]}],"ph":[{"t":"every single","ko":"하나하나 모든, 단 하나도 빠짐없이"},{"t":"single room","ko":"1인실"},{"t":"single out","ko":"골라내다, 지목하다"}],"ex":{"en":"I didn't get a single message today.","ko":"오늘 메시지 하나도 안 왔어."}},{"id":550,"w":"sister","def":"a girl or woman who has one or both of the same parents as you","pos":[{"p":"noun","senses":[{"ko":"언니, 누나, 여동생","en":"a girl or woman who has the same parents as you"},{"ko":"수녀","en":"a woman who is a member of a religious group, a nun"}]}],"ph":[{"t":"big sister","ko":"언니, 누나"},{"t":"little sister","ko":"여동생"}],"ex":{"en":"My sister lives in Busan.","ko":"우리 언니는 부산에 살아."}},{"id":551,"w":"sit","def":"to be in a resting position on a chair or couch","pos":[{"p":"verb","senses":[{"ko":"앉다, 앉아 있다","en":"to rest your weight on your bottom, as on a chair"},{"ko":"앉히다","en":"to make someone sit somewhere"},{"ko":"놓여 있다","en":"to be in a particular place and not move"}]}],"ph":[{"t":"sit down","ko":"앉다"},{"t":"sit tight","ko":"가만히 기다리다"},{"t":"sit back","ko":"편히 앉다; 수수방관하다"}],"ex":{"en":"Come in and sit down.","ko":"들어와서 앉아."}},{"id":552,"w":"site","def":"the place where something is, was, or will be located","pos":[{"p":"noun","senses":[{"ko":"장소, 부지, 현장","en":"the place where something is, was, or will be"},{"ko":"웹사이트","en":"a place on the internet with pages of information, a website"}]}],"ph":[{"t":"on site","ko":"현장에서"},{"t":"building site","ko":"공사 현장"}],"ex":{"en":"This is the site for the new hospital.","ko":"여기가 새 병원 부지야."}},{"id":553,"w":"situation","def":"a condition, location or position","pos":[{"p":"noun","senses":[{"ko":"상황, 처지","en":"the conditions that exist at a particular time and place"},{"ko":"위치, 입지","en":"the location of a place, especially a building or town"}]}],"ph":[{"t":"win-win situation","ko":"모두에게 이로운 상황"},{"t":"in this situation","ko":"이런 상황에서"}],"ex":{"en":"It's a difficult situation for everyone.","ko":"다들 힘든 상황이야."}},{"id":554,"w":"six","def":"the number 6","pos":[{"p":"number","senses":[{"ko":"여섯, 6","en":"the number 6"}]}],"ph":[{"t":"six-pack","ko":"식스팩(복근); 여섯 개들이"}],"ex":{"en":"There are six people on our team.","ko":"우리 팀은 여섯 명이야."}},{"id":555,"w":"sixty","def":"the number 60","pos":[{"p":"number","senses":[{"ko":"예순, 60","en":"the number 60"}]}],"ph":[{"t":"in your sixties","ko":"60대인"}],"ex":{"en":"There are sixty minutes in an hour.","ko":"한 시간은 60분이야."}},{"id":556,"w":"size","def":"the total amount of physical space that a person or thing occupies","pos":[{"p":"noun","senses":[{"ko":"크기","en":"how big or small someone or something is"},{"ko":"(옷, 신발) 사이즈, 치수","en":"one of the standard measurements for clothes or shoes"}]}],"ph":[{"t":"What size are you?","ko":"사이즈가 어떻게 되세요?"},{"t":"size up","ko":"가늠하다, 평가하다"},{"t":"one size fits all","ko":"프리사이즈; 획일적인 방식"}],"ex":{"en":"I was surprised by the size of the room.","ko":"방 크기에 놀랐어."}},{"id":557,"w":"sleep","def":"to rest your mind and body by closing your eyes and becoming unconscious","pos":[{"p":"verb","senses":[{"ko":"자다","en":"to rest your mind and body with your eyes closed, not conscious"},{"ko":"(잠잘) 자리가 있다","en":"to have enough beds for a particular number of people"}]},{"p":"noun","senses":[{"ko":"잠, 수면","en":"the natural state of resting when you are asleep"}]}],"ph":[{"t":"sleep in","ko":"늦잠 자다"},{"t":"sleep on it","ko":"하룻밤 자며 생각해 보다"},{"t":"get some sleep","ko":"좀 자다"}],"ex":{"en":"I couldn't sleep last night.","ko":"어젯밤에 잠을 못 잤어."}},{"id":558,"w":"small","def":"little in size, not great in amount","pos":[{"p":"adjective","senses":[{"ko":"작은, 적은","en":"little in size, or not great in amount"},{"ko":"사소한","en":"not important or serious"},{"ko":"어린","en":"young, used about children"}]}],"ph":[{"t":"small talk","ko":"잡담, 가벼운 대화"},{"t":"It's a small world","ko":"세상 참 좁다"}],"ex":{"en":"This shirt is too small for me.","ko":"이 셔츠 나한테 너무 작아."}},{"id":559,"w":"so","def":"to a degree that is suggested or stated","pos":[{"p":"adverb","senses":[{"ko":"아주, 그렇게","en":"to the degree that is suggested or stated, very"},{"ko":"그렇게, 그래","en":"used to refer back to something already said"},{"ko":"자, 그럼 (말 꺼낼 때)","en":"used to start a new topic or to move a conversation on"},{"ko":"(so do I) ~도 그렇다","en":"used before a verb to say the same is true of someone else"}]},{"p":"conjunction","senses":[{"ko":"그래서","en":"used to show the result of something"},{"ko":"~하도록","en":"used to show purpose, often as so that"}]}],"ph":[{"t":"I think so","ko":"그런 것 같아"},{"t":"so far","ko":"지금까지"},{"t":"or so","ko":"~쯤, ~ 정도"}],"ex":{"en":"I'm so tired today.","ko":"나 오늘 너무 피곤해."}},{"id":560,"w":"some","def":"used to refer to an unspecified amount or number","pos":[{"p":"determiner","senses":[{"ko":"약간의, 몇몇의","en":"used for an amount or number that is not stated"},{"ko":"어떤","en":"used for a person or thing that is not known or named"}]},{"p":"pronoun","senses":[{"ko":"일부, 약간","en":"an amount or number of something, not all of it"}]}],"ph":[{"t":"some day","ko":"언젠가"},{"t":"some more","ko":"조금 더"},{"t":"for some time","ko":"한동안"}],"ex":{"en":"Do you want some coffee?","ko":"커피 좀 마실래?"}},{"id":561,"w":"somebody","def":"person who is not known, named, or specified","pos":[{"p":"pronoun","senses":[{"ko":"누군가, 어떤 사람","en":"a person who is not known, named, or specified"}]},{"p":"noun","senses":[{"ko":"대단한 사람, 중요 인물","en":"an important or well-known person"}]}],"ph":[{"t":"somebody else","ko":"다른 누군가"}],"ex":{"en":"Somebody left their phone here.","ko":"누가 여기 폰 두고 갔어."}},{"id":562,"w":"someone","def":"some person; somebody","pos":[{"p":"pronoun","senses":[{"ko":"누군가, 어떤 사람","en":"a person who is not named or known, somebody"}]}],"ph":[{"t":"someone else","ko":"다른 사람"},{"t":"someone special","ko":"특별한 사람"}],"ex":{"en":"Is someone sitting here?","ko":"여기 누구 앉아요?"}},{"id":563,"w":"something","def":"a thing that is not yet know, specified or named","pos":[{"p":"pronoun","senses":[{"ko":"무언가, 어떤 것","en":"a thing that is not known, named, or specified"}]}],"ph":[{"t":"something like that","ko":"뭐 그런 거"},{"t":"or something","ko":"~이나 뭐"},{"t":"something else","ko":"다른 것; 정말 대단한 것"}],"ex":{"en":"I want to tell you something.","ko":"너한테 할 말이 있어."}},{"id":564,"w":"sometimes","def":"occasionally; only at certain times,","pos":[{"p":"adverb","senses":[{"ko":"가끔, 때때로","en":"on some occasions but not always"}]}],"ph":[],"ex":{"en":"Sometimes I cook, but usually I eat out.","ko":"가끔 요리하는데 보통은 외식해."}},{"id":565,"w":"somewhere","def":"in, at, or to a place not known, named, or specified","pos":[{"p":"adverb","senses":[{"ko":"어딘가에, 어딘가로","en":"in, at, or to a place that is not known or named"},{"ko":"대략, ~쯤","en":"used with numbers to mean about"}]}],"ph":[{"t":"somewhere else","ko":"다른 곳"},{"t":"get somewhere","ko":"진전이 있다"},{"t":"somewhere around","ko":"대략 ~쯤"}],"ex":{"en":"I left my keys somewhere.","ko":"열쇠를 어딘가에 뒀는데."}},{"id":566,"w":"soon","def":"at a time not long from now","pos":[{"p":"adverb","senses":[{"ko":"곧, 머지않아","en":"in a short time from now"},{"ko":"일찍, 빨리","en":"earlier or more quickly than expected"}]}],"ph":[{"t":"as soon as","ko":"~하자마자"},{"t":"See you soon","ko":"곧 봐"},{"t":"sooner or later","ko":"조만간, 언젠가는"}],"ex":{"en":"Dinner will be ready soon.","ko":"저녁 곧 준비돼."}},{"id":567,"w":"sorry","def":"feeling sorrow or regret","pos":[{"p":"adjective","senses":[{"ko":"미안한, 유감스러운","en":"feeling sorrow, regret, or shame about something"},{"ko":"안된, 안쓰러운","en":"feeling sympathy for someone who has a problem"}]},{"p":"interjection","senses":[{"ko":"뭐라고요?, 죄송한데요","en":"used to ask someone to repeat something, or to say excuse me"}]}],"ph":[{"t":"Sorry I'm late","ko":"늦어서 미안"},{"t":"I'm sorry to hear that","ko":"그거 안됐다"},{"t":"feel sorry for","ko":"~를 안쓰러워하다"}],"ex":{"en":"I'm sorry I forgot your birthday.","ko":"생일 깜빡해서 미안해."}},{"id":568,"w":"sort","def":"a group of people or things that have some shared quality","pos":[{"p":"noun","senses":[{"ko":"종류, 유형","en":"a group of people or things that share some quality"},{"ko":"(사람의) 유형, 타입","en":"a particular type of person"}]},{"p":"verb","senses":[{"ko":"분류하다, 정리하다","en":"to arrange things in groups or in a particular order"}]}],"ph":[{"t":"sort of","ko":"약간, 어느 정도"},{"t":"sort out","ko":"해결하다, 정리하다"},{"t":"all sorts of","ko":"온갖 종류의"}],"ex":{"en":"What sort of music do you like?","ko":"어떤 종류의 음악 좋아해?"}},{"id":569,"w":"sound","def":"something that is heard","pos":[{"p":"noun","senses":[{"ko":"소리","en":"something that you hear"}]},{"p":"verb","senses":[{"ko":"~하게 들리다","en":"to seem a particular way from what you hear or read"},{"ko":"소리를 내다, 울리다","en":"to make a noise, or make something produce a noise"}]},{"p":"adjective","senses":[{"ko":"건전한, 튼튼한","en":"in good condition, healthy, or sensible"}]}],"ph":[{"t":"Sounds good","ko":"좋아, 그러자"},{"t":"sounds like","ko":"~인 것 같네"},{"t":"sound asleep","ko":"푹 잠든"}],"ex":{"en":"What's that strange sound?","ko":"저 이상한 소리 뭐야?"}},{"id":570,"w":"speak","def":"to use words to tell information or express thoughts","pos":[{"p":"verb","senses":[{"ko":"말하다, 이야기하다","en":"to use words to give information or express thoughts"},{"ko":"(언어를) 할 줄 알다","en":"to be able to talk in a particular language"},{"ko":"연설하다","en":"to give a formal talk to a group of people"}]}],"ph":[{"t":"speak up","ko":"크게 말하다; 의견을 말하다"},{"t":"speaking of","ko":"~ 얘기가 나와서 말인데"},{"t":"so to speak","ko":"말하자면"}],"ex":{"en":"Can I speak to you for a minute?","ko":"잠깐 얘기 좀 할 수 있을까?"}},{"id":571,"w":"special","def":"different from what is usual, better or greater than normal","pos":[{"p":"adjective","senses":[{"ko":"특별한","en":"different from what is usual, and better or more important"},{"ko":"특수한, 전용의","en":"made or used for one particular purpose"}]},{"p":"noun","senses":[{"ko":"특별 메뉴, 특가 상품","en":"a dish or product offered for a short time, often cheaper"}]}],"ph":[{"t":"nothing special","ko":"별거 아니야, 그냥 그래"},{"t":"special offer","ko":"특가 판매"},{"t":"today's special","ko":"오늘의 특선 메뉴"}],"ex":{"en":"Today is a special day for us.","ko":"오늘은 우리한테 특별한 날이야."}},{"id":572,"w":"specific","def":"special or particular, clearly presented or stated","pos":[{"p":"adjective","senses":[{"ko":"특정한, 구체적인","en":"exact and clearly stated, about one particular thing"},{"ko":"~ 특유의, ~에 한정된","en":"belonging to or affecting only one particular thing or group"}]}],"ph":[{"t":"to be specific","ko":"구체적으로 말하면"},{"t":"anything specific","ko":"특별히 생각해 둔 것"}],"ex":{"en":"Can you be more specific?","ko":"좀 더 구체적으로 말해 줄래?"}},{"id":573,"w":"spend","def":"to use money to pay for something","pos":[{"p":"verb","senses":[{"ko":"(돈을) 쓰다","en":"to use money to pay for things"},{"ko":"(시간을) 보내다","en":"to use time doing something or being somewhere"}]}],"ph":[{"t":"spend time with","ko":"~와 시간을 보내다"},{"t":"spend money on","ko":"~에 돈을 쓰다"}],"ex":{"en":"I spent too much money on clothes.","ko":"옷에 돈을 너무 많이 썼어."}},{"id":574,"w":"staff","def":"a group of people who work for an organization or business","pos":[{"p":"noun","senses":[{"ko":"직원, 스태프","en":"the group of people who work for an organization or business"}]},{"p":"verb","senses":[{"ko":"직원을 두다","en":"to provide the workers needed for an organization or event"}]}],"ph":[{"t":"staff member","ko":"직원 한 명"},{"t":"short-staffed","ko":"일손이 부족한"}],"ex":{"en":"The staff here are really friendly.","ko":"여기 직원들 정말 친절해."}},{"id":575,"w":"stage","def":"a particular point in a process","pos":[{"p":"noun","senses":[{"ko":"단계, 시기","en":"a particular point or period in a process"},{"ko":"무대","en":"a raised area where actors or musicians perform"}]},{"p":"verb","senses":[{"ko":"무대에 올리다, 개최하다","en":"to organize and present a play or public event"}]}],"ph":[{"t":"at this stage","ko":"현 단계에서, 지금으로선"},{"t":"on stage","ko":"무대에서"},{"t":"stage fright","ko":"무대 공포증"}],"ex":{"en":"We're still in the early stages of the project.","ko":"우리 아직 프로젝트 초기 단계야."}},{"id":576,"w":"stand","def":"to be in an upright position supported by on your feet","pos":[{"p":"verb","senses":[{"ko":"서다, 서 있다","en":"to be in an upright position, supported by your feet"},{"ko":"참다, 견디다","en":"to accept something unpleasant, usually used in negatives"},{"ko":"(어떤 곳에) 있다, 위치하다","en":"to be in a particular place"}]},{"p":"noun","senses":[{"ko":"가판대, 노점","en":"a small shop or table, often outdoors, where things are sold"},{"ko":"입장, 태도","en":"an opinion that you state publicly"}]}],"ph":[{"t":"can't stand","ko":"못 참다, 너무 싫다"},{"t":"stand up","ko":"일어서다"},{"t":"stand for","ko":"~을 의미하다, 상징하다"}],"ex":{"en":"We had to stand for the whole trip.","ko":"우리 가는 내내 서 있어야 했어."}},{"id":577,"w":"standard","def":"a level of quality or achievement that is considered acceptable","pos":[{"p":"noun","senses":[{"ko":"수준, 기준","en":"a level of quality or achievement that people accept as good enough"},{"ko":"표준, 규범","en":"a rule or principle used to judge something"}]},{"p":"adjective","senses":[{"ko":"표준의, 일반적인","en":"normal, usual, or most common"}]}],"ph":[{"t":"up to standard","ko":"기준에 맞는"},{"t":"double standard","ko":"이중 잣대"},{"t":"standard of living","ko":"생활 수준"}],"ex":{"en":"This hotel has very high standards.","ko":"이 호텔은 기준이 아주 높아."}},{"id":578,"w":"start","def":"to begin doing something","pos":[{"p":"verb","senses":[{"ko":"시작하다","en":"to begin doing something"},{"ko":"시작되다","en":"to begin to happen or exist"},{"ko":"(기계를) 켜다, 시동을 걸다","en":"to make a machine or car begin to work"}]},{"p":"noun","senses":[{"ko":"시작, 출발","en":"the beginning of something"}]}],"ph":[{"t":"get started","ko":"시작하다"},{"t":"start over","ko":"처음부터 다시 하다"},{"t":"for a start","ko":"우선, 첫째로"}],"ex":{"en":"When did you start learning English?","ko":"영어 언제 배우기 시작했어?"}},{"id":579,"w":"state","def":"a way of living or existing","pos":[{"p":"noun","senses":[{"ko":"상태","en":"the condition that someone or something is in"},{"ko":"주(州)","en":"one of the areas with its own government in a country like the US"},{"ko":"국가, 정부","en":"a country, or its government"}]},{"p":"verb","senses":[{"ko":"말하다, 진술하다","en":"to say or write something clearly and formally"}]}],"ph":[{"t":"state of mind","ko":"심리 상태"},{"t":"in a state","ko":"몹시 흥분한; 엉망인"},{"t":"state the obvious","ko":"뻔한 소리를 하다"}],"ex":{"en":"The house was in a terrible state.","ko":"그 집 상태가 엉망이었어."}},{"id":580,"w":"statement","def":"something that someone says or writes officially","pos":[{"p":"noun","senses":[{"ko":"성명, 진술","en":"something that someone says or writes officially"},{"ko":"명세서, 거래 내역서","en":"a document showing the money paid into and out of an account"}]}],"ph":[{"t":"make a statement","ko":"성명을 내다; 개성을 드러내다"},{"t":"bank statement","ko":"은행 거래 내역서"}],"ex":{"en":"The police took a statement from the driver.","ko":"경찰이 운전자의 진술을 받았어."}},{"id":581,"w":"stay","def":"to continue to be in the same place; remain","pos":[{"p":"verb","senses":[{"ko":"머무르다, 남다","en":"to continue to be in the same place"},{"ko":"(상태를) 유지하다","en":"to continue to be in a particular state"},{"ko":"묵다, 지내다","en":"to live somewhere as a guest for a short time"}]},{"p":"noun","senses":[{"ko":"머무름, 체류","en":"a period of time spent somewhere"}]}],"ph":[{"t":"stay up","ko":"안 자고 깨어 있다"},{"t":"stay in touch","ko":"연락하고 지내다"},{"t":"stay out of","ko":"~에 끼어들지 않다"}],"ex":{"en":"Can you stay a little longer?","ko":"조금 더 있다 갈 수 있어?"}},{"id":582,"w":"step","def":"moving by lifting a foot and putting it down in a different place","pos":[{"p":"noun","senses":[{"ko":"걸음, 발걸음","en":"a movement of lifting your foot and putting it down in a new place"},{"ko":"단계, 조치","en":"one of a series of actions done to achieve something"},{"ko":"계단","en":"a flat surface you put your foot on to go up or down"}]},{"p":"verb","senses":[{"ko":"발을 디디다, 걸음을 옮기다","en":"to lift your foot and put it down in a different place"}]}],"ph":[{"t":"step by step","ko":"한 단계씩, 차근차근"},{"t":"watch your step","ko":"발밑 조심해"},{"t":"step in","ko":"개입하다, 나서다"}],"ex":{"en":"Take one step forward, please.","ko":"앞으로 한 걸음 나와 주세요."}},{"id":583,"w":"stick","def":"a cut or broken branch or twig","pos":[{"p":"noun","senses":[{"ko":"막대기, 나뭇가지","en":"a thin piece of wood that has been cut or broken from a tree"},{"ko":"지팡이","en":"a long thin piece of wood used to help you walk"}]},{"p":"verb","senses":[{"ko":"붙이다, 달라붙다","en":"to fix something to a surface, or to stay fixed to it"},{"ko":"찌르다, 꽂다","en":"to push something pointed into something else"}]}],"ph":[{"t":"stick around","ko":"가지 않고 머무르다"},{"t":"stick to","ko":"~을 고수하다, 지키다"},{"t":"stick with","ko":"~을 계속하다; ~ 곁에 있다"}],"ex":{"en":"The dog brought back the stick.","ko":"개가 막대기를 물어 왔어."}},{"id":584,"w":"still","def":"used to express that an action or condition continues","pos":[{"p":"adverb","senses":[{"ko":"아직, 여전히","en":"used to say that an action or condition continues"},{"ko":"그래도, 그럼에도","en":"despite what has just been said"}]},{"p":"adjective","senses":[{"ko":"가만히 있는, 고요한","en":"not moving, or calm and quiet"}]}],"ph":[{"t":"keep still","ko":"가만히 있어"},{"t":"stand still","ko":"가만히 서 있다; 정체되다"}],"ex":{"en":"Are you still at work?","ko":"아직 회사야?"}},{"id":585,"w":"stop","def":"to not move or come to an end","pos":[{"p":"verb","senses":[{"ko":"멈추다, 서다","en":"to no longer move, or to come to an end"},{"ko":"그만두다","en":"to no longer do something you were doing"},{"ko":"막다","en":"to prevent someone from doing something or something from happening"}]},{"p":"noun","senses":[{"ko":"정류장","en":"a place where a bus or train regularly stops for passengers"}]}],"ph":[{"t":"Stop it!","ko":"그만해!"},{"t":"stop by","ko":"잠깐 들르다"},{"t":"bus stop","ko":"버스 정류장"}],"ex":{"en":"The car stopped at the red light.","ko":"차가 빨간불에 멈췄어."}},{"id":586,"w":"story","def":"a description of how something happened","pos":[{"p":"noun","senses":[{"ko":"이야기, 경위","en":"a description of how something happened"},{"ko":"(지어낸) 이야기, 소설","en":"a description of made-up events told to entertain people"},{"ko":"(건물의) 층","en":"one level of a building"}]}],"ph":[{"t":"long story short","ko":"간단히 말하면"},{"t":"That's another story","ko":"그건 또 다른 얘기야"},{"t":"the same old story","ko":"늘 있는 일"}],"ex":{"en":"Tell me the whole story.","ko":"무슨 일인지 다 얘기해 봐."}},{"id":587,"w":"straight","def":"not having curves, bends, or angles","pos":[{"p":"adjective","senses":[{"ko":"곧은, 똑바른","en":"not having any curves, bends, or angles"},{"ko":"솔직한","en":"honest and direct in what you say"},{"ko":"연속의","en":"one after another without a break"}]},{"p":"adverb","senses":[{"ko":"곧장, 똑바로","en":"directly, without stopping or turning"}]}],"ph":[{"t":"go straight","ko":"직진하다"},{"t":"straight away","ko":"즉시, 곧바로"},{"t":"get something straight","ko":"~을 확실히 해 두다"}],"ex":{"en":"She has long, straight hair.","ko":"그녀는 긴 생머리야."}},{"id":588,"w":"street","def":"a public road in a city or town","pos":[{"p":"noun","senses":[{"ko":"거리, 도로","en":"a public road in a city or town, usually with buildings along it"}]}],"ph":[{"t":"across the street","ko":"길 건너편에"},{"t":"on the street","ko":"길에서; 노숙하는"}],"ex":{"en":"This street is always busy.","ko":"이 거리는 항상 붐벼."}},{"id":589,"w":"strong","def":"having physical power or strength","pos":[{"p":"adjective","senses":[{"ko":"힘센, 강한","en":"having a lot of physical power or strength"},{"ko":"튼튼한, 견고한","en":"not easily broken or damaged"},{"ko":"(맛, 냄새가) 진한, 강한","en":"having a lot of flavor or smell"}]}],"ph":[{"t":"still going strong","ko":"여전히 건재한"},{"t":"strong point","ko":"강점, 장점"}],"ex":{"en":"He's strong enough to lift the sofa.","ko":"그는 소파를 들 만큼 힘이 세."}},{"id":590,"w":"student","def":"a person who attends a school","pos":[{"p":"noun","senses":[{"ko":"학생","en":"a person who goes to a school to learn"},{"ko":"대학생","en":"a person who studies at a college or university"}]}],"ph":[{"t":"exchange student","ko":"교환 학생"},{"t":"student loan","ko":"학자금 대출"}],"ex":{"en":"My brother is a high school student.","ko":"내 동생은 고등학생이야."}},{"id":591,"w":"study","def":"devoting time to learn about something","pos":[{"p":"verb","senses":[{"ko":"공부하다","en":"to spend time learning about a subject"},{"ko":"연구하다, 자세히 살피다","en":"to look at something carefully to learn more about it"}]},{"p":"noun","senses":[{"ko":"공부, 학업","en":"the activity of learning about a subject"},{"ko":"연구","en":"a piece of research into a particular subject"},{"ko":"서재","en":"a room in a house used for reading and working"}]}],"ph":[{"t":"study for","ko":"~ 시험을 대비해 공부하다"},{"t":"study abroad","ko":"유학하다"},{"t":"case study","ko":"사례 연구"}],"ex":{"en":"I have to study for my exam tonight.","ko":"오늘 밤에 시험공부 해야 해."}},{"id":592,"w":"stuff","def":"materials, supplies, or equipment","pos":[{"p":"noun","senses":[{"ko":"물건, 것들, 짐","en":"things, materials, or equipment"},{"ko":"일, 것","en":"used to talk about ideas, things, or activities in general"}]},{"p":"verb","senses":[{"ko":"채워 넣다, 쑤셔 넣다","en":"to fill something tightly, or push something into a small space"}]}],"ph":[{"t":"and stuff","ko":"~ 같은 것들, 기타 등등"},{"t":"I'm stuffed","ko":"배불러"},{"t":"know your stuff","ko":"그 분야를 잘 알다"}],"ex":{"en":"Where should I put all my stuff?","ko":"내 짐 다 어디에 둘까?"}},{"id":593,"w":"subject","def":"the thing being discussed or described","pos":[{"p":"noun","senses":[{"ko":"주제, 화제","en":"the thing that is being talked or written about"},{"ko":"과목","en":"an area of knowledge studied at school"}]},{"p":"adjective","senses":[{"ko":"~의 영향을 받는, ~하기 쉬운","en":"likely to be affected by something, used as subject to"}]}],"ph":[{"t":"change the subject","ko":"화제를 바꾸다"},{"t":"subject to","ko":"~에 따라 달라질 수 있는"},{"t":"on the subject of","ko":"~에 관해서 말인데"}],"ex":{"en":"That's a hard subject to talk about.","ko":"그건 이야기하기 어려운 주제야."}},{"id":594,"w":"such","def":"like or similar","pos":[{"p":"determiner","senses":[{"ko":"그런, 그와 같은","en":"of the kind already mentioned, like or similar"},{"ko":"아주, 정말","en":"used to emphasize a quality"}]}],"ph":[{"t":"such as","ko":"~와 같은, 예를 들면"},{"t":"no such thing","ko":"그런 건 없다"},{"t":"such a shame","ko":"정말 안타깝다"}],"ex":{"en":"I've never seen such a thing before.","ko":"그런 건 처음 봐."}},{"id":595,"w":"suggest","def":"to mention something as a possible thing to be done","pos":[{"p":"verb","senses":[{"ko":"제안하다","en":"to mention an idea or plan for other people to consider"},{"ko":"암시하다, 시사하다","en":"to show that something is likely to be true without saying it directly"}]}],"ph":[{"t":"I suggest you ...","ko":"~하는 게 좋겠어"},{"t":"Are you suggesting ...?","ko":"~라는 말이야?"}],"ex":{"en":"I suggest we take a short break.","ko":"잠깐 쉬는 게 좋겠어."}},{"id":596,"w":"summer","def":"the warmest season of the year that is after spring and before autumn","pos":[{"p":"noun","senses":[{"ko":"여름","en":"the warmest season of the year, between spring and autumn"}]}],"ph":[{"t":"summer vacation","ko":"여름 방학, 여름휴가"},{"t":"this summer","ko":"올여름"}],"ex":{"en":"We're going to the beach this summer.","ko":"우리 올여름에 바다 가."}},{"id":597,"w":"support","def":"to give assistance to","pos":[{"p":"verb","senses":[{"ko":"지지하다, 돕다","en":"to give help or encouragement to someone"},{"ko":"부양하다","en":"to provide the money someone needs to live"},{"ko":"(팀을) 응원하다","en":"to like a sports team and want it to win"}]},{"p":"noun","senses":[{"ko":"지지, 도움","en":"help, encouragement, or money given to someone"}]}],"ph":[{"t":"Thanks for your support","ko":"응원해 줘서 고마워"},{"t":"tech support","ko":"기술 지원"},{"t":"emotional support","ko":"정서적 지지"}],"ex":{"en":"My parents always support my decisions.","ko":"부모님은 항상 내 결정을 지지해 주셔."}},{"id":598,"w":"suppose","def":"to think of something as happening or being true in order to imagine what might happen","pos":[{"p":"verb","senses":[{"ko":"가정하다, ~라고 치다","en":"to imagine that something is true to think about what might happen"},{"ko":"~라고 생각하다, 추측하다","en":"to think that something is probably true"}]}],"ph":[{"t":"be supposed to","ko":"~하기로 되어 있다"},{"t":"I suppose so","ko":"아마 그렇겠지"},{"t":"Suppose ...","ko":"만약 ~라면"}],"ex":{"en":"Suppose you won the lottery. What would you do?","ko":"복권에 당첨됐다고 쳐. 뭐 할 거야?"}},{"id":599,"w":"sure","def":"completely confident of being right, not having any doubt","pos":[{"p":"adjective","senses":[{"ko":"확신하는","en":"completely confident that you are right, with no doubt"},{"ko":"확실한, 틀림없는","en":"certain to happen or be true"}]},{"p":"adverb","senses":[{"ko":"물론, 그럼","en":"yes, used to agree or say you will do something"},{"ko":"정말, 확실히","en":"used informally to emphasize a statement, as in it sure is hot"}]}],"ph":[{"t":"make sure","ko":"확실히 하다, 꼭 ~하다"},{"t":"for sure","ko":"확실히, 틀림없이"},{"t":"Sure thing","ko":"물론이지"}],"ex":{"en":"Are you sure about that?","ko":"그거 확실해?"}},{"id":600,"w":"surprise","def":"an unexpected event, piece of information, etc.","pos":[{"p":"noun","senses":[{"ko":"뜻밖의 일, 놀라운 일","en":"an unexpected event or piece of information"},{"ko":"놀람","en":"the feeling caused by something unexpected"}]},{"p":"verb","senses":[{"ko":"놀라게 하다","en":"to make someone feel surprised"}]}],"ph":[{"t":"What a surprise!","ko":"이게 웬일이야!"},{"t":"surprise party","ko":"깜짝 파티"},{"t":"take someone by surprise","ko":"~를 깜짝 놀라게 하다"}],"ex":{"en":"I have a surprise for you.","ko":"너한테 줄 깜짝 선물이 있어."}},{"id":601,"w":"system","def":"a set of related parts that move or work together","pos":[{"p":"noun","senses":[{"ko":"체계, 시스템","en":"a set of related parts that work together"},{"ko":"제도, 방식","en":"an organized way of doing something"}]}],"ph":[{"t":"get it out of your system","ko":"속에 있는 걸 털어 버리다"},{"t":"operating system","ko":"운영 체제"}],"ex":{"en":"Our heating system broke last night.","ko":"어젯밤에 난방 시스템이 고장 났어."}},{"id":602,"w":"table","def":"a piece of furniture with a flat top and legs","pos":[{"p":"noun","senses":[{"ko":"탁자, 테이블","en":"a piece of furniture with a flat top and legs"},{"ko":"표","en":"a list of facts or numbers arranged in rows and columns"}]}],"ph":[{"t":"set the table","ko":"상을 차리다"},{"t":"on the table","ko":"논의 중인, 제시된"},{"t":"turn the tables","ko":"형세를 역전시키다"}],"ex":{"en":"Can I book a table for two?","ko":"두 명 자리 예약할 수 있어요?"}},{"id":603,"w":"take","def":"to carry or move with one's hands, to reach for","pos":[{"p":"verb","senses":[{"ko":"잡다, 가져가다","en":"to hold something with your hands, or carry it somewhere"},{"ko":"(시간이) 걸리다","en":"to need a particular amount of time"},{"ko":"데려가다","en":"to go with someone to a place"},{"ko":"(교통수단을) 타다","en":"to travel by a bus, train, taxi, or other vehicle"},{"ko":"(수업을) 듣다, (시험을) 보다","en":"to study a subject or do a test"}]}],"ph":[{"t":"take it easy","ko":"쉬엄쉬엄 해, 진정해"},{"t":"take care","ko":"잘 지내, 조심해"},{"t":"take off","ko":"벗다; 이륙하다"}],"ex":{"en":"Take my hand.","ko":"내 손 잡아."}},{"id":604,"w":"talk","def":"using words to express opinions or give information","pos":[{"p":"verb","senses":[{"ko":"말하다, 이야기하다","en":"to use words to express opinions or give information"},{"ko":"상의하다","en":"to discuss something serious with someone"}]},{"p":"noun","senses":[{"ko":"대화, 이야기","en":"a conversation between two or more people"},{"ko":"강연","en":"a speech given to a group of people"}]}],"ph":[{"t":"Talk to you later","ko":"나중에 얘기하자"},{"t":"talk about","ko":"~에 대해 이야기하다"},{"t":"talk someone into","ko":"~를 설득해 ~하게 하다"}],"ex":{"en":"We talked for hours last night.","ko":"우리 어젯밤에 몇 시간 동안 얘기했어."}},{"id":605,"w":"tape","def":"a long, narrow piece of material used to stick things","pos":[{"p":"noun","senses":[{"ko":"테이프","en":"a long narrow strip of sticky material used to join things"},{"ko":"(녹음, 녹화) 테이프","en":"a narrow plastic strip used to record sound or video"}]},{"p":"verb","senses":[{"ko":"테이프로 붙이다","en":"to stick something somewhere using tape"},{"ko":"녹음하다, 녹화하다","en":"to record sound or pictures"}]}],"ph":[{"t":"duct tape","ko":"강력 접착테이프"},{"t":"red tape","ko":"불필요한 행정 절차"}],"ex":{"en":"Do you have some tape?","ko":"테이프 있어?"}},{"id":606,"w":"tax","def":"money that a government requires people to pay","pos":[{"p":"noun","senses":[{"ko":"세금","en":"money that people and businesses must pay to the government"}]},{"p":"verb","senses":[{"ko":"세금을 부과하다","en":"to make someone pay money to the government on income or goods"}]}],"ph":[{"t":"tax return","ko":"세금 신고(서)"},{"t":"before tax","ko":"세전"},{"t":"after tax","ko":"세후"}],"ex":{"en":"Is tax included in the price?","ko":"가격에 세금 포함이에요?"}},{"id":607,"w":"tea","def":"a drink that is made by soaking the dried leaves of an Asian plant in hot water","pos":[{"p":"noun","senses":[{"ko":"차, 홍차","en":"a hot drink made by pouring boiling water onto dried leaves"},{"ko":"(오후의) 가벼운 식사","en":"a light meal eaten in the afternoon, especially in Britain"}]}],"ph":[{"t":"a cup of tea","ko":"차 한 잔"},{"t":"not my cup of tea","ko":"내 취향이 아니야"}],"ex":{"en":"Would you like some tea?","ko":"차 좀 드실래요?"}},{"id":608,"w":"teach","def":"to instruct or help to learn","pos":[{"p":"verb","senses":[{"ko":"가르치다","en":"to help someone learn something by showing or explaining it"},{"ko":"(교사로) 가르치다, 수업하다","en":"to give lessons in a subject as your job"}]}],"ph":[{"t":"teach someone a lesson","ko":"따끔하게 혼내 주다"},{"t":"That'll teach you.","ko":"그래야 정신 차리지"}],"ex":{"en":"Can you teach me how to cook this?","ko":"이거 요리하는 법 좀 가르쳐 줄래?"}},{"id":609,"w":"teacher","def":"someone whose job is to teach in a school, college, etc.","pos":[{"p":"noun","senses":[{"ko":"선생님, 교사","en":"a person whose job is teaching, especially in a school"}]}],"ph":[{"t":"English teacher","ko":"영어 선생님"},{"t":"homeroom teacher","ko":"담임 선생님"}],"ex":{"en":"My sister is a high school teacher.","ko":"우리 언니는 고등학교 선생님이야."}},{"id":610,"w":"team","def":"a group of people who compete in a sport, game","pos":[{"p":"noun","senses":[{"ko":"팀, 단체","en":"a group of people who play a sport or game together against others"},{"ko":"(함께 일하는) 팀, 조","en":"a group of people who work together on a task"}]}],"ph":[{"t":"team up (with)","ko":"(~와) 팀을 이루다, 협력하다"},{"t":"team player","ko":"협동을 잘하는 사람"}],"ex":{"en":"Which team are you rooting for?","ko":"너 어느 팀 응원해?"}},{"id":611,"w":"tell","def":"to say or communicate information to someone","pos":[{"p":"verb","senses":[{"ko":"말하다, 알려 주다","en":"to give information to someone by speaking or writing"},{"ko":"알다, 구별하다","en":"to know or recognize something from what you see or hear"},{"ko":"시키다, ~하라고 하다","en":"to order or advise someone to do something"}]}],"ph":[{"t":"I told you so.","ko":"내가 그랬잖아"},{"t":"I can tell.","ko":"딱 보면 알아"},{"t":"to tell you the truth","ko":"솔직히 말하면"}],"ex":{"en":"Can you tell me where the station is?","ko":"역이 어디인지 알려 줄래요?"}},{"id":612,"w":"ten","def":"the number 10","pos":[{"p":"number","senses":[{"ko":"10, 열","en":"the number 10, one more than nine"}]}],"ph":[{"t":"ten to one","ko":"십중팔구"},{"t":"top ten","ko":"상위 10위"}],"ex":{"en":"I'll be there in ten minutes.","ko":"10분 안에 도착할게."}},{"id":613,"w":"tend","def":"used to describe what often happens or what someone often does or is likely to do","pos":[{"p":"verb","senses":[{"ko":"~하는 경향이 있다","en":"to usually do something or be likely to happen"},{"ko":"돌보다, 보살피다","en":"to take care of someone or something"}]}],"ph":[{"t":"tend to","ko":"~하는 편이다, ~하기 쉽다"}],"ex":{"en":"I tend to wake up early.","ko":"나는 일찍 일어나는 편이야."}},{"id":614,"w":"term","def":"a word or phrase that describes something else","pos":[{"p":"noun","senses":[{"ko":"용어, 말","en":"a word or phrase used to name or describe something"},{"ko":"학기","en":"one of the periods that a school year is divided into"},{"ko":"기간, 임기","en":"a fixed period of time that something lasts"}]}],"ph":[{"t":"in terms of","ko":"~ 면에서, ~에 관해서"},{"t":"on good terms","ko":"사이가 좋은"},{"t":"come to terms with","ko":"(힘든 일을) 받아들이다"}],"ex":{"en":"I don't know that term. What does it mean?","ko":"그 용어 모르겠어. 무슨 뜻이야?"}},{"id":615,"w":"test","def":"a set of questions designed to measure a person's ability","pos":[{"p":"noun","senses":[{"ko":"시험, 테스트","en":"a set of questions or tasks that measures someone's knowledge or skill"},{"ko":"검사","en":"a medical check of part of your body"}]},{"p":"verb","senses":[{"ko":"시험하다, 검사하다","en":"to check how well something works or what someone knows"}]}],"ph":[{"t":"take a test","ko":"시험을 보다"},{"t":"put to the test","ko":"시험대에 올리다"},{"t":"test drive","ko":"시운전, 시승"}],"ex":{"en":"I have a math test tomorrow.","ko":"나 내일 수학 시험 있어."}},{"id":616,"w":"text","def":"the original words in main writing or speech","pos":[{"p":"noun","senses":[{"ko":"본문, 글","en":"the written words in a book, document, or speech"},{"ko":"문자 메시지","en":"a written message sent from one mobile phone to another"}]},{"p":"verb","senses":[{"ko":"문자를 보내다","en":"to send someone a written message by mobile phone"}]}],"ph":[{"t":"Text me.","ko":"문자 줘"},{"t":"text message","ko":"문자 메시지"}],"ex":{"en":"Read the text carefully before you answer.","ko":"답하기 전에 글을 잘 읽어 봐."}},{"id":617,"w":"than","def":"used to introduce a second part that is being compared","pos":[{"p":"conjunction","senses":[{"ko":"~보다","en":"used after a comparison word to introduce the second thing compared"}]}],"ph":[{"t":"more than","ko":"~ 이상, ~보다 많이"},{"t":"less than","ko":"~ 미만, ~보다 적게"},{"t":"rather than","ko":"~보다는, ~ 대신에"}],"ex":{"en":"She's taller than me.","ko":"걔가 나보다 키 커."}},{"id":618,"w":"thank","def":"to tell (someone) that you are grateful for something that he or she has done or given","pos":[{"p":"verb","senses":[{"ko":"감사하다, 고마워하다","en":"to tell someone you are grateful for something they did or gave"}]}],"ph":[{"t":"Thank you.","ko":"고마워요"},{"t":"Thank God.","ko":"다행이다"},{"t":"No, thank you.","ko":"아니요, 괜찮아요"}],"ex":{"en":"I just want to thank you for your help.","ko":"도와줘서 고맙다고 말하고 싶었어."}},{"id":619,"w":"that","def":"used to identify a specific person, thing, fact or idea","pos":[{"p":"determiner","senses":[{"ko":"그, 저","en":"used to point to a particular person or thing, often one farther away"}]},{"p":"pronoun","senses":[{"ko":"그것, 저것","en":"used for a thing or idea already mentioned or farther away"},{"ko":"~하는 (것, 사람)","en":"used to introduce a part that describes a person or thing"}]},{"p":"conjunction","senses":[{"ko":"~라는 것","en":"used to introduce a clause that reports or explains something"}]},{"p":"adverb","senses":[{"ko":"그렇게, 그 정도로","en":"to the degree that is mentioned or understood, as in not that bad"}]}],"ph":[{"t":"That's it.","ko":"바로 그거야; 그게 다야"},{"t":"That's right.","ko":"맞아"},{"t":"That's why","ko":"그래서 ~인 거야"}],"ex":{"en":"Who's that guy over there?","ko":"저기 저 남자 누구야?"}},{"id":620,"w":"the","def":"used to point to something already mentioned","pos":[{"p":"article","senses":[{"ko":"그, 앞서 말한","en":"used before a noun that has already been mentioned or is known"},{"ko":"(유일한 것 앞에서) 그","en":"used before something that there is only one of"}]}],"ph":[{"t":"by the way","ko":"그나저나, 그건 그렇고"},{"t":"the same","ko":"똑같은 (것)"},{"t":"the more, the better","ko":"많을수록 좋다"}],"ex":{"en":"I loved the movie we saw yesterday.","ko":"어제 본 그 영화 너무 좋았어."}},{"id":621,"w":"themselves","def":"the reflexive form of the pronoun 'they'","pos":[{"p":"pronoun","senses":[{"ko":"그들 자신","en":"used when the people doing an action are also affected by it"},{"ko":"직접, 스스로","en":"used to stress that a group did something without help"}]}],"ph":[{"t":"by themselves","ko":"자기들끼리, 혼자 힘으로"},{"t":"enjoy themselves","ko":"즐거운 시간을 보내다"}],"ex":{"en":"They really enjoyed themselves at the party.","ko":"걔들 파티에서 진짜 재밌게 놀았어."}},{"id":622,"w":"then","def":"at that time, at the time mentioned, after that","pos":[{"p":"adverb","senses":[{"ko":"그때, 그 당시","en":"at a particular time in the past or the future"},{"ko":"그다음에, 그러고 나서","en":"after that; next in order"},{"ko":"그러면, 그렇다면","en":"used to show that something follows from what was just said"}]}],"ph":[{"t":"See you then.","ko":"그때 봐"},{"t":"back then","ko":"그 시절에, 그때는"},{"t":"now and then","ko":"가끔, 때때로"}],"ex":{"en":"I was living in Busan then.","ko":"나 그때 부산에 살고 있었어."}},{"id":623,"w":"there","def":"in that place or position, at that location","pos":[{"p":"adverb","senses":[{"ko":"거기에, 그곳에","en":"in, at, or to that place or position"}]},{"p":"pronoun","senses":[{"ko":"(there is) ~이 있다","en":"used with the verb be to say that something exists"}]}],"ph":[{"t":"over there","ko":"저기, 저쪽에"},{"t":"There you go.","ko":"자, 여기 있어; 그렇지"},{"t":"I'll be there.","ko":"(거기) 갈게"}],"ex":{"en":"I left my bag over there.","ko":"가방 저기 뒀어."}},{"id":624,"w":"therefore","def":"for that reason or because of that","pos":[{"p":"adverb","senses":[{"ko":"그러므로, 따라서","en":"for that reason; as a result of that"}]}],"ph":[],"ex":{"en":"He's sick, and therefore he can't come.","ko":"걔 아파서 못 와."}},{"id":625,"w":"they","def":"used to refer to two or more people, animals, or things","pos":[{"p":"pronoun","senses":[{"ko":"그들, 그것들","en":"used for two or more people, animals, or things already mentioned"},{"ko":"(성별 모를 때) 그 사람","en":"used for one person when you do not know or say their gender"},{"ko":"(일반적인) 사람들","en":"used for people in general or people in authority"}]}],"ph":[{"t":"They say ...","ko":"사람들 말이 ~래"}],"ex":{"en":"Where are your parents? Are they home?","ko":"부모님 어디 계셔? 집에 계셔?"}},{"id":626,"w":"thing","def":"an object, animal, or quality doesn't have a specific name","pos":[{"p":"noun","senses":[{"ko":"것, 물건","en":"an object, idea, or quality that you do not name exactly"},{"ko":"일, 상황","en":"an event, action, or situation"}]}],"ph":[{"t":"The thing is ...","ko":"문제는 말이야, 사실은"},{"t":"first thing in the morning","ko":"아침에 제일 먼저"},{"t":"It's not my thing.","ko":"내 취향이 아니야"}],"ex":{"en":"What's that thing on the table?","ko":"탁자 위에 저거 뭐야?"}},{"id":627,"w":"think","def":"to believe or have a particular idea","pos":[{"p":"verb","senses":[{"ko":"생각하다, ~라고 여기다","en":"to believe or have an opinion that something is true"},{"ko":"생각하다, 고민하다","en":"to use your mind to consider something"}]}],"ph":[{"t":"I think so.","ko":"그런 것 같아"},{"t":"think twice","ko":"다시 한번 생각하다"},{"t":"Come to think of it","ko":"생각해 보니"}],"ex":{"en":"I think it's going to rain.","ko":"비 올 것 같아."}},{"id":628,"w":"thirty","def":"the number 30","pos":[{"p":"number","senses":[{"ko":"30, 서른","en":"the number 30, three times ten"}]}],"ph":[{"t":"in your thirties","ko":"30대에"}],"ex":{"en":"The bus comes every thirty minutes.","ko":"버스가 30분마다 와."}},{"id":629,"w":"this","def":"used to identify a specific person, thing, or idea that is close","pos":[{"p":"determiner","senses":[{"ko":"이","en":"used to point to a person or thing that is near or being discussed"}]},{"p":"pronoun","senses":[{"ko":"이것","en":"the thing that is near you or that you are talking about"},{"ko":"(소개·전화) 이 사람, 저","en":"used to introduce someone or say who you are on the phone"}]},{"p":"adverb","senses":[{"ko":"이만큼, 이렇게","en":"to the degree shown or mentioned, as in about this big"}]}],"ph":[{"t":"this time","ko":"이번에는"},{"t":"like this","ko":"이렇게"},{"t":"This is ...","ko":"(전화) 저 ~예요; 이쪽은 ~야"}],"ex":{"en":"Is this seat taken?","ko":"이 자리 주인 있어요?"}},{"id":630,"w":"though","def":"although, despite the fact that","pos":[{"p":"conjunction","senses":[{"ko":"비록 ~이지만","en":"despite the fact that; although"}]},{"p":"adverb","senses":[{"ko":"그래도, 하지만","en":"used at the end of a sentence to add a contrast"}]}],"ph":[{"t":"even though","ko":"비록 ~일지라도"},{"t":"as though","ko":"마치 ~인 것처럼"}],"ex":{"en":"I still went, though I was really tired.","ko":"엄청 피곤했지만 그래도 갔어."}},{"id":631,"w":"thousand","def":"the number 1000","pos":[{"p":"number","senses":[{"ko":"1000, 천","en":"the number 1000, ten times one hundred"}]}],"ph":[{"t":"thousands of","ko":"수천의, 엄청 많은"},{"t":"a thousand times","ko":"수도 없이, 몇 번이고"}],"ex":{"en":"This laptop cost over a thousand dollars.","ko":"이 노트북 천 달러 넘게 줬어."}},{"id":632,"w":"three","def":"the number 3","pos":[{"p":"number","senses":[{"ko":"3, 셋","en":"the number 3, one more than two"}]}],"ph":[{"t":"two or three","ko":"두세 개(의)"}],"ex":{"en":"I have three brothers.","ko":"나 남자 형제가 셋이야."}},{"id":633,"w":"through","def":"into one side and out of the other side","pos":[{"p":"preposition","senses":[{"ko":"~을 통과하여, 관통하여","en":"in one side or end of something and out the other"},{"ko":"~ 내내, 처음부터 끝까지","en":"from the beginning to the end of a period or activity"},{"ko":"~을 통해서","en":"by means of someone or something; because of"}]}],"ph":[{"t":"go through","ko":"겪다; 살펴보다"},{"t":"get through","ko":"견뎌 내다; 통과하다"},{"t":"be through with","ko":"~와 끝내다, ~을 다 하다"}],"ex":{"en":"We drove through the tunnel.","ko":"우리 차로 터널을 통과했어."}},{"id":634,"w":"throw","def":"to cause (something) to move out of your hand and through the air by quickly moving your arm forward","pos":[{"p":"verb","senses":[{"ko":"던지다","en":"to send something through the air by moving your arm quickly"},{"ko":"(파티를) 열다","en":"to organize and hold a party or event"}]}],"ph":[{"t":"throw away","ko":"버리다"},{"t":"throw up","ko":"토하다"},{"t":"throw a party","ko":"파티를 열다"}],"ex":{"en":"Throw me the ball!","ko":"공 던져 줘!"}},{"id":635,"w":"till","def":"until","pos":[{"p":"preposition","senses":[{"ko":"~까지","en":"up to a particular time; until"}]},{"p":"conjunction","senses":[{"ko":"~할 때까지","en":"up to the time when something happens"}]}],"ph":[{"t":"till then","ko":"그때까지"},{"t":"not till","ko":"~이 되어서야 비로소"}],"ex":{"en":"The shop is open till nine.","ko":"그 가게 9시까지 열어."}},{"id":636,"w":"time","def":"something measured in minutes, hours, days, etc.","pos":[{"p":"noun","senses":[{"ko":"시간","en":"what is measured in minutes, hours, days, and years"},{"ko":"시각, 때","en":"a particular moment shown on a clock or in the day"},{"ko":"번, 회","en":"an occasion when something happens"}]}],"ph":[{"t":"on time","ko":"제시간에"},{"t":"Take your time.","ko":"천천히 해"},{"t":"have a good time","ko":"즐거운 시간을 보내다"}],"ex":{"en":"I don't have time for this.","ko":"나 이럴 시간 없어."}},{"id":637,"w":"to","def":"used to indicate place or direction","pos":[{"p":"preposition","senses":[{"ko":"~로, ~에","en":"used to show the place or direction someone or something moves toward"},{"ko":"~까지","en":"used to show the end of a period or range"},{"ko":"~에게","en":"used to show who receives something or is spoken to"},{"ko":"(시각) ~분 전","en":"before the hour when saying the time, as in ten to five"}]}],"ph":[{"t":"from A to B","ko":"A부터 B까지"},{"t":"next to","ko":"~ 옆에"},{"t":"up to you","ko":"너한테 달렸어"}],"ex":{"en":"I'm heading to the gym.","ko":"나 헬스장 가는 중이야."}},{"id":638,"w":"today","def":"this day, this present day, at the present time","pos":[{"p":"adverb","senses":[{"ko":"오늘","en":"on this day, the day that is happening now"},{"ko":"요즘, 오늘날","en":"at the present period of time"}]},{"p":"noun","senses":[{"ko":"오늘","en":"this day, the present day"}]}],"ph":[{"t":"a week from today","ko":"다음 주 오늘"},{"t":"Today's the day.","ko":"드디어 오늘이야"}],"ex":{"en":"I'm so tired today.","ko":"오늘 너무 피곤해."}},{"id":639,"w":"together","def":"to be with each other or in one group","pos":[{"p":"adverb","senses":[{"ko":"함께, 같이","en":"with each other, or in one group or place"},{"ko":"동시에","en":"at the same time as each other"}]}],"ph":[{"t":"get together","ko":"모이다, 만나다"},{"t":"put together","ko":"조립하다; 준비하다"},{"t":"go together","ko":"잘 어울리다"}],"ex":{"en":"Let's have lunch together.","ko":"같이 점심 먹자."}},{"id":640,"w":"tomorrow","def":"the day after today","pos":[{"p":"adverb","senses":[{"ko":"내일","en":"on the day after today"}]},{"p":"noun","senses":[{"ko":"내일, 미래","en":"the day after today, or the future in general"}]}],"ph":[{"t":"See you tomorrow.","ko":"내일 봐"},{"t":"the day after tomorrow","ko":"모레"}],"ex":{"en":"Let's talk about it tomorrow.","ko":"내일 얘기하자."}},{"id":641,"w":"tonight","def":"this night or the night following this day","pos":[{"p":"adverb","senses":[{"ko":"오늘 밤에","en":"during the night of the present day"}]},{"p":"noun","senses":[{"ko":"오늘 밤","en":"the night or evening of the present day"}]}],"ph":[{"t":"Not tonight.","ko":"오늘 밤은 안 돼"}],"ex":{"en":"Are you free tonight?","ko":"오늘 밤에 시간 돼?"}},{"id":642,"w":"too","def":"in addition, also","pos":[{"p":"adverb","senses":[{"ko":"~도, 또한","en":"in addition to someone or something else; also"},{"ko":"너무, 지나치게","en":"more than is wanted, needed, or possible"}]}],"ph":[{"t":"Me too.","ko":"나도"},{"t":"Too bad.","ko":"안됐다, 아쉽다"},{"t":"too much","ko":"너무 많은, 과한"}],"ex":{"en":"I like pizza too.","ko":"나도 피자 좋아해."}},{"id":643,"w":"top","def":"the highest part, point, or level of something","pos":[{"p":"noun","senses":[{"ko":"맨 위, 꼭대기","en":"the highest part, point, or level of something"},{"ko":"뚜껑","en":"a cover that closes a bottle or container"},{"ko":"윗옷, 상의","en":"a piece of clothing worn on the upper body"}]},{"p":"adjective","senses":[{"ko":"최고의, 맨 위의","en":"highest in position, rank, or amount"}]}],"ph":[{"t":"on top of","ko":"~ 위에; ~에 더해"},{"t":"off the top of my head","ko":"얼핏 떠오르는 대로"},{"t":"top up","ko":"(가득) 채우다, 충전하다"}],"ex":{"en":"We climbed to the top of the hill.","ko":"우리 언덕 꼭대기까지 올라갔어."}},{"id":644,"w":"totally","def":"completely","pos":[{"p":"adverb","senses":[{"ko":"완전히, 전적으로","en":"completely; in every way"},{"ko":"정말, 완전 (맞장구)","en":"used in casual speech to strongly agree"}]}],"ph":[{"t":"totally different","ko":"완전히 다른"},{"t":"I totally agree.","ko":"완전 동의해"}],"ex":{"en":"I totally forgot about it.","ko":"그거 완전히 까먹었어."}},{"id":645,"w":"toward","def":"in the direction of","pos":[{"p":"preposition","senses":[{"ko":"~ 쪽으로, ~을 향해","en":"in the direction of someone or something"},{"ko":"~에 대한","en":"in relation to someone or something"},{"ko":"~ 무렵에","en":"near a particular time"}]}],"ph":[{"t":"toward the end","ko":"끝 무렵에"}],"ex":{"en":"He walked toward the door.","ko":"그가 문 쪽으로 걸어갔어."}},{"id":646,"w":"town","def":"a place people live, larger than a village, smaller than a city","pos":[{"p":"noun","senses":[{"ko":"마을, 소도시","en":"a place where people live that is bigger than a village but smaller than a city"},{"ko":"시내, 번화가","en":"the main shopping or business area of a place"}]}],"ph":[{"t":"go into town","ko":"시내에 나가다"},{"t":"out of town","ko":"타지에 (가 있는)"},{"t":"paint the town red","ko":"밤새 신나게 놀다"}],"ex":{"en":"I grew up in a small town.","ko":"나 작은 마을에서 자랐어."}},{"id":647,"w":"trade","def":"the activity of buying, selling, or exchanging","pos":[{"p":"noun","senses":[{"ko":"무역, 거래","en":"the activity of buying, selling, or exchanging goods"},{"ko":"직업, 기술","en":"a job that needs special skill, especially with your hands"}]},{"p":"verb","senses":[{"ko":"교환하다, 거래하다","en":"to give something and get something else in return"}]}],"ph":[{"t":"trade places","ko":"자리를 바꾸다, 입장을 바꾸다"},{"t":"trade in","ko":"(중고품을) 보상 판매하다"}],"ex":{"en":"Trade between the two countries is growing.","ko":"두 나라 간 무역이 늘고 있어."}},{"id":648,"w":"train","def":"a group of connected vehicles traveling on railways","pos":[{"p":"noun","senses":[{"ko":"기차, 열차","en":"a line of connected cars that travel together on a railway"}]},{"p":"verb","senses":[{"ko":"훈련하다, 교육하다","en":"to teach or learn the skills needed for a job or activity"},{"ko":"(운동) 훈련하다","en":"to exercise in order to prepare for a sports event"}]}],"ph":[{"t":"catch a train","ko":"기차를 (시간 맞춰) 타다"},{"t":"train of thought","ko":"생각의 흐름"}],"ex":{"en":"I'll take the train to Busan.","ko":"부산까지 기차 타고 갈게."}},{"id":649,"w":"travel","def":"to go on a trip or journey : to go to a place and especially one that is far away","pos":[{"p":"verb","senses":[{"ko":"여행하다","en":"to go on a trip, especially to a place that is far away"},{"ko":"이동하다, 다니다","en":"to move from one place to another"}]},{"p":"noun","senses":[{"ko":"여행","en":"the activity of going from place to place"}]}],"ph":[{"t":"travel light","ko":"짐을 가볍게 다니다"},{"t":"travel agency","ko":"여행사"}],"ex":{"en":"I want to travel around Europe someday.","ko":"언젠가 유럽 여행 다니고 싶어."}},{"id":650,"w":"trouble","def":"problems or difficulties","pos":[{"p":"noun","senses":[{"ko":"문제, 곤란","en":"problems, difficulties, or worries"},{"ko":"수고, 애씀","en":"extra effort or work needed to do something"}]},{"p":"verb","senses":[{"ko":"괴롭히다, 걱정시키다","en":"to make someone feel worried or upset"}]}],"ph":[{"t":"in trouble","ko":"곤경에 처한, 혼날 상황인"},{"t":"No trouble.","ko":"별거 아니야, 괜찮아"},{"t":"have trouble -ing","ko":"~하는 데 애를 먹다"}],"ex":{"en":"I'm having trouble with my phone.","ko":"폰에 문제가 좀 있어."}},{"id":651,"w":"true","def":"agreeing with the facts, not false, real or actual","pos":[{"p":"adjective","senses":[{"ko":"사실인, 맞는","en":"agreeing with the facts; not false"},{"ko":"진짜의, 진정한","en":"real or genuine, not pretended"},{"ko":"충실한","en":"loyal to a person or belief"}]}],"ph":[{"t":"come true","ko":"(꿈이) 이루어지다"},{"t":"That's true.","ko":"맞아, 그렇긴 해"},{"t":"true story","ko":"실화"}],"ex":{"en":"Is it true that you're moving?","ko":"너 이사 간다는 거 사실이야?"}},{"id":652,"w":"try","def":"to make an effort, to attempt to do something","pos":[{"p":"verb","senses":[{"ko":"노력하다, 시도하다","en":"to make an effort to do something"},{"ko":"해 보다, 먹어 보다","en":"to use, do, or taste something to see if you like it"}]},{"p":"noun","senses":[{"ko":"시도","en":"an attempt to do something"}]}],"ph":[{"t":"try on","ko":"입어 보다"},{"t":"give it a try","ko":"한번 해 보다"},{"t":"try your best","ko":"최선을 다하다"}],"ex":{"en":"I'll try to finish it tonight.","ko":"오늘 밤에 끝내 보도록 할게."}},{"id":653,"w":"turn","def":"to move around a central point","pos":[{"p":"verb","senses":[{"ko":"돌다, 돌리다","en":"to move, or make something move, around a central point"},{"ko":"방향을 바꾸다, 꺾다","en":"to change the direction you are facing or moving in"},{"ko":"~이 되다, 변하다","en":"to become something or change into something"}]},{"p":"noun","senses":[{"ko":"차례, 순서","en":"the time when someone in a group can or must do something"}]}],"ph":[{"t":"turn on / off","ko":"켜다 / 끄다"},{"t":"It's your turn.","ko":"네 차례야"},{"t":"turn down","ko":"거절하다; (소리를) 줄이다"}],"ex":{"en":"Turn the key to the right.","ko":"열쇠를 오른쪽으로 돌려."}},{"id":654,"w":"twelve","def":"the number 12","pos":[{"p":"number","senses":[{"ko":"12, 열둘","en":"the number 12, one more than eleven"}]}],"ph":[],"ex":{"en":"Let's meet at twelve for lunch.","ko":"점심 먹게 12시에 만나자."}},{"id":655,"w":"twenty","def":"the number 20","pos":[{"p":"number","senses":[{"ko":"20, 스물","en":"the number 20, two times ten"}]}],"ph":[{"t":"in your twenties","ko":"20대에"}],"ex":{"en":"I've known her for twenty years.","ko":"걔 안 지 20년 됐어."}},{"id":656,"w":"two","def":"the number 2","pos":[{"p":"number","senses":[{"ko":"2, 둘","en":"the number 2, one more than one"}]}],"ph":[{"t":"one or two","ko":"한두 개(의)"},{"t":"the two of us","ko":"우리 둘"}],"ex":{"en":"Can I get two coffees, please?","ko":"커피 두 잔 주세요."}},{"id":657,"w":"type","def":"a particular category of people or objects with a common characteristic","pos":[{"p":"noun","senses":[{"ko":"종류, 유형","en":"a group of people or things that share particular qualities"},{"ko":"(좋아하는) 타입","en":"the kind of person someone finds attractive"}]},{"p":"verb","senses":[{"ko":"타자를 치다, 입력하다","en":"to write something using a keyboard"}]}],"ph":[{"t":"my type","ko":"내 타입, 내 스타일"},{"t":"type in","ko":"(자판으로) 입력하다"}],"ex":{"en":"What type of music do you like?","ko":"어떤 종류의 음악 좋아해?"}},{"id":658,"w":"unclear","def":"not easy to understand","pos":[{"p":"adjective","senses":[{"ko":"불분명한, 이해하기 어려운","en":"not easy to understand or not clearly explained"},{"ko":"확실히 모르는","en":"not sure or certain about something"}]}],"ph":[{"t":"It's unclear whether ...","ko":"~인지 확실하지 않다"}],"ex":{"en":"Sorry, your instructions were a bit unclear.","ko":"미안, 설명이 좀 이해하기 어려웠어."}},{"id":659,"w":"under","def":"to be below something","pos":[{"p":"preposition","senses":[{"ko":"~ 아래에, 밑에","en":"below or lower than something, or covered by it"},{"ko":"~ 미만의","en":"less than a certain amount, age, or number"},{"ko":"~ 중인","en":"in the process of something, such as repair or construction"}]}],"ph":[{"t":"under control","ko":"잘 통제되는, 문제없는"},{"t":"under pressure","ko":"압박을 받는"},{"t":"under the weather","ko":"몸이 좀 안 좋은"}],"ex":{"en":"The cat is hiding under the bed.","ko":"고양이가 침대 밑에 숨어 있어."}},{"id":660,"w":"understand","def":"to know, to perceive or comprehend something","pos":[{"p":"verb","senses":[{"ko":"이해하다, 알다","en":"to know the meaning of something or how it works"},{"ko":"(사정·마음을) 이해하다","en":"to know how someone feels and why they act as they do"}]}],"ph":[{"t":"I understand.","ko":"알겠어요, 이해해요"},{"t":"make yourself understood","ko":"의사를 전달하다"}],"ex":{"en":"I don't understand what you mean.","ko":"무슨 말인지 모르겠어."}},{"id":661,"w":"unless","def":"used to say what will happen, be done, or be true if something else does not happen, is not done, or is not true","pos":[{"p":"conjunction","senses":[{"ko":"~하지 않으면, ~하지 않는 한","en":"except if; used to say what happens if something else does not"}]}],"ph":[],"ex":{"en":"We'll go out, unless it rains.","ko":"비 안 오면 나갈 거야."}},{"id":662,"w":"until","def":"up to, to indicate the point in time when a particular situation","pos":[{"p":"preposition","senses":[{"ko":"~까지","en":"up to a particular point in time"}]},{"p":"conjunction","senses":[{"ko":"~할 때까지","en":"up to the time when something happens"}]}],"ph":[{"t":"until then","ko":"그때까지"},{"t":"not until","ko":"~하고 나서야 비로소"}],"ex":{"en":"Wait until I get there.","ko":"내가 갈 때까지 기다려."}},{"id":663,"w":"up","def":"to move towards a high place from a lower one","pos":[{"p":"adverb","senses":[{"ko":"위로, 위쪽으로","en":"toward a higher place or position from a lower one"},{"ko":"완전히, 다","en":"so that something is finished, used up, or complete"},{"ko":"(잠에서) 깨어, 일어나","en":"awake and out of bed"}]},{"p":"adjective","senses":[{"ko":"(시간이) 다 된, 끝난","en":"finished, used about a period of time, as in time's up"}]}],"ph":[{"t":"What's up?","ko":"무슨 일이야?; 잘 지내?"},{"t":"give up","ko":"포기하다"},{"t":"up to you","ko":"너한테 달렸어"}],"ex":{"en":"Look up at the sky!","ko":"하늘 위를 봐!"}},{"id":664,"w":"use","def":"to do something with another thing","pos":[{"p":"verb","senses":[{"ko":"사용하다, 쓰다","en":"to do something with an object or method for a purpose"},{"ko":"소비하다, 쓰다","en":"to take an amount of something from a supply"}]},{"p":"noun","senses":[{"ko":"사용, 쓸모","en":"the act of using something, or the purpose it serves"}]}],"ph":[{"t":"used to","ko":"(예전에) ~하곤 했다"},{"t":"It's no use.","ko":"소용없어"},{"t":"make use of","ko":"~을 활용하다"}],"ex":{"en":"Can I use your phone for a second?","ko":"폰 잠깐 써도 돼?"}},{"id":665,"w":"usually","def":"in the way that most often happens","pos":[{"p":"adverb","senses":[{"ko":"보통, 대개","en":"in the way that happens most often; normally"}]}],"ph":[],"ex":{"en":"I usually get up at seven.","ko":"나 보통 7시에 일어나."}},{"id":666,"w":"value","def":"the amount of money something is worth","pos":[{"p":"noun","senses":[{"ko":"가치, 값","en":"the amount of money that something is worth"},{"ko":"중요성, 유용성","en":"how important or useful something is"}]},{"p":"verb","senses":[{"ko":"소중히 여기다","en":"to think that someone or something is important"}]}],"ph":[{"t":"good value","ko":"값어치를 하는, 싼 편인"},{"t":"value for money","ko":"가성비"}],"ex":{"en":"The value of our house has gone up.","ko":"우리 집값이 올랐어."}},{"id":667,"w":"various","def":"used to refer to several different or many different things","pos":[{"p":"adjective","senses":[{"ko":"여러 가지의, 다양한","en":"several different kinds of things or people"}]}],"ph":[{"t":"for various reasons","ko":"여러 가지 이유로"}],"ex":{"en":"I've tried various ways to fix it.","ko":"그거 고치려고 여러 방법을 써 봤어."}},{"id":668,"w":"very","def":"to a high degree","pos":[{"p":"adverb","senses":[{"ko":"매우, 아주","en":"to a high degree; extremely"}]},{"p":"adjective","senses":[{"ko":"바로 그","en":"used to stress that you mean exactly that one"}]}],"ph":[{"t":"very much","ko":"대단히, 무척"},{"t":"not very","ko":"별로 ~하지 않은"},{"t":"the very best","ko":"최고 중의 최고"}],"ex":{"en":"It's very cold today.","ko":"오늘 엄청 추워."}},{"id":669,"w":"view","def":"an opinion or way of thinking","pos":[{"p":"noun","senses":[{"ko":"견해, 의견","en":"an opinion or way of thinking about something"},{"ko":"경치, 전망","en":"what you can see from a particular place"}]},{"p":"verb","senses":[{"ko":"보다, 여기다","en":"to think about something in a particular way"}]}],"ph":[{"t":"in my view","ko":"내 생각에는"},{"t":"point of view","ko":"관점, 시각"},{"t":"in view of","ko":"~을 고려하여"}],"ex":{"en":"What's your view on this?","ko":"이거에 대해 네 생각은 어때?"}},{"id":670,"w":"visit","def":"to go somewhere to spend time with","pos":[{"p":"verb","senses":[{"ko":"방문하다, 찾아가다","en":"to go to see a person or place and spend time there"}]},{"p":"noun","senses":[{"ko":"방문","en":"an occasion when you go to see a person or place"}]}],"ph":[{"t":"pay a visit","ko":"방문하다, 들르다"}],"ex":{"en":"I'm going to visit my grandma this weekend.","ko":"이번 주말에 할머니 뵈러 갈 거야."}},{"id":671,"w":"vote","def":"to make an official choice for or against someone or something","pos":[{"p":"verb","senses":[{"ko":"투표하다","en":"to make an official choice for or against someone or something"}]},{"p":"noun","senses":[{"ko":"투표, 표","en":"a formal choice made in an election or group decision"}]}],"ph":[{"t":"vote for","ko":"~에게 투표하다, ~을 찍다"},{"t":"take a vote","ko":"표결에 부치다"}],"ex":{"en":"Who did you vote for?","ko":"누구 찍었어?"}},{"id":672,"w":"wait","def":"to stay or remain until an expected event happens","pos":[{"p":"verb","senses":[{"ko":"기다리다","en":"to stay where you are until something happens or someone comes"}]},{"p":"noun","senses":[{"ko":"기다림, 대기 시간","en":"a period of time spent waiting"}]}],"ph":[{"t":"Wait a minute.","ko":"잠깐만"},{"t":"can't wait","ko":"너무 기대된다"},{"t":"wait and see","ko":"두고 보다"}],"ex":{"en":"Can you wait for me here?","ko":"여기서 나 좀 기다려 줄래?"}},{"id":673,"w":"walk","def":"to move with your legs, to go on foot","pos":[{"p":"verb","senses":[{"ko":"걷다, 걸어가다","en":"to move on foot at a normal speed"},{"ko":"산책시키다, 바래다주다","en":"to take a person or animal somewhere on foot"}]},{"p":"noun","senses":[{"ko":"산책, 걷기","en":"a trip that you take on foot"}]}],"ph":[{"t":"go for a walk","ko":"산책하러 가다"},{"t":"walk away","ko":"자리를 뜨다, 손을 떼다"},{"t":"walk someone home","ko":"집까지 바래다주다"}],"ex":{"en":"I usually walk to work.","ko":"나 보통 회사에 걸어가."}},{"id":674,"w":"want","def":"to desire or wish for","pos":[{"p":"verb","senses":[{"ko":"원하다, 바라다","en":"to wish to have or do something"},{"ko":"~해 주길 바라다","en":"to wish that someone would do something"}]}],"ph":[{"t":"Do you want to ...?","ko":"~할래?"},{"t":"if you want","ko":"원하면"},{"t":"want to","ko":"~하고 싶다"}],"ex":{"en":"Do you want something to drink?","ko":"마실 거 뭐 줄까?"}},{"id":675,"w":"war","def":"a period of fighting or conflict between countries,","pos":[{"p":"noun","senses":[{"ko":"전쟁","en":"a period of fighting between countries or large groups"},{"ko":"싸움, 경쟁","en":"a strong fight or competition against something"}]}],"ph":[{"t":"at war","ko":"전쟁 중인"},{"t":"price war","ko":"가격 전쟁"}],"ex":{"en":"My grandfather fought in the war.","ko":"할아버지가 그 전쟁에 참전하셨어."}},{"id":676,"w":"watch","def":"to pay attention to what is happening","pos":[{"p":"verb","senses":[{"ko":"지켜보다, 보다","en":"to look at something for a time and pay attention to it"},{"ko":"조심하다, 주의하다","en":"to be careful about something"},{"ko":"봐 주다, 돌보다","en":"to look after someone or something for a short time"}]},{"p":"noun","senses":[{"ko":"손목시계","en":"a small clock that you wear on your wrist"}]}],"ph":[{"t":"Watch out!","ko":"조심해!"},{"t":"watch TV","ko":"TV를 보다"},{"t":"Watch your step.","ko":"발밑 조심해"}],"ex":{"en":"Watch how I do it.","ko":"내가 어떻게 하는지 봐."}},{"id":677,"w":"water","def":"the clear liquid which forms the seas, rivers and rain","pos":[{"p":"noun","senses":[{"ko":"물","en":"the clear liquid that falls as rain and fills seas and rivers"}]},{"p":"verb","senses":[{"ko":"(식물에) 물을 주다","en":"to pour water on plants or the ground"}]}],"ph":[{"t":"a glass of water","ko":"물 한 잔"},{"t":"in hot water","ko":"곤경에 빠진"}],"ex":{"en":"Can I have a glass of water?","ko":"물 한 잔 주실래요?"}},{"id":678,"w":"way","def":"a manner or characteristic of something","pos":[{"p":"noun","senses":[{"ko":"방식, 방법","en":"a manner or method of doing something"},{"ko":"길, 방향","en":"a road or route that leads to a place"}]},{"p":"adverb","senses":[{"ko":"훨씬, 너무","en":"very much or far, used in casual speech"}]}],"ph":[{"t":"No way!","ko":"말도 안 돼!"},{"t":"by the way","ko":"그건 그렇고"},{"t":"on my way","ko":"가는 중이야"}],"ex":{"en":"I like the way you think.","ko":"네 생각하는 방식이 좋아."}},{"id":679,"w":"we","def":"used to refer to the speaker and another person as the subject","pos":[{"p":"pronoun","senses":[{"ko":"우리","en":"the speaker and one or more other people as the subject"},{"ko":"(일반적인) 우리, 사람들","en":"people in general, including the speaker"}]}],"ph":[{"t":"Here we go.","ko":"자, 시작이다; 또 시작이네"},{"t":"We'll see.","ko":"두고 보자, 글쎄"}],"ex":{"en":"We should get going.","ko":"우리 이제 가야겠다."}},{"id":680,"w":"wear","def":"to use or have as clothing over part of your body","pos":[{"p":"verb","senses":[{"ko":"입다, 쓰다, 끼다","en":"to have clothes, shoes, glasses, or jewelry on your body"},{"ko":"닳다, 해지다","en":"to become thin or damaged from long use"}]}],"ph":[{"t":"wear out","ko":"닳다; 지치게 하다"},{"t":"wear makeup","ko":"화장하다"}],"ex":{"en":"What are you wearing to the party?","ko":"파티에 뭐 입고 갈 거야?"}},{"id":681,"w":"week","def":"a period of seven days, starts on Sunday and end on Saturday","pos":[{"p":"noun","senses":[{"ko":"주, 일주일","en":"a period of seven days, often from Sunday to Saturday"},{"ko":"평일, 주중","en":"the days of the week when people go to work or school"}]}],"ph":[{"t":"next week","ko":"다음 주"},{"t":"Have a good week.","ko":"좋은 한 주 보내"}],"ex":{"en":"I'll see you next week.","ko":"다음 주에 봐."}},{"id":682,"w":"weekend","def":"Saturday and Sunday","pos":[{"p":"noun","senses":[{"ko":"주말","en":"Saturday and Sunday, when many people do not work"}]}],"ph":[{"t":"Have a nice weekend!","ko":"좋은 주말 보내!"},{"t":"on the weekend","ko":"주말에"}],"ex":{"en":"Any plans for the weekend?","ko":"주말에 무슨 계획 있어?"}},{"id":683,"w":"well","def":"in a successful way, in a good or satisfactory way","pos":[{"p":"adverb","senses":[{"ko":"잘, 훌륭하게","en":"in a good, successful, or satisfactory way"},{"ko":"충분히, 완전히","en":"fully, carefully, or to a great degree"}]},{"p":"adjective","senses":[{"ko":"건강한","en":"healthy and not sick"}]},{"p":"interjection","senses":[{"ko":"음, 글쎄, 자","en":"used to pause or before you start to say something"}]}],"ph":[{"t":"as well","ko":"~도, 또한"},{"t":"Well done!","ko":"잘했어!"},{"t":"Oh well.","ko":"뭐, 어쩔 수 없지"}],"ex":{"en":"You did really well on the test.","ko":"너 시험 진짜 잘 봤더라."}},{"id":684,"w":"what","def":"asking for information about someone or something","pos":[{"p":"pronoun","senses":[{"ko":"무엇, 뭐","en":"used to ask for information about something"},{"ko":"~하는 것","en":"the thing or things that"}]},{"p":"determiner","senses":[{"ko":"무슨, 어떤","en":"used to ask which thing or what kind of thing"}]}],"ph":[{"t":"So what?","ko":"그래서 뭐?"},{"t":"What about ...?","ko":"~는 어때?"},{"t":"What if ...?","ko":"만약 ~하면 어떡해?"}],"ex":{"en":"What are you doing tonight?","ko":"오늘 밤에 뭐 해?"}},{"id":685,"w":"whatever","def":"anything or everything that or no matter what","pos":[{"p":"pronoun","senses":[{"ko":"무엇이든, 뭐든지","en":"anything or everything that"},{"ko":"무엇을 ~하더라도","en":"no matter what happens or what is true"}]},{"p":"interjection","senses":[{"ko":"아무렴 어때, 됐어","en":"used to show that you do not care"}]}],"ph":[{"t":"whatever you say","ko":"네 말대로 할게"},{"t":"or whatever","ko":"아니면 뭐 그런 거"}],"ex":{"en":"Take whatever you want.","ko":"원하는 거 뭐든 가져가."}},{"id":686,"w":"when","def":"at what time, at, in, during which, how soon","pos":[{"p":"adverb","senses":[{"ko":"언제","en":"at what time, used to ask about time"}]},{"p":"conjunction","senses":[{"ko":"~할 때","en":"at or during the time that something happens"},{"ko":"~하면","en":"after or as soon as something happens"}]}],"ph":[{"t":"Since when?","ko":"언제부터?"},{"t":"Say when.","ko":"됐으면 말해"}],"ex":{"en":"When are you coming back?","ko":"언제 돌아와?"}},{"id":687,"w":"where","def":"to be in at or in what place?","pos":[{"p":"adverb","senses":[{"ko":"어디에, 어디로","en":"in, at, or to what place"}]},{"p":"conjunction","senses":[{"ko":"~하는 곳(에)","en":"in, at, or to the place that"}]}],"ph":[{"t":"Where was I?","ko":"내가 어디까지 얘기했지?"},{"t":"Where to?","ko":"어디로 가세요?"}],"ex":{"en":"Where are you right now?","ko":"너 지금 어디야?"}},{"id":688,"w":"whether","def":"expressing a doubt between alternatives","pos":[{"p":"conjunction","senses":[{"ko":"~인지 (아닌지)","en":"used to show a doubt or choice between possibilities"},{"ko":"~이든 아니든","en":"used to say something is true in either case"}]}],"ph":[{"t":"whether or not","ko":"~이든 아니든"}],"ex":{"en":"I'm not sure whether he's coming.","ko":"걔가 올지 안 올지 모르겠어."}},{"id":689,"w":"which","def":"what one or ones of a group, one or more people or things","pos":[{"p":"determiner","senses":[{"ko":"어느, 어떤","en":"used to ask about one or more from a limited group"}]},{"p":"pronoun","senses":[{"ko":"어느 것","en":"used to ask which one or ones from a group"},{"ko":"~하는 (것)","en":"used to add information about a thing just mentioned"}]}],"ph":[{"t":"which one","ko":"어느 거"},{"t":"which way","ko":"어느 쪽으로"}],"ex":{"en":"Which one do you want?","ko":"어느 거로 할래?"}},{"id":690,"w":"while","def":"during the time that, at the same time","pos":[{"p":"conjunction","senses":[{"ko":"~하는 동안","en":"during the time that something is happening"},{"ko":"반면에","en":"used to show a contrast between two things"}]},{"p":"noun","senses":[{"ko":"잠시, 동안","en":"a period of time, usually a short one"}]}],"ph":[{"t":"for a while","ko":"한동안, 잠시"},{"t":"once in a while","ko":"가끔"},{"t":"worth your while","ko":"할 만한 가치가 있는"}],"ex":{"en":"I listen to music while I work.","ko":"나 일하면서 음악 들어."}},{"id":691,"w":"white","def":"having the color of snow, to be light or pale in color","pos":[{"p":"adjective","senses":[{"ko":"흰, 하얀","en":"having the color of snow or milk"},{"ko":"창백한","en":"pale in the face because of illness or fear"}]},{"p":"noun","senses":[{"ko":"흰색","en":"the color of snow or milk"}]}],"ph":[{"t":"white lie","ko":"선의의 거짓말"},{"t":"black and white","ko":"흑백의; 명백한"}],"ex":{"en":"I bought a white shirt.","ko":"흰 셔츠 하나 샀어."}},{"id":692,"w":"who","def":"what or which person or people, to ask about, talking about","pos":[{"p":"pronoun","senses":[{"ko":"누구","en":"used to ask which person or people"},{"ko":"~하는 (사람)","en":"used to give information about a person just mentioned"}]}],"ph":[{"t":"Who knows?","ko":"누가 알겠어?"},{"t":"Guess who?","ko":"누구게?"},{"t":"Who cares?","ko":"무슨 상관이야?"}],"ex":{"en":"Who's coming to the party?","ko":"파티에 누구 와?"}},{"id":693,"w":"whole","def":"complete or full, all of something","pos":[{"p":"adjective","senses":[{"ko":"전체의, 모든","en":"complete or full; all of something"},{"ko":"통째의","en":"in one piece, not cut or broken into parts"}]},{"p":"noun","senses":[{"ko":"전체","en":"all of something, or a complete thing"}]}],"ph":[{"t":"the whole time","ko":"그동안 내내"},{"t":"on the whole","ko":"대체로"},{"t":"the whole thing","ko":"그 일 전부"}],"ex":{"en":"I ate the whole pizza by myself.","ko":"피자 한 판 혼자 다 먹었어."}},{"id":694,"w":"why","def":"for what reason or purpose","pos":[{"p":"adverb","senses":[{"ko":"왜","en":"for what reason or purpose"}]}],"ph":[{"t":"Why not?","ko":"왜 안 돼?; 좋지"},{"t":"Why don't you ...?","ko":"~하는 게 어때?"}],"ex":{"en":"Why are you so late?","ko":"왜 이렇게 늦었어?"}},{"id":695,"w":"wife","def":"a married woman","pos":[{"p":"noun","senses":[{"ko":"아내, 부인","en":"the woman that a person is married to"}]}],"ph":[{"t":"husband and wife","ko":"부부"}],"ex":{"en":"This is my wife, Jenny.","ko":"이쪽은 제 아내 제니예요."}},{"id":696,"w":"will","def":"expressing the future, to say something is expected to happen","pos":[{"p":"modal","senses":[{"ko":"~할 것이다","en":"used to talk about what is expected to happen in the future"},{"ko":"~할게","en":"used to say that you are willing or plan to do something"},{"ko":"~해 줄래?","en":"used to ask someone to do something"}]},{"p":"noun","senses":[{"ko":"의지; 유언장","en":"strong determination, or a legal paper about property after death"}]}],"ph":[{"t":"Will do.","ko":"그렇게 할게"},{"t":"against your will","ko":"억지로, 본의 아니게"}],"ex":{"en":"It will be sunny tomorrow.","ko":"내일은 맑을 거야."}},{"id":697,"w":"win","def":"to achieve victory in a fight or game","pos":[{"p":"verb","senses":[{"ko":"이기다, 승리하다","en":"to be the most successful in a game, fight, or contest"},{"ko":"(상을) 타다, 따다","en":"to get a prize or reward by doing well"}]},{"p":"noun","senses":[{"ko":"승리","en":"a victory in a game or contest"}]}],"ph":[{"t":"You win.","ko":"네가 이겼어, 네 말대로 해"},{"t":"win-win","ko":"모두에게 좋은"},{"t":"can't win","ko":"뭘 해도 안 된다"}],"ex":{"en":"Did your team win last night?","ko":"어젯밤에 너네 팀 이겼어?"}},{"id":698,"w":"window","def":"an opening in a wall or door that usually contains a sheet of glass","pos":[{"p":"noun","senses":[{"ko":"창문, 창","en":"an opening in a wall or vehicle, usually filled with glass"},{"ko":"(컴퓨터) 창","en":"an area on a computer screen that shows a program"}]}],"ph":[{"t":"window shopping","ko":"아이쇼핑"},{"t":"out the window","ko":"물거품이 된, 사라진"}],"ex":{"en":"Can you open the window?","ko":"창문 좀 열어 줄래?"}},{"id":699,"w":"wish","def":"to want something to be true or to happen","pos":[{"p":"verb","senses":[{"ko":"~이면 좋겠다, 바라다","en":"to want something to be true or happen, often when it is unlikely"},{"ko":"빌다, 기원하다","en":"to hope that someone will have something good"}]},{"p":"noun","senses":[{"ko":"소원, 바람","en":"a desire or hope for something"}]}],"ph":[{"t":"I wish!","ko":"그러면 얼마나 좋을까!"},{"t":"make a wish","ko":"소원을 빌다"},{"t":"best wishes","ko":"행운을 빌어요"}],"ex":{"en":"I wish I could stay longer.","ko":"더 있을 수 있으면 좋겠다."}},{"id":700,"w":"with","def":"used to express that people or things are together","pos":[{"p":"preposition","senses":[{"ko":"~와 함께","en":"used to show that people or things are together or near each other"},{"ko":"~을 가지고, ~로","en":"using something as a tool or method"},{"ko":"~이 있는","en":"having or carrying something"}]}],"ph":[{"t":"I'm with you.","ko":"동의해, 네 편이야"},{"t":"What's wrong with ...?","ko":"~에 무슨 문제 있어?"}],"ex":{"en":"Do you want to come with me?","ko":"나랑 같이 갈래?"}},{"id":701,"w":"within","def":"inside something","pos":[{"p":"preposition","senses":[{"ko":"~ 안에, 내부에","en":"inside a place, group, or thing"},{"ko":"~ 이내에","en":"before a certain period of time has passed"}]}],"ph":[{"t":"within walking distance","ko":"걸어갈 수 있는 거리에"},{"t":"within reach","ko":"손이 닿는 곳에"}],"ex":{"en":"Smoking isn't allowed within the building.","ko":"건물 안에서는 흡연 금지야."}},{"id":702,"w":"without","def":"not having or including something, in the absence of","pos":[{"p":"preposition","senses":[{"ko":"~ 없이","en":"not having or including something or someone"},{"ko":"~하지 않고","en":"not doing a particular thing"}]}],"ph":[{"t":"without a doubt","ko":"의심의 여지 없이"},{"t":"go without","ko":"~ 없이 지내다"},{"t":"It goes without saying","ko":"말할 필요도 없다"}],"ex":{"en":"I can't live without coffee.","ko":"나 커피 없이는 못 살아."}},{"id":703,"w":"woman","def":"an adult female human being","pos":[{"p":"noun","senses":[{"ko":"여자, 여성","en":"an adult female human being"}]}],"ph":[{"t":"young woman","ko":"젊은 여성"}],"ex":{"en":"Who's that woman talking to Mike?","ko":"마이크랑 얘기하는 저 여자 누구야?"}},{"id":704,"w":"wonder","def":"something that is very surprising or amazing","pos":[{"p":"noun","senses":[{"ko":"경이, 놀라운 것","en":"something very surprising or amazing, or the feeling it causes"}]},{"p":"verb","senses":[{"ko":"궁금하다, 궁금해하다","en":"to want to know something or think about it"},{"ko":"~해 주실 수 있을까요","en":"used to ask for something politely, as in I wonder if"}]}],"ph":[{"t":"No wonder.","ko":"어쩐지, 그럴 만하네"},{"t":"I wonder if ...","ko":"~일까?; ~해 줄 수 있을까?"},{"t":"It's a wonder ...","ko":"~라니 신기하다"}],"ex":{"en":"The Grand Canyon is one of nature's wonders.","ko":"그랜드 캐니언은 자연의 경이 중 하나야."}},{"id":705,"w":"wonderful","def":"very good","pos":[{"p":"adjective","senses":[{"ko":"아주 좋은, 훌륭한","en":"extremely good, pleasant, or enjoyable"},{"ko":"놀라운, 경이로운","en":"causing a feeling of surprise and admiration"}]}],"ph":[{"t":"That's wonderful!","ko":"정말 잘됐다!"}],"ex":{"en":"We had a wonderful time.","ko":"정말 즐거운 시간 보냈어."}},{"id":706,"w":"word","def":"a unit of language that has a meaning","pos":[{"p":"noun","senses":[{"ko":"단어, 낱말","en":"a unit of language with a meaning that is spoken or written"},{"ko":"말, 이야기","en":"something that someone says, or a short talk"},{"ko":"약속","en":"a promise that you will do something"}]}],"ph":[{"t":"in other words","ko":"다시 말해"},{"t":"keep your word","ko":"약속을 지키다"},{"t":"have a word with","ko":"~와 잠깐 얘기하다"}],"ex":{"en":"What does this word mean?","ko":"이 단어 무슨 뜻이야?"}},{"id":707,"w":"work","def":"to have a job or activity involving mental or physical effort","pos":[{"p":"verb","senses":[{"ko":"일하다","en":"to do a job or activity that needs mental or physical effort"},{"ko":"작동하다, 효과가 있다","en":"to operate properly or have the result you want"}]},{"p":"noun","senses":[{"ko":"일, 직장","en":"a job, or the place where you do your job"}]}],"ph":[{"t":"work out","ko":"운동하다; 잘 풀리다"},{"t":"It works for me.","ko":"난 좋아, 괜찮아"},{"t":"at work","ko":"회사에서, 근무 중인"}],"ex":{"en":"I work at a bank.","ko":"나 은행에서 일해."}},{"id":708,"w":"world","def":"the earth and all people and things on it","pos":[{"p":"noun","senses":[{"ko":"세계, 세상","en":"the earth and all the people and things on it"},{"ko":"~계, 분야","en":"a particular area of activity or group of people"}]}],"ph":[{"t":"It's a small world.","ko":"세상 참 좁다"},{"t":"mean the world to","ko":"~에게 전부다, 아주 소중하다"},{"t":"out of this world","ko":"끝내주는, 최고인"}],"ex":{"en":"I want to see the whole world someday.","ko":"언젠가 온 세상을 다 보고 싶어."}},{"id":709,"w":"worry","def":"to think about problems or fears","pos":[{"p":"verb","senses":[{"ko":"걱정하다","en":"to keep thinking about problems or bad things that might happen"},{"ko":"걱정시키다","en":"to make someone feel anxious or upset"}]},{"p":"noun","senses":[{"ko":"걱정, 걱정거리","en":"a feeling of anxiety, or something that causes it"}]}],"ph":[{"t":"Don't worry.","ko":"걱정 마"},{"t":"No worries.","ko":"괜찮아, 신경 쓰지 마"},{"t":"worry about","ko":"~을 걱정하다"}],"ex":{"en":"I always worry about money.","ko":"나 맨날 돈 걱정해."}},{"id":710,"w":"worth","def":"used to indicate the value of something","pos":[{"p":"adjective","senses":[{"ko":"~의 가치가 있는","en":"having a particular value, especially in money"},{"ko":"~할 가치가 있는","en":"good or useful enough to do, see, or have"}]},{"p":"noun","senses":[{"ko":"가치, ~어치","en":"the value of something, or an amount of it"}]}],"ph":[{"t":"worth it","ko":"그럴 만한 가치가 있는"},{"t":"worth a try","ko":"해 볼 만한"},{"t":"for what it's worth","ko":"별건 아니지만, 참고로"}],"ex":{"en":"This ring is worth a lot of money.","ko":"이 반지 값이 꽤 나가."}},{"id":711,"w":"would","def":"indicating someone thinking about what will happen","pos":[{"p":"modal","senses":[{"ko":"~할 것이다 (과거에서 본 미래)","en":"used to say what someone thought or expected would happen"},{"ko":"~할 텐데, ~일 것이다","en":"used to talk about an imagined situation or its result"},{"ko":"~해 주시겠어요?","en":"used to ask for something or offer something politely"},{"ko":"~하곤 했다","en":"used to talk about things that happened often in the past"}]}],"ph":[{"t":"Would you like ...?","ko":"~하시겠어요?, ~드릴까요?"},{"t":"I would rather","ko":"차라리 ~하겠다"},{"t":"Would you mind ...?","ko":"~해 주시겠어요?"}],"ex":{"en":"I knew you would come.","ko":"네가 올 줄 알았어."}},{"id":712,"w":"write","def":"to compose letters and words on a surface","pos":[{"p":"verb","senses":[{"ko":"쓰다, 적다","en":"to form letters and words on paper or a screen"},{"ko":"(글·책·곡을) 쓰다","en":"to create a book, song, or other piece of writing"},{"ko":"편지를 쓰다","en":"to send a letter or message to someone"}]}],"ph":[{"t":"write down","ko":"적어 두다"},{"t":"write back","ko":"답장하다"}],"ex":{"en":"Can you write your name here?","ko":"여기 이름 좀 써 줄래요?"}},{"id":713,"w":"wrong","def":"not agreeing with the facts or truth : incorrect","pos":[{"p":"adjective","senses":[{"ko":"틀린, 잘못된","en":"not correct or not true"},{"ko":"문제가 있는","en":"not working properly, or causing a problem"},{"ko":"나쁜, 옳지 않은","en":"not morally right or fair"}]},{"p":"adverb","senses":[{"ko":"잘못, 틀리게","en":"in a way that is not correct"}]}],"ph":[{"t":"What's wrong?","ko":"무슨 일 있어?, 왜 그래?"},{"t":"go wrong","ko":"잘못되다, 틀어지다"},{"t":"Don't get me wrong.","ko":"오해하지 마"}],"ex":{"en":"Sorry, I think you have the wrong number.","ko":"죄송한데 전화 잘못 거신 것 같아요."}},{"id":714,"w":"yeah","def":"yes","pos":[{"p":"interjection","senses":[{"ko":"응, 그래","en":"yes, used in casual speech"}]}],"ph":[{"t":"Oh yeah?","ko":"아 그래?, 정말?"},{"t":"Yeah, right.","ko":"퍽이나, 설마"},{"t":"Yeah, yeah.","ko":"알았어 알았어"}],"ex":{"en":"Yeah, that sounds good to me.","ko":"응, 난 좋아."}},{"id":715,"w":"year","def":"a unit of time equal to 12 months or 365 days","pos":[{"p":"noun","senses":[{"ko":"해, 년","en":"a period of time equal to twelve months or 365 days"},{"ko":"학년","en":"a level or stage in school or university"}]}],"ph":[{"t":"Happy New Year!","ko":"새해 복 많이 받아!"},{"t":"years old","ko":"~살"},{"t":"all year round","ko":"일 년 내내"}],"ex":{"en":"I've lived here for three years.","ko":"나 여기 산 지 3년 됐어."}},{"id":716,"w":"yes","def":"used to give a positive answer or reply to a question, request, or offer","pos":[{"p":"interjection","senses":[{"ko":"네, 응","en":"used to give a positive answer or agree with something"},{"ko":"(부를 때 대답) 네?","en":"used to answer when someone calls you or wants your attention"}]},{"p":"noun","senses":[{"ko":"찬성, 승낙","en":"an answer or vote that agrees with something"}]}],"ph":[{"t":"Yes, please.","ko":"네, 부탁해요"},{"t":"say yes","ko":"승낙하다, 좋다고 하다"}],"ex":{"en":"Yes, I'd love to come!","ko":"응, 꼭 가고 싶어!"}},{"id":717,"w":"yesterday","def":"the day before today","pos":[{"p":"adverb","senses":[{"ko":"어제","en":"on the day before today"}]},{"p":"noun","senses":[{"ko":"어제","en":"the day before today"}]}],"ph":[{"t":"the day before yesterday","ko":"그저께"},{"t":"yesterday morning","ko":"어제 아침"}],"ex":{"en":"I saw her yesterday.","ko":"나 어제 걔 봤어."}},{"id":718,"w":"yet","def":"until now, up until the present","pos":[{"p":"adverb","senses":[{"ko":"아직","en":"until now; up to the present time"},{"ko":"벌써, 이제 (의문문)","en":"used in questions to ask if something has happened already"}]},{"p":"conjunction","senses":[{"ko":"그런데도, 그렇지만","en":"but at the same time; even so"}]}],"ph":[{"t":"not yet","ko":"아직 아니야"},{"t":"yet again","ko":"또다시"},{"t":"as yet","ko":"아직까지"}],"ex":{"en":"I haven't eaten yet.","ko":"나 아직 밥 안 먹었어."}},{"id":719,"w":"you","def":"used to refer to the person the speaker is addressing","pos":[{"p":"pronoun","senses":[{"ko":"너, 당신, 너희","en":"the person or people that the speaker is talking to"},{"ko":"(일반적인) 사람들","en":"people in general, used in casual speech"}]}],"ph":[{"t":"you know","ko":"있잖아, 그러니까"},{"t":"You know what?","ko":"있잖아, 그거 알아?"},{"t":"See you.","ko":"또 봐"}],"ex":{"en":"Are you okay?","ko":"너 괜찮아?"}},{"id":720,"w":"young","def":"in an early stage of life or growth","pos":[{"p":"adjective","senses":[{"ko":"어린, 젊은","en":"in an early stage of life or growth"}]},{"p":"noun","senses":[{"ko":"젊은이들; (동물의) 새끼","en":"young people as a group, or baby animals"}]}],"ph":[{"t":"young at heart","ko":"마음이 젊은"},{"t":"when I was young","ko":"내가 어렸을 때"}],"ex":{"en":"She looks so young for her age.","ko":"걔 나이에 비해 엄청 어려 보여."}},{"id":721,"w":"yourself","def":"the reflexive form of the pronoun 'you'","pos":[{"p":"pronoun","senses":[{"ko":"너 자신, 당신 자신","en":"used when the person you are talking to is also affected by the action"},{"ko":"직접, 스스로","en":"used to stress that you do something without help"}]}],"ph":[{"t":"Help yourself.","ko":"마음껏 드세요"},{"t":"Take care of yourself.","ko":"몸 잘 챙겨"},{"t":"by yourself","ko":"혼자서, 혼자 힘으로"}],"ex":{"en":"Be careful not to hurt yourself.","ko":"다치지 않게 조심해."}}];
